window.ARTICLES_L10N=window.ARTICLES_L10N||{};window.ARTICLES_L10N["vi"]={"a-n5-1":{"title":"Một ngày của tôi","topic":"Đời sống hằng ngày","trans":["Mỗi sáng tôi dậy lúc sáu giờ. Tôi rửa mặt rồi ăn sáng.","Bảy giờ rưỡi tôi ra khỏi nhà, đi tàu điện đến công ty. Công việc bắt đầu từ chín giờ.","Buổi trưa tôi ăn ramen ở quán gần công ty. Ăn rất ngon.","Sáu giờ chiều tôi tan làm. Tôi về nhà và nấu bữa tối.","Buổi tối tôi học tiếng Nhật một chút rồi đi ngủ lúc mười một giờ.","Cuối tuần tôi hầu như không có việc. Tôi đi dạo công viên với bạn bè, xem phim, v.v.","Ngày nào cũng bận rộn, nhưng tiếng Nhật của tôi giỏi dần lên từng chút một, tôi thấy rất vui."],"vocab":["thức dậy","mặt","công ty","buổi trưa","làm, chế biến"],"grammar":[{"t":"に (thời gian)","note":"Thêm 「に」 sau mốc thời gian cụ thể: 六時に、十一時に。「毎朝」 là thời gian mang tính tương đối nên không thêm に."},{"t":"で (phương tiện/địa điểm)","note":"Phương tiện giao thông dùng で: 電車で; nơi diễn ra hành động cũng dùng で: 店で食べる。"},{"t":"Nối câu bằng thể て","note":"Nối các hành động liên tiếp bằng thể て: 顔を洗って、朝ごはんを食べます。"}]},"a-n5-2":{"title":"Bữa sáng của Nhật Bản","topic":"Văn hóa","trans":["Bữa sáng truyền thống của Nhật Bản là cơm và súp miso.","Ngoài ra, người ta cũng hay ăn cá nướng và trứng. Rong biển khô cũng rất được ưa chuộng.","Gần đây, nhiều người ăn sáng bằng bánh mì và cà phê. Đặc biệt là người trẻ rất thích.","Vào những buổi sáng bận rộn, cũng có người chỉ ăn cơm nắm. Bữa sáng ở nước bạn thường ăn gì?","Bữa sáng bánh mì với cà phê cũng rất được ưa chuộng, nhưng tôi vẫn thích cơm và súp miso hơn.","Buổi sáng ăn đầy đủ thì cả ngày bạn sẽ có nhiều năng lượng."],"vocab":["mang tính truyền thống","nướng","được ưa chuộng","trẻ","bận rộn"],"grammar":[{"t":"や (liệt kê một phần)","note":"Nêu vài ví dụ tiêu biểu, ngụ ý còn có những thứ khác: 魚や卵、パンやコーヒー。"},{"t":"だけ","note":"Nghĩa là \"chỉ\": おにぎりだけ = chỉ có cơm nắm."},{"t":"が人気があります","note":"Nghĩa là \"~ được ưa chuộng\", đối tượng đi với が."}]},"a-n4-1":{"title":"Ngắm hoa anh đào (Hanami)","topic":"Văn hóa","trans":["Cứ đến mùa xuân là hoa anh đào nở khắp nơi trên nước Nhật.","Mọi người tụ tập ở công viên, ăn cơm hộp và uống rượu dưới tán hoa anh đào. Hoạt động này được gọi là「お花見」.","Hoa anh đào rất đẹp nhưng thời gian nở chỉ khoảng một tuần, khá ngắn. Vì vậy ai cũng mong chờ khoảng thời gian này.","Hoa anh đào được thắp đèn vào ban đêm cũng rất đẹp. Bạn nhất định hãy đi xem thử một lần nhé.","Phong tục ngắm hoa có từ rất lâu đời, người xưa cũng ngắm hoa anh đào để tận hưởng mùa xuân.","Tuy nhiên cũng có vấn đề như giữ chỗ và xả rác, nên việc giữ phép lịch sự là rất quan trọng."],"vocab":["(hoa) nở","tụ tập, tập hợp","khoảng thời gian, thời kỳ","niềm mong chờ, niềm vui thú","đẹp, đẹp đẽ"],"grammar":[{"t":"~と (điều kiện tất yếu)","note":"Nghĩa là \"hễ ~ thì ~\", diễn tả kết quả tự nhiên: 春になると、桜が咲く。"},{"t":"~たり~たり","note":"Liệt kê các hành động tiêu biểu, ngụ ý còn những việc khác nữa: 食べたり飲んだりする。"},{"t":"~てみる","note":"Thử làm gì đó xem sao: 行ってみてください。"}]},"a-n4-2":{"title":"Phép lịch sự trên tàu điện","topic":"Đời sống","trans":["Bên trong tàu điện ở Nhật rất yên tĩnh. Nhiều người đọc sách, xem điện thoại hoặc nhắm mắt nghỉ ngơi.","Gọi điện thoại trong tàu được coi là vi phạm phép lịch sự. Khi muốn nói chuyện, người ta xuống ga rồi mới gọi.","Ngoài ra, gần ghế ưu tiên, đôi khi bạn còn được nhắc tắt nguồn điện thoại, vì có thể ảnh hưởng đến máy tạo nhịp tim, v.v.","Đằng sau những phép lịch sự này là suy nghĩ của người Nhật: \"không làm phiền những người xung quanh\". Đó không hẳn là quy định mà đúng hơn là sự quan tâm dành cho nhau.","Những phép lịch sự này là để nhiều người có thể đi tàu một cách thoải mái.","Không chỉ nghĩ cho bản thân mà còn nghĩ đến những người xung quanh, thì mọi người đều có thể có một chuyến đi dễ chịu."],"vocab":["yên tĩnh","vi phạm","ghế ưu tiên","ảnh hưởng","sự quan tâm, sự chu đáo"],"grammar":[{"t":"~たり~たり","note":"Liệt kê các hành động: 読んだり、見たり、休んだり。"},{"t":"~ように言われる","note":"Bị yêu cầu (làm) ~: 電源を切るように言われる。"},{"t":"~という (trích dẫn danh từ hóa)","note":"「~という考え方」: dùng để dẫn nội dung hoặc tên gọi, nghĩa là \"cái gọi là ~\", \"suy nghĩ rằng ~\"."}]},"a-n3-2":{"title":"Những điều học được khi sống một mình","topic":"Cuộc sống","trans":["Vào đại học, lần đầu tiên tôi bắt đầu sống một mình. Lúc đầu, được tự do khiến tôi rất vui.","Nhưng khi thực sự sống rồi mới thấy, nấu ăn, giặt giũ, dọn dẹp, tất cả đều phải tự mình làm. Tôi mới nhận ra từ trước đến nay bố mẹ đã làm cho mình nhiều việc đến thế nào.","Tôi cũng bắt đầu suy nghĩ về cách tiêu tiền. Với khoản sinh hoạt phí có hạn, bạn sẽ tự nhiên học cách phán đoán đâu mới thật sự là thứ cần thiết.","Sống một mình có nhiều chuyện vất vả, nhưng giúp mình có được khả năng tự lo cho bản thân. Và quan trọng hơn cả, tôi hiểu được sự đáng quý của gia đình rõ hơn trước rất nhiều.","Sống một mình đôi khi cũng cô đơn, nhưng bù lại bạn có thể tự do sử dụng thời gian của mình.","Việc nhận ra gia đình đáng quý đến thế nào cũng chỉ đến sau khi tôi bắt đầu sống xa nhà."],"vocab":["sống một mình","giặt giũ","một lần nữa, nhận ra lại","phán đoán","đáng biết ơn, đáng quý"],"grammar":[{"t":"~てみると","note":"「Thử làm thực tế ~ thì (mới thấy)」: 暮らしてみると。"},{"t":"~なければならない","note":"「Phải ~」, diễn tả nghĩa vụ: 自分でやらなければならない。"},{"t":"~ようになる","note":"「Trở nên ~」, thay đổi một cách tự nhiên: 考えるようになった。"}]},"a-n3-3":{"title":"Văn hóa nhà tắm công cộng","topic":"Văn hóa","trans":["Sentō là nhà tắm công cộng nơi mọi người cùng vào tắm. Ngày xưa nhiều người trong nhà không có bồn tắm, nên sentō là nơi không thể thiếu trong cuộc sống.","Khi bồn tắm trong gia đình trở nên phổ biến, số lượng sentō giảm dần. Nhưng gần đây, người ta lại đánh giá lại những điều tốt đẹp của nó.","Ngâm mình thong thả trong bồn tắm rộng, không chỉ cơ thể mà cả tâm hồn cũng được thư giãn. Đôi khi bạn còn tự nhiên trò chuyện với một người lạ ngồi bên cạnh.","Có lẽ vì quá theo đuổi sự tiện lợi, chúng ta đang dần đánh mất sự kết nối với nhau. Sentō chính là nơi giúp ta nhớ lại khoảng cách giữa người với người trong thời đại như thế.","Sentō không chỉ là nơi để rửa cơ thể, mà còn từng là nơi người dân trong khu vực gặp gỡ nhau.","Ngày nay nhà nào cũng có bồn tắm nên số lượng sentō đang giảm, nhưng cũng có nhiều người đánh giá lại sự ấm áp ấy."],"vocab":["công cộng","phổ biến, lan rộng","nhìn nhận lại, đánh giá lại","sự kết nối, mối quan hệ","khoảng cách"],"grammar":[{"t":"~とは","note":"「Gọi là ~ (là)」, dùng để định nghĩa: 銭湯とは~のことだ。"},{"t":"~ていく","note":"「Dần dần ~ đi」, xu hướng thay đổi: 減っていった。"},{"t":"~つつある","note":"「Đang dần ~」, văn viết: 失いつつある。"}]},"a-n3-4":{"title":"Tình trạng tỷ lệ sinh giảm ngày càng nghiêm trọng","topic":"Tin tức","trans":["Hiện nay ở Nhật Bản, số trẻ em đang liên tục giảm. Hiện tượng này được gọi là「少子化」(tỷ lệ sinh thấp).","Nguyên nhân không chỉ có một. Nhiều lý do chồng chéo lên nhau: số người không kết hôn tăng lên, gánh nặng chi phí nuôi dạy con cái lớn, khó cân bằng giữa công việc và chăm con, v.v.","Trẻ em giảm thì số người đi làm trong tương lai cũng giảm theo. Kết quả là sức mạnh kinh tế có thể suy yếu, hoặc hệ thống hỗ trợ người cao tuổi có thể không còn duy trì nổi.","Chính phủ đang triển khai nhiều biện pháp, nhưng hiệu quả vẫn chưa đủ. Câu hỏi đặt ra cho toàn xã hội là làm thế nào để tạo ra môi trường dễ nuôi dạy con cái.","Người ta nói rằng đằng sau tình trạng tỷ lệ sinh thấp là gánh nặng quá lớn của việc kết hôn và nuôi con.","Nếu cứ tiếp tục như thế này, số người lao động sẽ giảm và việc nâng đỡ toàn xã hội sẽ trở nên khó khăn."],"vocab":["giảm","gánh nặng","cân bằng cả hai, song song","nâng đỡ, chống đỡ","biện pháp đối phó"],"grammar":[{"t":"~続ける","note":"「tiếp tục ~, cứ ~ mãi」: 減り続けている。"},{"t":"~たり~たりする","note":"Liệt kê các tình huống có thể xảy ra: 弱くなったり、立ちゆかなくなったり。"},{"t":"~おそれがある","note":"「có nguy cơ/khả năng ~」, dùng cho điều tiêu cực: 立ちゆかなくなるおそれがある。"}]},"a-n3-5":{"title":"飲みニケーション","topic":"Nơi làm việc","trans":["Ở các công ty Nhật Bản, sau giờ làm người ta thường đi uống rượu với đồng nghiệp hoặc sếp. Việc này được gọi là「飲みニケーション」(giao tiếp qua bữa nhậu).","Trong bữa nhậu, bạn có thể nói ra những suy nghĩ thật lòng khó nói ngày thường, và trò chuyện thoải mái với sếp. Nhiều người cho rằng đây là cơ hội tốt để thắt chặt mối quan hệ.","Mặt khác, trong giới trẻ, ngày càng nhiều người nghĩ「thời gian sau giờ làm muốn dành cho bản thân」. Cũng không ít người cảm thấy khó chịu khi bị ép tham gia.","Trong thời đại cách làm việc và giá trị quan ngày càng đa dạng như hiện nay, có lẽ cách thức của 「飲みニケーション」cũng đang dần thay đổi.","Tuy nhiên, trong số những người trẻ gần đây, ngày càng có nhiều người muốn tách bạch rõ ràng giữa công việc và đời tư.","Dù không dựa vào rượu, xây dựng được lòng tin qua những cuộc trò chuyện thường ngày mới là điều lý tưởng nhỉ."],"vocab":["đồng nghiệp","suy nghĩ thật lòng","thoải mái, tự nhiên","ép buộc, cưỡng chế","đa dạng"],"grammar":[{"t":"~にくい","note":"「khó ~」: 言いにくい。"},{"t":"一方で","note":"「mặt khác」, dùng để đối chiếu: ~という人も多い。一方で、~。"},{"t":"~つつある","note":"「đang dần ~」: 変わりつつある。"}]},"a-n4-3":{"title":"Dạo bước ở cố đô Kyoto","topic":"Du lịch","trans":["Kyoto là thành phố từng là thủ đô của Nhật Bản cách đây hơn một nghìn năm. Đến tận bây giờ, nơi đây vẫn còn giữ lại rất nhiều ngôi chùa và đền thờ cổ.","Hoa anh đào mùa xuân và lá đỏ mùa thu đều rất đẹp, mỗi mùa lại khoác lên mình một diện mạo khác nhau. Vì vậy, dù đến bao nhiêu lần bạn cũng không thấy chán.","Khi du lịch Kyoto, bạn nên đi dạo thong thả, đừng vội vàng. Rẽ vào một con hẻm nhỏ, bạn sẽ bắt gặp những ngôi chùa yên tĩnh hay những quán cà phê mang phong vị xưa cũ.","Không chỉ các địa điểm du lịch nổi tiếng, nếu thử ghé vào những cửa hàng nhỏ mà người dân địa phương hay lui tới, bạn sẽ nhìn thấy sức hút thực sự của Kyoto.","Mỗi mùa Kyoto lại khoác lên mình một diện mạo khác nhau. Hoa anh đào mùa xuân và lá đỏ mùa thu đều rất đẹp.","Vừa gìn giữ những công trình cổ, vừa tiếp nhận cả nền văn hóa mới, đó chính là sức hút của Kyoto."],"vocab":["thủ đô","còn lại, được lưu giữ","ghé thăm, viếng thăm","rẽ, quẹo","sức hút, sức quyến rũ"],"grammar":[{"t":"~ごとに","note":"「mỗi ~」: 季節ごとに = mỗi mùa."},{"t":"~ても(nhượng bộ)","note":"「dù ~ cũng」: 何度訪れてもあきない (dù đến bao nhiêu lần cũng không chán)."},{"t":"~だけでなく","note":"「không chỉ ~ (mà còn)」: 観光地だけでなく、小さな店も (không chỉ địa điểm du lịch mà cả những cửa hàng nhỏ)."}]},"a-n2-1":{"title":"Sự thay đổi trong cách làm việc","topic":"Xã hội","trans":["Những năm gần đây, cùng với sự phát triển của internet, cách làm việc đã thay đổi rất nhiều.","Ngày càng có nhiều doanh nghiệp áp dụng 「テレワーク」 (làm việc từ xa), tức là không đến công ty mà làm việc ở nhà. Thời gian đi lại giảm đi, nhưng mặt khác cũng có vấn đề là khó phân biệt giữa công việc và cuộc sống.","Ngoài ra, cũng có nhiều người không làm theo giờ cố định mà tự điều chỉnh thời gian để làm việc.","Theo kịp những thay đổi này, chúng ta cũng cần suy nghĩ về những cách làm việc mới.","Cùng với sự phổ biến của làm việc từ xa, mức độ tự do về địa điểm và thời gian làm việc đã tăng lên; mặt khác, cũng nảy sinh vấn đề là ranh giới giữa công việc và cuộc sống trở nên mờ nhạt.","Từ nay về sau, xã hội cần một môi trường nơi mỗi người có thể chọn cách làm việc phù hợp với mình."],"vocab":["phát triển","áp dụng, đưa vào","phân biệt, sự khác biệt","điều chỉnh","cần thiết"],"grammar":[{"t":"~にともなって","note":"「cùng với ~」, diễn tả sự thay đổi diễn ra song song: 発達にともなって."},{"t":"一方で","note":"「mặt khác」, đối chiếu hai mặt trái ngược nhau."},{"t":"~ていく","note":"「tiếp tục ~ về sau」, diễn tả sự tiếp diễn: 考えていく必要がある."}]},"a-n2-2":{"title":"Chuyện 「空気を読む」","topic":"Văn hóa","trans":["Tiếng Nhật có cách nói 「空気を読む」 (đọc bầu không khí). Nó chỉ việc nhận ra không khí của hoàn cảnh và cảm xúc của đối phương, rồi hành động phù hợp dù không ai nói thẳng ra.","Chẳng hạn, trong cuộc họp khi mọi người đều tán thành, chỉ một người đưa ra ý kiến phản đối thì cần có dũng khí. Nhiều người sẽ 「空気を読んで」, cố ý không phát biểu.","Cảm nhận này từ lâu đã có ích trong việc tránh xung đột giữa người với người và giữ gìn sự hòa hợp của tập thể. Nhưng mặt khác, cũng có vấn đề là những ý kiến thực sự cần thiết lại không nói ra được, còn tiếng nói của thiểu số thì bị dập tắt.","Khả năng đọc bầu không khí quả thật là một nét đặc trưng của xã hội Nhật Bản. Nhưng đôi khi, dũng khí lên tiếng mà không đọc bầu không khí chẳng phải cũng nên được coi trọng sao?","Đọc bầu không khí có thể là sự dịu dàng, biết quan tâm đến người khác, nhưng nếu đi quá xa thì bạn sẽ không nói được ý kiến của chính mình.","Điều quan trọng có lẽ là sự cân bằng giữa việc hòa theo xung quanh và việc truyền đạt suy nghĩ của bản thân."],"vocab":["bầu không khí","nhận ra, thấu hiểu","xung đột","hòa hợp, hài hòa","đặc trưng"],"grammar":[{"t":"~うえで","note":"「trong việc ~, về mặt ~」: 調和を保つうえで役立つ."},{"t":"その反面","note":"「mặt khác, ngược lại」: 役立つ。その反面、問題もある."},{"t":"~べきではないだろうか","note":"「chẳng phải nên ~ sao?」, cách nêu quan điểm một cách nhẹ nhàng: 大切にされるべきではないか."}]},"a-n2-3":{"title":"Báo cáo・Liên lạc・Trao đổi","topic":"Công sở","trans":["Khi vào làm ở công ty Nhật, việc đầu tiên bạn được dạy là tầm quan trọng của「報連相」. Đây là từ ghép từ chữ cái đầu của \"báo cáo・liên lạc・trao đổi\".","Bạn \"báo cáo\" tiến độ công việc cho cấp trên, \"liên lạc\" các thông tin cần thiết cho những người liên quan, và khi phân vân trong việc quyết định thì \"trao đổi\" càng sớm càng tốt. Làm được những điều này hay không sẽ khiến công việc trôi chảy khác hẳn.","Nếu bạn ôm vấn đề một mình và báo cáo chậm trễ, một sai sót nhỏ có thể trở thành rắc rối lớn. Ngược lại, nếu chia sẻ thông tin thường xuyên, mọi người xung quanh sẽ có thể giúp đỡ kịp thời.","報連相 không chỉ đơn thuần là quy tắc. Khi làm việc nhóm, đó là cách giao tiếp cơ bản để xây dựng lòng tin lẫn nhau.","Ở nơi làm việc mà 報連相 không suôn sẻ, những sai sót nhỏ dễ trở thành vấn đề lớn.","Ngược lại, việc chia sẻ thông tin thường xuyên sẽ giúp nâng cao sự tin tưởng và hiệu suất của cả nhóm."],"vocab":["tình hình, tình trạng","phân vân, do dự","ôm một mình, tự gánh vác","sự tin tưởng","xây dựng, tạo dựng"],"grammar":[{"t":"~かどうか","note":"\"Có ~ hay không\", câu hỏi gián tiếp: できるかどうかで変わる."},{"t":"~かねない","note":"\"Có thể sẽ ~ (điều xấu)\": トラブルに発展しかねない."},{"t":"~うえで","note":"\"Trong việc ~, khi ~\": チームで働くうえで."}]},"a-n2-4":{"title":"Suy nghĩ về \"ô nhiễm du lịch\"","topic":"Du lịch","trans":["Những năm gần đây, các điểm du lịch nổi tiếng đón rất đông du khách trong và ngoài nước đổ về. Du lịch mang lại lợi ích lớn cho địa phương, nhưng mặt khác cũng làm nảy sinh vấn đề gọi là \"ô nhiễm du lịch\".","Chẳng hạn, đường phố chật kín khách du lịch khiến người dân không đi lại được, rác thải và các hành vi thiếu ý thức cũng tăng lên. Cuộc sống yên bình của người dân đang bị đe dọa.","Trước những vấn đề này, một số địa phương đã giới hạn số người vào cửa hoặc áp dụng thuế du lịch. Tuy nhiên, nếu siết quy định quá mức, chính sức hấp dẫn của du lịch có thể bị mất đi.","Điều quan trọng có lẽ là người đến thăm đừng quên lòng kính trọng đối với địa phương. Chỉ khi tôn trọng văn hóa và quy tắc của vùng đất ấy thì du lịch mới trở nên phong phú cho cả du khách lẫn người dân, đúng không?","Du lịch mang tiền đến cho địa phương, nhưng mặt khác cũng có thể đe dọa cuộc sống của người dân.","Hiện nay, điều cần thiết là xây dựng một cơ chế để cả người đến thăm lẫn người sinh sống đều cảm thấy thoải mái."],"vocab":["đổ về, ùa đến","lợi ích","đe dọa","hạn chế, giới hạn","tôn trọng"],"grammar":[{"t":"~に対して","note":"\"Đối với ~, trước ~\": 問題に対して."},{"t":"~かねない","note":"\"Có thể sẽ ~ (điều xấu)\": 失われかねない."},{"t":"~てこそ","note":"\"Chính nhờ ~ mới ~\": 尊重してこそ豊かになる."}]},"a-n5-3":{"title":"Bức ảnh gia đình","topic":"Gia đình","trans":["Đây là bức ảnh gia đình của tôi. Tất cả có năm người.","Người đứng ở giữa là bố và mẹ. Bố là nhân viên công ty, còn mẹ là giáo viên.","Người bên phải là anh trai. Anh là sinh viên đại học và chơi bóng đá rất giỏi.","Cô bé nhỏ bên trái là em gái. Em chín tuổi và thích vẽ tranh.","Cả nhà tôi ai cũng rất thích chó. Chú chó đứng phía trước trong ảnh là chó của nhà tôi, tên là「マロ」.","Vào những ngày nghỉ, cả nhà thường cùng nhau đi công viên chụp ảnh.","Dù sống xa nhau nhưng mỗi tháng chúng tôi đều gọi điện nói chuyện một lần. Gia đình là báu vật của tôi."],"vocab":["gia đình","nhân viên công ty","sinh viên đại học","thích","báu vật"],"grammar":[{"t":"〜で (liệt kê/nối câu)","note":"Danh từ + で có thể nối hai câu với nhau: 「ちちは会社員で、ははは先生です」 dùng để nêu thông tin song song."},{"t":"〜が (đối tượng)","note":"Đối tượng của năng lực hoặc sở thích, ghét dùng が: 「サッカーが上手」「犬が好き」."},{"t":"〜のが","note":"Động từ + のが biến hành động thành danh từ: 「絵をかくのが好き」 (thích vẽ tranh)."}]},"a-n5-4":{"title":"Mua sắm ở cửa hàng tiện lợi","topic":"Đời sống","trans":["Ngày nào tôi cũng đến cửa hàng tiện lợi. Vì nó ở ngay cạnh công ty nên rất tiện.","Buổi sáng tôi mua cơm nắm và cà phê. Tổng cộng khoảng ba trăm yên.","Ở cửa hàng tiện lợi, bạn còn có thể thanh toán tiền điện và tiền nước.","Bạn cũng có thể gửi bưu kiện, rút tiền, v.v.","Buổi tối khi đói bụng, tôi mua oden nóng. Vào mùa đông, món này đặc biệt được ưa chuộng.","Gần đây có nhiều biển hướng dẫn bằng tiếng nước ngoài hơn, nên cũng thân thiện với người đến từ nước ngoài.","Tuy là một cửa hàng nhỏ nhưng làm được rất nhiều việc, là thứ không thể thiếu trong cuộc sống ở Nhật Bản."],"vocab":["tiện lợi","thanh toán, trả (tiền)","gửi đi, đưa ra","được ưa chuộng","cuộc sống, sinh hoạt"],"grammar":[{"t":"〜ことができる","note":"Động từ thể từ điển + ことができる diễn tả khả năng/có thể làm gì: 「はらうことができる」."},{"t":"〜たり〜たりする","note":"Liệt kê vài hành động tiêu biểu: 「出したり、おろしたりする」 (nào là gửi, nào là rút tiền…)."},{"t":"〜ので","note":"ので nêu lý do một cách khách quan: 「となりにあるので、べんりです」 (vì ở ngay bên cạnh nên tiện)."}]},"a-n1-1":{"title":"Nóng lên toàn cầu và cuộc sống của chúng ta","topic":"Môi trường","trans":["Trái đất nóng lên không còn là chuyện của tương lai xa xôi nữa, mà đã trở thành vấn đề ảnh hưởng trực tiếp đến cuộc sống của chúng ta.","Thiệt hại cho nông sản do thời tiết bất thường, cùng những thiệt hại đi kèm với mực nước biển dâng cao, ngày càng nghiêm trọng theo từng năm. Trước tình hình này, bạn có thể cảm thấy mỗi người chỉ làm được rất ít.","Tuy nhiên, chính những việc nhỏ được tích lũy như giảm lãng phí điện, đi phương tiện giao thông công cộng... mới là chìa khóa dẫn đến thay đổi lớn.","Để để lại một Trái Đất trù phú cho thế hệ tương lai, ngay bây giờ chúng ta cần bắt tay vào hành động.","Nóng lên toàn cầu không phải chuyện của một đất nước xa xôi nào đó, mà là vấn đề liên quan trực tiếp đến bữa cơm và cuộc sống hằng ngày của chúng ta.","Chúng ta không được quên rằng những hành động nhỏ của từng người cộng dồn lại rồi sẽ tạo nên thay đổi lớn."],"vocab":["gây ra (ảnh hưởng), tác động đến","thiệt hại, tai họa","nghiêm trọng","sự tích lũy, sự cộng dồn","thế hệ"],"grammar":[{"t":"~ばかりだ","note":"「Cứ ngày càng~」: thay đổi theo một chiều: 深刻さを増すばかりだ."},{"t":"~こそ","note":"「Chính ~ mới」: nhấn mạnh: 積み重ねこそが変化につながる."},{"t":"~ためにも","note":"「Cũng là để ~」: 世代に残すためにも行動を."}]},"a-n1-2":{"title":"Ý nghĩa của việc「học」trong thời đại AI","topic":"Tin tức","trans":["Nhờ sự phổ biến nhanh chóng của AI tạo sinh, rào cản để tiếp cận kiến thức đã thấp hơn bao giờ hết. Có thắc mắc, chỉ cần hỏi là AI đưa ra câu trả lời ngay lập tức.","Trong bối cảnh đó, người ta bắt đầu nghe thấy những ý kiến như「con người liệu có còn cần nỗ lực học nữa không?」. Tuy nhiên, điều đó dường như là hiểu sai bản chất của việc học.","Học không chỉ đơn thuần là có được câu trả lời. Đó là phân biệt thông tin đúng sai, so sánh nhiều quan điểm, rồi tự đưa ra phán đoán của mình — chính trong quá trình ấy, khả năng tư duy mới được nuôi dưỡng. Có thể xem xét câu trả lời của AI một cách có phản biện hay không phụ thuộc chính vào chiều sâu việc học của mỗi người.","Chính vì là thời đại mà câu trả lời dễ dàng có được, thái độ liên tục đặt câu hỏi「tại sao lại như vậy」càng trở nên quan trọng hơn bao giờ hết. Ý nghĩa của việc học không những không mất đi, mà ngược lại còn đang được đặt ra để suy nghĩ lại.","Chính vì đang sống trong thời đại có AI đưa ra câu trả lời ngay lập tức, thái độ liên tục đặt câu hỏi「tại sao lại như vậy」càng trở nên quan trọng.","So với việc tích trữ kiến thức, việc sử dụng và phán đoán nó như thế nào sẽ trở thành cốt lõi của việc học trong thời gian tới."],"vocab":["phổ biến","bản chất","nhìn rõ, phân biệt","xem xét kỹ lưỡng","đặt câu hỏi lại, suy xét lại"],"grammar":[{"t":"~により","note":"「Do ~, nhờ ~」: 普及により、低くなった."},{"t":"~どころか","note":"「Đừng nói là ~, không những ~ mà ngược lại」: 失われるどころか、問い直されている."},{"t":"~からこそ","note":"「Chính vì ~ nên」: 時代だからこそ、重要になっている."}]},"a-n4-5":{"title":"Một ngày đi làm thêm","topic":"Công việc","trans":["Tôi vừa học đại học vừa làm thêm ở quán cà phê. Mỗi tuần ba buổi, ca từ chiều đến tối.","Đến quán, trước tiên tôi thay đồng phục và rửa tay thật sạch.","Công việc gồm có ghi order, pha cà phê, dọn bàn và những việc tương tự.","Giờ cao điểm rất vất vả, nhưng mỗi khi khách nói một tiếng「ありがとう」là mệt mỏi bay biến hết.","Hồi mới đầu tôi toàn mắc lỗi và hay bị các anh chị đi trước nhắc nhở. Nhưng dần dần, những việc tôi làm được đã nhiều lên.","Nhờ làm thêm, tôi không chỉ có tiền mà còn học được cách nói chuyện với mọi người và tầm quan trọng của tinh thần làm việc nhóm.","Cân bằng giữa việc học và việc làm không hề dễ, nhưng tôi nghĩ đây là trải nghiệm quý giá trước khi bước vào xã hội."],"vocab":["đi lại, theo học / đi làm (đều đặn)","thay quần áo","dọn dẹp, thu dọn","tiền bối, người đi trước (đàn anh, đàn chị)","kinh nghiệm, trải nghiệm"],"grammar":[{"t":"〜ながら","note":"Động từ thể ます (bỏ ます) + ながら diễn tả làm hai việc cùng lúc: 「通いながら働く」(vừa đi học vừa đi làm)."},{"t":"〜ばかり","note":"「失敗ばかり」nghĩa là toàn là, suốt ngày chỉ toàn (lỗi)."},{"t":"〜おかげで","note":"「アルバイトのおかげで」diễn tả nguyên nhân tốt, nghĩa là nhờ vào, nhờ có."}]},"a-n3-6":{"title":"Bốn mùa và các lễ hội trong năm của Nhật Bản","topic":"Văn hóa","trans":["Nhật Bản có bốn mùa xuân, hạ, thu, đông, và những lễ hội phù hợp với từng mùa vẫn được trân trọng cho đến ngày nay.","Mùa xuân là mùa hoa anh đào. Mọi người tụ tập ở công viên, vừa ăn uống dưới tán hoa vừa chào đón xuân về.","Đến mùa hè, khắp nơi tổ chức lễ hội và đại hội pháo hoa, rất náo nhiệt với những người mặc yukata.","Mùa thu còn được gọi là「食欲の秋」「読書の秋」, nhiều người thích ngắm lá đỏ trong không khí đã se lạnh.","Mùa đông có dịp Tết. Việc cả gia đình quây quần ăn món osechi và đi lễ đền đầu năm (初詣) là điều rất phổ biến.","Những lễ hội này trở thành cơ hội để cảm nhận sự thay đổi của các mùa và củng cố sự gắn kết với gia đình, cộng đồng địa phương.","Dù trong cuộc sống tiện nghi, chắc hẳn tấm lòng trân trọng nhịp điệu của thiên nhiên vẫn sẽ tiếp tục được truyền lại về sau."],"vocab":["mùa","sự kiện, lễ hội","chúc mừng, ăn mừng","phổ biến, thông thường","kế thừa, truyền lại"],"grammar":[{"t":"〜に合わせて","note":"「季節に合わせた行事」diễn tả sự phù hợp, tùy theo, cho phù hợp với một điều gì đó."},{"t":"〜と言われる","note":"「食欲の秋と言われる」nghĩa là người ta thường nói, được gọi là."},{"t":"〜だろう","note":"「受けつがれていくだろう」diễn tả sự phỏng đoán, nghĩa là có lẽ, chắc là."}]},"a-n4-6":{"title":"Lễ hội mùa hè","topic":"Văn hóa","trans":["Vào mùa hè ở Nhật Bản, lễ hội mùa hè được tổ chức ở khắp nơi. Khi trời tối, rất nhiều người mặc yukata và tụ tập về đền thần đạo hoặc chùa.","Ở khu vực lễ hội có rất nhiều gian hàng bày bán dọc hai bên. Mọi người ăn takoyaki, ăn đá bào, chơi vớt cá vàng, trông ai cũng vui vẻ.","Cuối đêm, pháo hoa lớn được bắn lên. Sau tiếng nổ \"đùng\" thật to, khi ánh sáng bung tỏa trên bầu trời đêm, mọi người đều thốt lên \"wow\".","Lễ hội mùa hè là một sự kiện trở thành kỷ niệm đáng nhớ của mùa hè Nhật Bản. Nếu có cơ hội, bạn nhất định hãy mặc yukata đi thử nhé."],"vocab":["lễ hội mùa hè","tổ chức, mở","yukata (kimono mùa hè)","đền thần đạo","gian hàng, quầy hàng rong","xếp thành hàng, bày dọc","vớt cá vàng","pháo hoa","bầu trời đêm","sự kiện, nghi lễ truyền thống","cơ hội"],"grammar":[{"t":"〜たり〜たりする","note":"Liệt kê vài hành động: 食べたり、すくいをしたり (nào là ăn, nào là vớt cá vàng…)."},{"t":"〜と(kết quả tự nhiên)","note":"「光が広がると」: hễ ~ thì ~, diễn tả kết quả xảy ra một cách tự nhiên."},{"t":"〜てみてください","note":"「行ってみてください」: hãy thử làm ~ xem."}]},"a-n3-7":{"title":"Cẩn thận với sốc nhiệt","topic":"Đời sống","trans":["Những năm gần đây, mùa hè ở Nhật Bản ngày càng nóng hơn. Đặc biệt từ tháng 7 đến tháng 8, những ngày nhiệt độ vượt quá 35 độ cũng không còn hiếm.","Trong cái nóng như vậy, điều cần chú ý chính là sốc nhiệt (say nóng). Khi cơ thể thiếu nước, sẽ bị chóng mặt, đau đầu, nghiêm trọng thì thậm chí có thể nguy hiểm đến tính mạng.","Để phòng tránh sốc nhiệt, quan trọng là uống nước thường xuyên, trước khi bị khát. Tránh ra ngoài vào khung giờ nóng, dùng điều hòa hợp lý cũng là cách tốt.","Không ít trường hợp cơ thể trở nên mệt mỏi ngay khi đang nghĩ \"mình vẫn ổn\". Hãy nhắc nhở lẫn nhau với những người xung quanh để cùng vượt qua mùa hè nóng bức thật khỏe mạnh nhé."],"vocab":["những năm gần đây","sốc nhiệt, say nóng","nhiệt độ không khí","vượt quá","nước (lượng nước trong cơ thể)","đau đầu","sinh mạng","liên quan đến, ảnh hưởng đến","phòng tránh","khung giờ","ra ngoài","tình trạng sức khỏe","vượt qua"],"grammar":[{"t":"〜から〜にかけて","note":"「七月から八月にかけて」: diễn tả khoảng thời gian đại khái, từ ~ đến ~."},{"t":"〜うちに","note":"「思っているうちに」: trong lúc trạng thái ~ còn tiếp diễn (chẳng mấy chốc đã ~)."},{"t":"〜なければならない","note":"「気をつけなければならない」: diễn tả nghĩa vụ, phải làm."}]},"a-n2-5":{"title":"Thanh toán không tiền mặt đang lan rộng","topic":"Xã hội","trans":["Vài năm gần đây, thanh toán không tiền mặt cũng đang lan rộng nhanh chóng ở Nhật Bản. Trước đây có nhiều cửa hàng chỉ nhận tiền mặt, nhưng giờ ngày càng có nhiều cửa hàng cho phép thanh toán bằng điện thoại thông minh hoặc thẻ.","Thanh toán không tiền mặt có ưu điểm là trả tiền nhanh và dễ quản lý tiền bạc. Bạn không cần phải lục tìm tiền lẻ ở quầy thu ngân, và mỗi lần bạn tiêu tiền lúc nào, bao nhiêu đều được lưu lại thành bản ghi.","Mặt khác, vẫn còn những vấn đề cần giải quyết. Khi mất điện hoặc sự cố đường truyền xảy ra, có nguy cơ không thể thanh toán được. Ngoài ra, cũng không thể thiếu sự quan tâm dành cho những người tiêu xài quá tay và những người cao tuổi không quen thao tác với máy móc.","Làm thế nào để cân bằng giữa tiện lợi và an tâm? Xã hội cần có là một xã hội mà tiền mặt và thanh toán không tiền mặt có thể cùng tồn tại một cách hài hòa."],"vocab":["thanh toán, quyết toán","một cách nhanh chóng","tiền mặt","thanh toán, trả tiền","ưu điểm","tiền lẻ","bản ghi, ghi chép","vấn đề cần giải quyết","mất điện","sự cố đường truyền","nguy cơ, lo ngại","sự quan tâm, chu đáo","cùng tồn tại","đòi hỏi, mong muốn"],"grammar":[{"t":"〜てくる (sự thay đổi)","note":"「広がってきた」diễn tả sự thay đổi, xu hướng diễn ra cho đến hiện tại."},{"t":"〜恐れがある","note":"「できなくなる恐れがある」diễn tả khả năng xảy ra điều không tốt, nghĩa là \"có nguy cơ…\"."},{"t":"一方(で)","note":"「一方で、課題も残されている」dùng để đưa ra mặt đối lập, nghĩa là \"mặt khác…\"."}]},"a-n1-3":{"title":"Thách thức lớn mang tên già hóa dân số và giảm sinh","topic":"Xã hội","trans":["Nhật Bản đang già hóa dân số và giảm sinh với tốc độ chưa từng thấy trên thế giới. Tỷ lệ người cao tuổi trong tổng dân số tăng lên qua từng năm, trong khi đó số trẻ em được sinh ra vẫn liên tục giảm.","Ảnh hưởng mà xu hướng này mang lại có thể làm lung lay nền tảng của hệ thống an sinh xã hội. Bởi vì chi phí cho lương hưu, y tế và chăm sóc điều dưỡng ngày càng tăng, trong khi thế hệ đang đi làm gánh vác những khoản đó lại ngày càng giảm.","Về đối sách, người ta đang thảo luận những việc như hoàn thiện chế độ hỗ trợ cân bằng giữa nuôi dạy con và công việc, hay mở rộng tiếp nhận lao động nước ngoài. Tuy nhiên, không vấn đề nào trong số đó có thể giải quyết ngày một ngày hai.","Đằng sau việc tỷ lệ sinh giảm là nhiều yếu tố phức tạp đan xen, như nỗi bất an về kinh tế và sự đa dạng hóa các giá trị sống. Đây không phải là chuyện chỉ cần phát trợ cấp là xong.","Già hóa dân số và giảm sinh giờ đây đã là một thực tế không thể né tránh. Toàn xã hội sẽ đối mặt với nó thế nào, và sẽ để lại cho thế hệ sau một đất nước như thế nào? Chính lúc này, rất cần một cuộc thảo luận nghiêm túc."],"vocab":["tỷ lệ, tỉ trọng","khuynh hướng, xu hướng","nền tảng, cốt lõi","chăm sóc điều dưỡng","kết hợp, cân bằng hai việc","ngày một ngày hai, trong thời gian ngắn","tỷ lệ sinh","yếu tố, nhân tố"],"grammar":[{"t":"~かねない","note":"「có thể sẽ ~ (kết quả xấu)」: 根幹を揺るがしかねない = có thể làm lung lay nền tảng."},{"t":"~一方で","note":"Đối chiếu hai mặt: 費用は増える一方で、現役世代は減る = chi phí thì tăng, trong khi thế hệ đang đi làm lại giảm."},{"t":"~ではないのだ","note":"Nhấn mạnh phủ định, đưa ra kết luận: 済むという話ではないのだ = không phải chuyện cứ thế là xong."}]},"a-n1-6":{"title":"Những điều được truyền lại","topic":"Văn hóa","trans":["Văn hóa truyền thống và kỹ nghệ của các nghệ nhân lưu truyền khắp nơi là tài sản vô giá, được mài giũa và kế thừa qua một thời gian dài. Thế nhưng hiện nay, rất nhiều trong số đó đang đứng trước nguy cơ mai một.","Nguyên nhân lớn nhất là thiếu người kế nghiệp. Trong khi những người nắm giữ nghề ngày càng cao tuổi, giới trẻ lại đổ về thành phố, và số người muốn học nghề giảm dần theo từng năm.","Nói là gìn giữ truyền thống, nhưng không có nghĩa là chỉ cần giữ nguyên như xưa là đủ. Chỉ khi biết sáng tạo ra những giá trị mới phù hợp với sự thay đổi của thời đại thì văn hóa mới có thể tiếp tục sống.","Những năm gần đây, các thử nghiệm như đưa thiết kế hiện đại vào thủ công mỹ nghệ truyền thống hay quảng bá ra nước ngoài đang dần lan rộng. Sự kết hợp giữa cái cũ và cái mới chính là chìa khóa mở ra lối thoát.","Làm thế nào để nối tiếp những gì người đi trước đã xây dựng sang thế hệ sau? Có lẽ đó là một bài tập nặng nề được giao cho mỗi người chúng ta."],"vocab":["nghệ nhân, thợ thủ công lành nghề","sự tồn tại, sự duy trì","đứng trước (nguy cơ), bên bờ vực","người kế nghiệp, người nối nghiệp","người đảm nhận, lực lượng nòng cốt","sự hòa quyện, sự kết hợp","lối thoát, hướng đi","người đi trước, tiền nhân"],"grammar":[{"t":"~てこそ","note":"Nghĩa là \"chỉ khi ~ thì mới\": 新しい価値を生み出してこそ生き続けられる。"},{"t":"~わけではない","note":"Phủ định một phần, nghĩa là \"không có nghĩa là ~\": 昔のままを保てばよいというわけではない。"},{"t":"~つつある","note":"Nghĩa là \"đang dần dần ~\": 試みも広がりつつある。"}]},"a-n2-6":{"title":"Hãy coi trọng giấc ngủ","topic":"Sức khỏe","trans":["Trong những ngày bận rộn, thứ mà ta dễ vô tình cắt bớt nhất chính là thời gian ngủ. Tuy nhiên, giấc ngủ chất lượng là điều không thể thiếu để có một cuộc sống khỏe mạnh.","Nếu ngủ không đủ, khả năng tập trung sẽ giảm và sức khỏe cũng dễ bị ảnh hưởng. Chắc hẳn cũng có nhiều người vì buồn ngủ ban ngày mà công việc hay việc học không suôn sẻ.","Để ngủ ngon, trước hết điều quan trọng là điều chỉnh nhịp sinh hoạt. Hãy tạo thói quen đi ngủ và thức dậy vào cùng một giờ mỗi ngày.","Ngoài ra, trước khi ngủ bạn nên tránh xem điện thoại thông minh càng nhiều càng tốt. Vì ánh sáng chói của màn hình sẽ khiến não bộ tỉnh táo trở lại.","Dù chỉ chênh nhau vài tiếng, nhưng sự tích lũy mỗi ngày sẽ tạo nên khác biệt lớn. Bạn thử bắt đầu bằng việc đi ngủ sớm hơn một chút nhé?"],"vocab":["cắt giảm, hy sinh","giấc ngủ","không thể thiếu","khả năng tập trung","cơn buồn ngủ","điều chỉnh, sắp xếp cho ổn định","tránh","sự tích lũy"],"grammar":[{"t":"~がち","note":"Nghĩa là \"dễ, hay ~\": つい削ってしまいがち。"},{"t":"~うえで","note":"Nghĩa là \"trong việc ~, để ~\": 健康な生活を送るうえで欠かせない。"},{"t":"~たほうがよい","note":"Dùng để khuyên: スマホを見るのは避けたほうがよい。"}]},"a-n1-4":{"title":"Để bơi giữa biển thông tin","topic":"Truyền thông","trans":["Nhờ sự phổ biến của điện thoại thông minh, chúng ta có thể tiếp cận lượng thông tin khổng lồ mọi lúc, mọi nơi. Nhưng đằng sau sự tiện lợi ấy là những cái bẫy ẩn giấu mà ta không thể bỏ qua.","Trên internet tràn ngập những thông tin không rõ thật giả. Trong đó, không ít tin giả bị lan truyền với ác ý. Khả năng phân biệt sự thật và ý kiến chưa bao giờ cần thiết đến thế.","Rắc rối hơn nữa là cơ chế chỉ hiển thị những thông tin hợp sở thích của bản thân. Bất giác, tầm nhìn của bạn bị thu hẹp và dễ rơi vào những suy nghĩ lệch lạc.","Điều quan trọng là thái độ không tin ngay một thông tin duy nhất, mà tham khảo nhiều nguồn để kiểm chứng. Khi đăng tải thông tin, bạn cũng phải chịu trách nhiệm về nội dung đó.","Năng lực đọc hiểu thông tin một cách đúng đắn giờ đây không còn là của riêng một số ít chuyên gia. Đó là kiến thức nền tảng thiết yếu mà ai cũng nên trang bị để sống vững trong thời hiện đại."],"vocab":["phổ biến, lan rộng","khổng lồ","thật giả","lan truyền, phát tán","phiền phức, rắc rối","tầm nhìn, tầm mắt","tin sái cổ, nuốt trọn không suy xét","kiến thức nền tảng, học vấn, vốn hiểu biết"],"grammar":[{"t":"~ないうちに (và 「知らず知らずのうちに」)","note":"「知らず知らずのうちに」 = bất giác, lúc nào không hay."},{"t":"~ばかり","note":"Chỉ toàn, thiên về một thứ: 好みに合う情報ばかりが表示される (chỉ toàn thông tin hợp sở thích được hiển thị)."},{"t":"もはや~ない","note":"「Không còn ~ nữa」: もはや専門家だけのものではない (giờ đây không còn chỉ của riêng chuyên gia)."}]},"a-n1-5":{"title":"Thức ăn bị vứt bỏ","topic":"Xã hội","trans":["Thực phẩm vẫn còn ăn được nhưng bị vứt đi, tức là cái gọi là lãng phí thực phẩm, đã trở thành vấn đề toàn cầu. Nghe nói ở Nhật mỗi năm cũng có tới hàng triệu tấn thực phẩm bị bỏ phí một cách vô ích.","Trong khi đó, trên thế giới có rất nhiều người không có đủ bữa ăn. Đằng sau cảnh ăn uống dư dả tưởng như biểu tượng của sự giàu có là một sự mất cân bằng nghiêm trọng.","Nguyên nhân của lãng phí thực phẩm không chỉ là đồ ăn thừa từ gia đình và nhà hàng. Hiện trạng những sản phẩm lẽ ra vẫn bán được nhưng bị xử lý hàng loạt vì lý do hạn sử dụng cũng không thể làm ngơ.","Để giải quyết vấn đề này, nỗ lực của doanh nghiệp là điều đương nhiên, nhưng sự thay đổi trong ý thức của mỗi người cũng không thể thiếu. Những thói quen như không mua quá nhiều, không nấu quá nhiều sẽ là một bước tiến lớn.","Trân trọng nguồn tài nguyên có hạn cũng là trách nhiệm đối với thế hệ sau. Lối sống không lãng phí thức ăn đang được đặt ra để suy ngẫm lại một lần nữa."],"vocab":["loại bỏ, vứt bỏ","rất nhiều người","ăn uống no đủ, dư dả","mất cân bằng","hạn sử dụng (hạn dùng ngon nhất)","xử lý, thanh lý","không thể thiếu","tài nguyên"],"grammar":[{"t":"~のに","note":"Diễn tả sự trái ngược: まだ食べられるのに捨てられる (vẫn ăn được mà lại bị vứt)."},{"t":"~はもちろん","note":"「~là đương nhiên, chưa kể đến」: 企業の取り組みはもちろん (nỗ lực của doanh nghiệp thì khỏi phải nói)."},{"t":"~見逃せない","note":"「Không thể bỏ qua, không thể làm ngơ」: 現状も見逃せない (hiện trạng cũng không thể làm ngơ)."}]},"a-n2-7":{"title":"Phòng bệnh hơn chữa bệnh","topic":"Đời sống","trans":["Nhật Bản là đất nước có nhiều thiên tai như động đất và bão. Với những thảm họa không biết khi nào sẽ xảy ra, việc chuẩn bị sẵn từ ngày thường là vô cùng quan trọng.","Trước hết, hãy bắt đầu từ những việc có thể làm ngay tại nhà. Chuẩn bị nước, thực phẩm, đèn pin... rồi để ở nơi có thể mang đi ngay thì sẽ yên tâm hơn.","Cũng đừng quên bàn bạc trước với gia đình. Nếu chẳng may bị lạc nhau, chỉ cần quyết định sẵn sẽ tập trung ở đâu thì bạn có thể hành động mà không hoảng loạn.","Ngoài ra, biết trước những nơi nguy hiểm trong khu vực mình sống cũng rất hữu ích. Hãy xem bản đồ do tòa thị chính và các cơ quan khác phát, rồi kiểm tra sẵn đường đến nơi lánh nạn nhé.","Dù không thể ngăn chặn thiên tai, bạn vẫn có thể giảm thiệt hại. Sự chú ý nhỏ bé hằng ngày sẽ bảo vệ bạn và gia đình vào lúc nguy cấp."],"vocab":[{"w":"災害","m":"thiên tai, thảm họa"},{"w":"備えて","m":"phòng bị, chuẩn bị"},{"w":"懐中電灯","m":"đèn pin"},{"w":"持ち出せる","m":"có thể mang ra, có thể mang đi"},{"w":"避難所","m":"nơi lánh nạn"},{"w":"被害","m":"thiệt hại"},{"w":"心がけ","m":"sự chú ý, sự lưu tâm"},{"w":"守る","m":"bảo vệ, giữ gìn"}],"grammar":[{"t":"~ておく","note":"Làm sẵn, làm trước: 備えておく (chuẩn bị sẵn), 決めておく (quyết định trước)."},{"t":"~てはいけない","note":"Cấm đoán/không được: 話し合っておくことも忘れてはいけない (cũng không được quên bàn bạc trước)."},{"t":"いざというとき","note":"Cụm quen dùng, nghĩa là \"lúc nguy cấp, khi có chuyện xảy ra\": いざというときに守る (bảo vệ vào lúc nguy cấp)."}]},"a-n5-6":{"title":"Sở thích của tôi","topic":"Sở thích","trans":["Sở thích của tôi là chụp ảnh.","Vào ngày nghỉ, tôi mang theo máy ảnh và đi dạo quanh phố.","Tôi chụp ảnh hoa và chim.","Khi chụp được một bức ảnh đẹp, tôi rất vui.","Thỉnh thoảng tôi gửi ảnh cho bạn bè.","Bạn bè nói: 「じょうずですね」 (Chụp giỏi quá nhỉ).","Tôi muốn có một chiếc máy ảnh mới, nhưng vì đắt nên bây giờ tôi đang tiết kiệm tiền."],"vocab":[{"w":"趣味","m":"sở thích"},{"w":"写真","m":"ảnh, bức ảnh"},{"w":"撮る","m":"chụp (ảnh)"},{"w":"歩く","m":"đi bộ"},{"w":"送る","m":"gửi"},{"w":"貯める","m":"tiết kiệm, dành dụm (tiền)"}],"grammar":[{"t":"しゅみは~ことです","note":"\"Sở thích của tôi là ~\": dùng こと để danh từ hóa động từ ở cuối câu. しゅみは しゃしんを とる ことです。"},{"t":"~とき","note":"\"Khi ~, lúc ~\": とれた とき (khi chụp được)."},{"t":"~が ほしい","note":"\"Muốn có ~ (đồ vật)\": カメラが ほしいです。Thứ mình muốn có đi với が."}]},"a-n4-7":{"title":"Cách đổ rác","topic":"Cuộc sống","trans":["Sau khi bắt đầu sống ở Nhật, điều làm tôi ngạc nhiên nhất là cách đổ rác.","Rác phải được phân loại thành 「燃えるごみ」(rác cháy được), 「燃えないごみ」(rác không cháy được), 「資源ごみ」(rác tái chế) v.v.","Ngày đổ rác cũng được quy định cố định. Ở thị trấn tôi sống, rác cháy được là thứ Hai và thứ Năm.","Bạn phải mang rác ra đúng địa điểm quy định trước 8 giờ sáng.","Nếu phân loại sai, đôi khi rác sẽ không được thu gom.","Lúc đầu tôi thấy rất phiền phức, nhưng quen rồi thì không khó nữa.","Nhờ việc phân loại rác mà thị trấn lúc nào cũng sạch sẽ."],"vocab":["ngạc nhiên, kinh ngạc","chia ra, phân loại","được quyết định, cố định","nhầm, làm sai","phiền phức","quen (với)","phân loại (rác)"],"grammar":[{"t":"~なければなりません","note":"「Phải ~」: 分けなければなりません (phải phân loại)."},{"t":"~までに","note":"「Trước ~ (hạn chót)」: 朝八時までに出します (đổ trước 8 giờ sáng). までに chỉ thời hạn, còn まで chỉ hành động kéo dài đến mốc đó."},{"t":"~てもらえない","note":"「Không thể nhờ/được người khác làm ~ cho mình」: 持って行ってもらえない (không được thu gom). Là dạng phủ định khả năng của てもらう."},{"t":"~おかげで","note":"「Nhờ có ~」: 分別のおかげで、町はきれいです (nhờ phân loại rác mà thị trấn sạch sẽ). Dùng cho kết quả tốt."}]},"a-n3-8":{"title":"Đi bệnh viện ở Nhật","topic":"Cuộc sống","trans":["Lần đầu tiên bị sốt ở Nhật, tôi không biết phải làm sao nên rất lo lắng.","Tôi hỏi ý kiến bạn bè, bạn bảo: 「Trước hết bạn nên đến khoa nội gần nhà đi.」","Ở bệnh viện, trước tiên bạn xuất trình thẻ bảo hiểm, rồi ghi triệu chứng vào phiếu khám.","Những câu hỏi như 「いつから痛いですか」(Đau từ khi nào?) hay 「アレルギーはありますか」(Bạn có bị dị ứng không?) thì khá là cố định.","Khám xong, bạn nhận đơn thuốc rồi đến hiệu thuốc để lấy thuốc.","Chi phí rẻ hơn tôi tưởng. Vì nếu có tham gia bảo hiểm thì bạn chỉ phải tự trả 30%.","Nếu lo về vấn đề ngôn ngữ, bạn có thể viết triệu chứng ra giấy rồi đưa cho bác sĩ xem. Cách để truyền đạt thì có rất nhiều."],"vocab":["bất an, lo lắng","bàn bạc, tham khảo ý kiến","thẻ bảo hiểm","triệu chứng","khám bệnh","đơn thuốc","hiệu thuốc","nhận, lấy"],"grammar":[{"t":"~たほうがいい","note":"「Nên ~」(lời khuyên): 行ったほうがいい (nên đi)."},{"t":"~と(條件)","note":"「Hễ ~ thì…」: 相談すると、教えてくれた / 診察が終わると. Vế trước xảy ra thì vế sau tự nhiên xảy ra tiếp theo."},{"t":"~より","note":"「Hơn ~, so với ~」: 思ったより安かった (rẻ hơn tôi tưởng)."},{"t":"~といい","note":"「Nên ~ thì tốt, gợi ý ~」: 書いて見せるといい (bạn viết ra rồi cho xem là được)."}]},"a-n5-7":{"title":"Gửi bưu kiện ở bưu điện","topic":"Cuộc sống","trans":["Hôm nay mình đến bưu điện để gửi bưu kiện.","Ở quầy, mình nói「これを 台湾へ おねがいします」(Cho tôi gửi cái này đến Đài Loan).","Nhân viên hỏi mình「船便ですか、航空便ですか」(Bạn gửi đường biển hay đường hàng không?).","Đường biển rẻ nhưng mất khoảng một tháng. Đường hàng không nhanh nhưng đắt.","Mình chọn đường hàng không. Sau khi viết tên và địa chỉ vào phiếu thì mình trả tiền.","Mình hỏi「いつ とどきますか」(Khi nào thì đến?), nhân viên cho biết「一週間ぐらいです」(Khoảng một tuần).","Trên đường về, mình mua tem ở cửa hàng tiện lợi và gửi luôn cả bưu thiếp."],"vocab":["bưu điện","hành lý, bưu kiện","quầy giao dịch","gửi đường biển","gửi đường hàng không","phiếu, mẫu giấy","địa chỉ","tem","đến nơi, được chuyển đến"],"grammar":[{"t":"～てから","note":"Làm xong việc trước rồi mới làm việc sau. 「書いてから はらいます」= viết xong rồi mới trả tiền, thứ tự rất rõ ràng."},{"t":"～と いいます／ききます","note":"Trích dẫn lời đã nói hoặc câu đã hỏi, đặt cả câu trước 「と」: 「これを おねがいします」と いいます。"},{"t":"～に いきます(mục đích)","note":"Động từ thể ます bỏ ます + に いきます = đi để làm việc gì đó. 「おくりに いきます」= đi gửi (đồ)."}]},"a-n3-9":{"title":"Tìm phòng trọ ở Nhật","topic":"Cuộc sống","trans":["Thuê nhà ở Nhật tốn nhiều công sức hơn bạn tưởng.","Đầu tiên, bạn đến công ty môi giới bất động sản và cho họ biết ngân sách tiền thuê cùng khu vực mong muốn. Chỉ cần thêm điều kiện「cách ga trong vòng mười phút đi bộ」là tiền thuê tăng vọt ngay.","Dù tìm được căn phòng ưng ý, bạn cũng không thể quyết định ngay. Vì tiền đặt cọc, tiền lễ, phí môi giới... đều cần một khoản tiền lớn ngay từ đầu.","Với người nước ngoài, thường sẽ bị yêu cầu có người bảo lãnh. Gần đây việc dùng công ty bảo lãnh phổ biến hơn, bạn trả khoảng nửa tháng tiền thuê để ký hợp đồng.","Để vượt qua vòng xét duyệt, tốt nhất bạn nên chuẩn bị sẵn các giấy tờ chứng minh nơi làm việc và thu nhập.","Khi đi xem phòng, bạn không chỉ nên kiểm tra ánh sáng mặt trời và tiếng ồn mà còn nên xem chỗ đặt máy giặt và số lượng ổ điện. Chính những chỗ không thể biết qua ảnh mới là lý do đáng để đến xem tận nơi.","Nghe thì phiền phức, nhưng chỉ cần nắm được quy trình này, lần chuyển nhà tiếp theo sẽ nhẹ nhàng hơn nhiều."],"vocab":[{"w":"不動産屋","m":"công ty môi giới bất động sản"},{"w":"家賃","m":"tiền thuê nhà"},{"w":"敷金","m":"tiền đặt cọc"},{"w":"礼金","m":"tiền lễ (không hoàn lại)"},{"w":"仲介手数料","m":"phí môi giới"},{"w":"保証人","m":"người bảo lãnh"},{"w":"審査","m":"xét duyệt"},{"w":"内見","m":"xem phòng"},{"w":"日当たり","m":"độ đón nắng, ánh sáng mặt trời"},{"w":"手間がかかる","m":"tốn công sức"}],"grammar":[{"t":"～ように(目的)","note":"Chỉ trạng thái muốn đạt được, phía trước thường là thể khả năng hoặc động từ phi ý chí. 「審査に通るように」= để (có thể) vượt qua xét duyệt."},{"t":"～ほうがいい","note":"Lời khuyên. 「そろえておいたほうがいい」= nên chuẩn bị sẵn; nhẹ nhàng hơn mệnh lệnh nhưng vẫn rất rõ ràng."},{"t":"～こそ","note":"Nhấn mạnh \"chính là điều này\". 「わからない部分こそ」= chính những phần không thể biết được (mới là quan trọng)."}]},"a-n2-9":{"title":"Cửa ải gia hạn tư cách lưu trú","topic":"Xã hội","trans":["Với người nước ngoài sống ở Nhật, gia hạn tư cách lưu trú là một cửa ải không thể né tránh.","Bạn có thể nộp đơn từ ba tháng trước khi hết hạn, nhưng việc chuẩn bị giấy tờ mất nhiều thời gian nên hành động sớm chắc chắn không bao giờ thừa.","Ngoài đơn xin, bạn cần giấy chứng nhận thuế thị dân (thuế cư trú), giấy chứng nhận nộp thuế, giấy xác nhận đang đi làm, v.v. Người mới chuyển việc đôi khi còn bị yêu cầu nộp hợp đồng lao động.","Khi xét duyệt, họ sẽ xem thu nhập có ổn định không, thuế và tiền lương hưu có được nộp đầy đủ không.","Nói cách khác, cái giá của việc cứ trì hoãn thủ tục hằng ngày sẽ đến cùng một lúc vào thời điểm này.","Quầy của Cục Quản lý xuất nhập cảnh rất đông nên số người dùng đăng ký trực tuyến cũng ngày càng tăng. Cùng với đó, quy trình thủ tục cũng đang dần thay đổi.","Vài tuần chờ kết quả khiến bạn thấp thỏm, nhưng nếu đã chuẩn bị đủ giấy tờ cần thiết và khai báo trung thực thì không cần quá lo sợ."],"vocab":[{"w":"在留資格","m":"tư cách lưu trú (visa)"},{"w":"更新","m":"gia hạn"},{"w":"関門","m":"cửa ải, thử thách khó khăn"},{"w":"課税証明書","m":"giấy chứng nhận thu nhập chịu thuế"},{"w":"納税証明書","m":"giấy chứng nhận nộp thuế"},{"w":"在職証明書","m":"giấy xác nhận đang làm việc"},{"w":"入管","m":"Cục Quản lý xuất nhập cảnh"},{"w":"申告","m":"khai báo"},{"w":"つけが回る","m":"phải trả giá, bị tính sổ"}],"grammar":[{"t":"～に越したことはない","note":"\"Không gì tốt hơn là...\", chỉ cách làm an toàn nhất. 「早めに動くに越したことはない」= hành động càng sớm càng tốt."},{"t":"～というわけだ","note":"Rút ra kết luận từ vế trước. 「回ってくるというわけだ」= nói cách khác, kết quả sẽ là như vậy."},{"t":"～に伴って／それに伴い","note":"Khi một việc thay đổi thì việc khác cũng thay đổi theo. 「それに伴い、流れも変わりつつある」= cùng với đó, quy trình cũng đang thay đổi."},{"t":"～つつある","note":"Đang dần thay đổi liên tục, mang tính văn viết hơn「ている」. 「変わりつつある」= đang dần thay đổi."}]},"a-n1-8":{"title":"Lao động nước ngoài và tương lai của xã hội Nhật Bản","topic":"Xã hội","trans":["Giờ đây, khi thiếu hụt nhân lực đã trở thành vấn đề mang tính cơ cấu, việc tiếp nhận lao động nước ngoài đã bước vào giai đoạn không thể coi là biện pháp tạm thời nữa.","Các chế độ như Kỹ năng đặc định hay Nhân lực trình độ cao lần lượt được hoàn thiện, và số người cư trú liên tục lập kỷ lục mới. Tuy nhiên, số lượng tăng lên không đồng nghĩa với việc họ sẽ ở lại lâu dài.","Rào cản ngôn ngữ, chỗ ở, giáo dục cho con cái — nếu nền tảng cuộc sống chưa vững, thì dù cải thiện đãi ngộ đến đâu, con người cũng sẽ không bén rễ.","Đối với doanh nghiệp, sau khi tuyển dụng còn phải đảm nhận cả việc dạy tiếng Nhật và xây dựng mối liên kết với cộng đồng địa phương.","Ý thức của phía tiếp nhận cũng đang được đặt ra. Liệu chúng ta có thể đối diện với họ không phải như \"sức lao động\", mà như những người hàng xóm sống cùng một khu vực hay không.","Dù chế độ thế nào đi nữa, thứ cuối cùng quyết định việc họ có ở lại hay không có lẽ là sự tích lũy từng chút một trong các mối quan hệ hằng ngày.","Cuộc thảo luận về lao động nước ngoài thực ra là hai mặt của cùng một vấn đề với câu hỏi: xã hội Nhật Bản muốn trở thành một cộng đồng như thế nào."],"vocab":[{"w":"人手不足","m":"thiếu hụt nhân lực"},{"w":"受け入れ","m":"tiếp nhận"},{"w":"一時しのぎ","m":"biện pháp tạm thời, đối phó tạm"},{"w":"特定技能","m":"Kỹ năng đặc định (loại visa)"},{"w":"定着","m":"bén rễ, định cư lâu dài"},{"w":"待遇","m":"đãi ngộ"},{"w":"根を下ろす","m":"bén rễ, an cư"},{"w":"表裏一体","m":"hai mặt của một vấn đề, gắn bó không tách rời"},{"w":"問われる","m":"bị đặt câu hỏi, bị xem xét"}],"grammar":[{"t":"～ともなると","note":"Khi đã đến một cấp độ/vị thế nào đó thì tình hình sẽ khác. 「企業ともなると」= đến cấp độ doanh nghiệp thì trách nhiệm càng nhiều."},{"t":"～いかんによらず","note":"Dù vế trước thế nào cũng không ảnh hưởng đến kết quả. 「制度のいかんによらず」= bất kể chế độ ra sao."},{"t":"～たところで","note":"Dù có làm cũng vô ích, theo sau là kết quả phủ định. 「改善したところで、根を下ろさない」= dù có cải thiện cũng không bén rễ."},{"t":"～わけではない","note":"Phủ định một phần. 「定着を意味するわけではない」= không có nghĩa là sẽ ở lại lâu dài."}]},"a-n5-8":{"title":"ぎんこうで こうざを つくる","topic":"Cuộc sống","trans":["Hôm nay mình đi ngân hàng để mở tài khoản.","Nhân viên ở quầy nói: 「ざいりゅうカードと いんかんを おねがいします」(Cho tôi xin thẻ cư trú và con dấu).","Mình lấy thẻ và con dấu từ trong túi ra.","Mình viết tên, địa chỉ và số điện thoại vào mẫu đơn. Vì chữ Hán khó nên mình viết thật chậm.","Họ cho mình biết: 「キャッシュカードは 二週間ぐらいで うちに とどきます」(Thẻ ATM sẽ được gửi đến nhà khoảng hai tuần).","Sổ ngân hàng thì nhận được ngay trong ngày. Đây là cuốn sổ ngân hàng Nhật đầu tiên của mình.","Tuy hơi hồi hộp nhưng mình rất vui vì làm được hoàn toàn bằng tiếng Nhật."],"vocab":[{"w":"銀行","m":"ngân hàng"},{"w":"口座","m":"tài khoản"},{"w":"印鑑","m":"con dấu"},{"w":"用紙","m":"mẫu đơn, tờ khai"},{"w":"電話番号","m":"số điện thoại"},{"w":"通帳","m":"sổ ngân hàng"},{"w":"届く","m":"được gửi đến, đến nơi"},{"w":"緊張する","m":"hồi hộp, căng thẳng"}],"grammar":[{"t":"～に いきます(目的)","note":"Động từ thể ます bỏ ます + に いきます = đi để làm việc gì. 「こうざを つくりに いきます」= đi mở tài khoản."},{"t":"～と いいました","note":"Trích dẫn lời người khác nói, đặt nguyên câu trước 「と」."},{"t":"～てくれる","note":"Người khác làm gì đó cho mình, mang sắc thái biết ơn. 「おしえて くれました」= (họ) đã chỉ cho mình."}]},"a-n5-9":{"title":"Một ngày vui chơi ở công viên","topic":"Đời sống","trans":["Thứ Bảy trời đẹp. Mình hẹn với bạn đi công viên. Chín giờ sáng, bọn mình gặp nhau ở nhà ga.","Tối hôm trước, mình đã làm cơm hộp. Mình cho trứng cuộn, cơm nắm và rau vào. Mình cũng làm thêm một ít cho bạn.","Bọn mình đạp xe đến công viên. Trên đường có rất nhiều cây anh đào. Gió thổi rất dễ chịu.","Bọn mình ăn cơm hộp trên ghế dài trong công viên. Ăn rất ngon. Bạn mình cũng nói là ngon.","Ăn xong, mình với bạn chơi cầu lông, chụp ảnh, v.v. Ai cũng trông rất vui.","Chiều tối mình về nhà. Tuy hơi mệt nhưng đó là một ngày rất vui. Tuần sau mình cũng muốn đến công viên nữa."],"vocab":["thứ Bảy","thời tiết","bạn bè","công viên","lời hẹn, hẹn","cơm hộp","trứng cuộn","cơm nắm","xe đạp","ảnh, bức ảnh"],"grammar":[{"t":"へ(chỉ phương hướng)","note":"Chỉ hướng di chuyển, thường đi với các động từ như 「行く」:「こうえんへ 行く」."},{"t":"Thể た+あと","note":"Động từ thể た + 「あと」 nghĩa là \"sau khi ~\":「たべた あと、あそびました」."},{"t":"~たり~たりする","note":"Liệt kê vài hành động hoặc trạng thái tiêu biểu:「バドミントンを したり、しゃしんを とったり しました」."},{"t":"も(cũng)","note":"Đặt sau danh từ, nghĩa là \"cũng vậy\":「ともだちも おいしいと いいました」."}]},"a-n4-10":{"title":"Máy thanh toán tự động","topic":"Đời sống","trans":["Tuần trước, lần đầu tiên mình dùng máy thanh toán tự động ở siêu thị gần nhà. Dù không có nhân viên, bạn vẫn có thể tự thanh toán hàng hóa.","Trước tiên, bạn lấy từng món hàng ra khỏi giỏ rồi đưa mã vạch lên máy quét. Khi máy kêu một tiếng, nghĩa là đã quét thành công.","Tiếp theo, vừa nhìn màn hình vừa chọn cách thanh toán: tiền mặt hay thẻ. Nếu trả bằng tiền mặt thì bỏ tiền vào chỗ nhận tiền.","Vì là lần đầu nên mình không biết phải bấm vào đâu, có hơi bối rối. Nhưng khi gặp khó khăn, nhân viên ở gần đó đã đến giúp mình ngay.","Máy thanh toán tự động không cần xếp hàng ở quầy tính tiền, nên rất tiện khi bạn không có nhiều thời gian. Tuy nhiên, với người chưa quen thì có thể hơi khó.","Chỉ cần quen cách dùng thì ai cũng có thể dùng dễ dàng. Những bạn sắp dùng thử, hãy cứ thong thả vừa nhìn màn hình vừa thử nhé."],"vocab":["nhân viên cửa hàng","hàng hóa, sản phẩm","máy móc","màn hình","tiền mặt","thanh toán","chọn","phân vân, lúng túng","giúp đỡ","quen với"],"grammar":[{"t":"~てくれる","note":"Người khác làm gì đó cho mình:「店員さんが 手伝って くれました」(nhân viên đã giúp mình)."},{"t":"~なくてもいい","note":"Diễn tả không cần phải làm gì đó:「レジに ならばなくても いいです」(không cần xếp hàng cũng được)."},{"t":"~ずつ","note":"Nghĩa là \"mỗi lần/mỗi ~\", chia đều số lượng:「一つずつ とりだす」(lấy ra từng cái một)."},{"t":"~か~か","note":"Diễn tả việc chọn một trong hai:「げんきんか カードか」(tiền mặt hay thẻ)."}]},"a-n2-10":{"title":"Thực hành Báo cáo・Liên lạc・Thảo luận","topic":"Công sở","trans":["「報・連・相」 (hō-ren-sō) thường được nhắc đến ở các công ty Nhật, nhớ thì dễ nhưng thực hành mới khó.","Điều mà nhân viên nước ngoài dễ bị vướng nhất là phán đoán: \"Khi chưa có kết luận thì có nên báo cáo không?\"","Nói kết luận trước: chưa có kết luận cũng không sao. Ngược lại, chính lúc tiến độ không suôn sẻ mới càng cần chia sẻ sớm.","Vì điều cấp trên muốn biết không phải là một bản báo cáo hoàn hảo, mà là một câu nói trước khi rủi ro trở nên quá muộn.","「〇〇の件、今のところ半分ほど進んでいますが、資料待ちで少し遅れそうです」 — chỉ cần mức này là đã đủ hiệu quả.","Thảo luận cũng vậy, chưa có câu trả lời mà đến hỏi cũng không sao. Chỉ cần bạn diễn đạt được \"mình đang phân vân ở đâu\", thì bản thân điều đó đã là một cuộc thảo luận rồi.","Thay vì coi hō-ren-sō là phép tắc trong quan hệ trên dưới, hãy xem nó là cơ chế giúp cả nhóm tránh sự cố, và gánh nặng của bạn sẽ nhẹ đi rất nhiều."],"vocab":[{"w":"実践","m":"thực hành, đưa vào thực tế"},{"w":"とりわけ","m":"đặc biệt là"},{"w":"つまずく","m":"vấp ngã, gặp trở ngại"},{"w":"進捗","m":"tiến độ"},{"w":"思わしくない","m":"không như mong muốn"},{"w":"手遅れ","m":"đã quá muộn"},{"w":"言語化","m":"diễn đạt thành lời"},{"w":"作法","m":"phép tắc, quy củ"},{"w":"仕組み","m":"cơ chế"}],"grammar":[{"t":"～となると","note":"Khi đến tình huống đó thì khác hẳn. 「実践となると難しい」= nói đến thực hành thì khó."},{"t":"～こそ","note":"Nhấn mạnh \"chính lúc này\". 「思わしくないときこそ」= chính lúc không suôn sẻ (mới càng cần)."},{"t":"～ても構わない","note":"Dù… cũng không sao. 「行っても構わない」= có đi cũng không sao."},{"t":"～というより","note":"Nói là A thì đúng hơn là B. 「作法というより仕組み」= đúng hơn là một cơ chế chứ không phải phép tắc."}]},"a-n1-9":{"title":"Cảm giác về khoảng cách trong ngôi nhà","topic":"Văn hóa","trans":["Trong nhà ở của người Nhật, khắp nơi đều ẩn chứa cách giữ khoảng cách không nói thành lời.","Chỉ riêng thói quen cởi giày ở lối vào cũng đã vạch ra một ranh giới rõ ràng giữa \"bên ngoài\" và \"bên trong\". Động tác bước qua bậc thềm không chỉ là di chuyển đơn thuần, mà có thể nói là một nghi thức chuyển đổi.","Những vách ngăn như 「襖」 và 「障子」 rất đáng suy ngẫm ở chỗ chúng không đóng kín hoàn toàn. Chỉ là một lớp mỏng cho cả âm thanh lẫn hơi người lọt qua, vậy mà vẫn coi như đã chia tách không gian — chính sự mơ hồ này có lẽ là trí tuệ để sống cùng người khác trong ngôi nhà chật hẹp.","Ngay cả bây giờ, khi chung cư đã trở thành xu hướng chủ đạo, cảm giác ấy vẫn còn lại dưới hình thức khác. Sự quan tâm đến mức gần như quá nhạy cảm đối với tiếng ồn sinh hoạt, không hẳn là vì tường mỏng, mà đúng hơn là sự nối dài của phép tắc không xâm phạm không gian riêng của nhau.","Tuy nhiên, cảm giác về khoảng cách như vậy rất khó nhận ra với người từ bên ngoài đến. Có nên chào hỏi hay không, có thể bước vào đến mức nào — chính vì không được viết thành quy định rõ ràng nên nhiều khi người ta cũng phân vân.","Nhưng nói theo chiều ngược lại, điều đó cũng có nghĩa là mỗi người được giao cho tự cân nhắc chừng mực.","Nhà ở có lẽ là nơi mà câu hỏi \"nên đo khoảng cách với người khác như thế nào\" được lặng lẽ lặp đi lặp lại mỗi ngày."],"vocab":[{"w":"随所","m":"khắp nơi"},{"w":"隔てる","m":"ngăn cách"},{"w":"上がり框","m":"bậc chênh lệch ở lối vào (bậc thềm)"},{"w":"儀式","m":"nghi thức"},{"w":"仕切り","m":"vách ngăn"},{"w":"示唆に富む","m":"giàu gợi ý, đáng suy ngẫm"},{"w":"気配","m":"dấu hiệu, hơi người"},{"w":"配慮","m":"sự quan tâm, ý tứ"},{"w":"侵す","m":"xâm phạm"},{"w":"委ねる","m":"giao phó, để cho"}],"grammar":[{"t":"～をとっても","note":"Lấy một ví dụ để xét. 「習慣ひとつをとっても」= chỉ xét riêng một thói quen thôi cũng thấy."},{"t":"～ゆえに／～ゆえ","note":"Cách nói chỉ nguyên nhân mang tính văn viết. 「壁の薄さゆえ」= vì tường mỏng."},{"t":"～というより","note":"Nói là A thì đúng hơn là B. Dùng để điều chỉnh cách nói, đưa trọng tâm sang vế sau."},{"t":"裏を返せば","note":"Nói theo chiều ngược lại. Dùng khi lật sang mặt kia của cùng một sự việc."}]},"a-n3-11":{"title":"Tầm quan trọng của 報連相","topic":"Công sở","trans":["Trong các công ty Nhật, người ta thường nói rằng 「報連相」 rất quan trọng. Đây là cách gọi gộp ba từ: báo cáo, liên lạc và trao đổi.","Việc báo cho cấp trên biết tiến độ công việc được gọi là báo cáo. Khi có vấn đề xảy ra, bạn được yêu cầu phải báo cáo ngay.","Liên lạc là truyền đạt thông tin cần thiết cho những người liên quan. Chẳng hạn khi lịch trình thay đổi, việc liên lạc sớm được coi trọng.","Trao đổi là hỏi ý kiến cấp trên hoặc đồng nghiệp về những việc mình không thể tự quyết định. Dù là việc nhỏ, chỉ cần trao đổi thì bạn có thể tránh được sai sót lớn.","Với nhân viên người nước ngoài, thói quen 報連相 này lúc đầu có thể thấy khá khó. Bởi vì ở nước mình, đôi khi việc tự phán đoán và tự triển khai công việc lại được đánh giá cao.","Tuy nhiên, nếu thực hiện 報連相 đúng cách, bạn sẽ dễ có được sự tin tưởng trong nhóm hơn. Nếu làm việc ở công ty Nhật, hiểu cách nghĩ này sẽ rất có ích."],"vocab":["Cách gọi gộp của báo cáo, liên lạc, trao đổi","báo cáo","liên lạc","trao đổi, bàn bạc","tiến độ","cấp trên","đồng nghiệp","sự tin tưởng","phán đoán","đánh giá"],"grammar":[{"t":"~と言われています","note":"Diễn đạt \"người ta nói rằng ~, nghe nói ~\", ví dụ: 「報連相が大切だと言われています」(Người ta nói 報連相 rất quan trọng)."},{"t":"~ことです","note":"Danh từ hóa cụm động từ, nghĩa là \"việc ~\", ví dụ: 「情報を伝えることです」(Là việc truyền đạt thông tin)."},{"t":"~ば","note":"Diễn đạt điều kiện \"nếu ~ thì\", ví dụ: 「相談すれば、失敗を防げます」(Nếu trao đổi thì có thể tránh được sai sót)."},{"t":"~かもしれません","note":"Diễn đạt phỏng đoán \"có lẽ ~, có thể ~\", ví dụ: 「難しく感じられるかもしれません」(Có thể sẽ thấy khó)."}]},"a-n5-10":{"title":"Gọi món ở nhà hàng","topic":"Cuộc sống","trans":["Hôm nay, mình đã đi nhà hàng với bạn.","Mình xem thực đơn rồi chọn món.","Mình gọi nhân viên. Mình gọi một suất cơm set và trà.","Món ăn ra rất nhanh. Rất ngon.","Ăn xong, mình trả tiền ở quầy thu ngân. Có thể dùng thẻ nữa, tiện lắm."],"vocab":["nhà hàng","thực đơn","nhân viên phục vụ","gọi","cơm set (suất ăn)","gọi món","món ăn","quầy thu ngân","trả tiền","tiện lợi"],"grammar":[{"t":"〜て、〜(Thể て nối câu)","note":"Dùng thể て của động từ để nối hai hành động, ví dụ: 「メニュー を みて、りょうり を えらびました。」"},{"t":"〜ました(thì quá khứ)","note":"Diễn tả hành động đã xảy ra trong quá khứ, ví dụ: 「てんいん さん を よびました。」"},{"t":"〜あと、〜","note":"Diễn tả \"sau khi làm ~\", ví dụ: 「たべた あと、レジ で おかね を はらいました。」"},{"t":"〜も","note":"Nghĩa là \"cũng\", ví dụ: 「カード も つかえて、べんり でした。」"}]},"a-n4-11":{"title":"Ngày tôi để quên chiếc ô trên tàu điện","topic":"Cuộc sống","trans":["Hôm nay tôi đã để quên ô trên tàu điện. Khi nhận ra thì tàu đã đến ga tiếp theo rồi. Vì rất bối rối nên tôi quyết định đến quầy đồ thất lạc của nhà ga.","Tôi giải thích với nhân viên rằng mình đã làm mất ô. Họ bảo \"Xin hãy cho tôi biết đặc điểm\", nên tôi nói về màu sắc và hình dáng. Tôi nói: \"Đó là chiếc ô màu đen, cán hơi cong.\" Nhân viên nói \"Xin bạn đợi một chút, tôi sẽ thử tìm\" và đi tìm giúp tôi.","Đợi một lúc thì họ nói hình như đã tìm thấy chiếc ô giống vậy. Khi họ mang chiếc ô từ phía trong ra cho tôi xem, đó đúng là ô của tôi. Tôi nhận lại được ngay, thật sự nhẹ cả người. Từ giờ, mỗi khi xuống tàu tôi sẽ kiểm tra xem có quên đồ gì không."],"vocab":["đồ để quên, đồ thất lạc","nhận ra, để ý thấy","gặp rắc rối, khó xử","đặc điểm","cong, rẽ","được tìm thấy","nhận lấy, tiếp nhận","nhẹ nhõm, yên tâm","xác nhận, kiểm tra"],"grammar":[{"t":"〜たら","note":"Diễn tả sau khi hành động ở vế trước xảy ra thì có kết quả hoặc phát hiện ở vế sau, thường mang sắc thái bất ngờ. Ví dụ: 「気がついたら、もう電車は次の駅に着いていました。」"},{"t":"Thể khả năng","note":"Diễn tả khả năng hoặc trạng thái có thể làm được việc gì đó. Ví dụ: 「すぐに受け取れて、本当にほっとしました。」"},{"t":"Cách nói cho nhận (〜てくれる/〜てもらう)","note":"Diễn tả người khác làm việc gì đó cho mình, hoặc mình nhờ người khác làm và nhận được sự giúp đỡ. Ví dụ: 「係の人は…と言ってくれました。」、「奥から傘を持ってきてもらったら」"},{"t":"〜そうだ(様態)","note":"Diễn tả phán đoán dựa trên vẻ bề ngoài hoặc tình hình rằng điều gì đó sắp xảy ra. Ví dụ: 「同じような傘が見つかりそうだと言われました。」"}]},"a-n3-12":{"title":"Những điều cơ bản về email công việc","topic":"Công sở","trans":["Khi làm việc tại công ty Nhật, có một số quy tắc cơ bản khi viết email. Khác với điện thoại, email có ưu điểm là đối phương có thể đọc vào lúc thuận tiện cho họ. Nếu viết sai cách thì có thể gây ấn tượng thiếu lịch sự, nên nhân viên mới thường học hỏi kỹ từ các anh chị đi trước.","Trước hết, tiêu đề cần viết ngắn gọn để nhìn qua là hiểu ngay nội dung. Thay vì chỉ viết 「会議の件」, nên viết cụ thể như 「来週の会議の日程について」. Nếu tiêu đề khó hiểu, khi đối phương bận có thể họ sẽ bỏ sót email. Tuy nhiên, không có nghĩa là tiêu đề càng dài càng tốt, mà cũng cần khéo léo tóm gọn cho ngắn.","Phần mở đầu email thường dùng câu 「お世話になっております」. Đây là lời chào thể hiện lòng biết ơn đối với mối quan hệ với đối phương, được dùng cho cả người ngoài công ty lẫn người trong công ty. Với người liên lạc lần đầu, đôi khi cũng dùng cách nói như 「はじめてご連絡いたします」. Ở phần nội dung, để truyền đạt rõ ràng việc cần nói, bạn cần viết bằng những câu ngắn và lịch sự.","Nhiều người có thói quen kết thúc email bằng câu 「よろしくお願いいたします」. Nhờ câu này, toàn bộ bài viết tạo ấn tượng lịch sự và đối phương cũng đọc một cách dễ chịu. Ngoài ra, khi nhận được email thì trả lời càng sớm càng tốt cũng là một phép lịch sự quan trọng. Dù chưa thể trả lời ngay, chỉ cần gửi một câu như 「確認して後日ご連絡します」 là đối phương đã yên tâm."],"vocab":["tiêu đề email","ngắn gọn, súc tích","cụ thể","bỏ sót, nhìn sót","lịch sự, chu đáo","trả lời thư","phép lịch sự, quy tắc ứng xử","yên tâm","nhân viên mới","ưu điểm"],"grammar":[{"t":"〜ように","note":"Diễn tả làm việc gì đó để đạt được mục đích hoặc trạng thái nào đó. Trong bài: 「件名は一目で内容がわかるように、簡潔に書くことが大切です」."},{"t":"〜わけではない","note":"Diễn tả không hoàn toàn như vậy, phủ định một phần một cách nhẹ nhàng. Trong bài: 「件名を長くしすぎればよいというわけではなく」."},{"t":"〜ことにする","note":"Diễn tả cách làm do bản thân quyết định hoặc thói quen đã hình thành. Trong bài: 「よろしくお願いいたします、という言葉で締めることにしている人が多いです」."},{"t":"〜ておく","note":"Diễn tả việc làm sẵn trước để thuận tiện về sau. Trong bài: 「確認して後日ご連絡します、と一言送っておくと安心されます」."}]},"a-n5-11":{"title":"Chiếc thẻ IC đầu tiên","topic":"Cuộc sống","trans":["Sau khi đến Nhật, lần đầu tiên mình mua thẻ IC ở nhà ga. Mình bỏ một nghìn yên vào máy.","Khi đi tàu điện, bạn chạm thẻ ở cổng soát vé. Thẻ sẽ phát ra tiếng \"bíp\" ngắn.","Không cần mất thời gian mua vé, tiện lắm luôn.","Không chỉ đi tàu điện đâu nhé, xe buýt và cửa hàng tiện lợi cũng dùng được.","Hôm qua ở cổng soát vé bỗng vang lên một tiếng \"ting tong\" thật to. Thì ra tiền trong thẻ không đủ.","Nhân viên nhà ga bảo mình: \"Bạn hãy nạp tiền ở cái máy bên kia nhé.\"","Bây giờ, trước khi vào ga, mình luôn xem trong thẻ còn bao nhiêu tiền."],"vocab":[{"w":"駅","m":"nhà ga"},{"w":"機械","m":"máy móc, cái máy"},{"w":"改札","m":"cổng soát vé"},{"w":"切符","m":"vé"},{"w":"便利","m":"tiện lợi"},{"w":"足りる","m":"đủ"},{"w":"駅員","m":"nhân viên nhà ga"},{"w":"教える","m":"nói cho biết, dạy"},{"w":"チャージする","m":"nạp tiền"}],"grammar":[{"t":"～とき","note":"\"Khi làm gì đó\". Động từ thể từ điển + とき: 「でんしゃ に のる とき」= khi đi tàu điện."},{"t":"～ことができる","note":"Diễn tả khả năng hoặc sự có thể. Động từ thể từ điển + ことができる: 「つかう こと が できます」= có thể sử dụng."},{"t":"～まえに","note":"\"Trước khi làm gì đó\". Động từ luôn ở thể từ điển: 「えき に 入る まえ に」= trước khi vào ga."}]},"a-n4-12":{"title":"Tiêm vắc-xin cúm","topic":"Sức khỏe","trans":["Cứ đến tháng Mười, phòng khám gần nhà lại dán thông báo \"Đã bắt đầu tiêm vắc-xin cúm\".","Mùa đông năm ngoái, mình bị cúm và phải nghỉ làm cả một tuần.","Vì vậy năm nay mình quyết định đi tiêm phòng sớm hơn.","Mình gọi điện đặt lịch trước rồi mới đến, và ở quầy tiếp tân được đưa một phiếu khám sàng lọc. Mình phải đo nhiệt độ rồi ghi tình trạng sức khỏe.","Mũi tiêm không đau như mình nghĩ. Tiêm xong, họ dặn mình nghỉ ngơi một lúc ở phòng chờ.","Tiêm phòng không được dùng bảo hiểm y tế nên mình thấy hơi đắt. Nghe nói giá tùy từng bệnh viện, còn mình là 3.500 yên.","Nghe nói phải khoảng hai tuần thì vắc-xin mới có tác dụng. Tiêm trước khi dịch cúm lan rộng thì có thể yên tâm trải qua mùa đông."],"vocab":[{"w":"予防接種","m":"tiêm phòng, tiêm vắc-xin"},{"w":"受付","m":"quầy tiếp tân"},{"w":"早め","m":"sớm hơn một chút"},{"w":"渡す","m":"đưa, trao"},{"w":"調子","m":"tình trạng, trạng thái"},{"w":"注射","m":"tiêm"},{"w":"待合室","m":"phòng chờ"},{"w":"健康保険","m":"bảo hiểm y tế"},{"w":"効果","m":"hiệu quả, tác dụng"},{"w":"流行する","m":"lan rộng, thịnh hành"}],"grammar":[{"t":"～なければなりません","note":"Phải, bắt buộc phải. 「休まなければなりませんでした」= (lúc đó) đã phải nghỉ làm."},{"t":"～ことにする","note":"Tự mình quyết định làm gì. 「受けることにしました」= đã quyết định đi tiêm (vắc-xin)."},{"t":"～そうです(truyền đạt)","note":"Nghe nói. 「違うそうですが」「かかるそうです」= thông tin nghe từ người khác, không phải do chính mình xác nhận."},{"t":"～ておく","note":"Làm sẵn, chuẩn bị trước. 「受けておく」= tiêm sẵn (trước khi dịch cúm lan rộng)."}]},"a-n4-13":{"title":"Ngày Shichi-Go-San (七五三)","topic":"Văn hóa","trans":["Vào một ngày thứ Bảy của tháng Mười Một, tôi cùng bạn đi dạo ở một ngôi đền gần nhà. Trong khuôn viên đền có rất nhiều em nhỏ mặc kimono xinh đẹp cùng gia đình. Một bé gái mặc kimono màu đỏ, đang chụp ảnh với vẻ rất vui.","Anh Tanaka, người bạn Nhật của tôi, nói với tôi rằng đây là lễ Shichi-Go-San. Shichi-Go-San là một phong tục mừng sự trưởng thành của các em nhỏ khi tròn ba tuổi, năm tuổi và bảy tuổi. Gia đình sẽ nhờ đền cầu phúc cho con và cầu mong con lớn lên khỏe mạnh.","Anh Tanaka chỉ vào những chiếc túi giấy dài mà các em nhỏ đang cầm. Bên trong có loại kẹo dài và mảnh gọi là 「千歳あめ」 (kẹo Chitose). Nghe nói trong đó gửi gắm mong ước của gia đình là con sẽ sống lâu. Anh Tanaka bảo rằng kẹo Chitose cũng có thể mua ở các tiệm bánh kẹo Nhật và những nơi tương tự. Nếu sau này tôi có con, tôi cũng muốn chuẩn bị kẹo Chitose để chúc mừng."],"vocab":["đền thờ (thần xã)","khuôn viên đền","kimono (和服)","sự trưởng thành, lớn lên","chúc mừng, ăn mừng","sự kiện, nghi lễ, phong tục","lớn lên, trưởng thành","千歳あめ (kẹo Chitose – loại kẹo dài mảnh cầu mong trường thọ)","sống lâu, trường thọ","mong ước, nguyện vọng"],"grammar":[{"t":"〜てくれる/〜てもらう","note":"Diễn tả việc ai đó làm gì đó cho mình. 「田中さんが…教えてくれました」 là người kia chủ động giúp mình; 「お祈りをしてもらって」 là nhờ người khác làm và mình được hưởng lợi."},{"t":"〜そうだ(dáng vẻ・truyền đạt)","note":"Gắn vào thân của tính từ đuôi い hoặc động từ thì mang nghĩa 「trông có vẻ…」: 「うれしそうに写真をとっていました」. Gắn vào thể thường thì mang nghĩa truyền đạt 「nghe nói…」: 「願いがこめられているそうです」."},{"t":"〜たら","note":"Diễn tả giả định hoặc điều kiện, nghĩa là 「nếu… thì」: 「もし将来子どもができたら、わたしも…お祝いしたいです」."},{"t":"Thể khả năng","note":"Diễn tả 「có thể…」. 「買える」 là thể khả năng của 「買う」: 「和菓子屋さんなどでも買える」."}]},"a-n5-13":{"title":"Mua sắm mùa đông","topic":"Đời sống","trans":["Gần đây trời trở nên rất lạnh. Thứ Bảy, tôi cùng bạn đi đến một cửa hàng.","Tôi muốn một chiếc áo khoác màu đen. Bạn tôi nói: 「Cái màu đỏ cũng đẹp đấy.」 Tôi hỏi nhân viên cửa hàng: 「Tôi mặc thử được không ạ?」","Chiếc áo khoác màu đỏ rất đẹp. Tôi đã mua áo khoác, găng tay và khăn quàng cổ. Tất cả đều là màu tôi thích."],"vocab":["thứ Bảy","bạn bè","cửa hàng, tiệm","áo khoác","găng tay","khăn quàng cổ","màu đen, đen","màu đỏ, đỏ","màu sắc","đã hỏi (quá khứ của 聞く)"],"grammar":[{"t":"〜く なりました","note":"Bỏ 「い」 của tính từ đuôi い, thêm 「く」 rồi gắn 「なりました」 để diễn tả sự thay đổi trạng thái. Ví dụ: 「さいきん とても さむく なりました。」"},{"t":"〜が ほしい です","note":"Diễn tả muốn có một thứ gì đó. Quá khứ của 「muốn」 là 「ほしかった です」. Ví dụ: 「わたし は 黒い コート が ほしかった です。」"},{"t":"〜ても いい ですか","note":"Dùng để hỏi xin phép, nghĩa là 「…có được không?」, ví dụ khi hỏi nhân viên để mặc thử. Ví dụ: 「きても いい ですか」."},{"t":"A と B と C を 買いました","note":"Dùng 「と」 để nối các danh từ, nghĩa là 「A và B và C」. Ví dụ: 「コート と てぶくろ と マフラー を 買いました。」"}]},"a-n3-14":{"title":"Cùng đi ngắm lá đỏ nào","topic":"Văn hóa","trans":["Cuối tháng Mười, đồng nghiệp Tanaka rủ tôi: 「今週末、紅葉を見に行きませんか」 (Cuối tuần này bạn có muốn đi ngắm lá đỏ không?). Ở Nhật, việc lên núi hoặc ra công viên vào mùa thu để thưởng thức những chiếc lá đổi màu được gọi là 「紅葉狩り」, một thú vui được yêu thích từ xưa đến nay. Tôi thích lá đỏ, nhưng nghe nói những nơi nổi tiếng rất đông người nên tôi hơi lo.","Tanaka đề nghị: 「人込みを避けるために、朝早く出発するのはどうでしょうか」 (Để tránh đám đông, mình xuất phát thật sớm vào buổi sáng thì sao?). Từ trưa trở đi, bãi đỗ xe và đường sá đều đông nghẹt, nên nếu đến nơi trong buổi sáng thì nghe nói có thể thong thả đi dạo. Ngày thường thường vắng hơn, nhưng không phải lúc nào cũng yên tĩnh, nên tốt nhất đừng kỳ vọng quá nhiều.","Tiếp theo, chúng tôi quyết định tra 「紅葉情報」 (thông tin lá đỏ) được đăng trên trang web của hiệp hội du lịch hoặc trang dự báo thời tiết. Ở đó, tình trạng của cây được viết rất dễ hiểu bằng những cụm như 「色づき始め」 (bắt đầu đổi màu) và 「見ごろ」 (thời điểm đẹp nhất). Tanaka nhắc tôi rằng thời điểm đẹp nhất thay đổi tùy từng nơi, nên trước khi đi phải kiểm tra lại. Sau khi bàn bạc, chúng tôi chọn một công viên nhỏ gần núi và quyết định đi chuyến tàu sớm nhất buổi sáng.","Hôm đó tôi hơi buồn ngủ, nhưng dậy sớm thật xứng đáng, vì trên đường hầu như không có ai. Những chiếc lá đỏ và vàng được ánh sáng ban mai chiếu rọi, trông như thể cả không khí cũng nhuốm màu. Giữa những ngày bận rộn, chúng ta không có nhiều cơ hội để thong thả cảm nhận sự chuyển mùa. Trên đường về, tôi cảm ơn Tanaka: 「誘ってくださって、ありがとうございました」 (Cảm ơn anh/chị đã rủ tôi). Tanaka cười và nói 「来年も行きましょう」 (Năm sau mình lại đi nhé), nên từ bây giờ tôi đã háo hức chờ mùa thu tới."],"vocab":["ngắm lá đỏ, đi thưởng ngoạn lá đỏ","đồng nghiệp","đám đông, biển người","tránh","đề xuất, đề nghị","thông tin lá đỏ (tình trạng đổi màu)","thời điểm đẹp nhất để ngắm","đổi màu, nhuốm màu","chiếu sáng, rọi sáng","cơ hội"],"grammar":[{"t":"〜ように (yêu cầu・mục đích)","note":"Diễn tả làm việc gì để đạt được một trạng thái nào đó, hoặc nhắc/dặn người khác làm gì. Ví dụ: 「確認するように田中さんが教えてくれた」「午前のうちに着くようにすれば」."},{"t":"〜わけではない","note":"Nghĩa là \"không có nghĩa là...\", \"không phải là...\", dùng để phủ định một phần. Ví dụ: 「いつも静かなわけではないので」."},{"t":"〜ことにする","note":"Diễn tả người nói tự mình quyết định làm việc gì. Ví dụ: 「紅葉情報を調べることにした」「朝一番の電車で行くことにした」."},{"t":"Kính ngữ (くださる)","note":"「〜てくださる」là cách nói kính trọng của「〜てくれる」, dùng khi cảm ơn lòng tốt của đối phương. Ví dụ: 「誘ってくださって、ありがとうございました」."}]},"a-n5-12":{"title":"Oden ở cửa hàng tiện lợi","topic":"Đời sống","trans":["Vào một đêm mùa đông, tôi bước vào cửa hàng tiện lợi. Bên cạnh quầy thu ngân có oden. Mùi thơm quá, bụng tôi cũng đói cồn cào.","Tôi nói: 「だいこん と たまご を ください」 (Cho tôi củ cải trắng và trứng). Nhân viên hỏi: 「つゆ と からし は いりますか」 (Bạn có cần nước dùng và mù tạt không?). Tôi nói: 「つゆ だけ ください」 (Chỉ cho tôi nước dùng thôi).","Về đến nhà, tôi ăn ngay. Món oden nóng hổi làm cơ thể tôi ấm lên."],"vocab":["oden (món lẩu hầm kiểu Nhật)","củ cải trắng","trứng","quầy thu ngân","nước dùng","mù tạt Nhật (gia vị cay)","nhân viên cửa hàng","mùi, hương","ấm, ấm áp","đi vào, bước vào"],"grammar":[{"t":"〜を ください","note":"Dùng để xin hoặc gọi món. Ví dụ: 「だいこん と たまご を ください」. Khi chỉ muốn một thứ, dùng「だけ」, ví dụ: 「つゆ だけ ください」."},{"t":"〜と 言いました/聞きました","note":"「と」dùng để trích dẫn nội dung lời nói hoặc câu hỏi. Ví dụ: 「てんいん さん が『つゆ と からし は いりますか』と 聞きました」."},{"t":"Động từ thể て、〜","note":"Dùng「て」để nối các hành động hoặc nêu nguyên nhân. Ví dụ: 「いい におい が して、おなか が すきました」「うち に かえって、すぐ 食べました」."},{"t":"Tính từ い bỏ い + く なります","note":"Diễn tả sự thay đổi trạng thái. Ví dụ: 「からだ が あたたかく なりました」 (cơ thể ấm lên)."}]},"a-n2-12":{"title":"Suy ngẫm về Ngày Tạ ơn Lao động","topic":"Xã hội","trans":["Ngày 23 tháng 11 là 「勤労感謝の日」 (Ngày Tạ ơn Lao động), một ngày lễ quốc gia mà năm nào cũng có nhiều công ty và trường học nghỉ. Chỉ nhìn tên gọi thì dễ nghĩ đây là ngày dành riêng cho người đi làm, nhưng nguồn gốc ban đầu của nó hơi khác. Từ xưa, ở Nhật Bản mỗi độ thu về lại có nghi lễ 「新嘗祭」, dâng ngũ cốc mới thu hoạch trong năm lên thần linh để tạ ơn. 新嘗祭 là sự kiện mừng mùa thu hoạch và tạ ơn những ban tặng của thiên nhiên, thể hiện cách nghĩ của một xã hội coi trọng nông nghiệp.","Sau chiến tranh, trong quá trình chế độ của đất nước được xem xét lại một cách toàn diện, cách sắp xếp các ngày lễ cũng được chỉnh lý. Năm 1948, 「国民の祝日に関する法律」 (Luật về các ngày lễ quốc gia) được ban hành, và ngày này trở thành ngày lễ quốc gia với tên gọi 「勤労感謝の日」. Luật nêu rõ tôn chỉ của ngày này là: tôn trọng lao động, mừng sự sản xuất và để người dân cùng cảm ơn lẫn nhau. Bạn có thể hiểu đơn giản rằng lòng biết ơn dành cho thần linh đã mở rộng thành lòng biết ơn đối với chính việc lao động và làm ra sản phẩm.","Ở thời hiện đại, khi cách làm việc ngày càng đa dạng, hình ảnh mà ta liên tưởng đến từ \"lao động\" cũng đã thay đổi. Ngoài những người làm việc ở nhà máy và đồng ruộng, còn có vô số công việc nâng đỡ cuộc sống như cửa hàng, logistics, y tế, chăm sóc điều dưỡng. Hơn nữa, trong số đó có những công việc mà dù là ngày lễ thì đừng nói là được nghỉ, thậm chí còn buộc phải làm vất vả hơn ngày thường. Những tiện lợi mà chúng ta dùng như điều hiển nhiên chính là được xây dựng trên nỗ lực của những người như vậy.","Vậy, để biến lòng biết ơn thành hành động thì có thể làm gì? Chỉ cần nói một câu 「ありがとうございます」 với người giao hàng hay nhân viên cửa hàng là tấm lòng đã đủ để truyền đạt rồi. Ở nơi làm việc cũng vậy, ghi nhận công việc của đồng nghiệp và nói lời cảm ơn là một thói quen nhỏ mà bạn có thể bắt đầu ngay, lấy ngày này làm cơ hội. Ngoài ra, cách tính đi làm hay nghỉ vào ngày lễ khác nhau tùy công ty, nên muốn biết chi tiết bạn hãy xem thông báo của công ty. Lòng biết ơn chỉ thực sự có ý nghĩa khi được nói thành lời trong cuộc sống hằng ngày, chứ không chỉ vào một ngày lễ, bạn có thấy vậy không?"],"vocab":["nguồn gốc, xuất xứ","新嘗祭 (lễ tạ ơn mùa màng mới)","thu hoạch, mùa gặt","chế độ","tôn chỉ, ý nghĩa chính","đa dạng","logistics, vận chuyển hàng hóa","nâng đỡ, hỗ trợ","được xây dựng trên, dựa trên"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「働き方が多様になるに伴って、『勤労』という言葉から思い浮かべる姿も変わってきた」"},{"t":"〜どころか","note":"Nghĩa là \"không những không... mà còn...\", phủ định vế trước và nhấn mạnh vế sau. Ví dụ: 「祝日であっても休むどころか、いつも以上に働かざるを得ない」"},{"t":"〜ざるを得ない","note":"Nghĩa là \"đành phải...\", không có lựa chọn nào khác do hoàn cảnh. Ví dụ: 「いつも以上に働かざるを得ないものもある」"},{"t":"〜をきっかけに","note":"Diễn tả việc lấy một sự việc làm cơ hội để bắt đầu làm điều gì đó. Ví dụ: 「この日をきっかけにすぐ始められる小さな習慣である」"}]},"a-n5-14":{"title":"Bạn bè và nồi lẩu","topic":"Cuộc sống","trans":["Vào một ngày mùa đông, mình ăn lẩu ở nhà cùng bạn bè. Đầu tiên, mọi người cùng đi siêu thị. Bọn mình mua cải thảo, đậu phụ và thịt.","Ở nhà, bọn mình thái rau rồi cho vào nồi. Rau cho trước, thịt cho sau. Căn phòng trở nên ấm áp.","Mọi người cùng ăn với nhau thì rất ngon. Đó là một đêm lạnh nhưng rất vui."],"vocab":["mùa đông","nồi; lẩu","siêu thị","cải thảo","đậu phụ","thịt","cho vào","trước","ấm áp","mọi người"],"grammar":[{"t":"〜て、〜(động từ thể て)","note":"Dùng thể て để nối hai hành động, nghĩa là làm việc trước rồi làm việc sau. Ví dụ: 「やさい を 切って、なべ に 入れました。」"},{"t":"〜と、〜","note":"Diễn tả kết quả hoặc cảm nhận thông thường khi làm một việc gì đó, kiểu \"hễ... thì...\". Ví dụ: 「いっしょ に たべる と、おいしい です。」"},{"t":"〜く なります","note":"Tính từ い đổi thành 「〜く」 rồi thêm 「なります」, diễn tả sự thay đổi trạng thái. Ví dụ: 「へや が あたたかく なりました。」"},{"t":"〜が、〜","note":"Đặt ở cuối vế câu để diễn tả ý đối lập \"tuy... nhưng...\". Ví dụ: 「さむい よる でした が、たのしかった です。」"}]},"a-n3-15":{"title":"Lần đầu làm điều chỉnh cuối năm","topic":"Nơi làm việc","trans":["Khi cuối năm đến gần, phòng nhân sự gửi cho tôi một email và một số giấy tờ với tiêu đề 「年末調整のご案内」. Trong giấy tờ có các ô để điền tình trạng người phụ thuộc trong gia đình và phí bảo hiểm, nhưng tôi không biết nên bắt đầu viết từ đâu. Đây là lần đầu tôi làm việc ở Nhật, nên đến cả từ 「年末調整」 tôi cũng chưa từng nghe qua.","Tôi hỏi anh Tanaka ngồi bên cạnh, anh ấy nói: 「毎年の手続きですから、心配はいりませんよ」 (Đây là thủ tục năm nào cũng làm, nên bạn đừng lo nhé). Nghe nói số thuế bị trừ từ lương mỗi tháng chỉ là tính tạm, đến cuối năm sẽ tính lại cho cả năm. Vì thuế thay đổi tùy theo tình hình gia đình và số phí bảo hiểm đã đóng, nên việc điền đúng rất quan trọng. Có điều, cách điền mỗi công ty hơi khác nhau, nên anh ấy dặn chỗ nào không hiểu thì hỏi thẳng phòng nhân sự.","Hôm sau, tôi đến hỏi chị Sato ở phòng nhân sự. Chị vừa cho tôi xem bản điền mẫu vừa giải thích tỉ mỉ từng mục một. Nghe nói nếu có loại bảo hiểm tự mình đóng thì đôi khi còn cần giấy chứng nhận do công ty bảo hiểm gửi đến. Không phải tôi ngại hỏi, chỉ là thấy phòng nhân sự có vẻ bận nên khó mở lời. Nhưng chị Sato cười và trả lời: 「初めてなら聞いて当然ですよ」 (Lần đầu thì hỏi là chuyện đương nhiên mà).","Về đến nhà, tôi quyết định tìm các giấy tờ bảo hiểm trong nhà rồi thong thả kiểm tra nội dung cần điền. Thủ tục chi tiết và cách nộp khác nhau tùy công ty, nên bạn nhất định hãy xem kỹ hướng dẫn của công ty mình. Điều chỉnh cuối năm trông thì phiền phức, nhưng tôi đã hiểu đó là một thủ tục quan trọng để khớp lại chính xác thuế của cả năm."],"vocab":[{"w":"年末調整","m":"điều chỉnh cuối năm (quyết toán lại thuế thu nhập vào cuối năm)"},{"w":"人事部","m":"phòng nhân sự"},{"w":"扶養","m":"phụ thuộc, nuôi dưỡng (người phụ thuộc)"},{"w":"保険料","m":"phí bảo hiểm"},{"w":"手続き","m":"thủ tục"},{"w":"記入例","m":"mẫu điền"},{"w":"証明書","m":"giấy chứng nhận"},{"w":"確認","m":"xác nhận, kiểm tra"},{"w":"丁寧","m":"tỉ mỉ, lịch sự"},{"w":"給料","m":"tiền lương"}],"grammar":[{"t":"〜ように言われた","note":"Diễn tả việc được ai đó dặn dò, yêu cầu làm gì (câu gián tiếp). Ví dụ: 「わからない点は人事に直接聞くように言われた」"},{"t":"〜わけではない","note":"Nghĩa là \"không phải là...\", phủ định một phần, dùng để loại bỏ cách hiểu lầm có thể xảy ra. Ví dụ: 「質問するのが嫌なわけではなかったが」"},{"t":"〜ことにする","note":"Diễn tả người nói tự quyết định làm việc gì. Ví dụ: 「ゆっくり確認することにした」"},{"t":"〜そうだ(truyền đạt)","note":"Đi sau thể thường, diễn tả thông tin nghe được từ người khác (\"nghe nói là...\"). Ví dụ: 「年末に一年分を計算し直すのだそうだ」"}]},"a-n4-14":{"title":"Tiền điện mùa đông","topic":"Cuộc sống","trans":["Mùa đông ở Nhật, ngay cả trong nhà cũng lạnh hơn tôi tưởng nhiều. Phòng cũ thì hơi lạnh lùa vào từ cửa sổ, bật máy sưởi cũng khó ấm lên. Tháng trước, khi xem hóa đơn, tôi giật mình vì tiền điện cao hơn bình thường. Tôi kể với bạn bè và được chỉ cho rất nhiều mẹo tiết kiệm.","Trước hết, tôi dùng chăn điện để làm ấm chăn đệm trước khi đi ngủ. Nghe nói nếu bật máy tạo ẩm thì dù nhiệt độ phòng không đổi, bạn vẫn cảm thấy ấm hơn. Sau khi đổi sang rèm dày, cái lạnh gần cửa sổ giảm đi khá nhiều. Tôi chỉnh nhiệt độ máy sưởi thấp hơn một chút và mặc thêm áo khoác khi ở nhà.","Anh Tanaka bảo tôi nên tắt máy sưởi ở những phòng không dùng đến. Về các gói giá điện, bạn nên hỏi công ty điện lực để biết chi tiết. Nếu tiếp tục áp dụng những mẹo nhỏ, có vẻ tôi có thể vượt qua mùa đông lạnh giá mà không quá lo lắng về tiền điện."],"vocab":[{"w":"暖房","m":"máy sưởi, sưởi ấm"},{"w":"冷気","m":"hơi lạnh"},{"w":"請求書","m":"hóa đơn, giấy yêu cầu thanh toán"},{"w":"電気代","m":"tiền điện"},{"w":"節約","m":"tiết kiệm"},{"w":"電気毛布","m":"chăn điện"},{"w":"加湿器","m":"máy tạo ẩm"},{"w":"厚い","m":"dày"},{"w":"設定温度","m":"nhiệt độ cài đặt"},{"w":"工夫","m":"mẹo, cách làm khéo, sự sáng tạo"}],"grammar":[{"t":"〜たら","note":"Diễn tả \"khi làm... thì (phát hiện ra)...\" hoặc điều kiện giả định. Ví dụ: 「請求書を見たら、電気代がいつもより高くて」「厚いカーテンに換えたら、窓の近くの冷たさがかなり減りました」."},{"t":"Thể khả năng","note":"Diễn tả \"có thể...\". Ví dụ: 「あたたかく感じられる」「過ごせそうです」. Động từ nhóm 2 thêm「られる」, động từ nhóm 1 đổi đuôi sang hàng え + る."},{"t":"〜そうだ","note":"Có hai cách dùng: đi sau thể thường nghĩa là \"nghe nói\", đi sau thể ます bỏ ます nghĩa là \"trông có vẻ\". Ví dụ: 「あたたかく感じられるそうです」(truyền đạt), 「過ごせそうです」(dự đoán qua vẻ bề ngoài)."},{"t":"〜てもらう/〜てくれる","note":"Diễn tả việc nhận được sự giúp đỡ từ người khác (cách nói cho – nhận). Ví dụ: 「いろいろ教えてもらいました」「教えてくれました」. 〜てもらう lấy bản thân làm chủ ngữ, 〜てくれる lấy người kia làm chủ ngữ."}]},"eh-n5-2":{"title":"Lạc đường ở nhà ga","topic":"Truyện tranh","trans":["Hôm nay trời đẹp. Tanutarō đi tàu điện ra biển.","Nhà ga rộng quá. Người cũng rất đông. Tàu ra biển ở sân ga số mấy nhỉ? Tanutarō không biết.","Cậu xem bản đồ nhưng lại càng thấy rối hơn. Tanutarō lúng túng quá.","Lúc đó, bạn cáo コン đi tới. Bạn hỏi: 「Có chuyện gì vậy?」","Tanutarō hỏi: 「Xin lỗi, tàu ra biển ở đâu vậy ạ?」","コン chỉ cho cậu: 「Ở sân ga số 3 đó, bạn leo cầu thang bên kia lên nhé.」","Tanutarō nói 「Cảm ơn bạn」 rồi chạy đi. Cậu đã kịp chuyến tàu!"],"vocab":[{"w":"駅","m":"nhà ga"},{"w":"迷子","m":"(người) bị lạc đường"},{"w":"電車","m":"tàu điện"},{"w":"番線","m":"sân ga số …"},{"w":"地図","m":"bản đồ"},{"w":"困る","m":"gặp rắc rối, lúng túng"},{"w":"階段","m":"cầu thang"},{"w":"上る","m":"đi lên, leo"},{"w":"教える","m":"chỉ, nói cho biết; dạy"},{"w":"間に合う","m":"kịp, kịp giờ"}],"grammar":[{"t":"〜てください","note":"Động từ thể て + ください, dùng để nhờ hoặc đề nghị ai làm gì một cách lịch sự. Ví dụ: あそこの かいだんを のぼって ください。"},{"t":"Từ để hỏi (どこ・何)","note":"Hỏi địa điểm dùng 「どこ」, hỏi số thì dùng 「何ばんせん」. Ví dụ: うみへ 行く でんしゃは どこですか。"},{"t":"〜くなります","note":"Tính từ đuôi い bỏ い + くなります, nghĩa là \"trở nên…\". Với ない cũng vậy: わからない→わからなく なりました (càng trở nên khó hiểu)."}]},"a-n2-13":{"title":"Tiệc tất niên đang thay đổi, sự tinh tế vẫn còn đó","topic":"Công sở","trans":["Mỗi khi cuối năm đến gần, ở các công ty Nhật Bản, chuyện về 「忘年会」 từ trước đến nay vẫn tự nhiên được nhắc tới. Nó mang ý nghĩa quên đi những vất vả của một năm để gắn kết tình cảm hơn, và trước kia việc tham gia được xem là điều đương nhiên. Thế nhưng những năm gần đây, ngày càng nhiều người muốn dành thời gian sau giờ làm cho bản thân nên không muốn tham gia. Cùng với đó, không ít công ty bỏ tiệc tối để chuyển sang tiệc trưa, hoặc cho nhân viên tự do quyết định có tham gia hay không.","Đằng sau là sự đa dạng hóa về giá trị quan, cùng hoàn cảnh muốn ưu tiên cân bằng giữa công việc với gia đình và chăm sóc người thân. Không ít nhân viên trẻ cảm thấy ngồi cùng sếp chẳng những không thoải mái vui vẻ mà còn mệt vì phải để ý đủ thứ. Mặt khác, cũng có người coi đây là cơ hội quý để giao lưu với những đồng nghiệp ngày thường ít nói chuyện nên hoan nghênh việc tổ chức, và đó cũng là sự thật. Về phía công ty, nếu ép buộc thì sự bất mãn có thể tăng lên, nên buộc phải tìm một hình thức quan tâm đến hoàn cảnh của từng người.","Khi được mời mà muốn từ chối, nguyên tắc cơ bản là trước tiên hãy cảm ơn vì đã được mời. Ví dụ, nếu nói 「お誘いありがとうございます。あいにく先約がありまして」 thì sẽ không làm mất lòng ai. Nếu giải thích lý do quá chi tiết, đôi khi nghe lại giống như viện cớ, nên hãy nói ngắn gọn rồi thêm một câu 「またの機会にぜひ」 sẽ tốt hơn. Ngược lại, khi tham gia, nếu không uống được rượu thì bạn có thể cụng ly bằng trà ô long, và nói trước ngay từ đầu rằng mình sẽ về sớm thì cũng nhẹ lòng hơn.","Chúng ta nên tránh việc coi người không tham gia là lạnh nhạt, hay cho rằng người tham gia chỉ là vì nể nang xã giao. Về phía người tổ chức, khi gửi thông báo nếu thêm một câu 「参加は自由です」 thì gánh nặng tâm lý của người từ chối sẽ nhẹ đi rất nhiều. Điều quan trọng chẳng phải là thái độ cố gắng tôn trọng hoàn cảnh và cảm xúc của nhau, hơn là bản thân hình thức hay sao? Dù tiệc tất niên có đổi thành tiệc trưa, nó vẫn là nơi nuôi dưỡng niềm tin giữa người với người, điều đó không hề thay đổi."],"vocab":[{"w":"忘年会","m":"tiệc tất niên"},{"w":"親睦","m":"thân thiết, gắn kết tình cảm"},{"w":"価値観","m":"giá trị quan"},{"w":"両立","m":"cân bằng, vẹn cả đôi đường"},{"w":"強制","m":"ép buộc, cưỡng chế"},{"w":"配慮","m":"quan tâm, chu đáo, cân nhắc đến"},{"w":"先約","m":"hẹn trước, cuộc hẹn đã có từ trước"},{"w":"幹事","m":"người tổ chức, người phụ trách sự kiện"},{"w":"尊重","m":"tôn trọng"}],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「それに伴って、夜の宴会をやめて昼のランチ会にしたり…する会社も目立つようになった」."},{"t":"〜どころか","note":"Nghĩa là \"đừng nói là…, mà ngược lại…\": phủ định vế trước và nêu ra sự thật trái ngược hoặc cực đoan hơn. Ví dụ: 「気楽に楽しめるどころか、気を使って疲れるだけだと感じる」."},{"t":"〜かねない","note":"Đi với động từ thể ます bỏ ます, nghĩa là \"có thể xảy ra (điều không hay)\". Ví dụ: 「強制すれば不満が高まりかねない」."},{"t":"〜ざるを得ない","note":"Nghĩa là \"buộc phải…\": không có lựa chọn nào khác ngoài việc làm. Ví dụ: 「それぞれの事情に配慮した形を探さざるを得ない」."}]},"eh-n5-1":{"title":"Lần đầu đến cửa hàng tiện lợi","topic":"Truyện tranh","trans":["Tanutarō mới đến Nhật Bản hôm qua. Hôm nay cậu ấy lần đầu đến cửa hàng tiện lợi.","Bên trong cửa hàng rất sáng. Có rất nhiều cơm nắm, bánh mì và đồ uống.","Tanutarō chọn một hộp cơm và một chai trà. Cậu mang ra quầy thu ngân.","Nhân viên hỏi: 「あたためますか」. Tanutarō không hiểu nghĩa là gì.","「あたためますか」 có nghĩa là 「あつく しますか」 (bạn có muốn làm nóng không?). Tanutarō nói: 「はい、おねがいします」.","Tiếp theo, nhân viên hỏi: \"Bạn có cần túi không?\" Lần này cậu hiểu. Cậu trả lời: \"Không cần đâu, cảm ơn.\"","Hộp cơm nóng hổi rất ngon. Tanutarō muốn lại đến cửa hàng tiện lợi nữa."],"vocab":[{"w":"コンビニ","m":"cửa hàng tiện lợi"},{"w":"初めて","m":"lần đầu tiên"},{"w":"お弁当","m":"cơm hộp"},{"w":"選ぶ","m":"chọn"},{"w":"レジ","m":"quầy thu ngân"},{"w":"店員","m":"nhân viên cửa hàng"},{"w":"温める","m":"hâm nóng, làm nóng"},{"w":"意味","m":"ý nghĩa"},{"w":"袋","m":"túi"},{"w":"答える","m":"trả lời"}],"grammar":[{"t":"〜という","note":"「A という いみです」 = A có nghĩa là…, dùng để giải thích một từ. Ví dụ: 「あたためますか」は「あつく しますか」と いう いみです。"},{"t":"〜たいです","note":"Động từ thể ます bỏ ます + たいです, diễn tả \"muốn làm…\". Ví dụ: また コンビニに 行きたいです。"},{"t":"〜と(liệt kê)","note":"Danh từ と danh từ, dùng để liệt kê đầy đủ các thứ. Ví dụ: おべんとうを 一つと おちゃを 一つ。"}]},"a-n3-16":{"title":"Khi nhận được thiệp báo tang","topic":"Văn hóa","trans":["Đầu tháng Mười một, đồng nghiệp ở công ty là anh Tanaka gửi đến một tấm bưu thiếp. Mở ra xem thì thấy viết: 「喪中につき、年始のご挨拶をご遠慮申し上げます」 (Do đang có tang, xin phép không gửi lời chúc đầu năm). Đến lúc đó tôi mới lần đầu biết bố anh Tanaka đã qua đời vào mùa hè năm nay.","Đây gọi là 「喪中はがき」, tấm thiệp để người trong nhà có tang báo cho người khác biết là mình sẽ không gửi thiệp mừng năm mới. Thói quen này xuất phát từ quan niệm rằng trong thời gian có tang thì nên tránh những việc vui mừng. Loại thiệp này thường đến trước khi mọi người bắt đầu chuẩn bị thiệp mừng năm mới, nhằm báo cho đối phương biết sớm. 喪中はがき chỉ là thông báo \"tôi không thể gửi thiệp mừng năm mới\", chứ không có ý yêu cầu người nhận phải hồi âm.","Tôi hơi phân vân, nhưng sau khi hỏi một đồng nghiệp, tôi quyết định không gửi thiệp mừng năm mới cho anh Tanaka. Đồng nghiệp còn mách tôi rằng nếu sau khi sang năm mới một thời gian, mình gửi 「寒中見舞い」 thì tấm lòng sẽ được truyền đạt. 寒中見舞い là thiệp hỏi thăm sức khỏe người nhận trong mùa lạnh, và không viết lời chúc mừng. Khi viết nội dung, tôi chú ý ghi lời cảm ơn vì đã nhận được bưu thiếp, cùng lời chia sẻ, quan tâm đến gia đình anh Tanaka.","Cách xử lý thiệp mừng năm mới ở công ty khác nhau tùy từng nơi làm việc, nên muốn biết chi tiết thì hãy xem hướng dẫn của công ty. Thói quen gửi thiệp mừng năm mới đang giảm dần, nhưng văn hóa gửi gắm tấm lòng qua những lời chào theo mùa vẫn được trân trọng đến ngày nay. Qua lần này, tôi học được rằng biết thông cảm cho hoàn cảnh của người khác và thay đổi cách chào hỏi cho phù hợp cũng là một phép lịch sự quan trọng ở nơi làm việc."],"vocab":["thời gian có tang","thiệp mừng năm mới","đã qua đời","chào hỏi, lời chào","kiêng, xin phép không (làm gì)","hạn chế, tránh","thiệp hỏi thăm mùa đông (thiệp hỏi thăm trong mùa lạnh)","quan tâm, lo lắng cho","thói quen, tập quán","lưu ý, cố gắng thực hiện"],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Ví dụ: 「田中さんには年賀状を出さないことにした。」"},{"t":"〜わけではない","note":"Nghĩa là \"không phải là…\", dùng để phủ định một phần hoặc đính chính một cách hiểu sai. Ví dụ: 「返事を求めているわけではない。」"},{"t":"〜ように心がける","note":"Diễn tả việc cố gắng lưu ý để đạt được một mục tiêu nào đó. Ví dụ: 「お礼と、田中さんの家族を思う言葉を入れるように心がけた。」"},{"t":"〜によって違う","note":"Nghĩa là \"khác nhau tùy theo…\". Ví dụ: 「会社の年賀状の扱いは職場によって違う。」"}]},"a-n4-15":{"title":"年末の大そうじ、早めに始めよう","topic":"Đời sống","trans":["Cứ đến tháng Mười hai hằng năm, tổng vệ sinh lại rất vất vả và lúc nào mình cũng mệt rã rời. Năm nay, từ trước tháng Mười hai, mình đã thử viết ra một danh sách những chỗ cần dọn. Nào là bếp, phòng tắm, cửa sổ, lối vào nhà… có rất nhiều chỗ.","Tiếp theo, mình mua nước tẩy rửa và miếng bọt biển ở hiệu thuốc. Nhân viên cửa hàng bảo mình là nước tẩy dùng cho phòng tắm còn tẩy được cả nấm mốc. Làm hết một lúc thì mệt nên mình quyết định mỗi tuần chỉ dọn một chỗ. Mình đã lên kế hoạch như vậy: tuần này dọn bếp, tuần sau dọn phòng tắm.","Mình kể với bạn cùng phòng là Lin thì bạn ấy nói sẽ cùng làm. Mình phụ trách bếp và phòng tắm, còn Lin phụ trách cửa sổ và lối vào nhà. Còn rác cỡ lớn thì cần xem hướng dẫn của văn phòng quận để biết cách vứt. Nghe bạn bè nói, bắt đầu sớm thì tâm trạng cũng nhẹ nhõm hơn. Mình nghĩ nếu làm theo cách này thì cuối năm có lẽ cũng được nghỉ ngơi thong thả."],"vocab":["tổng vệ sinh","cuối năm","bếp","nước tẩy rửa, chất tẩy","mỗi tuần","một lần, cùng một lúc","phụ trách","văn phòng quận","tâm trạng, cảm giác"],"grammar":[{"t":"〜たら","note":"Diễn tả \"sau khi làm gì đó / nếu…\", thường nối với diễn biến phía sau. Ví dụ trong bài: 「ルームメイトのリンさんにも話したら、いっしょにやると言ってくれました。」"},{"t":"Thể khả năng","note":"Diễn tả \"có thể làm được\". Ví dụ trong bài: 「おふろ用の洗剤はカビも落とせると教えてくれました。」(落とす→落とせる), 「ゆっくり休めそうだ」(休む→休める)"},{"t":"〜てくれる (cho nhận)","note":"Diễn tả người khác làm gì đó cho mình, mang sắc thái biết ơn. Ví dụ trong bài: 「店の人が、…教えてくれました。」「いっしょにやると言ってくれました。」"},{"t":"〜そうだ","note":"Có hai cách dùng: ① gắn vào thể ます bỏ ます của động từ, nghĩa là \"trông có vẻ sắp / có lẽ sẽ\", như 「休めそうだ」; ② gắn vào thể thường, diễn tả tin nghe lại, như 「気持ちも楽になるそうです」."}]},"eh-n4-3":{"title":"Món quà ngày mưa","topic":"Truyện tranh","trans":["Thứ Bảy tuần sau là sinh nhật của Kon. Chiếc khăn quàng màu xanh mà Kon luôn đeo đã khá cũ rồi.","Tanutarō quyết định tặng một chiếc khăn quàng mới làm quà. Nhưng hôm đó trời mưa từ sáng.","Tanutarō che ô, đi đến cửa hàng tạp hóa trong thị trấn. Ở đó, cậu tìm thấy một chiếc khăn quàng màu xanh rất đẹp.","Tuy hơi đắt một chút, Tanutarō vẫn quyết định mua nó. Nhân viên đã gói giúp cậu rất đẹp.","Trên đường về, mưa càng lúc càng to. Để quà không bị ướt, Tanutarō ôm chặt cặp và chạy.","Cậu nói \"Chúc mừng sinh nhật\" rồi đưa quà, Kon vô cùng ngạc nhiên.","Kon quàng chiếc khăn mới, cười nói: \"Cảm ơn bạn, mình sẽ luôn trân trọng nó nhé.\""],"vocab":[{"w":"誕生日","m":"sinh nhật"},{"w":"マフラー","m":"khăn quàng cổ"},{"w":"傘","m":"cái ô, cái dù"},{"w":"雑貨屋","m":"cửa hàng tạp hóa"},{"w":"見つける","m":"tìm thấy"},{"w":"包む","m":"gói, bọc"},{"w":"濡れる","m":"bị ướt"},{"w":"抱える","m":"ôm, ẵm"},{"w":"驚く","m":"ngạc nhiên, giật mình"},{"w":"大切","m":"quý trọng, quan trọng"}],"grammar":[{"t":"〜うと思います","note":"Thể ý chí của động từ + と思います, diễn tả ý định của bản thân. Ví dụ: 新しいマフラーをプレゼントしようと思いました。"},{"t":"〜ことにします","note":"Động từ thể từ điển + ことにします, diễn tả bản thân đã quyết định làm gì. Ví dụ: それを買うことにしました。"},{"t":"〜ように(目的)","note":"「A ように、B」= làm B để tình trạng A được thực hiện; phía trước thường là thể ない hoặc thể khả năng. Ví dụ: プレゼントがぬれないように、かばんをしっかり抱えて走りました。"},{"t":"〜てくれます","note":"Người khác làm giúp mình việc gì đó. Ví dụ: 店員さんがきれいに包んでくれました。"}]},"a-n2-5-n3":{"title":"Thanh toán không tiền mặt ngày càng phổ biến","topic":"Xã hội","trans":["Vài năm gần đây, số người dùng thanh toán không tiền mặt ở Nhật cũng tăng lên rất nhanh. Trước đây nhiều cửa hàng chỉ nhận tiền mặt, còn bây giờ ngày càng có nhiều cửa hàng cho phép thanh toán bằng điện thoại thông minh hoặc thẻ.","Thanh toán không tiền mặt có ưu điểm là trả tiền nhanh và dễ quản lý tiền bạc. Vì không cần phải tìm tiền lẻ ở quầy thu ngân nên thời gian mua sắm cũng ngắn hơn. Ngoài ra, bạn đã tiêu lúc nào, bao nhiêu đều được lưu lại thành lịch sử, nên sau này rất dễ kiểm tra lại.","Mặt khác, vẫn còn những vấn đề cần phải giải quyết. Khi mất điện hoặc sự cố đường truyền xảy ra, có thể sẽ không thanh toán được. Có người lỡ tiêu quá tay, cũng có người cao tuổi không quen thao tác với máy móc. Vì vậy, chúng ta cũng không được quên quan tâm đến những người này.","Làm thế nào để cân bằng giữa sự tiện lợi và sự an tâm đây? Xã hội đang cần là một xã hội mà cả tiền mặt lẫn thanh toán không tiền mặt đều được sử dụng hiệu quả."],"vocab":["thanh toán","đột ngột, nhanh chóng","quản lý","tiền lẻ","ghi chép, lịch sử","mất điện","sự cố, trục trặc","thao tác","người cao tuổi","quan tâm, chú ý đến"],"grammar":[{"t":"〜やすい","note":"Gắn sau thể ます của động từ, diễn tả \"dễ làm việc gì\". Ví dụ: 「お金の管理がしやすい」「後で確認しやすい」."},{"t":"〜ため(原因)","note":"Diễn tả nguyên nhân, lý do, mang tính văn viết hơn 「から」. Ví dụ: 「小銭を探す必要がないため、買い物の時間が短くなる」."},{"t":"〜おそれがある","note":"Diễn tả khả năng xảy ra điều không tốt. Ví dụ: 「支払いができなくなるおそれがある」."},{"t":"〜なければならない","note":"Diễn tả \"phải làm việc gì\". Ví dụ: 「まだ解決しなければならない問題もある」."}]},"a-n2-5-n4":{"title":"Thanh toán không tiền mặt ngày càng phổ biến","topic":"Xã hội","trans":["Gần đây, ở Nhật số người trả tiền không dùng tiền mặt cũng tăng nhanh. Trước đây có nhiều cửa hàng chỉ nhận tiền mặt. Bây giờ ngày càng có nhiều cửa hàng cho trả bằng điện thoại thông minh hoặc thẻ.","Thanh toán không tiền mặt thì trả tiền nhanh, quản lý tiền cũng đơn giản. Vì bạn không cần tìm tiền lẻ ở quầy thu ngân. Bạn đã tiêu lúc nào, bao nhiêu cũng được lưu lại.","Tuy nhiên, vẫn còn một số vấn đề. Nếu mất điện hoặc đường truyền gặp sự cố, có thể sẽ không trả tiền được. Chúng ta cũng phải nghĩ đến những người tiêu quá tay và những người lớn tuổi không quen dùng máy móc. Một xã hội có thể dùng cả tiền mặt lẫn thanh toán không tiền mặt là điều quan trọng."],"vocab":["tiền mặt","trả tiền, thanh toán","tăng lên","tiền lẻ","quản lý","ghi chép, lịch sử","mất điện","máy móc","người lớn tuổi","xã hội"],"grammar":[{"t":"〜なくてもいい","note":"Diễn tả \"không cần làm ~ cũng được\". Ví dụ: 「レジで小銭を探さなくてもいいからです」"},{"t":"〜かもしれません","note":"Diễn tả \"có lẽ ~, có thể ~\". Ví dụ: 「払えなくなるかもしれません」"},{"t":"〜なければなりません","note":"Diễn tả \"phải làm ~\". Ví dụ: 「お年寄りのことも考えなければなりません」"},{"t":"動詞ます形+すぎる","note":"Diễn tả \"làm quá mức, quá ~\". Ví dụ: 「使いすぎる人」"}]},"a-n2-7-n3":{"title":"Có chuẩn bị thì không lo","topic":"Đời sống","trans":["Nhật Bản được biết đến là đất nước có nhiều thiên tai như động đất, bão. Chính vì thiên tai không biết bao giờ xảy ra nên việc chuẩn bị sẵn từ ngày thường là rất quan trọng.","Trước hết, hãy bắt đầu từ những việc có thể làm ở nhà. Nếu chuẩn bị sẵn nước, thức ăn, đèn pin v.v., bạn sẽ yên tâm khi có chuyện xảy ra. Hãy cố gắng để những thứ này ở nơi có thể mang đi ngay.","Bạn cũng đừng quên bàn bạc trước với gia đình, vì khi có thiên tai, các thành viên trong nhà có thể bị lạc nhau. Chỉ cần quyết định trước sẽ tập trung ở đâu, bạn sẽ có thể hành động mà không hoảng loạn. Ngoài ra, biết trước những nơi nguy hiểm trong khu vực mình sống cũng rất hữu ích. Hãy xem bản đồ do ủy ban thành phố v.v. phát và xác nhận trước đường đến nơi lánh nạn.","Dù không thể ngăn chặn bản thân thiên tai, chúng ta vẫn có thể giảm thiệt hại. Nhờ sự chú ý nhỏ bé trong ngày thường, bạn có thể bảo vệ mình và gia đình khi có chuyện xảy ra."],"vocab":["thiên tai","ngày thường, thường ngày","chuẩn bị, phòng bị","chuẩn bị, sẵn sàng","đèn pin","mang đi, đem ra ngoài","bị lạc, thất lạc","nơi lánh nạn","thiệt hại","sự để tâm, sự chú ý"],"grammar":[{"t":"〜だからこそ","note":"Diễn đạt ý \"chính vì như vậy nên càng...\", dùng để nhấn mạnh lý do. Ví dụ: 「いつ起こるか分からない災害だからこそ、日ごろから備えておくことが大切です」."},{"t":"〜ておく","note":"Diễn đạt việc làm sẵn một điều gì đó từ trước để chuẩn bị cho sau này. Ví dụ: 「水や食料、懐中電灯などを用意しておくと、いざというときに安心です」."},{"t":"〜ようにする","note":"Diễn đạt việc cố gắng tạo thói quen hoặc cố gắng làm điều gì đó. Ví dụ: 「すぐに持ち出せる場所に置いておくようにしましょう」."},{"t":"〜によって","note":"Diễn đạt phương tiện hoặc nguyên nhân, nghĩa là \"nhờ vào, bằng cách\". Ví dụ: 「ふだんのちょっとした心がけによって、いざというときに自分や家族を守ることができるのです」."}]},"a-n2-7-n4":{"title":"Hãy chuẩn bị cho thiên tai","topic":"Đời sống","trans":["Nhật Bản là đất nước có nhiều thiên tai như động đất, bão. Vì không biết khi nào sẽ xảy ra nên việc chuẩn bị sẵn từ ngày thường là rất quan trọng.","Trước hết, hãy bắt đầu từ những việc có thể làm ở nhà. Chuẩn bị sẵn nước, thức ăn và đèn pin sẽ giúp bạn yên tâm hơn. Hãy để ở nơi có thể mang ra ngoài ngay. Bạn cũng nên bàn bạc với gia đình và quyết định trước nơi tập trung khi bị lạc nhau.","Việc biết trước những nơi nguy hiểm trong khu phố mình sống cũng rất quan trọng. Hãy xem bản đồ của ủy ban thành phố và xác nhận trước đường đến nơi lánh nạn. Dù không thể ngăn chặn thiên tai, chúng ta vẫn có thể giảm thiệt hại. Sự để tâm nhỏ bé trong ngày thường sẽ bảo vệ bạn và gia đình."],"vocab":["động đất","bão","chuẩn bị","quan trọng, quý giá","yên tâm","chuẩn bị, sắm sẵn","bàn bạc, thảo luận","quyết định","nguy hiểm","nơi lánh nạn"],"grammar":[{"t":"〜ておく","note":"Diễn đạt việc làm sẵn một điều gì đó từ trước. Ví dụ: 「ふだんから準備しておくことが大切です」「決めておきましょう」."},{"t":"〜ので","note":"Diễn đạt nguyên nhân, lý do, nghe nhẹ nhàng hơn「から」. Ví dụ: 「いつ来るか分からないので、ふだんから準備しておくことが大切です」."},{"t":"〜ましょう","note":"Rủ người khác cùng làm hoặc đưa ra gợi ý. Ví dụ: 「まず、家でできることから始めましょう」."},{"t":"〜ても/〜ことができる","note":"「〜ても」nghĩa là \"dù... cũng...\"; 「ことができる」nghĩa là \"có thể làm được\". Ví dụ: 「災害は防げなくても、被害を少なくすることはできます」."}]},"a-n3-1-n2":{"title":"Sự tiện lợi của cửa hàng tiện lợi trong cuộc sống","topic":"Đời sống","trans":["Cửa hàng tiện lợi ở Nhật mở cửa 24 giờ, và sự thoải mái khi có thể dùng bất cứ lúc nào là một sức hút lớn. Không chỉ đồ ăn thức uống, bạn còn mua được cả tạp chí và đồ dùng hằng ngày, nên hầu như mọi thứ cần thiết cho cuộc sống đều có thể mua đủ ở một chỗ. Có thể nói đây không đơn thuần là cửa hàng thực phẩm, mà là một tiện ích gần gũi hỗ trợ cuộc sống.","Ngoài ra, bạn còn có thể làm xong những thủ tục không thể thiếu trong cuộc sống như thanh toán hóa đơn điện nước hay gửi hàng. Vì có đặt máy ATM của ngân hàng, bất cứ khi nào cần bạn cũng có thể rút tiền. Cửa hàng còn có máy photocopy và máy đặt vé, nên vai trò của cửa hàng không chỉ dừng lại ở việc mua sắm.","Nhờ những dịch vụ ngày càng đầy đủ này, cửa hàng tiện lợi đã trở thành một phần không thể thiếu trong cuộc sống của chúng ta. Với những người bận rộn, không có thời gian, có một nơi để giải quyết việc trong thời gian ngắn là một sự giúp đỡ rất lớn. Ngày nay, chắc hẳn không ít người cảm thấy thậm chí khó mà tưởng tượng nổi cuộc sống không có cửa hàng tiện lợi.","Tuy nhiên, đằng sau sự tiện lợi ấy là những vấn đề như nỗi vất vả của những người làm việc 24 giờ và lãng phí thực phẩm. Cửa hàng lúc nào cũng mở cửa cũng đồng nghĩa với việc ban đêm vẫn phải có người liên tục làm việc. Chúng ta thường dễ xem sự tiện lợi là điều đương nhiên, nhưng nó chỉ có được nhờ nỗ lực của rất nhiều người. Chúng ta không nên chỉ hưởng thụ sự tiện lợi, mà cũng nên hướng sự quan tâm đến những người đang vận hành hệ thống đó."],"vocab":["sự đơn giản, dễ dàng, nhẹ nhàng","hóa đơn dịch vụ công cộng (điện, nước, gas…)","gửi đi, vận chuyển","thủ tục","lắp đặt, bố trí","đầy đủ, hoàn thiện","không thể thiếu","lãng phí thực phẩm","đương nhiên, hiển nhiên","hỗ trợ, nâng đỡ"],"grammar":[{"t":"〜にとどまらない","note":"Nghĩa là \"không chỉ giới hạn ở ~\", phạm vi rộng hơn người ta nghĩ. Ví dụ: 「店の役割は買い物だけにとどまらない」."},{"t":"〜といった","note":"Dùng để nêu ví dụ tiêu biểu, nghĩa là \"những ~ như là...\". Ví dụ: 「食品ロスといった問題が隠れている」."},{"t":"〜がちだ","note":"Gắn vào thể ます của động từ (bỏ ます), chỉ xu hướng dễ xảy ra điều không tốt, nghĩa là \"hay ~, dễ ~\". Ví dụ: 「便利さを当たり前のものと考えがちだ」."},{"t":"〜て初めて","note":"Nghĩa là \"phải sau khi ~ thì mới (lần đầu) ~\", nhấn mạnh vế trước là điều kiện cần. Ví dụ: 「多くの人の努力があって初めて成り立っている」."}]},"a-n3-1-n4":{"title":"コンビニのべんりさ","topic":"Đời sống","trans":["Cửa hàng tiện lợi ở Nhật mở cửa 24 giờ nên rất tiện.","Không chỉ đồ ăn thức uống, bạn còn mua được cả tạp chí và đồ dùng hằng ngày. Ngoài ra, bạn còn có thể thanh toán hóa đơn điện nước và gửi hàng.","Vì cũng có máy ATM của ngân hàng nên lúc nào bạn cũng rút tiền được. Còn có máy photocopy và máy đặt vé. Nhờ những dịch vụ này, cửa hàng tiện lợi đã trở thành một phần quan trọng trong cuộc sống của chúng ta.","Nhưng đằng sau sự tiện lợi cũng có vấn đề. Những người làm việc 24 giờ rất vất vả. Còn có vấn đề lãng phí thực phẩm, tức là đồ ăn bị bỏ phí. Mình muốn đừng xem sự tiện lợi là điều đương nhiên, mà cũng nghĩ đến những người đang làm việc ở đó."],"vocab":["tiện lợi","tạp chí","đồ dùng hằng ngày","hóa đơn dịch vụ công cộng (điện, nước, gas…)","hành lý, hàng hóa, bưu kiện","đặt trước","máy móc","quan trọng, quý giá","vấn đề","lãng phí thực phẩm"],"grammar":[{"t":"〜ので","note":"Chỉ nguyên nhân, lý do, nghe nhẹ nhàng hơn「から」. Ví dụ: 「銀行のATMもあるので、いつでもお金をおろせます」"},{"t":"〜たり、〜たりする","note":"Liệt kê vài hành động hoặc sự việc. Ví dụ: 「公共料金をはらったり、荷物を送ったりもできます」"},{"t":"Thể khả năng (〜られる/〜える)","note":"Diễn tả \"có thể làm ~\". Ví dụ: 「雑誌や日用品も買えます」「お金をおろせます」"},{"t":"〜ないで","note":"Nghĩa là \"không làm ~ mà làm...\". Ví dụ: 「べんりさを当たり前だと思わないで、はたらく人のことも考えたいです」"}]},"a-n3-8-n2":{"title":"Quy trình đi khám bệnh ở Nhật","topic":"Cuộc sống","trans":["Lần đầu bị sốt khi đến Nhật, mình không biết phải xử lý thế nào nên cảm thấy rất lo lắng. Khi cơ thể không khỏe ở một nơi xa lạ, cảm giác bơ vơ thường còn lớn hơn cả bản thân căn bệnh. Mình hỏi một người bạn thì được khuyên: 「まず近くの内科に行ったほうがいいよ」.","Ở bệnh viện, quy trình thông thường là đưa thẻ bảo hiểm ở quầy tiếp nhận trước, rồi ghi triệu chứng vào phiếu khám. Khi khám, bạn sẽ bị hỏi những câu như 「いつから痛いですか」, 「アレルギーはありますか」. Nội dung câu hỏi đại khái là cố định, nên nếu nghĩ sẵn câu trả lời từ trước thì bạn sẽ không bị cuống.","Khám xong, bạn sẽ nhận đơn thuốc, rồi cầm đơn đến hiệu thuốc để lấy thuốc. Lúc đầu có thể bạn thấy có nhiều bước, nhưng chỉ cần trải qua một lần là không còn khó nữa. Khoản chi phí mình lo nhất cũng rẻ hơn nhiều so với dự đoán. Đó là vì nếu đã tham gia bảo hiểm, phần bạn tự trả ở bệnh viện chỉ là ba phần mười.","Nếu không tự tin về ngôn ngữ, bạn có thể viết triệu chứng ra giấy rồi đưa cho bác sĩ xem. Cách truyền đạt ý mình không nhất thiết chỉ có nói. Dù không nói trôi chảy thì vẫn có rất nhiều cách để truyền đạt, nên bạn không cần quá lo lắng."],"vocab":[{"w":"対処","m":"đối phó, xử lý"},{"w":"心細い","m":"bơ vơ, lo lắng, không có chỗ dựa"},{"w":"体調を崩す","m":"trong người không khỏe, bị ốm"},{"w":"問診票","m":"phiếu khám bệnh (điền triệu chứng)"},{"w":"症状","m":"triệu chứng"},{"w":"慌てる","m":"cuống lên, hoảng hốt"},{"w":"処方箋","m":"đơn thuốc"},{"w":"加入","m":"tham gia, đăng ký (bảo hiểm)"},{"w":"自己負担","m":"phần tự chi trả"},{"w":"手段","m":"phương tiện, cách thức"}],"grammar":[{"t":"〜たところ","note":"Diễn tả sau khi làm một việc thì có kết quả hoặc phát hiện nào đó. Ví dụ: 「友達に相談したところ、『まず近くの内科に行ったほうがいいよ』とアドバイスをもらった」."},{"t":"〜といった","note":"Dùng để liệt kê ví dụ, nghĩa là \"những ~ như là ~\". Ví dụ: 「『いつから痛いですか』『アレルギーはありますか』といった質問をされる」."},{"t":"〜ずに済む","note":"Diễn tả việc không cần làm gì đó mà vẫn ổn, tránh được kết quả không hay. Ví dụ: 「事前に答えを考えておけば慌てずに済む」."},{"t":"〜とは限らない","note":"Nghĩa là \"không hẳn là ~\", phủ định một phần. Ví dụ: 「意思を伝える手段は、話すことだけとは限らない」."}]},"a-n3-8-n4":{"title":"Đi khám bệnh ở Nhật","topic":"Cuộc sống","trans":["Lần đầu bị sốt ở Nhật, mình không biết phải làm sao nên rất lo lắng. Mình hỏi một người bạn thì bạn bảo: 「近くの内科に行ったほうがいいよ」.","Ở bệnh viện, trước tiên bạn đưa thẻ bảo hiểm và ghi triệu chứng ra giấy. Bác sĩ sẽ hỏi bạn 「いつから痛いですか」 hoặc 「アレルギーはありますか」. Khám xong, bạn sẽ nhận một tờ giấy gọi là đơn thuốc. Bạn cầm tờ giấy đó đến hiệu thuốc để lấy thuốc.","Chi phí bệnh viện rẻ hơn mình nghĩ. Vì nếu có bảo hiểm thì bạn chỉ phải tự trả ba phần mười. Nếu lo về ngôn ngữ, bạn chỉ cần viết triệu chứng ra giấy rồi đưa cho bác sĩ xem là được. Có rất nhiều cách để truyền đạt, nên bạn không cần lo đâu."],"vocab":[{"w":"熱","m":"sốt, nhiệt độ cơ thể"},{"w":"不安","m":"lo lắng, bất an"},{"w":"内科","m":"khoa nội"},{"w":"保険証","m":"thẻ bảo hiểm"},{"w":"症状","m":"triệu chứng"},{"w":"診察","m":"khám bệnh"},{"w":"薬局","m":"hiệu thuốc"},{"w":"受け取る","m":"nhận, lấy"},{"w":"料金","m":"chi phí, phí"},{"w":"伝える","m":"truyền đạt"}],"grammar":[{"t":"〜たほうがいい","note":"Dùng để đưa ra lời khuyên, nghĩa là \"nên làm ~\". Ví dụ: 「近くの内科に行ったほうがいいよ」. Đi với động từ thể た."},{"t":"〜たら","note":"Diễn tả \"sau khi làm xong ~\" hoặc \"nếu ~\". Ví dụ: 「診察が終わったら、処方箋という紙をもらいます」."},{"t":"〜ば(〜ていれば)","note":"Diễn tả điều kiện \"nếu ~ thì\". Ví dụ: 「保険に入っていれば、自分で払うのは三割だけだからです」."},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do với sắc thái nhẹ nhàng hơn. Ví dụ: 「伝える方法はたくさんあるので、心配しなくても大丈夫です」."}]},"a-n3-9-n2":{"title":"Quy trình tìm phòng ở Nhật và những điều cần lưu ý","topic":"Cuộc sống","trans":["Thuê nhà ở Nhật là một việc tốn nhiều công sức hơn nhiều so với những gì nhiều người nước ngoài tưởng tượng. Đầu tiên, bạn phải đến công ty môi giới bất động sản, nói với nhân viên phụ trách về ngân sách tiền thuê và khu vực mong muốn, thủ tục bắt đầu từ đây. Chỉ cần thêm điều kiện \"đi bộ trong vòng 10 phút từ ga\" là tiền thuê sẽ tăng vọt theo.","Dù đã tìm được phòng ưng ý, bạn cũng không thể quyết định ký hợp đồng ngay tại chỗ. Vì khi vào ở, bạn phải chuẩn bị sẵn một khoản tiền khá lớn như tiền đặt cọc, tiền lễ, phí môi giới... Với người nước ngoài, việc bị yêu cầu có người bảo lãnh khi ký hợp đồng không phải là hiếm. Gần đây, thay vì người bảo lãnh, việc dùng công ty bảo lãnh đã trở nên phổ biến, và khi ký hợp đồng bạn phải trả khoảng một nửa tháng tiền thuê.","Để vượt qua vòng xét duyệt, tốt nhất bạn nên chuẩn bị sẵn các giấy tờ có thể xác nhận nơi làm việc và thu nhập. Khi đi xem phòng, bạn không chỉ nên kiểm tra ánh sáng và tiếng ồn mà còn nên xem cả chỗ đặt máy giặt và số lượng ổ cắm. Chính những điều không thể biết qua ảnh mới là lý do khiến việc đích thân đến xem trở nên có ý nghĩa.","Những bước này có thể khiến người lần đầu trải qua cảm thấy phiền phức. Tuy nhiên, chỉ cần biết trước quy trình thì gánh nặng chuẩn bị sẽ khác đi rất nhiều. Vì vậy, lần chuyển nhà tiếp theo, bạn hẳn sẽ tìm phòng nhẹ nhàng hơn lần này nhiều."],"vocab":["công ty môi giới bất động sản","tiền thuê nhà","tiền đặt cọc","tiền lễ (tiền cảm ơn chủ nhà)","phí môi giới","người bảo lãnh","xét duyệt","xem phòng","ánh sáng mặt trời, hướng nắng","tiếng ồn"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「条件を加えると、それに伴って家賃は一気に高くなってしまう」"},{"t":"〜わけにはいかない","note":"Diễn tả không thể làm điều gì đó vì lý lẽ hay hoàn cảnh. Ví dụ: 「その場ですぐに契約を決めるわけにはいかない」"},{"t":"〜にあたって","note":"Diễn tả vào lúc, nhân dịp làm việc gì đó, thường dùng trong văn cảnh trang trọng. Ví dụ: 「契約にあたって保証人を求められることが少なくない」"},{"t":"〜こそ","note":"Nhấn mạnh từ đứng trước, nghĩa là \"chính là điều này\". Ví dụ: 「写真ではわからない部分こそ、実際に足を運んで見る意味があるといえる」"}]},"a-n3-12-n2":{"title":"Quy tắc cơ bản khi viết email công việc","topic":"Công sở","trans":["Khi làm việc tại công ty Nhật, việc nắm được các quy tắc cơ bản khi viết email là điều không thể thiếu. Khác với điện thoại, email có ưu điểm là đối phương có thể đọc vào lúc thuận tiện, nhưng mặt khác, tùy cách viết mà có thể để lại ấn tượng thiếu lịch sự. Vì vậy, nhân viên mới thường quan sát kỹ cách viết của các anh chị đi trước và dần dần học theo.","Trước hết, tiêu đề cần ngắn gọn để nhìn qua là hiểu ngay nội dung. Chỉ viết 「会議の件」 là chưa đủ, viết cụ thể như 「来週の会議の日程について」 sẽ dễ truyền đạt hơn. Nếu tiêu đề khó hiểu, khi đối phương bận thì email có nguy cơ bị bỏ sót. Tuy nhiên, tiêu đề không phải cứ dài là tốt, mà cũng cần khéo léo viết sao cho ngắn gọn.","Phần mở đầu thường dùng lời chào 「お世話になっております」. Đây là cách nói thể hiện lòng cảm ơn đối với mối quan hệ với đối phương, có thể dùng cho cả người ngoài công ty lẫn người trong công ty. Với người liên lạc lần đầu, đôi khi cũng dùng cách nói như 「はじめてご連絡いたします」. Phần nội dung chính đòi hỏi phải viết lịch sự bằng những câu ngắn để truyền đạt chính xác việc cần trao đổi.","Cuối email, nhiều người kết thúc bằng câu 「よろしくお願いいたします」. Chỉ cần có câu này, toàn bộ bài viết sẽ tạo ấn tượng lịch sự và đối phương cũng đọc một cách dễ chịu. Ngoài ra, khi nhận được email thì trả lời càng sớm càng tốt cũng là một quy tắc ứng xử quan trọng. Ngay cả khi chưa thể trả lời ngay, chỉ cần gửi trước một câu như 「確認して後日ご連絡します」 là đối phương sẽ yên tâm."],"vocab":["không thể thiếu","sự thuận tiện, hoàn cảnh","ấn tượng","ngắn gọn, súc tích","bỏ sót, nhìn sót","sự khéo léo, công sức suy nghĩ","việc cần làm, nội dung công việc","được yêu cầu, được kỳ vọng","kết thúc, khép lại","trả lời thư, hồi âm"],"grammar":[{"t":"〜うえで","note":"Diễn tả \"trong quá trình/về mặt làm việc gì đó\", phía sau thường là điều quan trọng hoặc cần thiết. Ví dụ: 「日本の会社で働くうえで、メールの書き方の基本的なルールを知っておくことは欠かせません」"},{"t":"〜反面","note":"Diễn tả cùng một sự việc có hai mặt trái ngược nhau: \"tuy… nhưng mặt khác…\". Ví dụ: 「相手の都合のよい時間に読んでもらえる反面、書き方次第では失礼な印象を与えかねません」"},{"t":"〜かねない","note":"Gắn vào thể ます của động từ bỏ ます, diễn tả \"có thể dẫn đến kết quả xấu\". Ví dụ: 「書き方次第では失礼な印象を与えかねません」"},{"t":"〜とは限らない","note":"Diễn tả \"không nhất thiết…\", phủ định suy nghĩ quá tuyệt đối. Ví dụ: 「件名は長ければ長いほどよいとは限らず、短くまとめる工夫も必要です」"}]},"a-n3-12-n4":{"title":"Những điều cơ bản về email công việc","topic":"Công sở","trans":["Khi làm việc tại công ty Nhật, có một số quy tắc cơ bản khi viết email. Email rất tiện vì đối phương có thể đọc vào lúc thuận tiện cho họ. Nếu viết sai cách, bạn có thể bị cho là thất lễ, nên nhân viên mới sẽ học hỏi từ các anh chị đi trước.","Trước hết, tiêu đề nên viết ngắn gọn để nhìn qua là hiểu nội dung, điều này rất quan trọng. Thay vì chỉ viết 「会議の件」, bạn nên viết 「来週の会議の日程について」. Nếu tiêu đề khó hiểu, đối phương đang bận có thể sẽ không đọc email.","Đầu email, người ta thường dùng câu 「お世話になっております」. Đây là lời thể hiện lòng biết ơn, có thể dùng cho cả người ngoài công ty và người trong công ty. Nhiều người kết thúc email bằng 「よろしくお願いいたします」. Khi nhận được email, trả lời càng sớm càng tốt cũng là một quy tắc ứng xử quan trọng. Ngay cả khi chưa thể trả lời ngay, chỉ cần gửi một câu như 「確認してあとで連絡します」 là đối phương sẽ yên tâm."],"vocab":["tiêu đề (của email)","lịch trình, kế hoạch","quan trọng","thất lễ, bất lịch sự","nhân viên mới","sự thuận tiện (về thời gian), hoàn cảnh","cảm ơn, lòng biết ơn","bên ngoài công ty","trả lời, hồi đáp","yên tâm"],"grammar":[{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do với giọng điệu nhẹ nhàng hơn. Ví dụ: 「相手が都合のいい時間に読めるので便利です」"},{"t":"〜ように","note":"Diễn tả mục đích hoặc trạng thái \"để…\". Ví dụ: 「一目で内容がわかるように、短く書くことが大切です」"},{"t":"〜と(điều kiện)","note":"Diễn tả \"hễ… thì…\", thường theo sau là kết quả hoặc lời khuyên. Ví dụ: 「件名がわかりにくいと、忙しい相手はメールを読まないかもしれません」"},{"t":"〜たら","note":"Diễn tả \"nếu/sau khi… thì…\", nói về hành động sau khi làm xong việc gì đó. Ví dụ: 「メールをもらったら、できるだけ早く返事をするのも大切なマナーです」"}]},"a-n4-2-n2":{"title":"Quy tắc ứng xử trên tàu điện và cách nghĩ của người Nhật","topic":"Đời sống","trans":["Bên trong tàu điện ở Nhật yên tĩnh đến mức gần như không nghe thấy tiếng trò chuyện. Phần lớn hành khách đọc sách, xem điện thoại hoặc nhắm mắt nghỉ ngơi, mỗi người một cách thoải mái. Mọi người vừa để ý đến xung quanh, vừa lặng lẽ tận hưởng khoảng thời gian riêng của mình.","Đặc biệt, việc gọi điện thoại trên tàu thường bị coi là vi phạm quy tắc ứng xử. Nếu thật sự muốn nói chuyện, bạn đành phải xuống tàu trước rồi mới gọi. Ngoài ra, gần ghế ưu tiên, đôi khi hành khách còn được yêu cầu tắt nguồn điện thoại di động. Lý do là vì điện thoại có thể ảnh hưởng đến các thiết bị y tế như máy tạo nhịp tim.","Đằng sau những quy tắc này là cách nghĩ của người Nhật: \"không làm phiền người xung quanh\". Có thể nói đó là một thói quen dựa trên sự quan tâm dành cho nhau hơn là một quy định được viết thành văn bản. Việc hình dung hành động của mình ảnh hưởng thế nào đến những người xung quanh chính là điểm xuất phát của cách nghĩ này.","Những quy tắc này là điều không thể thiếu để nhiều người có thể đi tàu một cách thoải mái. Điều quan trọng là không chỉ ưu tiên sự tiện lợi của bản thân, mà còn nghĩ đến những người xung quanh rồi mới hành động. Làm như vậy thì không gian mà ai cũng thấy dễ chịu sẽ được duy trì."],"vocab":[{"w":"思い思い","m":"mỗi người một kiểu, tùy ý thích của mình"},{"w":"周囲","m":"xung quanh, những người xung quanh"},{"w":"違反","m":"vi phạm"},{"w":"見なされる","m":"bị coi là, bị xem là"},{"w":"電源","m":"nguồn điện"},{"w":"おそれ","m":"nguy cơ, khả năng (xảy ra điều không hay)"},{"w":"背景","m":"bối cảnh, nền tảng phía sau"},{"w":"迷惑","m":"phiền phức, làm phiền"},{"w":"明文化","m":"văn bản hóa, viết thành quy định rõ ràng"},{"w":"欠かせない","m":"không thể thiếu"}],"grammar":[{"t":"〜ざるを得ない","note":"Diễn tả việc bất đắc dĩ phải làm, không có lựa chọn nào khác. Ví dụ: 「どうしても話したいときは、いったん電車を降りてからかけざるを得ません」"},{"t":"〜というより","note":"Nghĩa là \"nói là… thì đúng hơn là…\", dùng để điều chỉnh lại cách diễn đạt. Ví dụ: 「明文化されたルールというより、お互いへの思いやりに基づいた習慣だと言えます」"},{"t":"〜おそれがある","note":"Diễn tả khả năng xảy ra điều không tốt, thường dùng trong văn viết. Ví dụ: 「ペースメーカーなどの医療機器に影響を与えるおそれがあるからです」"},{"t":"〜に基づく","note":"Nghĩa là \"dựa trên…, căn cứ vào…\". Ví dụ: 「お互いへの思いやりに基づいた習慣だと言えます」"}]},"a-n4-2-n3":{"title":"Quy tắc ứng xử trên tàu điện","topic":"Đời sống","trans":["Người ta nói rằng so với các nước khác, bên trong tàu điện ở Nhật rất yên tĩnh. Nhiều người dành thời gian trên tàu để đọc sách, xem điện thoại hoặc nhắm mắt nghỉ ngơi.","Gọi điện thoại trên tàu được xem là vi phạm quy tắc ứng xử. Nếu thật sự muốn nói chuyện, thông thường người ta sẽ xuống tàu ở ga rồi mới gọi. Ngoài ra, gần ghế ưu tiên, đôi khi hành khách còn được nhờ tắt nguồn điện thoại di động. Vì điện thoại có thể ảnh hưởng đến các thiết bị y tế như máy tạo nhịp tim.","Đằng sau những quy tắc này là cách nghĩ của người Nhật: \"không làm phiền người xung quanh\". Mọi người tuân thủ không phải chỉ vì đó là luật, mà đúng hơn là xuất phát từ sự quan tâm dành cho nhau. Như vậy, toa tàu yên tĩnh được tạo nên nhờ sự chu đáo với những người xung quanh.","Những quy tắc này là để nhiều người có thể đi tàu một cách dễ chịu. Nếu không chỉ nghĩ cho bản thân mà còn nghĩ đến những người xung quanh khi hành động, chắc hẳn ai cũng sẽ thấy thoải mái."],"vocab":[{"w":"違反","m":"vi phạm, đi ngược lại"},{"w":"優先席","m":"ghế ưu tiên"},{"w":"電源","m":"nguồn điện"},{"w":"医療機器","m":"thiết bị y tế"},{"w":"影響","m":"ảnh hưởng"},{"w":"背景","m":"bối cảnh, nền tảng phía sau"},{"w":"迷惑","m":"phiền phức, làm phiền"},{"w":"思いやり","m":"sự quan tâm, sự đồng cảm"},{"w":"気づかい","m":"sự chu đáo, sự quan tâm để ý"},{"w":"快適","m":"thoải mái, dễ chịu"}],"grammar":[{"t":"〜ように(お願い・要求)","note":"Diễn tả nội dung của lời nhờ vả hoặc yêu cầu. Ví dụ: 「携帯電話の電源を切るようにお願いされる場合もあります」"},{"t":"〜というより","note":"Nghĩa là \"nói là… thì đúng hơn là…\". Ví dụ: 「ルールだからというより、お互いへの思いやりから守られているのです」"},{"t":"〜によって","note":"Diễn tả nguyên nhân, phương tiện hoặc căn cứ (\"nhờ, bởi, do\"). Ví dụ: 「周りへの気づかいによって作られているのです」"},{"t":"〜ための+名詞","note":"Diễn tả mục đích, bổ nghĩa cho danh từ phía sau (\"để, dành cho\"). Ví dụ: 「たくさんの人が気持ちよく電車を利用するためのものです」"}]},"a-n4-9-n2":{"title":"Điều tôi nhận ra sau khi đi khám nha sĩ","topic":"Cuộc sống","trans":["Từ ba ngày trước tôi bắt đầu bị đau răng. Dù vậy, tôi cũng không thể cứ để mặc như thế nên đã đặt lịch hẹn ở một phòng nha gần nhà. Khi đưa thẻ bảo hiểm ở quầy lễ tân, tôi được yêu cầu điền vào phiếu khám bệnh trước. Tôi lần lượt trả lời các mục như cơn đau bắt đầu từ khi nào, răng có bị ê buốt khi ăn đồ lạnh không.","Sau khi khám, bác sĩ nói: 「虫歯が一本ありますね」, rồi vừa cho tôi xem phim X-quang vừa giải thích tình trạng răng. Hôm nay bác sĩ chỉ mài phần bị tổn thương và đặt thuốc vào, rồi dặn tôi tuần sau quay lại thêm một lần. Biết được nguyên nhân nên tôi thấy nhẹ nhõm, nhưng nghe nói một lần không điều trị xong thì tôi cũng thấy hơi tiếc.","Điều trị xong, tôi còn được hướng dẫn cách đánh răng. Nghe nói nếu dùng lực mạnh và chải quá mạnh thì ngược lại có thể làm tổn thương nướu. Biết rằng thói quen mà mình làm vô thức mỗi ngày thực ra có thể phản tác dụng, tôi rất ngạc nhiên.","Ở nha khoa Nhật, bạn buộc phải đến khám nhiều lần, nhưng đổi lại, mỗi lần điều trị đều được làm rất cẩn thận. Tuy việc đi lại đúng là khá tốn công, nhưng tôi cảm thấy việc điều trị cẩn thận có giá trị không gì thay thế được. Qua trải nghiệm lần này, tôi thấm thía rằng không nên đợi đến khi đau rồi mới cuống cuồng chạy đi khám, mà nên hành động trước khi triệu chứng xuất hiện. Tôi nghĩ ít nhất mỗi nửa năm đi kiểm tra một lần là cách tốt nhất để không phải chịu đau."],"vocab":[{"w":"放っておく","m":"để mặc, bỏ mặc"},{"w":"保険証","m":"thẻ bảo hiểm"},{"w":"提示","m":"xuất trình, đưa ra"},{"w":"問診票","m":"phiếu khám bệnh (phiếu hỏi bệnh)"},{"w":"患部","m":"vùng bị bệnh, vùng tổn thương"},{"w":"指導","m":"hướng dẫn, chỉ dẫn"},{"w":"傷める","m":"làm tổn thương, làm hỏng"},{"w":"逆効果","m":"phản tác dụng"},{"w":"通院","m":"đi khám bệnh định kỳ, đến bệnh viện/phòng khám"},{"w":"痛感","m":"thấm thía, cảm nhận sâu sắc"}],"grammar":[{"t":"〜ものの","note":"Nghĩa là 「tuy... nhưng...」, hai vế đối lập nhau. Ví dụ: 「三日前から歯が痛み始めたものの、放っておくわけにもいかず」."},{"t":"〜かねない","note":"Gắn vào thể ます của động từ bỏ ます, nghĩa là 「có thể xảy ra (chuyện không hay)」. Ví dụ: 「実は逆効果になりかねないと知り」."},{"t":"〜ざるを得ない","note":"Nghĩa là 「buộc phải...」, mang sắc thái bất đắc dĩ. Ví dụ: 「何度も通院せざるを得ませんが」."},{"t":"〜とはいえ","note":"Nghĩa là 「tuy nói là... nhưng」, thừa nhận vế trước rồi nêu quan điểm ở vế sau. Ví dụ: 「通う手間は確かに大きいとはいえ」."}]},"a-n4-9-n3":{"title":"Ngày đi khám nha sĩ","topic":"Cuộc sống","trans":["Vì từ ba ngày trước tôi bắt đầu bị đau răng nên đã đặt lịch hẹn ở một phòng nha gần nhà. Khi đưa thẻ bảo hiểm ở quầy lễ tân, tôi được yêu cầu điền vào phiếu khám bệnh. Tôi viết những thông tin như đau từ khi nào, răng có bị ê buốt khi ăn đồ lạnh không.","Bác sĩ nói: 「虫歯が一本ありますね」, rồi cho tôi xem phim X-quang. Hôm nay chỉ mài phần răng sâu và đặt thuốc vào, bác sĩ dặn tuần sau quay lại thêm một lần nữa.","Sau khi điều trị xong, tôi còn được chỉ cách đánh răng. Nghe nói nếu dùng lực mạnh và chải quá mạnh thì đôi khi sẽ làm tổn thương nướu. Tôi biết rằng ngay cả việc đánh răng mỗi ngày cũng có cách làm đúng.","Ở nha khoa Nhật, bạn phải đi khám nhiều lần. Tuy nhiên, đổi lại mỗi lần đều được điều trị cẩn thận nên rất yên tâm. Thay vì đợi đến khi đau rồi mới cuống lên, tôi nghĩ nên đi kiểm tra nửa năm một lần. Từ giờ tôi sẽ đi khám nha sĩ sớm hơn."],"vocab":[{"w":"予約","m":"đặt lịch hẹn, đặt trước"},{"w":"受付","m":"quầy lễ tân"},{"w":"記入","m":"điền vào, ghi vào"},{"w":"問診票","m":"phiếu khám bệnh (phiếu hỏi bệnh)"},{"w":"虫歯","m":"răng sâu"},{"w":"削る","m":"mài, bào, cạo bớt"},{"w":"傷める","m":"làm tổn thương, làm hỏng"},{"w":"丁寧","m":"cẩn thận, tỉ mỉ, lịch sự"},{"w":"慌てる","m":"cuống lên, hoảng hốt"},{"w":"検診","m":"kiểm tra sức khỏe, khám định kỳ"}],"grammar":[{"t":"〜ように言われる","note":"Diễn đạt việc bị yêu cầu hoặc chỉ thị làm gì đó, dùng để trích dẫn gián tiếp. Ví dụ: 「問診票に記入するように言われました」"},{"t":"〜について","note":"Nghĩa là 「về...」, dùng để nêu chủ đề. Ví dụ: 「歯みがきの仕方についても教えてもらいました」"},{"t":"〜ぶん","note":"Nghĩa là 「đổi lại, tương ứng với mức đó」, chỉ lợi ích hay kết quả tương xứng nhờ tình huống ở vế trước. Ví dụ: 「そのぶん一回ずつ丁寧に治療してくれる」"},{"t":"〜ことにする","note":"Diễn đạt việc bản thân quyết định làm gì đó. Ví dụ: 「これからは早めに歯医者へ行くことにします」"}]},"a-n4-8-n2":{"title":"Quy trình làm thủ tục tại văn phòng quận","topic":"Cuộc sống","trans":["Ở Nhật, khi chuyển nhà, bạn phải đến văn phòng quận trong vòng mười bốn ngày để khai báo về địa chỉ. Tôi nói ở quầy: 「転入届を出したいのですが」 và nhận được một tấm phiếu số thứ tự. Phát phiếu số là cơ chế để xử lý theo thứ tự, nên ngay cả vào khung giờ đông người cũng khó bị hỗn loạn.","Cho đến khi được gọi tên, tôi đành phải ngồi ghế chờ, nhưng tôi tranh thủ điền sẵn địa chỉ và ngày tháng năm sinh vào giấy tờ. Khi đến lượt và đi tới quầy, nhân viên kiểm tra thẻ cư trú rồi ghi địa chỉ mới vào mặt sau giúp tôi. Thẻ cư trú là giấy tờ quan trọng để chứng minh thân phận, nên việc địa chỉ mới được ghi chính xác là rất quan trọng.","Trong cùng ngày, bạn cũng có thể làm xong thủ tục bảo hiểm y tế quốc dân, nhưng vì quầy phụ trách khác nhau nên tôi đã di chuyển từ tầng một lên tầng hai. Việc chia quầy theo loại thủ tục có lẽ sẽ khiến bạn thấy hơi phiền khi chưa quen. Làm xong toàn bộ mất khoảng một tiếng, nhưng tôi có ấn tượng là mọi việc suôn sẻ hơn mình nghĩ. Hơn nữa, việc hoàn thành thủ tục chỉ bằng tiếng Nhật cũng giúp tôi có thêm chút tự tin rằng mình có thể tiếp tục sống ở đây.","Nếu có điều gì không hiểu, tôi nghĩ bạn nên hỏi ngay, đừng ngại. Ngay cả với người nước ngoài, nhân viên cũng nói chậm và lịch sự, nên bạn không cần do dự khi hỏi lại. Dù không tự tin về tiếng Nhật, cũng không có nghĩa là làm thủ tục ở quầy sẽ khó. Nếu vừa xác nhận từng việc một vừa tiến hành, chắc chắn bạn sẽ bình tĩnh hoàn thành các thủ tục cần thiết."],"vocab":["khai báo, đăng ký","quầy, cửa sổ giao dịch","phiếu số thứ tự","cơ chế, cấu trúc","điền, ghi vào","mặt sau","chứng minh","phụ trách","khác, khác nhau","do dự, ngần ngại"],"grammar":[{"t":"〜に伴って","note":"Nghĩa là「cùng với ~, theo sự ~」: thay đổi ở vế trước kéo theo vế sau. Ví dụ:「引っ越しに伴って、十四日以内に区役所へ行き」"},{"t":"〜ざるを得ない","note":"Nghĩa là「đành phải ~, buộc phải ~」, không còn lựa chọn nào khác. Ví dụ:「椅子に座って待たざるを得ませんが」"},{"t":"〜に対して","note":"Nghĩa là「đối với ~」, chỉ đối tượng của hành động hoặc thái độ. Ví dụ:「外国人の利用者に対しても、係の人はゆっくり丁寧に話してくれる」"},{"t":"〜とは限らない","note":"Nghĩa là「không phải lúc nào cũng ~, chưa chắc ~」, phủ định suy nghĩ cho rằng「chắc chắn là ~」. Ví dụ:「窓口での手続きが難しいとは限りません」"}]},"a-n4-8-n3":{"title":"Làm thủ tục tại văn phòng quận","topic":"Cuộc sống","trans":["Sau khi chuyển nhà, bạn phải đến văn phòng quận trong vòng mười bốn ngày để làm thủ tục đổi địa chỉ. Khi tôi nói ở quầy: 「転入届を出したいのですが」, tôi được phát một tấm phiếu số thứ tự. Tôi ngồi ghế chờ đến khi được gọi tên, và trong lúc đó tôi điền sẵn địa chỉ và ngày tháng năm sinh vào giấy tờ.","Khi đến lượt, nhân viên kiểm tra thẻ cư trú của tôi rồi ghi địa chỉ mới vào mặt sau giúp tôi. Vì trong cùng ngày cũng có thể làm thủ tục bảo hiểm y tế quốc dân, nên tôi quyết định làm luôn sau đó. Có điều, vì quầy khác nhau nên tôi phải di chuyển từ tầng một lên tầng hai.","Làm xong toàn bộ mất khoảng một tiếng. Dù vậy, vì có thể làm thủ tục chỉ bằng tiếng Nhật nên tôi cũng có thêm chút tự tin.","Tôi nghĩ nếu có điều gì không hiểu thì bạn nên hỏi nhân viên, đừng ngại. Vì nhân viên sẽ nói chậm để chúng ta có thể hiểu."],"vocab":["thủ tục","quầy, cửa sổ giao dịch","đơn đăng ký chuyển đến","phiếu số thứ tự","giấy tờ, biểu mẫu","thẻ cư trú","xác nhận, kiểm tra","di chuyển","tự tin","ngại, e dè"],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì. Ví dụ:「続けて行うことにしました」(tôi quyết định làm luôn sau đó)."},{"t":"〜ため(原因・理由)","note":"Cách nói khá trang trọng, văn viết để nêu nguyên nhân, lý do. Ví dụ:「窓口が違うため、一階から二階へ移動しなければなりませんでした」."},{"t":"〜ように","note":"Diễn tả mục đích, để một trạng thái nào đó xảy ra. Ví dụ:「こちらが分かるようにゆっくり話してくれる」(nói chậm để chúng ta hiểu được)."},{"t":"Thể bị động (〜れる・〜られる)","note":"Diễn tả việc bị/được người khác làm gì đó cho. Ví dụ:「番号札を渡されました」「名前を呼ばれるまで」."}]},"a-n4-11-n2":{"title":"Ngày tôi để quên chiếc ô trên tàu điện","topic":"Cuộc sống","trans":["Hôm nay tôi lỡ để quên chiếc ô trên tàu điện, đúng là một sơ suất. Khi nhận ra thì tàu đã đến ga kế tiếp, chiếc ô không còn ở bên mình nữa. Tôi hoàn toàn bối rối, nhưng vẫn quyết định đến trung tâm đồ thất lạc của ga để hỏi thử.","Tôi trình bày với nhân viên ở quầy đầy đủ đầu đuôi việc mình làm mất ô theo đúng thứ tự. Nhân viên bảo \"Xin hãy cho tôi biết đặc điểm\", nên trước hết tôi nói về màu sắc và hình dáng. Tôi nói cụ thể: \"Đó là chiếc ô màu đen, cán hơi cong.\" Nhân viên nói \"Xin bạn chờ một chút, tôi sẽ tìm thử\" rồi đi tìm giúp tôi ngay.","Chờ một lúc thì có thông báo rằng hình như đã tìm thấy một chiếc ô giống vậy. Tôi nhờ họ mang chiếc ô từ phía trong ra để kiểm tra, và đó đúng là ô của tôi không nhầm vào đâu được. Tôi nhận lại được ô ngay tại chỗ, thật sự nhẹ cả người. Vì đã có lúc suýt bỏ cuộc nên cảm giác yên tâm lại càng đặc biệt mạnh.","Qua trải nghiệm lần này, tôi thấm thía rằng việc để quên đồ có thể xảy ra dù mình đã cẩn thận. Từ nay, tôi định luôn nhớ kiểm tra xem mình có bỏ quên gì không mỗi khi xuống tàu. Tuy chỉ là một thói quen nhỏ, nhưng tôi nghĩ không lơ là việc này chính là cách tốt nhất để không lặp lại sai lầm."],"vocab":[{"w":"到着","m":"đến nơi, tới nơi"},{"w":"手元","m":"bên mình, trong tầm tay"},{"w":"途方に暮れる","m":"bối rối, không biết làm sao"},{"w":"経緯","m":"đầu đuôi, diễn biến sự việc"},{"w":"順を追って","m":"theo thứ tự, lần lượt"},{"w":"まぎれもなく","m":"không thể nhầm lẫn, chắc chắn"},{"w":"ひとしお","m":"đặc biệt hơn, càng thêm"},{"w":"痛感","m":"thấm thía, cảm nhận sâu sắc"},{"w":"心がける","m":"lưu tâm, cố gắng thực hiện"},{"w":"怠る","m":"lơ là, xao nhãng"}],"grammar":[{"t":"〜たところ","note":"Diễn tả sau khi làm một hành động thì phát hiện ra một kết quả; vế sau thường là sự thật được xác nhận. Ví dụ: 「奥から傘を持ってきてもらって確認したところ、それはまぎれもなく私の傘でした」."},{"t":"〜だけに","note":"Diễn tả chính vì tình huống ở vế trước nên cảm xúc hay kết quả ở vế sau càng mạnh mẽ. Ví dụ: 「一時はあきらめかけていただけに、安心感はひとしおでした」."},{"t":"〜を通じて","note":"Diễn tả việc đạt được một kết quả nào đó thông qua một trải nghiệm hay phương tiện. Ví dụ: 「今回の経験を通じて、忘れ物は気をつけていても起こり得ることだと痛感しました」."},{"t":"〜かける","note":"Gắn vào thể ます của động từ (bỏ ます), diễn tả hành động đang làm dở hoặc sắp sửa làm. Ví dụ: 「一時はあきらめかけていただけに」."}]},"a-n4-11-n3":{"title":"Ngày tôi để quên chiếc ô trên tàu điện","topic":"Cuộc sống","trans":["Hôm nay tôi để quên ô trên tàu điện và vô cùng cuống cuồng. Đến khi tàu tới ga kế tiếp, tôi mới nhận ra mình không còn ô. Tôi phân vân không biết làm sao, nhưng cuối cùng quyết định đến trung tâm đồ thất lạc của ga để hỏi.","Tôi giải thích với nhân viên rằng mình đã làm mất ô trên tàu. Nhân viên hỏi \"Bạn có thể cho tôi biết đặc điểm của chiếc ô không?\", nên tôi nói về màu sắc và hình dáng. Tôi nói càng chi tiết càng tốt: \"Đó là chiếc ô màu đen, cán hơi cong.\" Nhân viên nói \"Xin bạn chờ một chút, tôi sẽ tìm thử\" rồi vào phía trong tìm giúp tôi.","Chờ một lúc thì họ cho tôi biết hình như đã tìm được một chiếc ô giống vậy. Khi nhìn chiếc ô được mang từ phía trong ra, đó đúng là ô của tôi. Tôi nhận lại được ngay, thật sự nhẹ cả người. Từ nay, tôi định sẽ kiểm tra xem mình có để quên gì không mỗi khi xuống tàu."],"vocab":[{"w":"置き忘れる","m":"để quên (đồ ở đâu đó)"},{"w":"慌てる","m":"cuống lên, hoảng hốt"},{"w":"気がつく","m":"nhận ra, phát hiện"},{"w":"相談","m":"bàn bạc, hỏi ý kiến"},{"w":"係","m":"nhân viên phụ trách"},{"w":"特徴","m":"đặc điểm"},{"w":"柄","m":"cán, tay cầm (của ô, v.v.)"},{"w":"曲がる","m":"cong, uốn cong"},{"w":"受け取る","m":"nhận, lấy"},{"w":"確認","m":"xác nhận, kiểm tra"}],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc bản thân quyết định làm gì đó. Ví dụ: 「忘れ物センターへ行って相談することにしました」 (quyết định đến trung tâm đồ thất lạc để hỏi)."},{"t":"〜ようだ","note":"Diễn tả suy đoán hoặc tin nghe được dựa trên tình huống, nghĩa là \"hình như~\". Ví dụ: 「似ている傘が見つかったようだと教えてもらいました」 (được cho biết hình như đã tìm thấy chiếc ô giống vậy)."},{"t":"〜てもらう","note":"Diễn tả việc nhờ ai đó làm gì cho mình, nhận được sự giúp đỡ của người khác. Ví dụ: 「奥から持ってきてもらった傘を見ると」 (khi nhìn chiếc ô được nhờ mang từ phía trong ra)."},{"t":"〜ようにする","note":"Diễn tả việc cố gắng tạo thói quen hoặc cố gắng làm gì đó. Ví dụ: 「忘れ物がないか確認するようにしようと思います」 (định cố gắng kiểm tra xem có để quên đồ không)."}]},"a-n3-1":{"title":"Sự tiện lợi của cửa hàng tiện lợi","topic":"Đời sống","trans":["Cửa hàng tiện lợi ở Nhật mở cửa 24 giờ, rất tiện.","Không chỉ đồ ăn, thức uống, bạn còn mua được cả tạp chí và đồ dùng hằng ngày. Ngoài ra, bạn còn có thể thanh toán các loại hóa đơn tiện ích và gửi bưu kiện.","Vì có cả ATM ngân hàng nên lúc nào bạn cũng rút tiền được. Còn có cả máy để photocopy và đặt vé.","Nhờ những dịch vụ này, cửa hàng tiện lợi đã trở thành một phần không thể thiếu trong cuộc sống của chúng ta.","Tuy nhiên, đằng sau sự tiện lợi ấy là nỗi vất vả của những người làm việc 24 giờ, cùng các vấn đề như lãng phí thực phẩm.","Đừng xem sự tiện lợi là điều hiển nhiên, mà hãy nghĩ thêm về những người đang chống đỡ cho hệ thống này."],"vocab":["tiện lợi","thanh toán, chi trả","gửi đi (hàng, bưu kiện)","không thể thiếu","sự tồn tại"],"grammar":[{"t":"~だけでなく","note":"「Không chỉ ~ (mà còn)」."},{"t":"~ので","note":"「Vì ~」, mang sắc thái khách quan, nhẹ nhàng: ATM があるので."},{"t":"~おかげで","note":"「Nhờ có ~」, chỉ nguyên nhân tích cực: サービスのおかげで."}]},"a-n5-5":{"title":"Thị trấn của tôi","topic":"Đời sống","trans":["Tôi sống ở một thị trấn nhỏ. Thị trấn nằm gần biển, không khí rất trong lành.","Trong thị trấn tuy không có tòa nhà lớn nào, nhưng có bưu điện, bệnh viện và siêu thị.","Từ ga về nhà, đi bộ khoảng mười phút. Giữa đường có một con sông, tôi phải đi qua cầu.","Vào mùa xuân, hoa anh đào bên bờ sông rất đẹp, nhiều người đến ngắm hoa.","Gần đó có một ngôi chùa cổ, yên tĩnh và rất dễ chịu.","Đi mua sắm thì hơi bất tiện một chút, nhưng mọi người đều thân thiện, đây là một thị trấn dễ sống.","Tôi rất yêu thị trấn này. Tôi muốn sống ở đây mãi mãi."],"vocab":["sống, cư trú","gần, lân cận","đi qua, băng qua","thân thiện, tốt bụng","yên tĩnh"],"grammar":[{"t":"〜やすい","note":"Động từ thể ます (bỏ ます) + やすい nghĩa là dễ làm gì: 「すみやすい」là dễ sống."},{"t":"〜たい","note":"Động từ thể ます (bỏ ます) + たい diễn tả mong muốn: 「住みたい」là muốn sống."},{"t":"〜が(逆接)","note":"Dùng が khi hai vế đối lập nhau: 「ふべんですが、しんせつです」(tuy bất tiện nhưng thân thiện)."}]},"a-n1-7":{"title":"Tiếng Nhật không ngừng thay đổi","topic":"Ngôn ngữ","trans":["Bạn đã bao giờ nghe đến cụm từ 「ら抜き言葉」 (từ lược bỏ ら) chưa?","Đó là cách nói như biến 「食べられる」 thành 「食べれる」, và thường bị chê là tiếng Nhật không đúng.","Nhưng nếu nhìn từ góc độ ngôn ngữ học, cũng có quan điểm cho rằng đây không đơn thuần là sự \"lệch chuẩn\" mà là một biến đổi hợp lý.","Bởi vì 「見られる」 có nhiều nghĩa như bị động, kính ngữ và khả năng, còn 「見れる」 thì chỉ cần nhìn là biết ngay nghĩa \"có thể xem\".","Suy cho cùng, ngôn ngữ vốn luôn không ngừng thay đổi.","Ngay cả thứ tiếng Nhật mà chúng ta đang tin là \"chuẩn\" hôm nay, trong mắt người của một trăm năm trước cũng chẳng khác gì một thứ ngôn ngữ bị lệch chuẩn.","Thay vì than thở về sự thay đổi, chẳng phải suy nghĩ xem vì sao nó thay đổi như vậy mới giúp ta tiến gần hơn đến bản chất của ngôn ngữ sao?"],"vocab":["phê phán, chỉ trích","sự lệch chuẩn, sự rối loạn","có tính hợp lý","thể bị động","kính ngữ, sự tôn kính","than thở, thở than","bản chất","đến gần, tiến gần"],"grammar":[{"t":"~にほかならない","note":"Nghĩa là \"chẳng khác gì ~, chính là ~\": 乱れた言葉にほかならない。Dùng để khẳng định, mang sắc thái văn viết."},{"t":"~ゆく","note":"Nghĩa là \"dần dần ~\" (văn viết): 変わりゆく日本語。Là dạng văn ngữ của ていく, diễn tả sự thay đổi diễn ra liên tục."},{"t":"単なる~ではなく","note":"Nghĩa là \"không đơn thuần là ~\": 単なる「乱れ」ではなく、合理的な変化。"},{"t":"~のではないだろうか","note":"Nghĩa là \"chẳng phải là ~ sao\" (cách nêu ý kiến nhẹ nhàng): 近づけるのではないだろうか。Dùng câu hỏi tu từ để diễn đạt quan điểm một cách tế nhị."}]},"a-n4-8":{"title":"Làm thủ tục ở ủy ban quận","topic":"Cuộc sống","trans":["Sau khi chuyển nhà, bạn phải đến ủy ban quận trong vòng mười bốn ngày.","Tôi nói với quầy: 「転入届を出したいんですが」 thì được phát một tấm phiếu số thứ tự.","Cho đến khi được gọi tên, tôi ngồi ghế chờ. Trong lúc chờ, tôi đã điền sẵn địa chỉ và ngày tháng năm sinh vào giấy tờ.","Nhân viên xem thẻ cư trú xong thì viết địa chỉ mới vào mặt sau giúp tôi.","Cùng ngày cũng có thể làm thủ tục bảo hiểm y tế quốc dân. Vì quầy khác nhau nên tôi di chuyển từ tầng một lên tầng hai.","Làm xong tất cả mất khoảng một tiếng, nhưng tôi có thể làm thủ tục chỉ bằng tiếng Nhật nên cũng thấy tự tin hơn một chút.","Nếu có điều gì không hiểu, bạn đừng ngại mà hãy hỏi thì tốt hơn. Nhân viên sẽ nói chậm cho bạn nghe."],"vocab":["ủy ban quận","thủ tục","giấy đăng ký chuyển đến","phiếu số thứ tự","giấy tờ, hồ sơ","ngày tháng năm sinh","thẻ cư trú","bảo hiểm y tế quốc dân","ngại, e ngại"],"grammar":[{"t":"～なければなりません","note":"Diễn tả nghĩa vụ, bắt buộc phải làm. 「十四日以内に行かなければなりません」 = phải đi trong vòng mười bốn ngày, đây là quy định."},{"t":"～ておく","note":"Làm sẵn, chuẩn bị trước. 「書いておきました」 = tranh thủ lúc chờ để viết sẵn, lát nữa khỏi cuống."},{"t":"～てくれる","note":"Người khác làm việc gì đó cho mình, mang sắc thái biết ơn. 「書いてくれました」 = (người ấy) đã viết giúp tôi."}]},"a-n4-9":{"title":"Đi khám nha sĩ","topic":"Cuộc sống","trans":["Vì bị đau răng từ ba ngày trước, tôi đã đặt lịch hẹn ở một phòng khám nha khoa gần nhà.","Khi đưa thẻ bảo hiểm ở quầy lễ tân, tôi được yêu cầu điền phiếu khám. Trong phiếu phải ghi đau từ khi nào, có bị ê buốt khi ăn đồ lạnh không, v.v.","Bác sĩ nói: 「虫歯が一本ありますね」 (Có một chiếc răng sâu nhỉ), rồi cho tôi xem phim X-quang.","Hôm nay chỉ mài phần răng sâu và bôi thuốc thôi, bác sĩ bảo tuần sau hãy quay lại một lần nữa.","Sau khi điều trị, tôi còn được hướng dẫn cách đánh răng. Nghe nói nếu chải quá mạnh thì sẽ làm tổn thương nướu.","Nha sĩ ở Nhật phải đến khám nhiều lần, nhưng đổi lại họ chữa rất tỉ mỉ.","Tôi nghĩ nên đi kiểm tra sáu tháng một lần, trước khi bị đau."],"vocab":["nha sĩ","đặt lịch hẹn","thẻ bảo hiểm","phiếu khám (phiếu hỏi bệnh)","ê buốt, nhạy cảm (với nóng/lạnh)","răng sâu","điều trị","nướu (lợi)","khám sức khỏe, kiểm tra định kỳ"],"grammar":[{"t":"～ように言われる","note":"Bị yêu cầu làm gì đó (chỉ thị gián tiếp). 「書くように言われました」= được yêu cầu điền vào."},{"t":"～そうです(truyền đạt)","note":"Nghe nói là… 「傷めてしまうそうです」= nghe nói sẽ làm tổn thương, thông tin nghe từ người khác."},{"t":"～なければなりません","note":"Phải làm gì đó. 「通わなければなりません」= bắt buộc phải đến nhiều lần."}]},"a-n3-10":{"title":"Quy tắc đổ rác","topic":"Cuộc sống","trans":["Sau khi bắt đầu sống ở Nhật, điều đầu tiên khiến tôi bối rối là cách phân loại rác.","Rác cháy được, rác không cháy được, rác tái chế — cách phân loại và ngày thu gom khác nhau tùy từng quận. Sau khi chuyển nhà, tốt nhất bạn nên xem trước bảng phân loại phát ở tòa thị chính.","Chai nhựa cần gỡ nhãn và nắp, tráng sơ bên trong rồi mới đem đổ. Nghe có vẻ phiền, nhưng nghe nói chính công đoạn nhỏ này quyết định chai có tái sử dụng được hay không.","Giờ đổ rác cũng có quy định, ở nhiều khu vực là trước 8 giờ sáng của ngày thu gom. Vì nếu đem ra từ tối hôm trước, rác có thể bị quạ bới tung.","Rác cỡ lớn phải đăng ký trước qua điện thoại hoặc mạng, rồi mua tem ở cửa hàng tiện lợi và dán lên. Không ít người không biết điều này, cứ thế để rác ra ngoài và bị nhắc nhở.","Lúc đầu tôi thấy nó quá chi li, nhưng sống một thời gian thì quen dần.","Cách đổ rác có lẽ là 「quy tắc chung」 đầu tiên để sống trong một khu vực."],"vocab":["bối rối, lúng túng","phân loại","rác tái chế","bảng liệt kê","tráng, xả (nước)","một công đoạn nhỏ","bới tung, phá phách","rác cỡ lớn","đăng ký, nộp đơn"],"grammar":[{"t":"～によって(tùy theo…)","note":"Khác nhau tùy theo danh từ phía trước. 「区によって分類も違う」= phân loại cũng khác nhau tùy từng quận."},{"t":"～らしい(truyền đạt)","note":"Suy đoán dựa trên thông tin nghe được. 「決まるらしい」= nghe nói là được quyết định như vậy."},{"t":"～ているうちに","note":"Trong lúc việc gì đó diễn ra liên tục, dần dần có sự thay đổi lúc nào không hay. 「住んでいるうちに慣れてきた」= sống một thời gian thì quen dần."}]},"a-n3-13":{"title":"Khi nhận được phiếu báo vắng nhà","topic":"Đời sống","trans":["Đi làm về, tôi thấy trong hòm thư có một tờ giấy. Đó là \"phiếu báo vắng nhà\" của dịch vụ giao hàng.","Vì lúc tôi vắng nhà có bưu kiện được gửi đến, nên tôi phải nhờ họ giao lại một lần nữa. Việc này gọi là「再配達」(giao lại).","Trước đây, cách thông thường là gọi đến số điện thoại ghi trên tờ giấy, còn bây giờ chỉ cần dùng điện thoại là đăng ký dễ dàng. Bạn chỉ cần quét mã QR trên phiếu, rồi chọn ngày và khung giờ mình muốn là xong.","Tuy nhiên, trên phiếu báo cũng ghi thời hạn lưu giữ. Nếu không làm thủ tục sớm, bưu kiện có thể bị trả về cho người gửi, nên bạn cần chú ý.","Mặt khác, giao lại tốn cả nhiên liệu của xe tải lẫn nhân công. Trong bối cảnh thiếu tài xế đã trở thành vấn đề xã hội như hiện nay, mọi người được kỳ vọng nhận hàng ngay trong một lần giao nếu có thể.","Lúc này,「置き配」(giao để trước cửa) và tủ nhận hàng sẽ rất tiện. Nếu nhờ họ để hàng trước cửa nhà hoặc trong tủ, bạn không có nhà vẫn nhận được hàng.","Gần đây, khi đặt hàng online, tôi cũng cố gắng nghĩ trước cả cách nhận hàng. Dù chỉ là một chút chu đáo nhỏ, nhưng đây là thói quen tốt cho cả tôi lẫn tài xế."],"vocab":["hòm thư","giao hàng tận nhà","phiếu báo vắng nhà","vắng nhà","giao lại","khung giờ","thời hạn lưu giữ","người gửi","nhân lực, nhân công","giao để trước cửa","mua hàng online, đặt hàng qua mạng"],"grammar":[{"t":"～ように頼む","note":"Nhờ ai đó làm việc gì (nói gián tiếp nội dung yêu cầu). 「届けてくれるように頼まなければならない」= phải nhờ họ giao lại."},{"t":"～だけで済む","note":"Chỉ cần làm ~ là xong, không cần gì thêm. 「選ぶだけで済む」= chỉ cần chọn là xong."},{"t":"～ないと","note":"\"Nếu không ~ thì (sẽ…)\", phía sau thường là kết quả không tốt. 「早めに手続きしないと、…返されてしまう」."},{"t":"～ようにしている","note":"Thói quen cố ý duy trì. 「考えるようにしている」= tôi luôn cố gắng nghĩ trước."}]},"a-n2-11":{"title":"「お通し」ở quán izakaya","topic":"Văn hóa","trans":["Khi ngồi vào bàn ở quán izakaya Nhật, đôi khi dù bạn chưa gọi gì vẫn được mang ra một đĩa nhỏ. Đó chính là「お通し」.","Ở vùng Kansai, nó cũng thường được gọi là「突き出し」, và món gì thì tùy từng quán, như đậu nành luộc, món hầm, món trộn, v.v.","Trong số những người lần đầu đến Nhật, không ít người thấy hóa đơn bị cộng thêm tiền お通し khi thanh toán thì bối rối, tự hỏi có phải mình bị tính tiền vô lý không.","Mức giá thông thường được cho là khoảng 300 đến 500 yên, và với quán thì nó mang ý nghĩa gần giống phí chỗ ngồi.","Ngoài ra, cũng có quan điểm cho rằng đây là sự chu đáo của quán, để khách không thấy rảnh rỗi chán chường trong lúc chờ món lên.","Tuy vậy, có từ chối được hay không còn tùy chính sách của quán, và gần đây số quán không mang お通し ra cũng đang tăng dần. Nếu bạn thấy băn khoăn, chỉ cần hỏi một câu khi vào quán là xong.","Nếu hiểu bối cảnh phía sau, thì ngay cả đĩa nhỏ lạ mắt cũng có thể thưởng thức như một phần của văn hóa nhậu của Nhật, phải không nhỉ?"],"vocab":["quán izakaya","bát nhỏ, đĩa nhỏ","お通し (món khai vị nhỏ ở izakaya)","thanh toán","cộng thêm, tính thêm","bối rối, lúng túng","mức giá thông thường","hàm ý, ý nghĩa","rảnh rỗi, không biết làm gì","sự chu đáo, quan tâm","chính sách, phương châm"],"grammar":[{"t":"～際(に)","note":"\"Khi ~\", trang trọng hơn「とき」. 「会計の際に」= khi thanh toán."},{"t":"～次第","note":"\"Tùy vào ~, phụ thuộc vào ~\". 「店の方針次第であり」= tùy chính sách của quán."},{"t":"～つつある","note":"Một sự thay đổi đang tiếp diễn. 「増えつつある」= đang dần tăng lên."},{"t":"とはいえ","note":"\"Tuy vậy\", thừa nhận điều vừa nói rồi đưa ra ý kiến bảo lưu hoặc trái ngược."}]},"a-n3-9-n4":{"title":"Tìm phòng ở Nhật","topic":"Cuộc sống","trans":["Thuê phòng ở Nhật tốn nhiều công sức hơn bạn nghĩ. Trước tiên, bạn đến công ty môi giới bất động sản, nói về ngân sách tiền thuê và khu vực mong muốn. Nếu chọn nơi cách ga trong vòng mười phút đi bộ, tiền thuê sẽ đắt lên khá nhiều.","Dù tìm được phòng tốt, bạn cũng không thể quyết định ngay. Vì lúc đầu cần rất nhiều tiền, như tiền đặt cọc, tiền lễ cho chủ nhà, phí môi giới... Người nước ngoài thường bị yêu cầu phải có người bảo lãnh. Hiện nay nhiều người dùng công ty bảo lãnh, trả khoảng một nửa tiền thuê để ký hợp đồng. Để vượt qua vòng xét duyệt, bạn nên chuẩn bị sẵn giấy tờ chứng minh công việc và thu nhập.","Vì không thể biết hết qua ảnh, bạn nên trực tiếp đến xem và kiểm tra ánh nắng cũng như tiếng ồn. Chỗ đặt máy giặt và số lượng ổ cắm điện cũng nên xem trước. Nghe có vẻ vất vả, nhưng nếu biết quy trình này thì lần chuyển nhà tới sẽ nhẹ nhàng hơn."],"vocab":[{"w":"部屋","m":"phòng"},{"w":"手間","m":"công sức, phiền phức"},{"w":"不動産屋","m":"công ty môi giới bất động sản"},{"w":"家賃","m":"tiền thuê nhà"},{"w":"予算","m":"ngân sách"},{"w":"保証人","m":"người bảo lãnh"},{"w":"契約","m":"hợp đồng, ký hợp đồng"},{"w":"書類","m":"giấy tờ, hồ sơ"},{"w":"準備","m":"chuẩn bị"},{"w":"確認","m":"xác nhận, kiểm tra"}],"grammar":[{"t":"〜ても","note":"Diễn tả ý \"dù ~ cũng ~\". Ví dụ: 「いい部屋が見つかっても、すぐには決められない」"},{"t":"〜ように","note":"Diễn tả mục đích hoặc kết quả muốn đạt được (để ~). Ví dụ: 「審査に通るように、仕事と収入がわかる書類を準備しておくといい」"},{"t":"〜ておく","note":"Diễn tả việc làm sẵn, chuẩn bị trước. Ví dụ: 「書類を準備しておくといい」「見ておいたほうがいい」"},{"t":"〜たほうがいい","note":"Diễn tả ý \"nên làm ~\", dùng để đưa ra lời khuyên. Ví dụ: 「コンセントの数も、見ておいたほうがいい」"}]},"a-n4-4":{"title":"Chuyến du lịch một mình đầu tiên","topic":"Du lịch","trans":["Tháng trước, lần đầu tiên mình đi du lịch một mình. Điểm đến là Kanazawa, nơi mình đã tò mò từ lâu.","Trước khi đi mình hơi lo, nhưng tự lên kế hoạch lại thú vị hơn mình tưởng.","Mình đi tàu Shinkansen từ sáng sớm và đến Kanazawa sau buổi trưa. Nhà ga rộng lớn đến mức mình giật mình.","Đầu tiên mình đi xem một khu vườn nổi tiếng. Thời tiết đẹp nên mình chụp rất nhiều ảnh.","Buổi tối mình ăn hải sản tươi ở chợ. Vì đi một mình nên mình có thể gọi món mình thích, muốn ăn bao nhiêu thì gọi bấy nhiêu.","Đi bộ một mình trong một thị trấn xa lạ thì hơi cô đơn một chút, nhưng rất tự do và dễ chịu.","Chuyến đi này giúp mình có thêm tự tin rằng dù một mình cũng xoay xở được. Mình muốn đi nữa."],"vocab":["du lịch một mình","lên kế hoạch","tươi, tươi mới","tự do","sự tự tin"],"grammar":[{"t":"〜より","note":"「思ったより楽しい」nghĩa là thú vị hơn so với dự đoán."},{"t":"〜だけ","note":"「好きなだけ注文できる」chỉ mức giới hạn: muốn bao nhiêu thì được bấy nhiêu."},{"t":"〜という〜","note":"「何とかなるという自信」dùng という để giải thích nội dung của danh từ phía sau."}]},"a-n2-8":{"title":"Chuyển về vùng quê: một lựa chọn","topic":"Xã hội","trans":["Nghe nói gần đây ngày càng nhiều người rời thành phố để chuyển về vùng quê sinh sống.","Một lý do lớn là nhờ làm việc từ xa phổ biến, giờ đây sống ở đâu cũng có thể làm việc được.","Tiền thuê nhà chưa bằng một nửa ở thành phố, lại không phải chịu cảnh giờ cao điểm đi làm, cuộc sống giữa thiên nhiên trông thật hấp dẫn.","Tuy nhiên, chuyển về quê tuyệt đối không phải chuyện đơn giản.","Có nhiều vùng không có xe thì không sống nổi, và đôi khi bạn cũng thấy bất tiện về y tế và giáo dục.","Việc có hòa nhập được với các mối quan hệ trong cộng đồng địa phương hay không cũng được cho là một vấn đề lớn.","Điều quan trọng có lẽ là đừng quyết định chỉ dựa trên lý tưởng, mà hãy thực sự đến đó vài lần để tự mình kiểm chứng cuộc sống ở vùng đất ấy."],"vocab":["chuyển đến định cư","phổ biến, lan rộng","tiền thuê nhà","không liên quan, thoát khỏi","hòa nhập","vấn đề cần giải quyết","đích thân đến, đi một chuyến","xác nhận, kiểm chứng"],"grammar":[{"t":"~という(傳聞)","note":"Nghĩa là \"nghe nói ~\": 増えているという。Đặt という ở cuối câu để thuật lại tin đồn, lời kể lại."},{"t":"~によって","note":"Nghĩa là \"do ~, nhờ ~\": 普及によって~ようになった。Chỉ nguyên nhân hoặc phương tiện."},{"t":"決して~ない","note":"Nghĩa là \"tuyệt đối không ~\": 決して簡単なものではない。Phó từ đi cùng dạng phủ định."},{"t":"~かどうか","note":"Nghĩa là \"có ~ hay không\": 溶け込めるかどうか。"},{"t":"~のではなく","note":"Nghĩa là \"không phải ~ mà là …\": 理想だけで決めるのではなく、実際に確かめる。"}]},"eh-n4-1":{"title":"Ngày bị cảm","topic":"Truyện tranh","trans":["Sáng ngủ dậy, đầu đau, cổ họng cũng rất đau. Hình như còn bị sốt nữa.","Tanutarō gọi điện đến công ty và nói: 「すみません、かぜをひいたので、今日は休ませてください」","Sau đó, cậu ấy đến phòng khám gần nhà. Ở quầy tiếp tân, cậu đưa thẻ bảo hiểm và điền phiếu khám bệnh.","Bác sĩ hỏi: 「いつからですか」 Cậu trả lời: 「きのうの夜からで、せきも出ます」","Bác sĩ nói: 「ただのかぜですね、薬を飲んで、ゆっくり休んだほうがいいですよ」","Tối hôm đó, Kon mang cháo đến cho cậu. Cháo nóng hổi và rất ngon.","Ba ngày sau, Tanutarō đã khỏe hẳn. Đi bệnh viện ở Nhật lúc đầu hơi sợ, nhưng giờ thì ổn rồi.”"],"vocab":[{"w":"熱","m":"sốt, nhiệt độ cơ thể cao"},{"w":"休む","m":"nghỉ làm, nghỉ ngơi"},{"w":"受付","m":"quầy tiếp tân, nơi đăng ký"},{"w":"保険証","m":"thẻ bảo hiểm y tế"},{"w":"問診票","m":"phiếu khám bệnh (phiếu hỏi bệnh)"},{"w":"お医者さん","m":"bác sĩ"},{"w":"薬","m":"thuốc"},{"w":"おかゆ","m":"cháo"},{"w":"すっかり","m":"hoàn toàn, hẳn"},{"w":"元気","m":"khỏe, có tinh thần"}],"grammar":[{"t":"〜ので","note":"Nêu nguyên nhân, lý do; lịch sự hơn 「から」, hay dùng khi xin nghỉ hoặc xin lỗi. Ví dụ: かぜをひいたので、今日は休ませてください。"},{"t":"〜ほうがいいです","note":"Động từ thể た + ほうがいいです dùng để khuyên người khác: \"nên…\". Ví dụ: ゆっくり休んだほうがいいですよ。"},{"t":"受身形","note":"「(人)に〜られる」diễn tả việc bị/được ai đó làm gì với mình. Ví dụ: お医者さんに「いつからですか」と聞かれました。"},{"t":"〜てくれます","note":"Người khác làm giúp mình một việc gì đó (mang sắc thái biết ơn). Ví dụ: コンちゃんがおかゆを持ってきてくれました。"}]},"eh-n4-2":{"title":"Ở tiệm ramen","topic":"Truyện tranh","trans":["Gần ga có một tiệm ramen rất nổi tiếng. Hôm nay Tanutarō lần đầu bước vào đó.","Ở lối vào có một máy bán vé. Nghe nói ở tiệm này phải mua vé ăn trước.","Nhưng có quá nhiều nút, cậu không biết nên bấm nút nào.","Lúc đó, Kon đứng phía sau chỉ cho cậu: 「いちばん左が普通のラーメンだよ」","Ngồi vào chỗ và đưa vé ăn xong, nhân viên hỏi cậu: 「麺のかたさはどうしますか」","Tanutarō trả lời: 「かためでお願いします」 「かため」 nghĩa là sợi mì hơi cứng một chút.","Nước dùng nóng hổi và mì hơi cứng thật tuyệt vời. Tanutarō đã uống hết sạch nước dùng."],"vocab":[{"w":"人気","m":"được yêu thích, nổi tiếng"},{"w":"入口","m":"lối vào"},{"w":"券売機","m":"máy bán vé"},{"w":"食券","m":"vé ăn"},{"w":"押す","m":"bấm, nhấn, đẩy"},{"w":"普通","m":"bình thường, thông thường"},{"w":"席","m":"chỗ ngồi"},{"w":"渡す","m":"đưa, trao"},{"w":"麺","m":"mì"},{"w":"全部","m":"toàn bộ, tất cả"}],"grammar":[{"t":"〜そうです(伝聞)","note":"Thể thường + そうです nghĩa là \"nghe nói…\". Ví dụ: この店では、先に食券を買うそうです。"},{"t":"〜ばいい","note":"「どれを〜ばいいか」= nên… cái nào thì được. Ví dụ: どれを押せばいいかわかりません。"},{"t":"〜てしまいます","note":"Diễn tả hành động đã làm xong hoàn toàn, cũng hay mang sắc thái \"lỡ…\". Ví dụ: スープを全部飲んでしまいました。"},{"t":"〜と(条件)","note":"「A と、B」= hễ làm A thì B xảy ra. Ví dụ: 食券を渡すと、店員さんに聞かれました。"}]},"a-n1-1-n3":{"title":"Nóng lên toàn cầu và cuộc sống của chúng ta","topic":"Môi trường","trans":["Trái đất nóng lên không còn là chuyện của tương lai xa nữa, mà là vấn đề liên quan trực tiếp đến cuộc sống của chúng ta. Khí hậu cực đoan khiến nông sản bị thiệt hại, mực nước biển dâng cao cũng gây ra thiệt hại. Những thiệt hại này ngày càng nghiêm trọng hơn qua từng năm.","Nhìn tình hình như vậy, có lẽ bạn sẽ cảm thấy mỗi người có thể làm được rất ít. Tuy nhiên, giảm lãng phí điện là việc chúng ta cũng có thể làm ngay. Ngoài ra, sử dụng phương tiện giao thông công cộng như tàu điện, xe buýt cũng là một cách hay. Chính những việc nhỏ tích lũy như thế mới dẫn đến thay đổi lớn.","Để lại một Trái đất trù phú cho các thế hệ tương lai, ngay bây giờ chúng ta cần hành động. Nóng lên toàn cầu không phải chuyện của những đất nước xa xôi, mà còn liên quan trực tiếp đến bữa ăn và cuộc sống của chúng ta. Đừng quên rằng những hành động nhỏ của mỗi người rồi sẽ tạo nên thay đổi lớn."],"vocab":[{"m":"khí hậu cực đoan, thời tiết bất thường"},{"m":"nông sản"},{"m":"thiệt hại, tổn thất"},{"m":"mực nước biển"},{"m":"nghiêm trọng"},{"m":"phương tiện giao thông công cộng"},{"m":"sự tích lũy"},{"m":"thế hệ"},{"m":"bàn ăn, bữa ăn"},{"m":"được yêu cầu, được kỳ vọng"}],"grammar":[{"t":"〜によって","note":"Chỉ nguyên nhân hoặc phương tiện, nghĩa là \"do…, bởi…\". Ví dụ: 「異常気象によって農作物が被害を受けたり」。"},{"t":"〜一方だ","note":"Chỉ xu hướng cứ tiếp diễn theo một hướng, nghĩa là \"ngày càng…\". Ví dụ: 「ますます深刻になる一方です」。"},{"t":"〜ためにも","note":"Nghĩa là \"cũng là để…\", nhấn mạnh tầm quan trọng của mục đích. Ví dụ: 「未来の世代に豊かな地球を残すためにも」。"},{"t":"〜こそ","note":"Nhấn mạnh từ đứng trước, nghĩa là \"chính là…\". Ví dụ: 「こうした小さな積み重ねこそが」。"}]},"a-n1-1-n4":{"title":"Nóng lên toàn cầu và cuộc sống của chúng ta","topic":"Môi trường","trans":["Trái đất nóng lên không còn là chuyện của tương lai xa nữa. Cuộc sống của chúng ta cũng đã chịu ảnh hưởng trực tiếp. Do thời tiết khác thường, rau và gạo đang bị thiệt hại.","Mực nước biển dâng cao, số người gặp khó khăn cũng ngày càng nhiều. Những thiệt hại này mỗi năm lại nặng nề hơn một chút. Có thể bạn sẽ nghĩ rằng một người thì làm được rất ít.","Nhưng chúng ta có thể cố gắng không dùng điện lãng phí, hoặc đi xe buýt, tàu điện. Nếu tiếp tục làm những việc nhỏ như vậy, chúng sẽ dẫn đến thay đổi lớn. Để lại một Trái đất sạch đẹp cho những người của tương lai, hãy bắt đầu hành động từ bây giờ nhé. Nóng lên toàn cầu là vấn đề cũng liên quan đến bữa ăn và cuộc sống của chúng ta. Mong bạn đừng quên rằng hành động nhỏ sẽ tạo nên thay đổi lớn."],"vocab":[{"m":"Trái đất"},{"m":"tương lai"},{"m":"cuộc sống, sinh hoạt"},{"m":"ảnh hưởng"},{"m":"thời tiết"},{"m":"thiệt hại, tổn thất"},{"m":"điện, điện năng"},{"m":"tiếp tục"},{"m":"để lại"},{"m":"quên"}],"grammar":[{"t":"〜ている","note":"Chỉ trạng thái hoặc sự thay đổi đang diễn ra. Ví dụ: 「野菜や米が被害を受けている」「困る人も増えている」"},{"t":"〜かもしれない","note":"Nghĩa là \"có lẽ, có thể\". Ví dụ: 「思うかもしれない」"},{"t":"〜ようにする","note":"Chỉ việc cố gắng duy trì một thói quen hoặc cố gắng làm điều gì đó. Ví dụ: 「電気をむだに使わないようにしたり」"},{"t":"〜と(điều kiện)","note":"Nghĩa là \"hễ… thì…\", làm việc ở vế trước thì kết quả ở vế sau tự nhiên xảy ra. Ví dụ: 「小さなことを続けると、大きな変化につながる」"}]},"a-n1-2-n3":{"title":"Suy ngẫm về ý nghĩa của việc \"học\" trong thời đại AI","topic":"Tin tức","trans":["Nhờ AI tạo sinh phổ biến, việc tiếp nhận kiến thức đã trở nên cực kỳ dễ dàng. Có điều gì không hiểu, chỉ cần hỏi AI là có thể nhận được câu trả lời ngay lập tức.","Vì vậy, bắt đầu xuất hiện cả những người nói rằng \"con người chắc không cần cố gắng học nữa\". Tuy nhiên, mình cho rằng suy nghĩ như vậy là đã quên mất ý nghĩa thực sự của việc học.","Học không chỉ đơn thuần là lấy được câu trả lời. Đó là kiểm tra xem thông tin có đúng hay không, so sánh nhiều quan điểm khác nhau, rồi tự mình đưa ra phán đoán. Chính nhờ quá trình này mà năng lực tư duy mới được bồi đắp từng chút một. Việc có thể suy nghĩ kỹ và kiểm chứng câu trả lời do AI đưa ra hay không phụ thuộc vào chiều sâu việc học của mỗi người.","Chính vì là thời đại câu trả lời dễ dàng có được, nên thái độ không ngừng đặt câu hỏi \"tại sao lại như vậy\" mới quan trọng. Ý nghĩa của việc học không phải là mất đi, mà ngược lại đang được suy nghĩ lại một lần nữa. Thay vì tích lũy kiến thức, việc sử dụng nó như thế nào và phán đoán ra sao sẽ trở thành trọng tâm của việc học trong tương lai."],"vocab":[{"w":"広がる","m":"lan rộng, phổ biến"},{"w":"手に入れる","m":"có được, giành được"},{"w":"努力","m":"nỗ lực, cố gắng"},{"w":"本当","m":"thật sự, thực sự"},{"w":"情報","m":"thông tin"},{"w":"確かめる","m":"xác nhận, kiểm chứng"},{"w":"比べる","m":"so sánh"},{"w":"判断","m":"phán đoán, đánh giá"},{"w":"過程","m":"quá trình"},{"w":"姿勢","m":"thái độ, tư thế"}],"grammar":[{"t":"〜ため(nguyên nhân)","note":"Biểu thị nguyên nhân, lý do, trang trọng hơn một chút so với「から」, hay dùng trong văn viết. Ví dụ:「生成AIが広がったため、知識を手に入れることはとても簡単になった」"},{"t":"〜わけではない","note":"Nghĩa là \"không hẳn là…\", phủ định một phần, tránh nói quá tuyệt đối. Ví dụ:「学ぶ意味はなくなるわけではなく、むしろもう一度考え直されている」"},{"t":"〜によって","note":"Nghĩa là \"tùy theo…, phụ thuộc vào…\", cũng có thể chỉ phương tiện hoặc nguyên nhân. Ví dụ:「その人の学びの深さによって決まる」"},{"t":"〜かどうか","note":"Nghĩa là \"có… hay không\", lồng một câu hỏi vào trong câu. Ví dụ:「情報が正しいかどうかを確かめ」"}]},"a-n1-2-n4":{"title":"Suy ngẫm về ý nghĩa của việc \"học\" trong thời đại AI","topic":"Tin tức","trans":["Từ khi AI phổ biến, những điều muốn biết đã có thể tra cứu ngay lập tức. Có điều gì không hiểu, chỉ cần hỏi AI là nó sẽ cho bạn câu trả lời. Vì thế, cũng bắt đầu xuất hiện những người nói rằng \"con người không cần học nữa\".","Nhưng mình nghĩ học không chỉ đơn thuần là nhận câu trả lời. Đó là suy nghĩ xem thông tin có đúng hay không và so sánh nhiều ý kiến khác nhau. Nhờ tự mình suy nghĩ và quyết định mà năng lực tư duy được bồi đắp. Việc có thể suy xét câu trả lời của AI đúng hay sai phụ thuộc vào việc người đó đã học được bao nhiêu.","Chính vì là thời đại câu trả lời dễ dàng có được, nên việc suy nghĩ \"tại sao\" càng quan trọng hơn. Thay vì ghi nhớ thật nhiều kiến thức, việc suy nghĩ cách vận dụng nó sẽ trở nên quan trọng hơn trong tương lai. Ý nghĩa của việc học không hề mất đi, mà ngược lại đang được suy nghĩ lại một lần nữa."],"vocab":[{"w":"広がる","m":"lan rộng, phổ biến"},{"w":"調べる","m":"tra cứu, điều tra"},{"w":"答え","m":"câu trả lời, đáp án"},{"w":"比べる","m":"so sánh"},{"w":"考える","m":"suy nghĩ, nghĩ"},{"w":"育つ","m":"lớn lên, được bồi đắp"},{"w":"簡単","m":"đơn giản, dễ dàng"},{"w":"時代","m":"thời đại"},{"w":"大切","m":"quan trọng, quý giá"},{"w":"意味","m":"ý nghĩa"}],"grammar":[{"t":"〜ようになる","note":"Biểu thị sự thay đổi, trở nên có thể làm được việc gì đó. Ví dụ:「知りたいことをすぐに調べられるようになった」"},{"t":"〜なくてもいい","note":"Biểu thị không làm cũng được, không cần thiết. Ví dụ:「もう人が勉強しなくてもいい」"},{"t":"〜かどうか","note":"Nghĩa là \"có phải… hay không\", đưa câu hỏi vào trong câu. Ví dụ:「情報が正しいかどうかを考えて」"},{"t":"AよりB","note":"Biểu thị so với A thì B hơn…. Ví dụ:「知識をたくさん覚えるより、どう使うかを考えることが大事になるだろう」"}]},"a-n1-4-n3":{"title":"Để bơi giữa biển thông tin","topic":"Truyền thông","trans":["Nhờ điện thoại thông minh phổ biến, chúng ta có thể xem rất nhiều thông tin mọi lúc mọi nơi. Nhưng đằng sau sự tiện lợi ấy lại ẩn chứa những mối nguy khó nhận ra.","Trên Internet có rất nhiều thông tin không rõ thật hay giả. Trong đó, tin giả được lan truyền một cách cố ý để lừa người khác cũng không hề ít. Khả năng phân biệt sự thật và ý kiến đang cần thiết hơn bao giờ hết.","Điều rắc rối hơn là cơ chế chỉ hiển thị những thông tin hợp với sở thích của bản thân. Trong lúc không hay biết, phạm vi những gì bạn xem bị thu hẹp lại, và dễ hình thành lối suy nghĩ phiến diện.","Điều quan trọng là đừng tin ngay vào một thông tin duy nhất mà hãy tra cứu nhiều nguồn để kiểm chứng. Khi tự mình đăng tải thông tin, bạn cũng phải chịu trách nhiệm về nội dung đó.","Khả năng đọc hiểu thông tin một cách đúng đắn không còn chỉ là của một số ít chuyên gia. Đó là kiến thức mà ai cũng nên có, không thể thiếu để sống trong thời đại ngày nay."],"vocab":["lan rộng, phổ biến","nguy hiểm","ẩn giấu, tiềm ẩn","phân biệt","cơ chế, cấu trúc","phạm vi","phiến diện, thiên lệch","nguồn thông tin","trách nhiệm","học được, trang bị (kiến thức, kỹ năng)"],"grammar":[{"t":"〜によって","note":"Chỉ nguyên nhân hoặc phương tiện, nghĩa là「do ～ / bằng ～」. Ví dụ:「スマートフォンが広まったことによって、私たちはいつでもどこでもたくさんの情報を見られるようになった」"},{"t":"〜ようになる","note":"Chỉ sự thay đổi về trạng thái hoặc khả năng, nghĩa là「trở nên có thể ～」. Ví dụ:「たくさんの情報を見られるようになった」"},{"t":"〜ために","note":"Chỉ mục đích, nghĩa là「để ～」. Ví dụ:「わざと人をだますために広められるうそのニュース」"},{"t":"〜なければならない","note":"Chỉ sự bắt buộc, nghĩa vụ, nghĩa là「phải ～」. Ví dụ:「その内容に責任を持たなければならない」"}]},"a-n1-4-n4":{"title":"Để dùng thông tin một cách khôn ngoan","topic":"Truyền thông","trans":["Nhờ có điện thoại thông minh, chúng ta có thể xem rất nhiều thông tin bất cứ lúc nào. Nhưng nó không chỉ tiện lợi mà còn có những vấn đề cần lưu ý.","Trên Internet có rất nhiều thông tin không rõ thật hay giả. Cũng có người với ý đồ xấu đã lan truyền tin giả. Vì vậy, khả năng tách bạch sự thật và ý kiến để suy xét trở nên rất quan trọng.","Điều rắc rối hơn là toàn những thông tin mình thích cứ hiện ra. Trong lúc không hay biết, thế giới mình nhìn thấy sẽ bị thu hẹp lại. Điều quan trọng là đừng tin ngay vào một thông tin, mà hãy xem cả những thông tin khác để kiểm chứng. Khi tự mình đăng tải thông tin, bạn cũng phải chịu trách nhiệm về nội dung. Khả năng đọc thông tin một cách đúng đắn không còn chỉ dành cho chuyên gia nữa. Để sống trong thời đại ngày nay, đây là năng lực quan trọng mà ai cũng nên có."],"vocab":["thông tin","tiện lợi","vấn đề","thật, sự thật","lan truyền, phổ biến","sự thật","ý kiến","xác nhận, kiểm chứng","trách nhiệm","học được, trang bị (năng lực)"],"grammar":[{"t":"〜ようになる","note":"Chỉ sự thay đổi, việc trước đây không làm được thì nay trở nên làm được. Ví dụ:「いつでもたくさんの情報が見られるようになった」"},{"t":"〜ないで","note":"Nghĩa là「không làm việc này mà làm việc khác」. Ví dụ:「一つの情報をすぐ信じないで、ほかの情報も見て確かめることだ」"},{"t":"〜なければならない","note":"Chỉ việc bắt buộc phải làm. Ví dụ:「内容に責任を持たなければならない」"},{"t":"〜ばかり","note":"Chỉ hầu như toàn là cùng một loại. Ví dụ:「自分が好きな情報ばかり出てくる」"}]},"a-n1-3-n3":{"title":"Vấn đề già hóa dân số và giảm sinh","topic":"Xã hội","trans":["Nhật Bản đang già hóa dân số và giảm sinh với tốc độ nhanh đến mức hiếm thấy ngay cả trên thế giới. Tỷ lệ người cao tuổi trong tổng dân số tăng lên từng chút một mỗi năm. Mặt khác, số trẻ em được sinh ra vẫn tiếp tục giảm.","Nếu cứ tiếp tục như thế này, các chế độ an sinh xã hội như lương hưu, y tế, chăm sóc điều dưỡng có thể sẽ không thể duy trì được nữa. Bởi vì chi phí cho những khoản này đang tăng lên, trong khi thế hệ lao động gánh vác chúng lại ngày càng ít đi.","Để đối phó, người ta đang cân nhắc việc hoàn thiện hơn nữa các chế độ giúp cân bằng giữa nuôi con và đi làm dễ dàng hơn. Việc tăng số lượng lao động nước ngoài được tiếp nhận cũng đang được thảo luận. Tuy nhiên, không có vấn đề nào trong số đó có thể giải quyết ngay được.","Đằng sau việc trẻ em ít đi là nhiều lý do khác nhau, chẳng hạn như nỗi lo về tiền bạc và sự thay đổi trong suy nghĩ. Vì vậy, không phải chỉ cần phát tiền hỗ trợ là vấn đề sẽ được giải quyết. Già hóa dân số và giảm sinh đã trở thành một thực tế không thể tránh khỏi. Cả xã hội phải đối mặt với nó như thế nào và để lại cho thế hệ sau một đất nước ra sao, chúng ta cần suy nghĩ nghiêm túc."],"vocab":["già hóa dân số và giảm sinh","tỷ lệ","lương hưu","chăm sóc điều dưỡng","gánh vác, chống đỡ","cân bằng cả hai, vừa làm được cả hai","tiếp nhận, chấp nhận","bối cảnh, nền tảng","tiền trợ cấp","thực tế"],"grammar":[{"t":"〜かもしれない","note":"Diễn tả suy đoán không chắc chắn của người nói: \"có lẽ, có thể\". Ví dụ: 「社会保障の制度が続けられなくなるかもしれない」"},{"t":"〜やすい","note":"Đi sau thể ます của động từ (bỏ ます), nghĩa là \"dễ làm gì đó\". Ví dụ: 「子育てと仕事を両立しやすくする制度」"},{"t":"〜わけではない","note":"Nghĩa là \"không có nghĩa là...\", phủ định một phần, phủ định suy nghĩ thường dễ nảy sinh. Ví dụ: 「補助金を配るだけで問題が解決するわけではない」"},{"t":"〜なければならない","note":"Diễn tả \"phải, bắt buộc phải\", nói về nghĩa vụ hoặc sự cần thiết. Ví dụ: 「真剣に考えなければならない」"}]},"a-n1-3-n4":{"title":"Vấn đề già hóa dân số và giảm sinh","topic":"Xã hội","trans":["Nhật Bản là một trong những nước già hóa dân số và giảm sinh rất nhanh trên thế giới. Tỷ lệ người cao tuổi mỗi năm lại tăng dần. Nhưng số trẻ em được sinh ra thì cứ liên tục giảm.","Nếu cứ thế này, những cơ chế quan trọng của xã hội có thể sẽ gặp khó khăn. Số tiền dùng cho lương hưu, y tế, chăm sóc điều dưỡng có vẻ sẽ còn tăng nữa. Nhưng thế hệ lao động gánh vác những khoản đó thì lại ít dần đi.","Để đối phó, người ta đang thảo luận về các chế độ giúp vừa nuôi con vừa dễ đi làm. Cũng có chuyện tăng thêm lao động nước ngoài, nhưng không thể giải quyết ngay được. Lý do trẻ em sinh ra ít đi có rất nhiều, chẳng hạn như nỗi lo về tiền bạc. Già hóa dân số và giảm sinh là vấn đề không thể xóa bỏ, nên mọi người hãy cùng nhau thảo luận nghiêm túc nhé."],"vocab":["già hóa dân số và giảm sinh","người cao tuổi","tỷ lệ","tăng","giảm","lương hưu","gánh vác, chống đỡ","chế độ","giải quyết","nghiêm túc"],"grammar":[{"t":"〜かもしれません","note":"Diễn tả suy đoán không chắc chắn của người nói: \"có lẽ, có thể\". Ví dụ: 「社会の大切な仕組みが大変になるかもしれません」"},{"t":"Động từ thể ます (bỏ ます) + そうです","note":"Diễn tả suy đoán dựa vào tình hình hiện tại: \"trông có vẻ sẽ...\". Ví dụ: 「これからも増えそうです」"},{"t":"〜ながら","note":"Diễn tả một người làm hai việc cùng lúc: \"vừa... vừa...\". Ví dụ: 「子育てをしながら働きやすくする制度」"},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do, giọng nhẹ nhàng hơn「から」. Ví dụ: 「なくせない問題なので、みんなで真剣に話し合いましょう」"}]},"a-n1-6-n3":{"title":"Những điều được truyền lại","topic":"Văn hóa","trans":["Văn hóa truyền thống và tay nghề của các nghệ nhân trên khắp Nhật Bản là tài sản quý giá đã được truyền lại qua một thời gian dài. Thế nhưng hiện nay, nhiều thứ trong số đó đang đối mặt với nguy cơ có thể biến mất.","Nguyên nhân lớn nhất là thiếu người kế nghiệp để tiếp nối nghề. Không chỉ dân số ngày càng già đi, mà thanh niên cũng rời lên thành phố, nên số người muốn học nghề giảm dần theo từng năm.","Tuy nói là giữ gìn truyền thống, nhưng không có nghĩa là cứ giữ nguyên như xưa là được. Chỉ khi tạo ra giá trị mới phù hợp với sự thay đổi của thời đại, văn hóa mới có thể tiếp tục sống.","Gần đây, ngày càng có nhiều ví dụ đưa thiết kế hiện đại vào nghề thủ công truyền thống. Những nỗ lực quảng bá nét hấp dẫn ấy ra nước ngoài cũng đang dần lan rộng. Kết hợp cái cũ với cái mới có lẽ sẽ là chìa khóa mở ra con đường phía trước. Làm thế nào để nối tiếp những gì người xưa đã xây dựng cho thế hệ sau? Đó có lẽ là một bài tập lớn dành cho mỗi người chúng ta."],"vocab":["được truyền lại, lưu truyền","nghệ nhân, thợ thủ công lành nghề","kế thừa, tiếp nối","tài sản, của cải","khủng hoảng, nguy cơ","đối mặt","người kế nghiệp","già hóa (dân số)","giữ, duy trì","tạo ra, sản sinh"],"grammar":[{"t":"〜というわけではない","note":"Nghĩa là \"không có nghĩa là...\", dùng để phủ định một phần. Ví dụ: 「昔のままを保てばいいというわけではない」"},{"t":"〜といっても","note":"Nghĩa là \"tuy nói là... nhưng...\", dùng để bổ sung hoặc điều chỉnh ấn tượng ở vế trước. Ví dụ: 「伝統を守るといっても、昔のままを保てばいいというわけではない」"},{"t":"〜によって","note":"Chỉ phương tiện hoặc cách thức, nghĩa là \"bằng cách...\", \"nhờ...\". Ví dụ: 「新しい価値を生み出すことによって、文化は生き続けることができる」"},{"t":"〜ため(に)","note":"Chỉ nguyên nhân, lý do, nghĩa là \"vì...\". Ví dụ: 「若者が都市に出ていくため、学ぼうとする人は毎年減っている」"}]},"a-n1-6-n4":{"title":"Những điều được truyền lại","topic":"Văn hóa","trans":["Nhật Bản có rất nhiều nét văn hóa và tay nghề của các nghệ nhân được truyền lại từ xưa. Đó là những thứ đã được gìn giữ cẩn thận qua một thời gian dài. Nhưng hiện nay, nhiều thứ trong số đó sắp biến mất, khiến mọi người rất lo lắng.","Lý do lớn nhất là không đủ người tiếp tục nghề. Những người có tay nghề đang dần lớn tuổi. Giới trẻ rời lên thành phố, và số người học nghề cũng ít đi mỗi năm.","Để giữ gìn truyền thống thì không thể chỉ giữ nguyên như xưa. Tạo ra những nét hay mới phù hợp với thời đại cũng rất quan trọng. Gần đây, có những người đưa thiết kế mới vào nghề thủ công cũ. Những người giới thiệu nét hay đó ra nước ngoài cũng đã nhiều lên. Để lưu lại những thứ xưa cho thế hệ sau, chúng ta cũng muốn suy nghĩ xem mình có thể làm được gì."],"vocab":["truyền thống","nghệ nhân, thợ thủ công lành nghề","tay nghề, kỹ thuật","lo lắng","lý do","thành phố","học","nghề thủ công","thế hệ"],"grammar":[{"t":"〜そうだ(樣態)","note":"Diễn tả vẻ bề ngoài cho thấy sắp xảy ra điều gì đó. Ví dụ: 「その多くがなくなりそうで」nghĩa là nhiều thứ sắp biến mất."},{"t":"〜てきた","note":"Diễn tả sự thay đổi đã tiếp diễn liên tục cho đến hiện tại. Ví dụ: 「人も増えてきました」nghĩa là số người cũng dần tăng lên."},{"t":"〜ために","note":"Diễn tả mục đích, nghĩa là \"để làm gì đó\". Ví dụ: 「次の世代に残すために」nghĩa là để lưu lại cho thế hệ sau."},{"t":"〜たいです","note":"Diễn tả mong muốn của người nói. Ví dụ: 「考えたいです」nghĩa là muốn suy nghĩ."}]},"a-n1-5-n3":{"title":"Thức ăn bị vứt bỏ","topic":"Xã hội","trans":["Thức ăn vẫn còn ăn được nhưng lại bị vứt đi đang trở thành một vấn đề lớn trên toàn thế giới. Loại thức ăn như vậy được gọi là「食品ロス」(lãng phí thực phẩm). Người ta nói rằng ngay cả ở Nhật Bản, mỗi năm cũng có hàng triệu tấn thực phẩm bị vứt bỏ một cách lãng phí.","Mặt khác, trên thế giới có rất nhiều người không có đủ cơm ăn. Đằng sau cuộc sống tưởng như thức ăn thừa mứa, một khoảng cách rất lớn đang hình thành.","Nguyên nhân của lãng phí thực phẩm không chỉ là đồ ăn thừa từ gia đình hay nhà hàng. Những sản phẩm lẽ ra vẫn bán được lại bị xử lý hàng loạt vì lý do hạn sử dụng cũng là một nguyên nhân. Chúng ta không thể làm ngơ trước thực trạng này.","Để giải quyết vấn đề này, nỗ lực của doanh nghiệp là điều đương nhiên, ý thức của mỗi người cũng rất quan trọng. Những việc nhỏ như không mua quá nhiều, không nấu quá nhiều sẽ trở thành một bước tiến lớn. Trân trọng nguồn tài nguyên có hạn cũng là trách nhiệm đối với thế hệ sau. Lối sống không lãng phí thức ăn đang được coi trọng trở lại vào lúc này."],"vocab":["lãng phí thực phẩm","vứt bỏ","lãng phí, vô ích","đủ, đầy đủ","hạn sử dụng (thời hạn ngon nhất)","xử lý, giải quyết (hàng hóa)","làm ngơ, bỏ qua","nỗ lực, biện pháp","ý thức","sự lưu tâm, để ý"],"grammar":[{"t":"〜ように見える","note":"Diễn tả ý \"trông có vẻ như…\". Ví dụ:「食べ物があふれているように見える生活の裏で、大きな差が生まれているのです」"},{"t":"〜わけではない","note":"Diễn tả ý \"không phải là…\", phủ định một phần, phủ định nhẹ nhàng một suy nghĩ nào đó. Ví dụ:「このような現状を、見逃していいわけではありません」"},{"t":"〜ためには","note":"Diễn tả ý \"để…thì phải…\", phía sau là điều kiện hoặc cách làm cần thiết. Ví dụ:「この問題を解決するためには、企業の取り組みはもちろん、一人ひとりの意識も大切です」"},{"t":"〜はもちろん","note":"Diễn tả ý \"…là điều đương nhiên, ngay cả…cũng\", nêu ví dụ hiển nhiên trước. Ví dụ:「企業の取り組みはもちろん、一人ひとりの意識も大切です」"}]},"a-n1-5-n4":{"title":"Thức ăn bị vứt bỏ","topic":"Xã hội","trans":["Thức ăn vẫn còn ăn được nhưng lại bị vứt đi đã trở thành vấn đề của cả thế giới. Việc lãng phí thức ăn như vậy được gọi là 食品ロス (lãng phí thực phẩm). Nghe nói ở Nhật Bản, mỗi năm cũng có rất nhiều thức ăn bị vứt đi một cách lãng phí.","Mặt khác, trên thế giới có rất nhiều người không được ăn đủ no. Đằng sau những quốc gia nhiều thức ăn, một khoảng cách rất lớn đã hình thành. Nguyên nhân của lãng phí thực phẩm không chỉ là cơm canh thừa ở nhà hay ở nhà hàng.","Những sản phẩm vẫn bán được cũng bị vứt đi nhiều vì hạn sử dụng. Để giải quyết vấn đề này, nỗ lực của công ty và suy nghĩ của mỗi người đều quan trọng. Cố gắng không mua quá nhiều, không nấu quá nhiều sẽ là một bước tiến lớn. Trân trọng nguồn tài nguyên có hạn cũng là trách nhiệm đối với thế hệ sau. Hãy cùng suy nghĩ lại về lối sống không lãng phí thức ăn ngay từ bây giờ nhé."],"vocab":["bị vứt đi","lãng phí thực phẩm","vấn đề","mỗi năm","lãng phí, vô ích","đủ","nguyên nhân","giải quyết","quan trọng, trân trọng","trách nhiệm"],"grammar":[{"t":"〜のに","note":"Diễn tả ý \"rõ ràng… vậy mà…\", mang sắc thái bất mãn hoặc tiếc nuối. Ví dụ:「まだ食べられるのに捨てられてしまう食べ物が、世界で問題になっている」"},{"t":"〜そうだ(傳聞)","note":"Gắn sau thể thông thường, diễn tả ý \"nghe nói…\". Ví dụ:「日本でも、毎年とても多くの食べ物がむだに捨てられているそうだ」"},{"t":"Thể khả năng (食べられる)","note":"Chuyển động từ sang thể khả năng để diễn tả \"có thể…\", dạng phủ định là \"không thể…\". Ví dụ:「世界にはご飯を十分に食べられない人がたくさんいる」"},{"t":"〜ようにする","note":"Diễn tả việc cố gắng tạo thói quen hoặc cố hết sức làm gì đó (phủ định là「〜ないようにする」). Ví dụ:「買いすぎない、作りすぎないようにするのが、大きな一歩になる」"}]},"a-n1-7-n3":{"title":"変わりゆく日本語","topic":"Ngôn ngữ","trans":["Bạn đã bao giờ nghe đến từ 「ら抜き言葉」 (từ bị lược \"ら\") chưa? Việc nói 「食べられる」 thành 「食べれる」 thường bị cho là tiếng Nhật không chuẩn. Vì đây là dạng bỏ \"ら\" khỏi 「食べられる」 nên cũng có người cảm thấy chướng tai.","Tuy nhiên, nếu nhìn từ góc độ ngôn ngữ học, cũng có quan điểm cho rằng đây không đơn thuần là sự \"lộn xộn\" của ngôn ngữ mà là một sự thay đổi hợp lý. 「見られる」 có nhiều nghĩa như bị động, kính ngữ, khả năng. Còn với 「見れる」 thì có thể nhận ra ngay đó là nghĩa khả năng. Có lẽ chính vì trở nên dễ hiểu hơn nên nó mới thay đổi như vậy.","Suy cho cùng, ngôn ngữ vốn luôn thay đổi từ xa xưa. Tiếng Nhật mà ngày nay chúng ta tin là \"chuẩn\", trong mắt người của một trăm năm trước cũng chỉ là thứ ngôn ngữ méo mó mà thôi. Nếu người của một trăm năm trước nghe tiếng Nhật bây giờ, có thể họ cũng sẽ thấy rất kỳ lạ.","Thay vì buồn bã trước sự thay đổi, chẳng phải suy nghĩ xem \"vì sao lại thay đổi\" sẽ giúp ta đến gần hơn với bản chất của ngôn ngữ sao? Khi ngôn ngữ thay đổi, chắc chắn phải có lý do nào đó."],"vocab":["ngôn ngữ học","lập trường, quan điểm","đơn thuần, chỉ là","hợp lý","sự thay đổi","bị động (thể bị động)","tôn kính (kính ngữ)","khả năng (có thể làm)","đang tin, tin chắc","bản chất"],"grammar":[{"t":"〜ため (nguyên nhân・lý do)","note":"Chỉ nguyên nhân hoặc lý do, mang tính văn viết hơn 「から」. Ví dụ: 「分かりやすくなるため」 giải thích lý do của sự thay đổi."},{"t":"〜にすぎない","note":"Nghĩa là \"chỉ là, chẳng qua là\", mang sắc thái \"không có gì to tát\". Ví dụ: 「乱れた言葉にすぎないでしょう」."},{"t":"〜より〜ほうが","note":"So sánh hai việc, nghĩa là \"thay vì A thì B hơn\". Ví dụ: 「変化を悲しむより、なぜ変わるのかを考えるほうが」."},{"t":"〜はずだ","note":"Diễn tả suy đoán dựa trên lẽ thường hoặc căn cứ, nghĩa là \"chắc hẳn, lẽ ra phải\". Ví dụ: 「何か理由があるはずです」."}]},"a-n1-7-n4":{"title":"変わっていく日本語","topic":"Ngôn ngữ","trans":["Bạn đã bao giờ nghe đến từ 「ら抜き言葉」 chưa? Bây giờ có nhiều người nói 「食べられる」 thành 「食べれる」. Nhưng cách nói này thường bị cho là tiếng Nhật không chuẩn.","Có những người nghiên cứu về ngôn ngữ cho rằng đây không phải là một sự thay đổi xấu. 「見られる」 có vài nghĩa nên đôi khi khó phân biệt. Nhưng nếu là 「見れる」 thì có thể biết ngay là nghĩa \"có thể xem\".","Hơn nữa, ngôn ngữ vốn luôn thay đổi từ xưa đến nay. Tiếng Nhật mà bây giờ được cho là chuẩn, với người của một trăm năm trước chắc cũng là cách nói kỳ lạ. Thay vì buồn vì sự thay đổi, bạn thử nghĩ xem vì sao nó thay đổi nhé?"],"vocab":["ngôn ngữ, từ ngữ","đã nghe (thể quá khứ của 聞く)","đúng, chuẩn","nghiên cứu","sự thay đổi","ý nghĩa","hiểu, biết","ngày xưa, từ lâu","cảm thấy buồn","suy nghĩ (thể て của 考える)"],"grammar":[{"t":"〜たことがある","note":"Diễn tả kinh nghiệm đã từng làm gì. Ví dụ: 「聞いたことがありますか」 là hỏi đối phương đã từng nghe chưa."},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do, nhẹ nhàng hơn 「から」. Ví dụ: 「いくつか意味があるので、分かりにくいことがあります」"},{"t":"〜にくい","note":"Gắn sau thể ます của động từ (bỏ ます), diễn tả việc khó làm. Ví dụ: 「分かりにくいことがあります」"},{"t":"〜てくる","note":"Diễn tả sự thay đổi diễn ra liên tục từ quá khứ đến hiện tại. Ví dụ: 「言葉は昔からずっと変わってきました」"}]},"a-n1-8-n3":{"title":"Nhân lực nước ngoài và tương lai của xã hội Nhật Bản","topic":"Xã hội","trans":["Vấn đề thiếu nhân lực được cho là sẽ còn tiếp diễn trong thời gian tới. Vì vậy, việc tiếp nhận người nước ngoài không còn có thể gọi là biện pháp tạm thời nữa.","Sau khi các chế độ như Kỹ năng đặc định được thiết lập, số người nước ngoài sống ở Nhật liên tục lập kỷ lục cao nhất từ trước đến nay. Tuy nhiên, không phải cứ có nhiều người hơn thì họ sẽ sống lâu dài ở Nhật.","Nếu nền tảng cuộc sống như ngôn ngữ không thông, việc tìm nhà ở, giáo dục cho con cái… chưa vững chắc, thì dù có tăng lương hay cải thiện điều kiện, người ta cũng sẽ không ổn định cuộc sống ở Nhật.","Sau khi tuyển dụng người, doanh nghiệp cũng cần dạy tiếng Nhật và tạo ra sự gắn kết với người dân địa phương.","Cách nghĩ của chúng ta, những người tiếp nhận, cũng rất quan trọng. Vấn đề được đặt ra là liệu chúng ta có thể không chỉ xem họ là \"người lao động\", mà còn cư xử với họ như những người hàng xóm sống cùng khu vực hay không.","Tuy có những phần thay đổi tùy theo chế độ, nhưng điều quyết định cuối cùng việc họ có ở lâu dài hay không có lẽ là sự tích lũy của những mối quan hệ nhỏ bé hằng ngày.","Suy nghĩ về vấn đề người nước ngoài cũng chính là suy nghĩ xem Nhật Bản muốn trở thành một xã hội như thế nào."],"vocab":["nhân lực, nhân công","tiếp nhận, chấp nhận","mang tính tạm thời","chế độ, thể chế","nền tảng, cơ sở","ổn định cuộc sống, định cư","doanh nghiệp","khu vực, cộng đồng địa phương","hàng xóm"],"grammar":[{"t":"〜ようになる/〜ようにする(ở đây là 〜と考えられている)","note":"Bài dùng「考えられている」(thể bị động) để diễn đạt quan điểm chung. 「人手が足りない問題は、これからも続くと考えられている」"},{"t":"〜からといって〜わけではない","note":"Diễn tả \"dù có lý do nào đó thì cũng không hẳn là...\". 「人が増えたからといって、その人たちが日本に長く住むわけではない」"},{"t":"〜によって","note":"Diễn tả căn cứ, nguyên nhân hoặc phương tiện; ở đây nghĩa là \"tùy theo chế độ mà khác nhau\". 「制度によって変わる部分もあるが」"},{"t":"〜かどうか","note":"Diễn tả \"có... hay không\", đưa câu hỏi vào bên trong câu. 「同じ地域に住む隣人として付き合えるかどうかが問われている」"}]},"a-n1-8-n4":{"title":"Người từ nước ngoài đến và tương lai của Nhật Bản","topic":"Xã hội","trans":["Nhật Bản hiện nay vẫn liên tục gặp vấn đề thiếu người lao động. Vì vậy, việc nhờ người từ nước ngoài đến làm việc không còn chỉ là biện pháp trong thời gian ngắn nữa.","Sau khi có chế độ mới, số người nước ngoài sống ở Nhật đang ở mức nhiều nhất từ trước đến nay. Nhưng dù số người tăng lên, cũng không chắc họ sẽ sống ở Nhật mãi mãi. Nếu tiếng Nhật khó, tìm nhà vất vả, hoặc lo lắng về việc học của con, thì cuộc sống sẽ không ổn định. Dù lương có tốt hơn, nếu cuộc sống không ổn định thì người đó cũng không thể ở Nhật lâu dài.","Công ty cũng cần dạy tiếng Nhật sau khi họ bắt đầu làm việc và tạo cơ hội để họ gặp gỡ người dân địa phương. Người Nhật cũng mong rằng đừng chỉ xem người nước ngoài là \"người lao động\", mà hãy nghĩ về họ như những người hàng xóm sống cùng một thị trấn. Suy nghĩ về người nước ngoài cũng chính là suy nghĩ xem Nhật Bản muốn trở thành một xã hội như thế nào."],"vocab":["thiếu, không đủ","chế độ, thể chế","tăng lên","cuộc sống","ổn định","lương","khu vực, địa phương","cơ hội","bên cạnh, hàng xóm","xã hội"],"grammar":[{"t":"〜ても","note":"Diễn tả \"dù... cũng...\". Ví dụ: 「給料がよくなっても、生活が安定しなければ、その人は日本に長くいられない」"},{"t":"〜ば(thể điều kiện)","note":"Diễn tả điều kiện \"nếu... thì...\". Ví dụ: 「生活が安定しなければ、その人は日本に長くいられない」"},{"t":"〜とは限らない","note":"Diễn tả \"không hẳn là...\". Ví dụ: 「ずっと日本に住むとは限らない」"},{"t":"〜てほしい","note":"Diễn tả mong muốn đối phương làm một việc gì đó. Ví dụ: 「同じ町に住む隣の人として考えてほしい」"}]},"a-n2-1-n3":{"title":"Sự thay đổi trong cách làm việc","topic":"Xã hội","trans":["Những năm gần đây, nhờ internet phát triển, cách làm việc của mọi người đã thay đổi rất nhiều. Trước đây, đến công ty làm việc là chuyện đương nhiên, nhưng giờ số người không như vậy ngày càng nhiều. Ngày càng có nhiều doanh nghiệp áp dụng hình thức \"làm việc từ xa\", tức là không đến công ty mà làm việc tại nhà.","Làm việc từ xa có ưu điểm là giảm được thời gian đi lại. Tuy nhiên, cũng có vấn đề là khó phân biệt giữa công việc và cuộc sống. Ngoài ra, số người không làm việc theo giờ cố định mà tự điều chỉnh thời gian để làm việc cũng nhiều hơn.","Như vậy, nhờ làm việc từ xa được phổ biến, mức độ tự do về nơi làm việc và thời gian đã cao hơn. Mặt khác, một vấn đề mới cũng xuất hiện là ranh giới giữa công việc và cuộc sống trở nên mờ nhạt. Cùng với những thay đổi này, chúng ta có lẽ cũng cần suy nghĩ về những cách làm việc mới.","Từ nay về sau, xã hội cần một môi trường cho phép mỗi người chọn cách làm việc phù hợp với mình. Để làm được điều đó, mình nghĩ cả công ty lẫn người lao động đều cần cố gắng tìm hiểu suy nghĩ của nhau."],"vocab":["phát triển","áp dụng, đưa vào","doanh nghiệp, công ty","đi làm (đi lại giữa nhà và nơi làm việc)","sự phân biệt, phân chia","điều chỉnh","ranh giới, điểm phân chia","vấn đề cần giải quyết, thách thức","được yêu cầu, được đòi hỏi"],"grammar":[{"t":"〜ことによって","note":"Nghĩa là \"nhờ/bởi việc ...\", diễn tả nguyên nhân hoặc phương tiện. Ví dụ: 「テレワークが広がったことによって、働く場所や時間の自由度は高くなりました」"},{"t":"〜一方で","note":"Nghĩa là \"một mặt ..., mặt khác ...\", thường đi với khía cạnh trái ngược hoặc khác biệt. Ví dụ: 「その一方で、仕事と生活の境目があいまいになるという課題も生まれています」"},{"t":"〜に合わせて","note":"Nghĩa là \"phù hợp với, theo, cùng với ...\". Ví dụ: 「こうした変化に合わせて、私たちも新しい働き方を考えていく必要があるでしょう」"},{"t":"〜のではなく","note":"Nghĩa là \"không phải ... mà là ...\", phủ định vế trước và nhấn mạnh vế sau. Ví dụ: 「決まった時間に働くのではなく、自分で時間を調整して働く人も多くなりました」"}]},"a-n2-1-n4":{"title":"Sự thay đổi trong cách làm việc","topic":"Xã hội","trans":["Internet trở nên tiện lợi hơn, nên cách làm việc đã thay đổi rất nhiều.","Ngày càng có nhiều công ty cho nhân viên làm việc tại nhà thay vì đến công ty. Thời gian đi tàu điện ít đi, nên rất nhẹ nhàng. Nhưng cũng có vấn đề là khó phân biệt giữa công việc và cuộc sống.","Ngoài ra, số người tự quyết định thời gian làm việc cũng nhiều hơn.","Tuy có thể làm việc tự do, nhưng dường như cũng có người quên mất thời gian nghỉ ngơi.","Từ nay về sau, một xã hội cho phép chọn cách làm việc phù hợp với mình là điều quan trọng.","Chúng ta cũng phải suy nghĩ về những cách làm việc mới."],"vocab":["tiện lợi","thay đổi","tăng lên","sự phân biệt, phân chia","vấn đề","quyết định","tự do","quên","xã hội","quan trọng"],"grammar":[{"t":"〜て(で)、〜(thể て chỉ nguyên nhân・trình tự)","note":"Dùng thể て để nối hai vế câu, diễn tả nguyên nhân hoặc trình tự. Ví dụ: 「インターネットが 便利に なって、はたらき方が 大きく 変わりました」"},{"t":"〜ないで","note":"Nghĩa là \"không làm ... mà làm ...\". Ví dụ: 「会社に 行かないで、家で 仕事を する」"},{"t":"Thể khả năng (はたらける・えらべる)","note":"Diễn tả có thể làm việc gì đó. Ví dụ: 「自由に はたらける」「自分に 合った はたらき方を えらべる」"},{"t":"〜ようだ","note":"Suy đoán dựa trên tình hình, nghĩa là \"dường như ...\". Ví dụ: 「忘れて しまう 人も いるようです」"}]},"a-n1-9-n3":{"title":"Khoảng cách giữa người với người trong không gian sống","topic":"Văn hóa","trans":["Trong những ngôi nhà Nhật Bản, ở nhiều nơi ẩn chứa cách giữ khoảng cách với người khác mà không ai nói thành lời. Ví dụ, thói quen cởi giày ở lối vào (genkan) đã vạch ra một ranh giới rõ ràng giữa \"bên ngoài\" và \"bên trong\". Động tác bước qua bậc thềm không chỉ là di chuyển, mà giống như một nghi thức để chuyển đổi tâm trạng.","Điểm thú vị của các vách ngăn như cửa fusuma hay shoji là chúng không đóng kín hoàn toàn. Dù chỉ là một lớp mỏng để âm thanh và hơi người xuyên qua được, người ta vẫn xem như không gian đã được chia ra. Sự mơ hồ này có lẽ chính là trí tuệ để sống cùng người khác trong những ngôi nhà chật hẹp.","Ngay cả bây giờ, khi chung cư đã trở thành phổ biến, cảm giác ấy vẫn còn lại dưới một hình thức khác. Việc để ý đến tiếng ồn sinh hoạt không phải chỉ vì tường mỏng. Có thể cho rằng đó là vì phép tắc có từ xưa là \"không xâm phạm không gian của nhau\" vẫn đang được duy trì đến ngày nay.","Tuy nhiên, kiểu khoảng cách này rất khó để người từ bên ngoài nhận ra. Vì không có quy định nào được viết ra, nên họ thường băn khoăn không biết có nên chào hỏi hay không, và có thể đến gần đến mức nào. Nhưng điều đó cũng có nghĩa là mức độ vừa phải được giao cho từng người tự cân nhắc. Nhà ở có lẽ là nơi câu hỏi \"nên đo khoảng cách với người khác như thế nào\" được lặng lẽ lặp lại mỗi ngày."],"vocab":["lối vào (genkan)","thói quen","nghi thức","vách ngăn","hơi người, dấu hiệu","mơ hồ, nhập nhằng","trí tuệ, sự khôn ngoan","khu chung cư, nhà tập thể","phạm vi, lãnh địa","phép tắc, quy tắc ứng xử"],"grammar":[{"t":"〜のようなもの","note":"Nghĩa là \"cái gì đó giống như…\", dùng để so sánh. Ví dụ: 「気持ちを切り替えるための儀式のようなものだ」 ví động tác bước qua bậc thềm như một nghi thức."},{"t":"〜ことにする","note":"Nghĩa là \"coi như là…\" hoặc tự quyết định làm việc gì. Trong bài dùng theo nghĩa \"coi như đã chia ra\". Ví dụ: 「それでも空間を分けたことにする」"},{"t":"〜わけではない","note":"Nghĩa là \"không có nghĩa là…\", phủ định một phần, dùng để bác bỏ một suy nghĩ hay lý do thường thấy. Ví dụ: 「壁が薄いからというわけではない」"},{"t":"〜ため(nguyên nhân)","note":"Chỉ nguyên nhân, lý do, mang tính văn viết hơn 「から」. Ví dụ: 「今も続いているためだと考えられる」"}]},"a-n1-9-n4":{"title":"Cảm giác về khoảng cách trong ngôi nhà","topic":"Văn hóa","trans":["Trong nhà ở Nhật Bản có rất nhiều cách giữ khoảng cách với người khác mà không nói thành lời. Chỉ riêng thói quen cởi giày ở lối vào (genkan) cũng đã có một ranh giới chia bên ngoài và bên trong. Động tác bước lên khỏi genkan giống như một nghi thức nhỏ để đổi tâm trạng.","Cửa fusuma và shoji dù để âm thanh và động tĩnh của người khác lọt qua, vẫn chia căn phòng ra. Sự mơ hồ này có lẽ là trí tuệ để sống chung với người khác trong những ngôi nhà chật hẹp. Bây giờ chung cư đã nhiều hơn, nhưng cảm giác ấy vẫn còn lại dưới một hình thức khác. Việc để ý đến tiếng ồn sinh hoạt cũng là một phép tắc: không xâm phạm không gian của nhau.","Tuy nhiên, với người từ nước ngoài đến, cảm giác về khoảng cách này rất khó hiểu. Họ băn khoăn không biết có nên chào hỏi không, và nên đến gần đến mức nào, vì không có quy định. Nhưng điều đó cũng có nghĩa là mỗi người có thể tự quyết định. Nhà ở có lẽ là nơi mỗi ngày ta lặng lẽ suy nghĩ về khoảng cách với người khác."],"vocab":["lối vào (genkan)","thói quen","cởi giày","shoji (cửa giấy kiểu Nhật)","trí tuệ, sự khôn ngoan","cảm giác","sinh hoạt, cuộc sống","khoảng cách","băn khoăn, phân vân","quyết định"],"grammar":[{"t":"〜ようなものだ","note":"Nghĩa là \"giống như…\", dùng để so sánh. Ví dụ: 「気持ちを変える小さな儀式のようなものだ」"},{"t":"〜のに","note":"Nghĩa là \"mặc dù… nhưng…\", diễn tả sự trái ngược giữa hai vế. Ví dụ: 「音も人の様子も通すのに、部屋を分けてくれる」"},{"t":"〜にくい","note":"Gắn sau động từ thể ます (bỏ ます), nghĩa là \"khó…\". Ví dụ: 「この距離感は分かりにくい」"},{"t":"〜かもしれない","note":"Nghĩa là \"có lẽ…\", diễn tả suy đoán không chắc chắn của người nói. Ví dụ: 「場所なのかもしれない」"}]},"a-n2-10-n3":{"title":"Thử thực hành báo cáo・liên lạc・thảo luận","topic":"Công sở","trans":["「報連相」là cụm từ thường được nhắc đến ở nơi làm việc của Nhật. Nhớ thì dễ, nhưng làm thật lại khó. Đặc biệt là nhân viên nước ngoài, họ thường phân vân không biết có nên báo cáo khi chưa có kết luận hay không. Xin nói đáp án trước: dù chưa có kết luận, bạn vẫn có thể báo cáo.","Khi công việc không tiến triển như mong muốn thì càng quan trọng phải báo sớm. Bởi vì điều sếp muốn biết không phải là một bản báo cáo hoàn hảo, mà là một lời nhắn trước khi vấn đề trở nên lớn hơn. Bạn chỉ cần nói: 「今半分ほど進んでいますが、資料待ちで少し遅れそうです」là đủ.","Khi thảo luận, bạn không cần có sẵn câu trả lời. Đi hỏi ý kiến không nhất thiết là để nhận được đáp án. Chỉ cần giải thích được mình đang vướng ở đâu, thế là đã thành một buổi trao đổi rất tốt rồi.","「報連相」không hẳn là phép lịch sự giữa cấp trên và cấp dưới, mà đúng hơn là cơ chế giúp cả nhóm tránh sự cố. Nếu nghĩ theo cách đó, tâm trạng của bạn sẽ nhẹ nhõm hơn nhiều."],"vocab":["nơi làm việc, công sở","thực tế, trên thực tế","kết luận","báo cáo","sớm, sớm hơn một chút","cấp trên, sếp","hoàn hảo","tài liệu, dữ liệu","sự cố, tai nạn","cơ chế, cấu trúc"],"grammar":[{"t":"〜ように(様態・目標)","note":"Diễn tả ý \"theo như, giống như～\". Ví dụ: 「仕事が思うように進んでいないときほど」「そう考えるようにすれば」."},{"t":"〜わけではない","note":"Diễn tả ý \"không phải là～\", phủ định một phần. Ví dụ: 「相談は、必ず答えをもらうために行くわけではないのです」."},{"t":"〜というより","note":"Diễn tả ý \"nói là～thì đúng hơn là…\". Ví dụ: 「上下関係のマナーというより、チームで事故を防ぐための仕組みです」."},{"t":"〜ほど","note":"Diễn tả ý \"càng～càng…\", mức độ thay đổi theo điều kiện. Ví dụ: 「進んでいないときほど、早めに伝えることが大切です」."}]},"a-n2-10-n4":{"title":"Thử làm tốt báo cáo・liên lạc・thảo luận","topic":"Công sở","trans":["Ở các công ty Nhật, mọi người thường dùng từ「報・連・相」. Nhớ thì dễ, nhưng làm thật lại khó. Nhân viên nước ngoài hay phân vân: \"Khi chưa có câu trả lời thì có được nói không nhỉ?\"","Nhưng chưa có câu trả lời cũng không sao. Khi công việc không tiến triển như mong muốn, bạn nên báo sớm thì hơn. Điều sếp muốn biết không phải là một bản báo cáo hoàn hảo, mà là một lời nhắn trước khi vấn đề trở nên lớn hơn.","Ví dụ, bạn chỉ cần nói: 「この仕事は、今半分ぐらいできています。でも資料を待っているので、少し遅れそうです」là đủ. Khi cần thảo luận, bạn cũng có thể đi hỏi dù chưa có câu trả lời. Chỉ cần nói được mình đang gặp khó khăn ở đâu, thế là đã thành một buổi trao đổi. Nếu nghĩ rằng 報・連・相 là cách để cả nhóm tránh sai sót, tâm trạng bạn sẽ nhẹ nhõm hơn."],"vocab":["công ty","nhân viên","phân vân, lúng túng","câu trả lời, đáp án","truyền đạt, báo cho biết","cấp trên, sếp","vấn đề","tài liệu, dữ liệu","bị chậm, bị trễ","gặp khó khăn, bối rối"],"grammar":[{"t":"〜ても大丈夫です","note":"Diễn tả ý \"dù～cũng không sao\". Ví dụ: 「答えが出ていなくても大丈夫です」"},{"t":"〜たほうがいい","note":"Diễn tả ý \"nên～\", dùng để đưa ra lời khuyên. Ví dụ: 「早く伝えたほうがいいです」"},{"t":"〜そうだ(様態)","note":"Dựa vào tình hình hiện tại để phỏng đoán \"có vẻ sẽ～\". Ví dụ: 「少し遅れそうです」"},{"t":"〜と考えると","note":"Diễn tả ý \"nếu nghĩ rằng～\", phía sau nối với kết quả. Ví dụ: 「防ぐための方法だと考えると、気持ちが楽になります」"}]},"a-n2-2-n3":{"title":"Chuyện \"đọc bầu không khí\" (空気を読む)","topic":"Văn hóa","trans":["Tiếng Nhật có cách nói 「空気を読む」 (đọc bầu không khí) và nó được dùng rất thường xuyên. Đó là việc cân nhắc không khí lúc đó và cảm xúc của đối phương, rồi hành động vừa vặn dù không ai nói ra. Ví dụ, khi trong cuộc họp mọi người đều tán thành, việc chỉ một mình phản đối cần có dũng khí. Vì vậy, nhiều người sẽ đọc bầu không khí và cố ý chọn cách không nói gì cả.","Cách nghĩ này từ trước đến nay rất hữu ích trong việc tránh để mọi người va chạm nhau và giữ gìn sự hòa thuận chung. Tuy nhiên, mặt khác, cũng có lúc những ý kiến thật sự cần thiết lại không thể nói ra. Ngoài ra, còn có vấn đề là tiếng nói của thiểu số bị mất đi.","Khả năng đọc bầu không khí quả thật có thể nói là một trong những đặc trưng của xã hội Nhật Bản. Tuy nhiên, chẳng phải đôi khi dũng khí nói ra ý kiến của mình mà không đọc bầu không khí cũng nên được coi trọng hay sao?","Đọc bầu không khí đôi khi cũng là sự dịu dàng, biết quan tâm đến người khác. Nhưng nếu đi quá đà thì sẽ trở nên không thể nói ra ý kiến của mình. Điều quan trọng có lẽ là sự cân bằng giữa việc hòa theo xung quanh và việc truyền đạt suy nghĩ của bản thân."],"vocab":["bầu không khí","tán thành","phản đối","dũng khí","cố ý, dám làm","hòa hợp, hòa thuận","có ích, hữu dụng","thiểu số, số ít","đặc trưng","quan tâm, nghĩ cho người khác"],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc tự quyết định làm gì đó. Ví dụ trong bài: 「あえて何も言わないことにする」, nghĩa là cố ý chọn không nói gì."},{"t":"〜ないように","note":"Diễn tả mục đích để một việc nào đó không xảy ra. Ví dụ trong bài: 「人がぶつからないように」, nghĩa là để mọi người không va chạm, xung đột với nhau."},{"t":"〜ために","note":"Diễn tả mục đích, nghĩa là \"để~\". Ví dụ trong bài: 「みんなの調和を守るために役に立ってきた」."},{"t":"〜てしまう","note":"Diễn tả kết quả không mong muốn hoặc việc đã hoàn tất. Ví dụ trong bài: 「自分の意見が言えなくなってしまう」, mang sắc thái tiếc nuối."}]},"a-n2-2-n4":{"title":"「空気を読む」ってなに?","topic":"Văn hóa","trans":["Tiếng Nhật có cách nói 「空気を読む」 (đọc bầu không khí). Nghĩa là cân nhắc tình hình lúc đó và cảm xúc của đối phương rồi hành động. Dù không được nói rõ ràng, bạn vẫn biết mình nên làm gì.","Ví dụ, giả sử trong cuộc họp mọi người đều tán thành. Lúc đó, việc chỉ một mình nói là phản đối cần có dũng khí. Vì thế, nhiều người sẽ \"đọc bầu không khí\" và không nói gì. Cảm giác này từ trước đến nay rất hữu ích để tránh cãi vã với người khác.","Nhưng cũng có lúc những ý kiến thật sự cần thiết lại không nói ra được. Cũng có lúc tiếng nói của số ít người không được lắng nghe. Mình nghĩ đôi khi dũng khí nói ra mà không đọc bầu không khí cũng quan trọng. Điều quan trọng là sự cân bằng giữa việc hòa theo xung quanh và việc nói ra suy nghĩ của bản thân."],"vocab":["không khí; bầu không khí","tâm trạng, cảm xúc","cuộc họp","tán thành","phản đối","dũng khí","ý kiến","quan trọng, đáng quý","hòa theo, điều chỉnh cho phù hợp"],"grammar":[{"t":"〜なくても","note":"Nghĩa là \"dù không ~ cũng\". Ví dụ: 「はっきり言われなくても、何をしたらいいか分かる」 nghĩa là dù không được nói rõ ràng vẫn hiểu."},{"t":"〜たらいいか","note":"Dùng thể た của động từ + ら để hỏi \"nên làm thế nào thì tốt\". Ví dụ: 「何をしたらいいか分かる」."},{"t":"〜ために","note":"Diễn tả mục đích, \"để ...\". Ví dụ: 「人とけんかしないために役に立ってきました」."},{"t":"Thể khả năng (言えなくなる)","note":"Thể khả năng của động từ + なくなる, diễn tả việc trở nên không thể làm gì đó. Ví dụ: 「必要な意見が言えなくなる」."}]},"a-n2-3-n3":{"title":"Báo cáo・Liên lạc・Trao đổi","topic":"Công sở","trans":["Khi vào làm ở công ty Nhật, điều đầu tiên bạn thường được dạy là tầm quan trọng của 「報連相」. Đây là từ được ghép từ chữ cái đầu của ba từ 「報告」「連絡」「相談」 (báo cáo, liên lạc, trao đổi). Người ta nói đây là một quan niệm rất quan trọng để hiểu cách làm việc của người Nhật.","Trước hết, việc \"báo cáo\" với cấp trên về tiến độ công việc đến đâu là rất quan trọng. Với những người liên quan thì \"liên lạc\" thông tin cần thiết, còn khi phân vân không biết nên làm thế nào thì nên sớm \"trao đổi\". Làm được những điều này hay không sẽ khiến kết quả công việc khác nhau rất nhiều.","Nếu một mình ôm vấn đề rồi báo cáo chậm trễ, lỗi nhỏ cũng có thể biến thành rắc rối lớn. Ngược lại, nếu chịu khó chia sẻ thông tin thường xuyên, những người xung quanh có thể giúp đỡ sớm. Ở nơi làm việc mà 報連相 không suôn sẻ, lỗi nhỏ rất dễ trở thành vấn đề lớn.","報連相 không chỉ đơn thuần là một quy tắc. Khi làm việc nhóm, đó là cách giao tiếp cơ bản cần thiết để tin tưởng lẫn nhau. Việc chia sẻ thông tin thường xuyên hẳn sẽ giúp nâng cao sự tin tưởng và hiệu quả của cả nhóm."],"vocab":["cấp trên, sếp","báo cáo","liên lạc, thông báo","trao đổi, hỏi ý kiến","phân vân, do dự","ôm đồm, một mình gánh vác","chia sẻ","nơi làm việc","tin tưởng","hiệu suất, hiệu quả"],"grammar":[{"t":"〜によって","note":"Diễn tả \"tùy theo, phụ thuộc vào\". Ví dụ: 「これができるかどうかによって」, nghĩa là kết quả sẽ khác nhau tùy vào việc có làm được hay không."},{"t":"〜わけではない","note":"Diễn tả \"không có nghĩa là……\", dùng để phủ định một phần hoặc đính chính hiểu lầm. Ví dụ: 「ただのルールというわけではない」."},{"t":"〜ことがある/〜こともある","note":"Diễn tả \"đôi khi……, cũng có thể……\". Ví dụ: 「大きなトラブルになることもある」."},{"t":"〜てくれる","note":"Diễn tả hành động của đối phương mang lại lợi ích cho mình hoặc người liên quan. Ví dụ: 「信頼と効率を高めてくれるだろう」."}]},"a-n2-3-n4":{"title":"Báo cáo・Liên lạc・Trao đổi","topic":"Công sở","trans":["Khi vào làm ở công ty Nhật, trước tiên bạn sẽ được dạy về tầm quan trọng của 「報連相」. Đây là từ được ghép từ chữ cái đầu của ba từ 「報告」「連絡」「相談」 (báo cáo, liên lạc, trao đổi).","Nói với cấp trên về tình hình công việc là \"báo cáo\". Thông báo những việc cần thiết cho người có liên quan là \"liên lạc\". Khi không biết nên làm thế nào, hỏi sớm là \"trao đổi\". Làm được những điều này hay không sẽ khiến kết quả công việc khác nhau rất nhiều.","Nếu một mình phiền muộn rồi báo cáo chậm, lỗi nhỏ rất dễ trở thành vấn đề lớn. Ngược lại, nếu thường xuyên chia sẻ thông tin, những người xung quanh có thể giúp đỡ sớm. 報連相 không chỉ là quy tắc. Khi làm việc nhóm, đó là cách giao tiếp quan trọng để tin tưởng lẫn nhau."],"vocab":["quan trọng, đáng quý","báo cáo","liên lạc, thông báo","trao đổi, hỏi ý kiến","cấp trên","quan hệ, liên quan","muộn, chậm trễ","thông tin","chia sẻ","tin, tin tưởng"],"grammar":[{"t":"〜と(điều kiện)","note":"Diễn tả \"hễ……thì……\", nói về kết quả tự nhiên hoặc thói quen. Ví dụ: 「日本の会社に入ると、最初に「報連相」の大切さを教えてもらいます」、「報告が遅れると、小さなミスが大きな問題になりやすいです」."},{"t":"〜かどうか","note":"Diễn tả \"có……hay không\", đưa một câu hỏi vào bên trong câu. Ví dụ: 「これができるかどうかで、仕事の結果が大きく変わります」."},{"t":"〜やすい","note":"Gắn sau động từ dạng ます (bỏ ます), diễn tả \"dễ……\". Ví dụ: 「小さなミスが大きな問題になりやすいです」."},{"t":"〜ば(điều kiện)/〜ための","note":"「〜ば」diễn tả \"nếu……thì……\", 「〜ための」diễn tả \"để……, dành cho việc……\". Ví dụ: 「よく情報を共有すれば、まわりの人が早く助けられます」、「おたがいを信じるための大切なコミュニケーションです」."}]},"a-n2-4-n3":{"title":"Suy ngẫm về \"ô nhiễm du lịch\"","topic":"Du lịch","trans":["Những năm gần đây, các điểm du lịch nổi tiếng thu hút rất nhiều du khách, không chỉ trong nước mà cả từ nước ngoài. Du lịch mang lại lợi ích lớn cho địa phương, nhưng cũng làm nảy sinh vấn đề được gọi là 「観光公害」 (ô nhiễm du lịch).","Chẳng hạn, đường phố chật kín khách du lịch khiến người dân có lúc không thể đi lại. Ngoài ra, rác thải tăng lên, số người không tuân thủ phép lịch sự cũng nhiều hơn. Vì vậy, những người vốn sống yên tĩnh đã không còn có thể sinh hoạt thoải mái được nữa.","Trước những vấn đề này, một số địa phương đã bắt đầu quy định số người được vào tham quan hoặc áp dụng thuế du lịch. Tuy nhiên, nếu quy định quá nghiêm ngặt thì bản thân sức hấp dẫn của du lịch cũng có nguy cơ mất đi. Chúng ta phải cân nhắc cả hai việc: giải quyết vấn đề và giữ cho nơi đó tiếp tục là điểm đến mà mọi người có thể tận hưởng chuyến đi.","Điều quan trọng là người đến thăm đừng quên lòng tôn trọng đối với người dân địa phương, phải không nhỉ? Nếu biết trân trọng văn hóa và quy tắc của vùng đất ấy, du lịch hẳn sẽ trở nên phong phú hơn cho cả du khách lẫn người dân. Điều đang được cần đến hiện nay là xây dựng một cơ chế để cả người đến thăm lẫn người sinh sống đều cảm thấy dễ chịu."],"vocab":["ô nhiễm du lịch (du lịch quá tải)","lợi ích","khu vực, địa phương","cư dân, người dân","vào cửa, vào tham quan","sức hấp dẫn, sức cuốn hút","nghiêm ngặt, khắt khe","giải quyết","sự tôn trọng","đến thăm, ghé thăm"],"grammar":[{"t":"〜だけでなく〜も","note":"Nghĩa là \"không chỉ… mà còn…\". Ví dụ: 「国内だけでなく外国からも多くの旅行者が集まっている」."},{"t":"〜たり〜たりする","note":"Liệt kê vài hành động hoặc tình trạng để làm ví dụ. Ví dụ: 「ゴミが増えたり、マナーを守らない人が増えたりする」."},{"t":"〜おそれがある","note":"Diễn tả khả năng xảy ra kết quả xấu. Ví dụ: 「魅力がなくなってしまうおそれもある」."},{"t":"〜はずだ","note":"Diễn tả suy đoán của người nói dựa trên lẽ thường, nghĩa là \"hẳn là…, chắc chắn sẽ…\". Ví dụ: 「豊かなものになるはずだ」."}]},"a-n2-4-n4":{"title":"Suy ngẫm về \"ô nhiễm du lịch\"","topic":"Du lịch","trans":["Các điểm du lịch nổi tiếng có rất nhiều du khách từ trong và ngoài nước đến. Địa phương có thêm nguồn thu, nhưng cũng xuất hiện vấn đề gọi là 「観光公害」 (ô nhiễm du lịch).","Chẳng hạn, đường phố chật kín khách du lịch, người dân không thể đi lại được. Rác thải tăng lên, người không giữ phép lịch sự cũng nhiều hơn. Cuộc sống của những người vốn sống yên tĩnh vì thế trở nên tệ đi.","Vì vậy, có địa phương quy định số người được vào hoặc đặt ra thuế du lịch. Nhưng nếu quy định quá nghiêm ngặt thì sức hấp dẫn của du lịch có thể sẽ mất đi. Điều quan trọng là du khách đừng quên tấm lòng tôn trọng đối với người dân địa phương. Nếu biết trân trọng văn hóa và quy tắc của vùng đất ấy, mọi người đều có thể có khoảng thời gian thoải mái."],"vocab":["điểm du lịch","du khách","khu vực, địa phương","vấn đề","cư dân, người dân","tuân thủ, bảo vệ","cuộc sống, sinh hoạt","nghiêm ngặt, khắt khe","quan trọng, trân trọng","quên"],"grammar":[{"t":"〜たり〜たりする","note":"Liệt kê vài hành động hoặc tình trạng. Ví dụ: 「ゴミが増えたり、マナーを守らない人が増えたりします」"},{"t":"〜なくなる(thể khả năng+ない+なる)","note":"Thể khả năng phủ định + 「なる」 diễn tả việc trở nên không thể làm được điều gì. Ví dụ: 「住民が通れなくなります」"},{"t":"〜すぎる","note":"Động từ thể ます bỏ ます + すぎる, diễn tả làm quá mức. Ví dụ: 「ルールを厳しくしすぎると」"},{"t":"〜かもしれない","note":"Diễn tả khả năng có thể xảy ra nhưng chưa chắc chắn. Ví dụ: 「観光の魅力がなくなるかもしれません」"}]},"a-n2-6-n3":{"title":"Coi trọng giấc ngủ","topic":"Sức khỏe","trans":["Khi sống những ngày bận rộn, ta thường vô thức cắt giảm thời gian ngủ đầu tiên. Thế nhưng, giấc ngủ chất lượng là điều không thể thiếu để có một cuộc sống khỏe mạnh.","Nếu ngủ không đủ, khả năng tập trung có thể giảm sút và cơ thể cũng có thể trở nên khó chịu. Chắc hẳn cũng không ít người vì cơn buồn ngủ ban ngày mà công việc hay việc học không suôn sẻ.","Để ngủ thật sâu, trước hết điều quan trọng là điều chỉnh nhịp sinh hoạt. Hãy cố gắng đi ngủ và thức dậy vào cùng một giờ mỗi ngày. Ngoài ra, trước khi ngủ bạn nên hạn chế xem điện thoại thông minh hết mức có thể. Vì ánh sáng chói từ màn hình sẽ khiến não bộ tỉnh táo trở lại.","Dù chỉ chênh nhau vài tiếng, nếu duy trì mỗi ngày thì sẽ tạo nên khoảng cách lớn. Bạn thử bắt đầu bằng việc lên giường sớm hơn một chút nhé?"],"vocab":["giấc ngủ","cắt giảm (thời gian, v.v.)","chất lượng","khả năng tập trung","tình trạng (sức khỏe), trạng thái","cơn buồn ngủ","điều chỉnh cho ổn định, sắp xếp gọn gàng","lưu ý, cố gắng thực hiện","não","chăn đệm kiểu Nhật (futon)"],"grammar":[{"t":"〜がちだ","note":"Diễn tả xu hướng dễ xảy ra điều gì đó (thường là điều không tốt). Ví dụ: 「ついいちばん先に睡眠の時間を削ってしまいがちです」"},{"t":"〜のせいで","note":"Diễn tả vì một nguyên nhân nào đó mà dẫn đến kết quả xấu. Ví dụ: 「昼間の眠気のせいで、仕事や勉強がうまくいかない人も少なくないでしょう」"},{"t":"〜ように心がける","note":"Diễn tả việc cố gắng lưu ý, hết sức làm điều gì đó. Ví dụ: 「毎日同じ時間に寝て、同じ時間に起きるように心がけましょう」"},{"t":"〜によって","note":"Diễn tả nguyên nhân hoặc phương tiện, nói về ảnh hưởng do sự vật nào đó gây ra. Ví dụ: 「画面の明るい光によって、脳が目を覚ましてしまうからです」"}]},"a-n2-8-n3":{"title":"Lựa chọn chuyển về vùng quê sinh sống","topic":"Xã hội","trans":["Nghe nói gần đây ngày càng nhiều người rời thành phố để chuyển về vùng quê sống. Lý do lớn nhất là làm việc từ xa đã trở nên phổ biến. Giờ đây, nhiều người dù sống ở đâu cũng có thể làm việc được.","Tiền thuê nhà ở vùng quê chưa bằng một nửa ở thành phố, lại cũng không phải chịu cảnh giờ cao điểm đi làm. Cuộc sống được thiên nhiên bao quanh trông rất hấp dẫn. Vì vậy, dường như cũng có người bắt đầu nghiêm túc cân nhắc việc chuyển đi.","Tuy nhiên, chuyển về vùng quê tuyệt đối không phải chuyện đơn giản. Có nhiều vùng không có xe thì không sống nổi, và đôi khi bạn còn thấy bất tiện về y tế và giáo dục. Ngoài ra, việc có hòa nhập tốt với các mối quan hệ trong cộng đồng địa phương hay không cũng được cho là một thách thức lớn. Có thể có người sẽ bối rối trước những thói quen và cách giao tiếp khác với thành phố.","Điều quan trọng là đừng quyết định chỉ dựa vào lý tưởng. Tốt nhất bạn nên đến vùng đất đó vài lần, tận mắt xem cuộc sống ở đó ra sao. Làm như vậy, chẳng phải sẽ giảm được những thất bại sau khi chuyển đến sao?"],"vocab":["chuyển đến sống (ở nơi khác)","lan rộng, phổ biến","tiền thuê nhà","hấp dẫn, có sức cuốn hút","khu vực, vùng","bất tiện","hòa nhập","vấn đề cần giải quyết, thách thức","đích thân đến, tới tận nơi","xác nhận, kiểm tra cho chắc"],"grammar":[{"t":"〜ようになる","note":"Diễn tả sự thay đổi về khả năng hoặc trạng thái: trước đây không làm được, giờ trở nên làm được. Ví dụ: 「どこに住んでいても仕事ができるようになった人が多いのである」"},{"t":"〜かどうか","note":"Nghĩa là \"có ~ hay không\", lồng một câu hỏi có/không vào trong câu. Ví dụ: 「地域の人間関係にうまく溶け込めるかどうかも、大きな課題だと言われている」"},{"t":"〜と言われている","note":"Nghĩa là \"người ta nói rằng ~, thường được cho là ~\", dùng để thuật lại một quan điểm chung trong xã hội một cách khách quan. Ví dụ: 「大きな課題だと言われている」"},{"t":"〜のではないだろうか","note":"Cách nói nhẹ nhàng, tế nhị để nêu ý kiến của mình, nghĩa là \"chẳng phải là ~ sao\", \"có lẽ là ~\". Ví dụ: 「移住してからの失敗を減らせるのではないだろうか」"}]},"a-n2-8-n4":{"title":"Lựa chọn sống ở vùng quê","topic":"Xã hội","trans":["Nghe nói gần đây ngày càng nhiều người rời thành phố lớn để chuyển về vùng quê. Vì giờ có thể làm việc qua Internet nên sống ở đâu cũng làm việc được.","Ở vùng quê tiền thuê nhà rẻ, tàu điện buổi sáng cũng không đông. Gần núi và biển, có thể sống giữa thiên nhiên trong lành cũng là lý do khiến nơi đây được yêu thích.","Nhưng chuyển nhà không đơn giản. Có nhiều nơi không có xe thì không sống được, bệnh viện và trường học ở xa nên đôi khi cũng gặp khó khăn.","Ngoài ra, việc có thể thân thiết với hàng xóm hay không cũng nghe nói là một vấn đề quan trọng. Vì vậy, tốt nhất đừng quyết định chỉ dựa vào lý tưởng. Mình nghĩ bạn nên đến thị trấn đó vài lần, tận mắt xem mình có thể sống cuộc sống như thế nào."],"vocab":["chuyển nhà","tăng lên","làm việc","tiền thuê nhà","đông đúc","thiên nhiên","lý do","bệnh viện","hàng xóm, khu vực lân cận","lý tưởng"],"grammar":[{"t":"〜そうだ(truyền đạt)","note":"Diễn tả thông tin nghe được từ người khác. Ví dụ: 「いなかに引っ越す人が増えているそうだ」"},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do. Ví dụ: 「インターネットで仕事ができるようになったので、どこに住んでも働ける」"},{"t":"Thể khả năng","note":"Diễn tả có thể làm được việc gì đó. Ví dụ: 「きれいな自然の中で暮らせる」"},{"t":"〜ないと〜ない/〜ほうがいい","note":"「車がないと生活できない」nghĩa là nếu không có thì không được; 「決めないほうがいい」nghĩa là khuyên nên không làm việc gì đó"}]},"a-n2-9-n3":{"title":"Cửa ải gia hạn tư cách lưu trú","topic":"Xã hội","trans":["Với người nước ngoài sống ở Nhật, gia hạn tư cách lưu trú là một cửa ải quan trọng nhất định phải vượt qua. Bạn có thể nộp đơn gia hạn từ ba tháng trước ngày hết hạn lưu trú. Tuy nhiên, vì việc chuẩn bị hồ sơ khá tốn thời gian nên tốt nhất bạn nên bắt tay vào sớm nhất có thể.","Ngoài đơn xin, các giấy tờ cần thiết còn có giấy chứng nhận thuế cư trú, giấy chứng nhận đã nộp thuế, giấy xác nhận đang làm việc, v.v. Những người mới chuyển việc đôi khi còn bị yêu cầu nộp hợp đồng lao động. Khi xét duyệt, cơ quan sẽ xem thu nhập có ổn định không, và bạn có đóng thuế cũng như tiền lương hưu đầy đủ không.","Nói cách khác, với những người thường xuyên trì hoãn các thủ tục hằng ngày, các vấn đề đó sẽ đồng loạt lộ ra vào thời điểm này. Quầy tiếp nhận của Cục Quản lý xuất nhập cảnh rất đông, vì vậy số người nộp đơn trực tuyến cũng đang tăng lên. Cùng với đó, quy trình thủ tục cũng đang dần thay đổi.","Vài tuần chờ kết quả có thể khiến bạn thấy bồn chồn. Tuy nhiên, chỉ cần chuẩn bị đủ giấy tờ cần thiết và khai báo trung thực thì bạn không cần lo lắng quá."],"vocab":["在留資格 (tư cách lưu trú ở Nhật)","gia hạn","cửa ải","nộp đơn, đăng ký","hồ sơ, giấy tờ","xét duyệt","thu nhập","trì hoãn, để sau","quầy tiếp nhận","khai báo"],"grammar":[{"t":"〜ため (nguyên nhân, lý do)","note":"Diễn tả nguyên nhân, lý do, mang sắc thái trang trọng, văn viết hơn「から」. Ví dụ: 「書類の準備には時間がかかるため、できるだけ早く動いたほうがいいです」"},{"t":"〜たばかり","note":"Diễn tả vừa mới làm xong việc gì đó cách đây không lâu. Ví dụ: 「転職したばかりの人は、雇用契約書を出すように言われることもあります」"},{"t":"〜ように言われる","note":"Diễn tả việc bị yêu cầu hoặc được dặn phải làm gì đó. Ví dụ: 「雇用契約書を出すように言われることもあります」"},{"t":"〜わけだ","note":"Diễn tả một kết luận hiển nhiên, tất yếu, nghĩa là \"nói cách khác thì…\". Ví dụ: 「その問題がこの時期に一度に出てくるわけです」"}]},"a-n2-9-n4":{"title":"Gia hạn tư cách lưu trú","topic":"Xã hội","trans":["Người nước ngoài sống ở Nhật phải gia hạn tư cách lưu trú. Bạn có thể nộp đơn từ ba tháng trước ngày hết hạn. Vì chuẩn bị giấy tờ mất thời gian nên bạn nên bắt đầu sớm.","Các giấy tờ cần thiết gồm đơn xin, giấy chứng nhận thuế cư trú, giấy chứng nhận đã nộp thuế, giấy xác nhận do công ty cấp, v.v. Người mới đổi việc có thể cũng cần giấy tờ hợp đồng lao động.","Khi xét duyệt, cơ quan sẽ xem thu nhập có ổn định hay không. Họ cũng xem bạn có đóng thuế và tiền lương hưu đầy đủ hay không. Nếu lúc nào cũng không làm thủ tục, đến khi gia hạn có vẻ bạn sẽ gặp rắc rối. Quầy tiếp nhận của Cục Quản lý xuất nhập cảnh rất đông người nên số người nộp đơn qua mạng cũng đang tăng lên. Trong lúc chờ kết quả thì cũng hơi lo, nhưng nếu chuẩn bị đủ giấy tờ và viết đúng sự thật thì bạn không cần lo lắng quá."],"vocab":["在留資格 (tư cách lưu trú)","gia hạn","thời hạn","nộp đơn, đăng ký","giấy tờ, hồ sơ","giấy chứng nhận","thu nhập","ổn định","quầy tiếp nhận","chuẩn bị đủ, gom đủ"],"grammar":[{"t":"〜なければなりません","note":"Diễn tả ý \"phải làm gì đó\". Ví dụ: 「在留資格を更新しなければなりません」"},{"t":"〜たほうがいい","note":"Diễn tả ý \"nên làm ~\", dùng để đưa ra lời khuyên. Ví dụ: 「早めに始めたほうがいいです」"},{"t":"〜そうだ","note":"Diễn tả sự phán đoán dựa trên tình hình, nghĩa là \"có vẻ sẽ ~\". Ví dụ: 「更新のときに困りそうです」"},{"t":"〜ば (thể điều kiện)","note":"Diễn tả ý \"nếu ~ thì\". Ví dụ: 「書類をそろえて本当のことを書けば、あまり心配しなくてもいいです」"}]},"a-n3-10-n2":{"title":"Quy tắc đổ rác dạy cho tôi điều gì","topic":"Đời sống","trans":["Điều khiến tôi bối rối đầu tiên khi bắt đầu sống ở Nhật là cách phân loại rác được quy định chi tiết hơn tôi tưởng rất nhiều. Các nhóm như rác cháy được, rác không cháy được, rác tái chế có tiêu chuẩn và ngày thu gom khác nhau tùy từng quận, đó là thực tế. Vì vậy, sau khi chuyển nhà, tốt nhất bạn nên xem qua bảng phân loại phát ở tòa thị chính (市役所) trước.","Khi đổ chai nhựa, nguyên tắc cơ bản là tháo nhãn và nắp, tráng sơ bên trong rồi mới đem đổ. Thật lòng thì đây là việc khá phiền, nhưng nghe nói chính công đoạn nhỏ ấy quyết định chai có tái sử dụng được hay không. Giờ đổ rác cũng có quy định, ở nhiều khu vực là trước tám giờ sáng của ngày thu gom. Nếu đem ra từ tối hôm trước thì có thể bị quạ bới tung, nên đem ra sớm chưa chắc đã là yên tâm.","Với rác cồng kềnh, bạn cần làm nhiều thủ tục hơn rác thông thường, buộc phải đăng ký trước qua điện thoại hoặc mạng. Sau khi đăng ký, quy trình là mua tem ở cửa hàng tiện lợi rồi dán lên. Nghe nói không ít người không biết quy định này, cứ để nguyên ra ngoài rồi bị nhắc nhở. Với người từ nước ngoài đến, ngoài rào cản ngôn ngữ, những quy ước ngầm kiểu này đôi khi cũng trở thành gánh nặng.","Lúc đầu tôi thấy quá tỉ mỉ, nhưng sống một thời gian thì dần thành thói quen. Việc đổ rác hằng ngày không chỉ là một công việc đơn thuần, mà còn là hành động thể hiện sự quan tâm đến những người xung quanh. Cách đổ rác có lẽ chính là \"quy tắc chung\" đầu tiên để sống trong khu vực đó."],"vocab":["bối rối, lúng túng","tiêu chuẩn","tình hình thực tế","xem qua, liếc qua","tráng, súc","tái sử dụng","bới tung, phá phách","rác cồng kềnh","quy ước ngầm, sự ngầm hiểu","sự quan tâm, chu đáo"],"grammar":[{"t":"〜に越したことはない","note":"Diễn tả \"làm việc gì đó là tốt nhất\", mang sắc thái khuyên nhủ. Ví dụ: 「市役所でもらえる一覧表に目を通しておくに越したことはない」"},{"t":"〜ざるを得ない","note":"Diễn tả \"buộc phải ~\", không còn lựa chọn nào khác. Ví dụ: 「事前に電話やネットで申し込まざるを得ない」"},{"t":"〜とは限らない","note":"Diễn tả \"không hẳn là ~\", phủ định cách nói tuyệt đối. Ví dụ: 「早めに出せば安心とは限らない」"},{"t":"〜にとどまらず","note":"Diễn tả \"không chỉ dừng ở ~, mà còn hơn thế\". Ví dụ: 「単なる作業にとどまらず、地域の人々への配慮を示す行為でもある」"}]},"a-n3-10-n4":{"title":"Quy tắc đổ rác","topic":"Đời sống","trans":["Khi bắt đầu sống ở Nhật, điều làm tôi khó khăn đầu tiên là cách phân loại rác.","Có rác cháy được, rác không cháy được và rác tái chế. Cách phân loại và ngày thu gom khác nhau tùy theo quận bạn sống. Sau khi chuyển nhà, bạn nên xem bảng phân loại phát ở tòa thị chính (市役所).","Chai nhựa thì tháo nhãn và nắp, tráng sơ bên trong rồi mới đem đổ. Nghe có vẻ phiền, nhưng nghe nói chính công đoạn nhỏ này quyết định chai có thể được dùng lại hay không.","Giờ đổ rác cũng có quy định, ở nhiều khu vực là trước tám giờ sáng của ngày đó. Vì nếu đem ra từ tối hôm trước, quạ có thể làm rác vương vãi khắp nơi.","Rác cỡ lớn thì phải đăng ký trước bằng điện thoại hoặc internet. Sau đó mua tem ở cửa hàng tiện lợi rồi dán lên rác.","Không ít người không biết quy định này, cứ đem rác ra rồi bị nhắc nhở.","Lúc đầu tôi nghĩ quá tỉ mỉ, nhưng dần dần cũng quen.","Cách đổ rác có lẽ chính là quy tắc chung đầu tiên để sống ở thành phố đó."],"vocab":["gặp khó khăn, bối rối","cách phân loại","thu gom","chuyển nhà","rửa","phiền phức","được quyết định","đăng ký","nhắc nhở, cảnh báo","quen, thích nghi"],"grammar":[{"t":"〜たら","note":"Diễn tả \"nếu/sau khi làm ...\". Ví dụ: 「引っ越したら、市役所でもらえる表を見たほうがいいです」"},{"t":"〜たほうがいい","note":"Diễn tả \"nên ...\", dùng để đưa ra lời khuyên. Ví dụ: 「市役所でもらえる表を見たほうがいいです」"},{"t":"〜そうだ(樣態/傳聞)","note":"「面倒そうです」là vẻ bề ngoài (trông có vẻ); 「決まるそうです」là truyền đạt (nghe nói). Ví dụ: 「このひと手間で、もう一度使えるかどうかが決まるそうです」"},{"t":"〜ので/〜からです(理由)","note":"Dùng để giải thích lý do. Ví dụ: 「前の晩に出すと、カラスがゴミを散らかすことがあるからです」"}]},"a-n3-11-n2":{"title":"Tầm quan trọng của 報連相","topic":"Công sở","trans":["Khi làm việc tại công ty Nhật, quan niệm 「報連相」 được nhiều người cho là cực kỳ quan trọng. Đây là từ viết tắt, ghép từ chữ đầu của ba từ 「報告」「連絡」「相談」 (báo cáo, liên lạc, trao đổi). Thoạt nhìn chỉ là một thói quen đơn giản, nhưng điểm đặc trưng là nó được xem như nền tảng để công việc diễn ra suôn sẻ.","Trước hết, 報告 (báo cáo) là việc cho cấp trên biết tiến độ công việc. Đặc biệt khi có vấn đề phát sinh, bạn được yêu cầu báo cáo ngay lập tức, không để lại sau. Tiếp theo, 連絡 (liên lạc) là việc truyền đạt thông tin cần thiết cho công việc đến những người liên quan. Chẳng hạn khi lịch trình thay đổi, người ta coi trọng việc liên lạc càng sớm càng tốt. Cuối cùng, 相談 (trao đổi) là việc hỏi ý kiến cấp trên hoặc đồng nghiệp về những điều mình không thể tự quyết định. Dù là chuyện nhỏ nhặt, nếu trao đổi sớm thì có thể ngăn chặn thất bại lớn từ trước khi nó xảy ra.","Với nhân viên nước ngoài, thói quen 報連相 này lúc đầu có thể khiến bạn cảm thấy là một gánh nặng. Ở đất nước của mình, đôi khi thái độ tự phán đoán và tự tiến hành công việc lại được đánh giá cao, nên việc có người bối rối cũng không có gì lạ. Việc tự làm mà không trao đổi với những người xung quanh chưa chắc đã dẫn đến kết quả tốt ở Nhật.","Tuy nhiên, nếu thực hiện 報連相 đúng cách thì có lợi thế là dễ nhận được sự tin tưởng trong nhóm. Nếu làm việc tại công ty Nhật, hiểu được cách nghĩ này sẽ giúp ích rất nhiều. Dù bối rối trước sự khác biệt về thói quen, chắc hẳn cũng sẽ có những lúc bạn buộc phải làm quen dần từng chút một."],"vocab":["suôn sẻ, trôi chảy","nền tảng, gốc rễ","ngay lập tức","coi trọng, xem trọng","nhỏ nhặt, vụn vặt","từ trước khi xảy ra, phòng ngừa từ sớm","bối rối, lúng túng","đánh giá, ghi nhận","tin tưởng"],"grammar":[{"t":"〜うえで","note":"Diễn tả \"trong quá trình / ở phương diện làm việc gì đó\". Ví dụ: 「日本の会社で働くうえで、「報連相」という考え方は非常に重要だと広く言われています」"},{"t":"〜にとって","note":"Diễn tả \"đứng ở lập trường của ai đó mà xét\", nghĩa là \"đối với…\". Ví dụ: 「外国人の社員にとっては、この報連相の習慣は、最初のうちは負担に感じられるかもしれません」"},{"t":"〜とは限らない","note":"Diễn tả \"chưa chắc là…\", phủ định cách nói tuyệt đối. Ví dụ: 「周囲に相談せず進めることが、日本では必ずしも良い結果につながるとは限らないのです」"},{"t":"〜ざるを得ない","note":"Diễn tả \"buộc phải…\", mang sắc thái bất đắc dĩ. Ví dụ: 「習慣の違いに戸惑いながらも、少しずつ慣れていかざるを得ない場面もあるはずです」"}]},"a-n3-11-n4":{"title":"報連相って大切です","topic":"Công sở","trans":["Ở các công ty Nhật, người ta nói 「報連相」 rất quan trọng. Đây là từ ghép của ba từ 「報告」「連絡」「相談」 (báo cáo, liên lạc, trao đổi).","Việc nói cho cấp trên biết công việc đã tiến hành đến đâu gọi là 報告 (báo cáo). Khi có vấn đề xảy ra, bạn phải báo cáo ngay. 連絡 (liên lạc) là việc truyền đạt những điều cần thiết cho người có liên quan. Khi lịch trình thay đổi, liên lạc sớm là điều quan trọng.","相談 (trao đổi) là việc hỏi cấp trên hoặc người cùng công ty về những điều mình không thể tự quyết định. Dù là chuyện nhỏ, nếu trao đổi thì bạn có thể tránh được thất bại lớn. Với người nước ngoài, lúc đầu có thể bạn sẽ thấy khó. Vì ở đất nước của mình, đôi khi việc tự suy nghĩ và tự làm lại được đánh giá tốt. Nhưng nếu thực hiện 報連相 đúng cách, bạn sẽ dễ được mọi người trong nhóm tin tưởng hơn. Nếu làm việc tại công ty Nhật, biết trước cách nghĩ này sẽ có ích."],"vocab":["báo cáo","liên lạc","trao đổi, bàn bạc","vấn đề","dự định, lịch trình","quan trọng, quý giá","thất bại","người nước ngoài","tin, tin tưởng","có ích, hữu dụng"],"grammar":[{"t":"〜たら","note":"Diễn tả \"nếu… thì / hễ… thì / một khi…\". Ví dụ: 「問題が起きたら、すぐに報告しなければなりません」"},{"t":"〜なければなりません","note":"Diễn tả \"phải…\", \"bắt buộc phải…\". Ví dụ: 「すぐに報告しなければなりません」"},{"t":"〜ば","note":"Diễn tả điều kiện \"chỉ cần… thì…\". Ví dụ: 「小さなことでも相談すれば、大きな失敗をしないで済みます」"},{"t":"〜かもしれません","note":"Diễn tả \"có lẽ…\", nói về khả năng có thể xảy ra. Ví dụ: 「最初は難しいと思うかもしれません」"}]},"a-n3-2-n2":{"title":"Những điều cuộc sống tự lập dạy cho tôi","topic":"Cuộc sống","trans":["Nhờ cơ hội lên đại học, lần đầu tiên trong đời tôi bắt đầu sống một mình. Ban đầu, việc không cần bận tâm đến ánh mắt của bố mẹ mà vẫn có thể tự do quyết định mọi thứ khiến tôi vui không tả nổi. Giờ nghĩ lại, tôi cho rằng khi ấy mình vẫn chưa hiểu rằng sự tự do đó đương nhiên đi kèm với trách nhiệm.","Thế nhưng, khi thực sự bắt đầu cuộc sống ấy, nào là nấu ăn, giặt giũ, dọn dẹp, tôi đều buộc phải tự làm hết. Trong lúc bị công việc nhà cuốn đi, tôi mới nhận ra bấy lâu nay bố mẹ đã làm cho mình biết bao nhiêu việc như thể đó là chuyện đương nhiên. Cùng với sự thay đổi trong cuộc sống, tôi cũng bắt đầu nghiêm túc suy nghĩ về cách tiêu tiền. Khi liên tục xoay xở với số sinh hoạt phí có hạn, dần dần tôi tự nhiên phân biệt được đâu mới là thứ thực sự cần thiết.","Sống một mình có nhiều điều vất vả, nhưng cũng có cái lợi là rèn được khả năng tự lo cho bản thân. Ngoài ra, ở một mình đôi lúc cảm thấy cô đơn, nhưng đổi lại, việc được tự do sử dụng thời gian của mình cũng là sự thật. Khoảng thời gian có thể tập trung vào điều mình thích là thứ khó mà có được khi còn sống cùng gia đình. Có lẽ chính nhờ đặt mình vào môi trường không thể dựa dẫm vào ai, con người mới lần đầu suy nghĩ về ý nghĩa của sự tự lập.","Và hơn hết, tôi hiểu rõ giá trị của gia đình hơn trước rất nhiều. Nhìn lại, tôi nhận ra sự đáng quý ấy là từ sau khi bắt đầu sống xa gia đình. Sống một mình không chỉ dừng lại ở sự thay đổi trong cuộc sống, mà có thể nói là một trải nghiệm quý giá giúp thay đổi cách nhìn nhận mọi việc."],"vocab":["học lên (cấp cao hơn)","đi kèm, kéo theo","đương nhiên, lẽ tất nhiên","bị làm cho nhận ra, bất giác nhận ra","bị giới hạn, có hạn","nhìn rõ, phân biệt","học được, rèn được","tự lập","quý giá"],"grammar":[{"t":"〜に伴って","note":"Diễn tả \"cùng với sự thay đổi của …, một việc khác cũng thay đổi theo\". Ví dụ: 「生活の変化に伴って、お金の使い方についても真剣に考えるようになった」."},{"t":"〜ざるを得ない","note":"Diễn tả \"buộc phải …\", mang sắc thái bất đắc dĩ (thể ない bỏ ない + ざるを得ない). Ví dụ: 「すべて自分でやらざるを得なかった」."},{"t":"〜てこそ","note":"Nhấn mạnh \"chính nhờ … mới có thể …\", vế sau thường là kết quả hoặc đánh giá tích cực. Ví dụ: 「誰にも頼れない環境に身を置いてこそ、人は初めて自立の意味を考えるのかもしれない」."},{"t":"〜にとどまらず","note":"Diễn tả \"không chỉ giới hạn ở …, mà còn …\", dùng để mở rộng phạm vi. Ví dụ: 「単なる生活の変化にとどまらず、物の見方を変えてくれる貴重な経験だ」."}]},"a-n3-2-n4":{"title":"Những điều học được từ cuộc sống một mình","topic":"Cuộc sống","trans":["Vào đại học, lần đầu tiên tôi sống một mình. Lúc đầu, được sống tự do khiến tôi rất vui. Nhưng nấu ăn, giặt giũ, dọn dẹp đều phải tự làm. Khi ấy tôi mới hiểu bố mẹ đã làm cho mình rất nhiều việc.","Tôi cũng bắt đầu suy nghĩ về cách tiêu tiền. Vì số tiền có thể dùng không nhiều nên tôi suy nghĩ kỹ rồi mới mua những thứ thực sự cần. Sống một mình tuy vất vả, nhưng sẽ trở nên có thể tự lo cho bản thân.","Ở một mình đôi lúc cũng buồn, nhưng có thể tự do sử dụng thời gian của mình. Và tôi hiểu gia đình quan trọng đến mức nào rõ hơn trước. Tôi nhận ra sự đáng quý của gia đình là sau khi sống xa nhà."],"vocab":["lần đầu tiên","sống, ở","tự do","nấu ăn, món ăn","giặt giũ","cần thiết","vất vả, khó khăn","quan trọng, quý giá","nhận ra, phát hiện","xa, rời xa"],"grammar":[{"t":"〜なければならない","note":"Diễn tả \"phải làm 〜\". Trong bài: 「自分でしなければならない」, nghĩa là nấu ăn, giặt giũ, dọn dẹp đều phải tự làm."},{"t":"〜ようになる","note":"Diễn tả sự thay đổi, từ không làm được thành làm được, hoặc thói quen thay đổi. Trong bài: 「考えるようになった」「分かるようになった」."},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do, giọng điệu nhẹ nhàng. Trong bài: 「使えるお金が少ないので」, vế sau là kết quả."},{"t":"〜てから","note":"Diễn tả \"sau khi làm xong 〜 thì mới\". Trong bài: 「離れて住んでからだった」, cho biết mình chỉ nhận ra sau khi sống xa nhà."}]},"a-n3-3-n2":{"title":"Văn hóa nhà tắm công cộng sentō","topic":"Văn hóa","trans":["Sentō là nhà tắm công cộng, nơi nhiều người cùng ngâm mình, và trước đây từng là một phần không thể thiếu trong cuộc sống hằng ngày. Ngày xưa nhiều gia đình không có phòng tắm riêng nên người ta buộc phải dùng sentō. Sentō không chỉ là nơi để tắm rửa mà còn đóng vai trò là nơi gặp gỡ, giao lưu của người dân trong khu vực.","Tuy nhiên, khi phòng tắm trong mỗi gia đình dần phổ biến, số người dùng sentō giảm dần. Kết quả là số lượng sentō cũng giảm nhanh, và chúng bị xem là thứ lỗi thời. Nhưng gần đây, những nét hay riêng có của sentō lại được đánh giá lại.","Thong thả ngâm mình trong bồn tắm rộng, không chỉ cơ thể hết mệt mà cả sự căng thẳng trong lòng cũng được thả lỏng. Cảm giác thoải mái, thông thoáng này, thứ khó có được ở bồn tắm nhỏ trong nhà, có lẽ chính là sức hấp dẫn của sentō. Ngoài ra, việc trò chuyện tự nhiên với một người lạ ngồi bên cạnh mà chẳng cần lý do gì cũng không hiếm. Những tiếp xúc với người khác mà ngày thường ta hay vô thức né tránh lại diễn ra một cách nhẹ nhàng, không gượng ép ở đây.","Có lẽ vì quá mải mê theo đuổi sự tiện lợi mà chúng ta đang dần đánh mất sự kết nối với mọi người. Chính vì đang sống trong thời đại cái gì cũng có thể tự mình giải quyết, nên giá trị của khoảng thời gian ở chung một không gian với người khác càng trở nên nổi bật. Trong thời hiện đại này, sentō là nơi quý giá giúp ta nhớ lại khoảng cách giữa người với người."],"vocab":["nhà tắm công cộng (sentō)","không thể thiếu","sự tồn tại, thứ tồn tại","giao lưu, qua lại","phổ biến, lan rộng","đánh giá lại, nhìn nhận lại","cảm giác thoải mái, thông thoáng","không quen biết, xa lạ","đánh mất","nổi bật"],"grammar":[{"t":"〜ざるを得ない","note":"Diễn tả \"buộc phải…\", không có lựa chọn nào khác. Ví dụ: 「人々は銭湯を利用せざるを得なかったのである」. Bỏ ない ở thể ない của động từ rồi thêm ざるを得ない; する chuyển thành せざるを得ない."},{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「各家庭におふろが広まるに伴って、銭湯を利用する人は次第に減っていった」."},{"t":"〜にとどまらず","note":"Diễn tả \"không chỉ giới hạn ở…, mà còn…\". Ví dụ: 「銭湯は単に体を洗う場所にとどまらず、地域の人々が顔を合わせる交流の場としての役割も果たしていた」."},{"t":"〜あまり","note":"Diễn tả vì quá mức… nên dẫn đến kết quả (thường là không tốt). Ví dụ: 「便利さを追い求めるあまり、私たちは人とのつながりを失いつつあるのかもしれない」."}]},"a-n3-3-n4":{"title":"Văn hóa nhà tắm công cộng sentō","topic":"Văn hóa","trans":["Sentō là nhà tắm lớn nơi mọi người cùng vào tắm. Ngày xưa nhiều người không có phòng tắm ở nhà nên sentō là nơi rất quan trọng. Đó cũng là nơi người dân trong khu vực gặp gỡ nhau.","Khi nhà nào cũng có phòng tắm, số lượng sentō giảm dần. Nhưng gần đây, ngày càng nhiều người nhìn lại những điểm hay của sentō. Thong thả ngâm mình trong bồn tắm rộng, cả cơ thể lẫn tâm hồn đều thấy thoải mái.","Đôi khi bạn còn có thể trò chuyện tự nhiên với một người lạ ngồi bên cạnh. Trong cuộc sống tiện lợi, mối liên kết giữa người với người có lẽ đang yếu đi. Sentō là nơi giúp ta nhớ lại sự gần gũi giữa người với người."],"vocab":["nhà tắm công cộng (sentō)","ngày xưa, trước đây","quan trọng, quý giá","khu vực, cộng đồng","giảm","gần đây","tăng","tự nhiên, một cách tự nhiên","tiện lợi","nhớ lại, nhớ ra"],"grammar":[{"t":"〜と(điều kiện)","note":"Diễn tả \"hễ làm A thì tự nhiên sẽ có B\". Ví dụ: 「家におふろができると、銭湯の数はだんだん減っていった」."},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do, giọng điệu nhẹ nhàng hơn「から」. Ví dụ: 「昔は家におふろがない人が多かったので、銭湯は大切な場所だった」."},{"t":"〜ことがある(thể khả năng+こともある)","note":"Diễn tả \"có lúc…\". Ở đây đi với thể khả năng「話せる」. Ví dụ: 「知らない人と、自然に話せることもある」."},{"t":"〜かもしれない","note":"Diễn tả \"có lẽ…\", người nói không chắc chắn lắm. Ví dụ: 「人とのつながりは弱くなっているかもしれない」."}]},"a-n3-4-n2":{"title":"Tình trạng thiếu trẻ em ngày càng nghiêm trọng","topic":"Tin tức","trans":["Cùng với tình trạng tỷ lệ sinh giảm, số trẻ em ở Nhật Bản cứ giảm dần theo từng năm, và bản thân diện mạo của xã hội cũng sắp thay đổi lớn. Thiếu trẻ em (少子化) là hiện tượng số trẻ được sinh ra giảm đi, khiến tỷ lệ trẻ em trong toàn xã hội ngày càng nhỏ lại. Thoạt nhìn thì đây có vẻ là một thay đổi diễn ra chậm rãi, nhưng người ta cho rằng ảnh hưởng của nó lan đến nhiều mặt trong cuộc sống của chúng ta.","Nguyên nhân của tình trạng này không thể quy về một yếu tố duy nhất, có thể nói là nhiều yếu tố đan xen phức tạp với nhau. Trước hết, có ý kiến chỉ ra rằng số người không kết hôn tăng lên, khiến cơ hội có con vốn đã ít đi. Ngoài ra, gánh nặng chi phí nuôi dạy con rất lớn, không ít gia đình dù muốn có con cũng đành phải từ bỏ. Hơn nữa, việc khó cân bằng giữa công việc và chăm con cũng là một lý do lớn khiến người ta do dự chuyện sinh con.","Khi trẻ em giảm đi thì kéo theo đó, số người đi làm trong xã hội tương lai chắc chắn cũng sẽ giảm. Người đi làm giảm thì sức mạnh kinh tế có nguy cơ suy yếu, và cũng không thể loại trừ khả năng sức sống của doanh nghiệp và địa phương bị mất đi. Thêm vào đó, nỗi lo rằng hệ thống hỗ trợ người cao tuổi sẽ không thể duy trì được cũng đang dần lan rộng. Thiếu trẻ em không chỉ là vấn đề của thế hệ đang nuôi con, mà nên được xem là vấn đề liên quan đến tương lai của toàn xã hội.","Chính phủ cũng đang triển khai nhiều biện pháp, nhưng có thể nói hiệu quả vẫn chưa thể hiện đầy đủ. Bởi vì dù đã hoàn thiện chế độ hỗ trợ, cũng chưa chắc việc sinh và nuôi con sẽ lập tức trở nên dễ dàng hơn. Làm thế nào để toàn xã hội xây dựng một môi trường dễ nuôi dạy trẻ là câu hỏi đang được đặt ra một lần nữa vào lúc này."],"vocab":["Thiếu trẻ em (tỷ lệ sinh giảm, trẻ em ít đi)","Nguyên nhân chính, yếu tố","Đan xen, vướng víu vào nhau","Gánh nặng","Cân bằng cả hai, vẹn cả đôi đường","Phủ định, phủ nhận","Khó duy trì, không thể tiếp tục","Biện pháp đối phó","Sức sống","Bị đặt câu hỏi, bị thử thách"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「少子化に伴って、子どもの数が年々減り続けており」。"},{"t":"〜ざるを得ない","note":"Diễn tả việc đành phải làm như vậy, không có lựa chọn nào khác. Ví dụ: 「子どもを持ちたくても諦めざるを得ない家庭も少なくない」。"},{"t":"〜とは限らない","note":"Diễn tả điều gì đó không phải lúc nào cũng vậy, chưa chắc là vậy. Ví dụ: 「すぐに子どもを産み育てやすくなるとは限らない」。"},{"t":"〜つつある","note":"Diễn tả một sự thay đổi đang tiếp diễn. Ví dụ: 「不安も、広がりつつある」。"}]},"a-n3-4-n4":{"title":"Số trẻ em đang giảm","topic":"Tin tức","trans":["Hiện nay ở Nhật Bản, số trẻ em cứ giảm mãi. Điều này được gọi là 「少子化」. Nguyên nhân không chỉ có một. Số người không kết hôn tăng lên. Nuôi con tốn nhiều tiền. Vừa đi làm vừa chăm con cũng rất vất vả.","Khi trẻ em giảm đi thì sau này người đi làm cũng sẽ ít đi. Như vậy, sức mạnh kinh tế của đất nước có thể sẽ yếu đi. Hệ thống giúp đỡ người cao tuổi cũng có vẻ sẽ khó duy trì hơn.","Nhà nước đang làm nhiều việc nhưng vẫn chưa đủ. Điều quan trọng là mọi người cùng suy nghĩ về một xã hội dễ nuôi dạy trẻ. Người ta nói rằng nếu cứ tiếp tục thế này thì việc chống đỡ xã hội sẽ trở nên khó khăn."],"vocab":["Giảm","Nguyên nhân","Kết hôn","Tăng lên","Nuôi dạy, nuôi dưỡng","Tương lai","Người cao tuổi","Hệ thống, cơ chế","Đủ, đầy đủ","Chống đỡ, hỗ trợ"],"grammar":[{"t":"〜と、…(điều kiện)","note":"Diễn tả kết quả tất yếu kiểu 「hễ… thì sẽ…」. Ví dụ: 「子どもが減ると、将来働く人も少なくなります」"},{"t":"〜かもしれません","note":"Diễn tả phỏng đoán kiểu 「có lẽ…」. Ví dụ: 「国のお金の力が弱くなるかもしれません」"},{"t":"〜にくい","note":"Gắn sau thể ます của động từ, nghĩa là 「khó…」. Ví dụ: 「続けにくくなりそうです」"},{"t":"〜そうだ(dạng vẻ ngoài)","note":"Diễn tả điều dựa vào tình hình thì 「có vẻ sẽ…」. Ví dụ: 「続けにくくなりそうです」"}]},"a-n3-5-n2":{"title":"Nomikai giao tiếp: văn hóa nhậu ở công sở","topic":"Công sở","trans":["Ở các công ty Nhật Bản, thói quen sau giờ làm rủ đồng nghiệp hoặc sếp đi uống rượu cùng nhau đến nay vẫn rất phổ biến. Kiểu giao lưu trên bàn tiệc này kết hợp giữa \"rượu\" và \"giao tiếp\", nên được gọi là 「飲みニケーション」. Vì từ lâu nó được xem như phần nối dài của công việc và diễn ra gần như là điều hiển nhiên, nên chuyện nhân viên mới được đàn anh đàn chị rủ đi cùng cũng không hiếm.","Trên bàn nhậu, có cái lợi là bạn có thể nói ra những lời thật lòng mà ở chỗ làm khó mở miệng. Với sếp, bạn cũng dễ bắt chuyện thoải mái hơn so với lúc ở phòng họp. Vì vậy, không ít người đánh giá 飲みニケーション là cơ hội quý giá để gắn kết các mối quan hệ. Bởi men rượu có thể kéo mọi người lại gần nhau hơn, và đôi khi giúp công việc suôn sẻ hơn.","Mặt khác, trong giới trẻ, ngày càng có nhiều người nghĩ rằng \"thời gian sau giờ làm muốn dành cho bản thân\". Với họ, cách sống ngoài giờ làm vốn dĩ phải do mỗi người tự do quyết định. Dù vậy, vẫn có không ít người cảm thấy rất khó chịu khi thực chất bị ép phải tham gia. Nếu từ chối thì có thể bị cho là khó gần, nên cũng có người dù không muốn vẫn đành phải đi.","Cùng với việc cách làm việc và giá trị quan ngày càng đa dạng, có lẽ cách thức của 飲みニケーション cũng đang dần thay đổi. Việc gần đây ngày càng nhiều bạn trẻ muốn phân biệt rạch ròi giữa công việc và cuộc sống riêng có lẽ cũng là một biểu hiện của điều đó. Không cần dựa vào rượu mà vẫn xây dựng được lòng tin qua những cuộc trò chuyện thường ngày, đó mới là hình ảnh lý tưởng vốn có."],"vocab":["đồng nghiệp","thói quen","lời thật lòng","thổ lộ, nói ra hết","quý giá","cưỡng ép","sự phản kháng, khó chịu","miễn cưỡng, không tự nguyện","đa dạng hóa","quan hệ tin cậy"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「働き方や価値観が多様化するのに伴って、飲みニケーションのあり方も少しずつ変わりつつあるのかもしれない」"},{"t":"〜ざるを得ない","note":"Diễn tả dù không muốn nhưng do hoàn cảnh nên đành phải làm như vậy. Ví dụ: 「断れば付き合いが悪いと見られかねず、不本意ながら出席せざるを得ない人もいる」"},{"t":"〜に対して","note":"Diễn tả thái độ hay hành động hướng tới một đối tượng nào đó. Ví dụ: 「参加を事実上強制されることに対して、強い抵抗を感じる人も決して少なくない」"},{"t":"〜かねない","note":"Diễn tả có khả năng xảy ra kết quả xấu (động từ thể ます bỏ ます + かねない). Ví dụ: 「断れば付き合いが悪いと見られかねず、不本意ながら出席せざるを得ない人もいる」"}]},"a-n3-5-n4":{"title":"Nomikai giao tiếp: văn hóa nhậu ở công sở","topic":"Công sở","trans":["Ở các công ty Nhật Bản, sau giờ làm người ta thường đi uống rượu với đồng nghiệp. Đôi khi cũng đi cùng sếp. Việc này được gọi là 「飲みニケーション」.","Khi uống rượu, bạn có thể nói ra những điều bình thường khó nói. Vì có thể trò chuyện thoải mái với cả sếp nên cũng có người thấy vui. Nhiều người cho rằng đây là cơ hội tốt để quan hệ giữa người với người trở nên gắn bó hơn.","Trong giới trẻ, ngày càng có nhiều người muốn trân trọng thời gian riêng của mình sau giờ làm. Cũng không ít người thấy khó chịu khi bị ép đi. Cùng với việc cách làm việc và cách nghĩ thay đổi, các buổi nhậu có vẻ cũng sẽ dần thay đổi. Dù không có rượu, việc xây dựng được lòng tin qua những cuộc trò chuyện thường ngày mới là tốt nhất."],"vocab":["đồng nghiệp","sếp, cấp trên","thoải mái, không câu nệ","quan hệ","cơ hội","trân trọng, coi trọng","tăng lên (thể て của 増える)","ép buộc, cố ép","thay đổi (thể て của 変わる)","lòng tin"],"grammar":[{"t":"〜と(điều kiện)","note":"Diễn tả \"hễ làm A thì tự nhiên sẽ xảy ra B\". Ví dụ: 「お酒を飲むと、ふだんは言いにくいことが話せます」."},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do, nhẹ nhàng hơn「から」. Ví dụ: 「上司とも気軽に話せるので、楽しいと思う人もいます」."},{"t":"Thể khả năng","note":"Diễn tả \"có thể làm ~\". Ví dụ: 「ふだんは言いにくいことが話せます」「信頼を作れるのがいちばんです」."},{"t":"〜そうです(dáng vẻ)","note":"Động từ thể ます bỏ ます + そうです, diễn tả suy đoán \"có vẻ sẽ ~\" dựa vào tình hình hiện tại. Ví dụ: 「飲み会も少しずつ変わりそうです」."}]},"a-n3-6-n2":{"title":"Bốn mùa và các lễ hội trong năm của Nhật Bản","topic":"Văn hóa","trans":["Nhật Bản có bốn mùa xuân, hạ, thu, đông, và những lễ hội phù hợp với từng mùa vẫn được trân trọng gìn giữ cho đến ngày nay. Vì bốn mùa thay đổi rất rõ rệt, từ xưa người ta đã điều chỉnh nhịp sống của mình theo những biến đổi của thiên nhiên. Các lễ hội chính là trí tuệ sống ấy được hiện thực hóa, và cách tận hưởng của mỗi mùa cũng có những nét khác nhau.","Mùa xuân là mùa hoa anh đào, mọi người tụ tập ở công viên, vừa ăn uống dưới tán hoa vừa chào đón xuân về, và việc này đã trở thành thông lệ. Cộng thêm niềm vui khi mùa đông lạnh giá kết thúc, có thể nói ngắm hoa là một lễ hội mang ý nghĩa đặc biệt hơn nhiều so với một buổi tụ họp ăn uống đơn thuần. Đến mùa hè, khắp nơi tổ chức lễ hội và đại hội pháo hoa, cả thành phố náo nhiệt với những người mặc yukata. Nói rằng các lễ hội mùa hè mang đến cho đường phố vẻ rực rỡ và sức sống chỉ riêng mùa này mới có cũng không hề quá lời.","Mùa thu còn được gọi là \"mùa thu của sự ngon miệng\" và \"mùa thu của việc đọc sách\", nhiều người tận hưởng lá đỏ trong không khí đã trở nên mát mẻ. Khi cái nóng dịu bớt, mọi người dần trải qua những khoảng thời gian thư thả tùy theo sở thích riêng, như thưởng thức ăn uống hay đọc sách. Mùa đông có Tết Nhật (Shōgatsu), việc cả gia đình quây quần ăn osechi và đi lễ đền đầu năm (hatsumōde) là điều rất phổ biến. Rời xa cuộc sống thường nhật bận rộn, cùng gia đình đón chào một năm mới có thể xem là ý nghĩa lớn của dịp Tết.","Những lễ hội này không chỉ giúp ta cảm nhận sự thay đổi của các mùa bằng chính cơ thể mình, mà còn là cơ hội quý giá để xác nhận lại sự gắn kết với gia đình và những người trong cộng đồng. Cùng với việc cuộc sống ngày càng tiện lợi, ta đã có thể sống mà không cần để ý đến mùa, nhưng giá trị của các lễ hội vẫn không hề mất đi. Ngay cả giữa sự tiện lợi, tấm lòng trân trọng nhịp điệu của thiên nhiên hẳn sẽ tiếp tục được truyền lại qua nhiều thế hệ."],"vocab":["được kế thừa, được truyền lại","sự biến đổi, sự thay đổi (của mùa)","điều chỉnh, sắp xếp cho ổn","sự đến, sự tới","thông lệ, việc tổ chức định kỳ","náo nhiệt, nhộn nhịp","nói quá, phóng đại","dịu bớt, trở nên dịu nhẹ","lễ đền đầu năm mới","quý giá, quý báu"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「生活が便利になるに伴って、季節を意識しなくても暮らせるようになったが、行事の価値は失われていない」. Vế đầu cho thấy khi cuộc sống trở nên tiện lợi thì cách sống cũng thay đổi theo."},{"t":"〜につれて","note":"Diễn tả khi vế trước tiến triển thì vế sau cũng thay đổi dần dần, thường dùng cho sự thay đổi từng bước. Ví dụ: 「暑さが和らぐにつれて、人々は食事や読書など、それぞれの好みに合わせて穏やかな時間を過ごすようになる」."},{"t":"〜と言っても過言ではない","note":"Nghĩa là \"nói như vậy cũng không quá lời\", dùng để nhấn mạnh quan điểm của mình. Ví dụ: 「夏の行事は、季節ならではの華やかさと活気を街にもたらしていると言っても過言ではない」."},{"t":"〜という以上に","note":"Nghĩa là \"hơn cả mức...\", chỉ ra ý nghĩa của sự việc không chỉ dừng lại ở đó. Ví dụ: 「花見は単なる食事会という以上に特別な意味を持つ行事だと言えるだろう」."}]},"a-n3-6-n4":{"title":"Bốn mùa và các lễ hội trong năm của Nhật Bản","topic":"Văn hóa","trans":["Nhật Bản có bốn mùa, và mỗi mùa đều có những lễ hội riêng. Mùa xuân là mùa hoa anh đào, mọi người tụ tập ở công viên. Mọi người vừa ăn cơm dưới tán hoa vừa chào đón mùa xuân đến.","Đến mùa hè, nhiều nơi có lễ hội và đại hội pháo hoa. Rất nhiều người mặc yukata đến, rất náo nhiệt. Mùa thu được gọi là \"mùa thu của sự ngon miệng\" và \"mùa thu của việc đọc sách\". Vì trời trở nên mát mẻ nên nhiều người đi ngắm lá đỏ.","Mùa đông có Tết Nhật (Shōgatsu), cả gia đình quây quần ăn osechi. Sau đó, cũng có nhiều người đi lễ đền đầu năm (hatsumōde). Những lễ hội này là cơ hội để cảm nhận sự thay đổi của các mùa và sự gắn kết với gia đình. Dù trong cuộc sống tiện lợi, tấm lòng trân trọng thiên nhiên hẳn vẫn sẽ tiếp tục mãi."],"vocab":["mùa","lễ hội, sự kiện","tụ tập","chúc mừng, ăn mừng","lễ hội (matsuri)","yukata (kimono mùa hè)","lá đỏ","mát mẻ","Tết Nhật, năm mới","cơ hội"],"grammar":[{"t":"〜ながら","note":"Diễn tả hai hành động diễn ra cùng lúc. Dạng ます của động từ bỏ ます rồi thêm ながら. Ví dụ: 「花の下でご飯を食べながら、春が来たことを祝います」"},{"t":"〜と(〜なると)","note":"Diễn tả khi gặp tình huống nào đó thì sẽ có kết quả nào đó, thường dùng cho việc thuộc về tự nhiên hoặc cố định. Ví dụ: 「夏になると、いろいろな所で祭りや花火大会があります」"},{"t":"〜と言われている","note":"Nghĩa là \"người ta nói là...\", dùng để giới thiệu cách nói thông thường. Ví dụ: 「秋は「食欲の秋」や「読書の秋」と言われています」"},{"t":"〜でしょう","note":"Diễn tả sự suy đoán, nghĩa là \"chắc là... nhỉ\". Ví dụ: 「自然を大切にする心はずっと続くでしょう」"}]},"a-n3-7-n2":{"title":"Suy nghĩ về cách phòng ngừa sốc nhiệt","topic":"Đời sống","trans":["Những năm gần đây, một phần do ảnh hưởng của sự nóng lên toàn cầu, mùa hè ở Nhật Bản ngày càng khắc nghiệt hơn qua từng năm. Đặc biệt từ tháng Bảy đến tháng Tám, những ngày nắng nóng gay gắt với nhiệt độ vượt quá 35 độ đã không còn hiếm gặp nữa.","Cùng với cái nóng như vậy, vấn đề năm nào cũng được nhắc đến chính là sốc nhiệt (say nóng). Khi sự cân bằng nước và muối trong cơ thể bị phá vỡ, bạn sẽ bị chóng mặt, đau đầu, và nếu trở nặng thì thậm chí có thể dẫn đến tình trạng nguy hiểm đến tính mạng.","Nguyên tắc cơ bản của việc phòng ngừa là bổ sung nước thường xuyên, từng chút một, trước khi cảm thấy khát. Ngoài ra, hạn chế ra ngoài vào khung giờ nhiệt độ cao nhất có thể, và sử dụng điều hòa hợp lý để điều chỉnh nhiệt độ phòng cũng là điều không thể thiếu.","Mặt khác, suy nghĩ chủ quan kiểu \"mình vẫn ổn mà\" lại không hiếm khi dẫn đến nguy hiểm. Triệu chứng không phải lúc nào cũng tiến triển mà bản thân không hề hay biết, nhưng cũng có trường hợp đến khi nhận ra thì đã quá muộn, vì vậy thói quen hỏi han, nhắc nhở lẫn nhau với những người xung quanh trở nên rất quan trọng. Hãy cùng quan tâm đến nhau để vượt qua mùa hè khắc nghiệt này một cách nhẹ nhàng, không gắng sức quá mức."],"vocab":["hằng năm, năm này qua năm khác","ngày nắng nóng gay gắt (nhiệt độ cao nhất từ 35 độ trở lên)","mất cân bằng, sụp đổ","gây ra, dẫn đến","trở nặng, nặng hơn","bổ sung","hạn chế, kiềm chế","không thể thiếu","suy nghĩ chủ quan, định kiến sẵn","đã quá muộn"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một sự việc thay đổi thì một việc khác cũng xảy ra theo. Ví dụ:「こうした暑さに伴って、毎年問題になるのが熱中症である」"},{"t":"〜かねない","note":"Đi với thân động từ dạng ます, diễn tả khả năng xảy ra kết quả không tốt. Ví dụ:「命に関わる事態にもなりかねない」"},{"t":"〜とは限らない","note":"Diễn tả \"không hẳn là\", \"chưa chắc\", dùng để phủ định một nhận định mang tính tuyệt đối. Ví dụ:「症状は本人が自覚しないうちに進むとは限らない」"},{"t":"〜に加えて","note":"Diễn tả việc bổ sung thêm một sự việc khác ngoài những điều đã có. Ví dụ:「それに加えて、気温の高い時間帯の外出はできるだけ控え」"}]},"a-n3-7-n4":{"title":"Cẩn thận với sốc nhiệt","topic":"Đời sống","trans":["Gần đây, mùa hè ở Nhật Bản trở nên rất nóng. Tháng Bảy và tháng Tám có những ngày nhiệt độ cao hơn 35 độ.","Vào những ngày nóng như thế này, điều cần chú ý là sốc nhiệt (say nóng). Khi cơ thể thiếu nước, bạn sẽ bị đau đầu, choáng váng, loạng choạng. Trường hợp nặng, thậm chí có thể nguy hiểm đến tính mạng.","Để phòng tránh sốc nhiệt, hãy uống nước trước khi thấy khát. Vào những giờ nóng, tốt nhất là cố gắng đừng ra ngoài. Sử dụng điều hòa một cách hợp lý cũng rất quan trọng. Dù bạn nghĩ \"mình vẫn ổn\", cơ thể vẫn có thể trở nên không khỏe. Hãy nhắc nhở nhau với những người xung quanh và cùng trải qua mùa hè thật khỏe mạnh nhé."],"vocab":["nhiệt độ không khí","sốc nhiệt, say nóng","trở nên thiếu","đầu","tính mạng","phòng tránh","bên ngoài","giỏi, khéo, một cách hợp lý","quan trọng","khỏe mạnh, tràn đầy sức sống"],"grammar":[{"t":"〜たり〜たりする","note":"Liệt kê một vài hành động hoặc trạng thái. Ví dụ:「頭が痛くなったり、ふらふらしたりする」"},{"t":"〜ようにする","note":"Diễn tả việc cố gắng tạo thói quen, cố gắng làm gì đó. Ví dụ:「のどがかわく前に水を飲むようにする」"},{"t":"〜ないほうがいい","note":"Khuyên người khác không nên làm việc gì đó. Ví dụ:「できるだけ外に出ないほうがいい」"},{"t":"〜と(điều kiện)","note":"Khi việc ở vế trước xảy ra thì kết quả ở vế sau tự nhiên xuất hiện. Ví dụ:「体の水が足りなくなると、頭が痛くなったり」"}]},"a-n4-1-n2":{"title":"お花見――日本の春を彩る習慣","topic":"Văn hóa","trans":["Khi mùa xuân đến, hoa anh đào ở khắp nơi trên Nhật Bản đồng loạt bắt đầu nở, cả thành phố được bao phủ trong sắc hồng nhạt. Mọi người tụ tập ở công viên, vừa ăn cơm hộp, uống rượu dưới tán hoa anh đào, vừa chào đón mùa xuân. Tục lệ này được gọi là 「Hanami」 (ngắm hoa anh đào), là hoạt động tiêu biểu cho mùa xuân Nhật Bản và được yêu thích rộng rãi.","Hoa anh đào là loài hoa rất đẹp, nhưng đặc điểm là thời gian từ lúc nở rộ đến khi rụng chỉ khoảng một tuần, khá ngắn ngủi. Chính vì mùa hoa có hạn nên năm nào cũng có nhiều người háo hức mong chờ thời điểm này. Khi đêm xuống, hoa anh đào được chiếu sáng bằng đèn mang đến một bầu không khí huyền ảo khác hẳn ban ngày. Nếu có cơ hội, bạn nhất định hãy đến tận nơi một lần để tận mắt chiêm ngưỡng vẻ đẹp ấy nhé.","Tục ngắm hoa đã có từ rất lâu đời, người xưa cũng vừa ngắm hoa anh đào vừa tận hưởng mùa xuân đến. Dù thời đại có thay đổi, cảm giác cảm nhận sự chuyển mùa qua hoa anh đào có lẽ xưa nay vẫn không đổi. Có thể nói, đằng sau việc hoa anh đào luôn được mọi người yêu mến chính là sự nhạy cảm của người Nhật đối với thiên nhiên.","Tuy nhiên, cùng với việc Hanami ngày càng thịnh hành, các vấn đề như giữ chỗ và rác thải cũng trở nên nổi cộm. Dù là hoạt động vui vẻ, nếu thiếu sự quan tâm đến những người xung quanh thì cũng có thể dẫn đến rắc rối. Để ai cũng có thể thoải mái tận hưởng mùa xuân, có thể nói tuân thủ phép lịch sự là điều quan trọng hơn hết."],"vocab":["nhạt, nhẹ (màu)","sự đến, ghé thăm","nở rộ","huyền ảo, như trong mơ","đích thân đến, đến tận nơi","sự chuyển biến, thay đổi (theo mùa)","sự nhạy cảm, cảm quan","giữ chỗ","sự quan tâm, ý tứ"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một sự việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ trong bài: 「お花見が盛んになるに伴って、場所取りやゴミの問題も目立つようになってきました」"},{"t":"〜かねない","note":"Diễn tả khả năng xảy ra kết quả xấu, thường dùng cho tình huống tiêu cực. Ví dụ trong bài: 「周りの人への配慮を欠けば、トラブルにつながりかねません」"},{"t":"〜からこそ","note":"Nhấn mạnh chính vì lý do này mà mới có kết quả phía sau. Ví dụ trong bài: 「咲いている期間が限られているからこそ、多くの人がこの時期を毎年心待ちにしているのです」"},{"t":"〜に対する","note":"Chỉ đối tượng mà cảm xúc, thái độ hoặc hành động hướng tới, bổ nghĩa cho danh từ phía sau. Ví dụ trong bài: 「日本人の自然に対する感性があると言えるでしょう」"}]},"a-n4-1-n3":{"title":"お花見","topic":"Văn hóa","trans":["Khi mùa xuân đến, hoa anh đào bắt đầu nở khắp nơi trên Nhật Bản, cả thành phố được bao trùm trong bầu không khí tươi sáng. Mọi người tụ tập ở công viên, ăn cơm hộp, uống rượu dưới tán hoa anh đào và tận hưởng. Việc vừa ngắm hoa anh đào vừa vui chơi như vậy được gọi là 「お花見」 (ngắm hoa anh đào).","Hoa anh đào rất đẹp, nhưng thời gian nở chỉ khoảng một tuần. Vì vậy, nhiều người rất mong chờ thời điểm này.","Khi đêm xuống, hoa anh đào được thắp đèn cũng mang một vẻ đẹp khác với ban ngày. Nếu có cơ hội, bạn nhất định hãy đi ngắm một lần, cả hoa anh đào ban ngày lẫn ban đêm nhé.","Tục ngắm hoa đã có từ rất lâu, người xưa cũng ngắm hoa anh đào để tận hưởng mùa xuân đến. Dù là xưa hay nay, có thể nói hoa anh đào là một sự tồn tại đặc biệt khiến mọi người cảm nhận được mùa xuân. Tuy nhiên, vì cũng có vấn đề về giữ chỗ và rác thải nên sự quan tâm đến những người xung quanh là điều không thể thiếu. Để ai cũng có thể thoải mái tận hưởng, điều quan trọng là tuân thủ phép lịch sự."],"vocab":["bị bao trùm, được bao bọc","tụ tập","thời gian, khoảng thời gian","mong chờ, háo hức","vẻ đẹp","tục lệ, thói quen","sự đến, ghé thăm","giữ chỗ","sự quan tâm, ý tứ","không thể thiếu"],"grammar":[{"t":"〜たり〜たりする","note":"Liệt kê một vài hành động tiêu biểu, nghĩa là \"lúc thì…, lúc thì…\". Ví dụ: 「お弁当を食べたり、お酒を飲んだりして楽しみます」"},{"t":"〜ながら","note":"Diễn tả hai hành động diễn ra cùng lúc. Ví dụ: 「このように桜を見ながら過ごすことを」"},{"t":"〜ため","note":"Diễn tả nguyên nhân, lý do, mang tính văn viết hơn 「から」. Ví dụ: 「場所取りやゴミの問題もあるため」"},{"t":"〜ように","note":"Diễn tả mục đích, nhằm để một trạng thái nào đó thực hiện được. Ví dụ: 「誰もが気持ちよく楽しめるように」"}]},"a-n4-10-n2":{"title":"Máy tự thanh toán – cách mua sắm mới","topic":"Đời sống","trans":["Tuần trước, lần đầu tiên tôi dùng máy tự thanh toán ở siêu thị gần nhà và rất ấn tượng với cách nó vận hành. Điểm đặc trưng nhất là khách có thể tự thanh toán xong xuôi mà không cần qua nhân viên. Những năm gần đây, do thiếu nhân lực, ngày càng nhiều cửa hàng đưa vào các thiết bị thanh toán không cần người. Tiện thì có tiện, nhưng lần đầu dùng cũng có lúc tôi không khỏi bối rối.","Đầu tiên, bạn lấy từng món hàng ra khỏi giỏ, rồi đưa mã vạch lại gần máy để máy quét. Nếu máy kêu lên tức là món hàng đó đã được ghi nhận đúng. Tiếp theo, làm theo hướng dẫn trên màn hình để chọn trả bằng tiền mặt hay bằng thẻ. Nếu chọn tiền mặt, bạn bỏ tiền vào khe nhận tiền được chỉ định.","Vì là lần đầu nên tôi không biết phải bấm vào đâu và lúng túng một lúc lâu. Tuy nhiên, một nhân viên ở gần đó nhận ra tôi đang gặp khó khăn nên chạy đến ngay và nhiệt tình giúp đỡ. Dù là cửa hàng giao phó cho máy móc, có sự hỗ trợ của con người vẫn khiến mình yên tâm hơn nhiều.","Máy tự thanh toán không cần xếp hàng chờ ở quầy nên rất tiện khi bạn không có nhiều thời gian. Tuy nhiên, so với những người quen thao tác với máy móc thì người chưa quen có thể sẽ thấy hơi khó. Dù vậy, khi đã quen cách dùng thì ai cũng sẽ dùng thành thạo một cách dễ dàng. Những bạn sắp dùng thử, trước hết hãy bình tĩnh vừa nhìn màn hình vừa thử nhé."],"vocab":["thanh toán, tính tiền","cơ chế, cách vận hành","khâm phục, ấn tượng","thiếu nhân lực","đưa vào, áp dụng","hướng dẫn","khe nhận tiền, khe bỏ tiền","chạy đến ngay, vội vã tới","đáng tin cậy, khiến yên tâm","sự dư dả, thong thả"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một sự thay đổi xảy ra thì một thay đổi khác cũng xảy ra theo. Ví dụ: 「近年は人手不足に伴って」 thiết bị thanh toán không cần người cũng tăng theo."},{"t":"〜ざるを得ない","note":"Diễn tả việc không thể không làm, không tránh khỏi. Gắn vào thể ない của động từ (bỏ ない). Ví dụ: 「戸惑わざるを得ない場面もありました」"},{"t":"〜に従って","note":"Diễn tả việc hành động theo chỉ dẫn, quy tắc hoặc hướng dẫn. Ví dụ: 「画面の案内に従って」 chọn phương thức thanh toán."},{"t":"〜に対して","note":"Dùng để đối chiếu hai đối tượng hoặc hai tình huống. Ví dụ: 「操作に慣れている人に対して」 người chưa quen thì thấy khó hơn."}]},"a-n4-10-n3":{"title":"Máy tự thanh toán","topic":"Đời sống","trans":["Tuần trước, lần đầu tiên trong đời tôi thử dùng máy tự thanh toán ở siêu thị gần nhà. Máy tự thanh toán là loại máy giúp bạn tự tính tiền món hàng mà không cần nhờ đến nhân viên. Tôi nghĩ biết cách dùng trước sẽ có ích cho bạn sau này.","Đầu tiên, bạn lấy từng món hàng trong giỏ ra, rồi đưa mã vạch lại gần máy. Nếu nghe tiếng \"bíp\" thì tức là món hàng đó đã được quét đúng. Tiếp theo, vừa xem hướng dẫn trên màn hình, bạn vừa chọn trả bằng tiền mặt hay bằng thẻ.","Nếu chọn tiền mặt, bạn bỏ tiền vào chỗ nhận tiền của máy để thanh toán. Vì là lần đầu nên tôi không biết phải bấm vào đâu và hơi lúng túng. Nhưng khi tôi đang gặp khó khăn thì một nhân viên ở gần đó đến ngay và giúp tôi, nên tôi thấy yên tâm.","Máy tự thanh toán không cần xếp hàng ở quầy nên tôi thấy rất tiện khi không có nhiều thời gian. Có điều, với những người chưa quen với máy móc thì có thể sẽ thấy hơi khó. Khi đã quen cách dùng thì ai cũng dùng được dễ dàng. Những bạn sắp dùng thử, đừng vội nhé, hãy từ từ vừa nhìn màn hình vừa thử."],"vocab":["máy tự thanh toán","thanh toán, tính tiền","lấy ra","đưa lại gần, giơ trước (máy quét)","đọc, quét","hướng dẫn, chỉ dẫn","phân vân, lúng túng","giúp đỡ","quen, quen thuộc","thử"],"grammar":[{"t":"〜ておく","note":"Diễn tả việc làm sẵn từ trước để chuẩn bị. Ví dụ: 「使い方を知っておくと」 nghĩa là biết trước cách dùng thì sau này sẽ có ích."},{"t":"〜ため(nguyên nhân・lý do)","note":"Cách nói khá trang trọng để chỉ nguyên nhân. Ví dụ: 「私は初めてだったため」 nghĩa là \"vì là lần đầu\"."},{"t":"〜にとって","note":"Diễn tả quan điểm, lập trường của ai đó. Ví dụ: 「機械に慣れていない人にとっては」 nghĩa là \"đối với những người chưa quen với máy móc\"."},{"t":"〜ようになる","note":"Diễn tả sự thay đổi về khả năng hoặc trạng thái. Ví dụ: 「誰でも簡単に使えるようになります」 nghĩa là \"ai cũng sẽ trở nên có thể dùng dễ dàng\"."}]},"a-n4-3-n2":{"title":"古都・京都を歩く","topic":"Du lịch","trans":["Kyoto là thành phố từng hưng thịnh với vai trò thủ đô của Nhật Bản hơn một nghìn năm trước, và nổi tiếng là đô thị lưu giữ lịch sử lâu đời cho đến ngày nay. Cùng với sự đổi thay của thời đại, diện mạo thành phố tuy đã thay đổi dần dần, nhưng các ngôi chùa và đền thờ cổ vẫn còn lại rất nhiều đến tận bây giờ. Những công trình đó không chỉ đơn thuần là tài nguyên du lịch, mà có thể nói là những tồn tại gắn bó sâu sắc với cuộc sống và tín ngưỡng của con người.","Một trong những nét hấp dẫn của Kyoto là, như hoa anh đào mùa xuân và lá đỏ mùa thu tiêu biểu cho điều đó, mỗi mùa thành phố lại cho thấy một diện mạo hoàn toàn khác. Dù là cùng một nơi, ấn tượng nhận được cũng rất khác nhau tùy theo mùa bạn đến thăm. Vì vậy, dù đến bao nhiêu lần cũng không chán, thậm chí không ít người nói rằng mỗi lần đến lại có một khám phá mới.","Nếu đi du lịch Kyoto, mình khuyên bạn đừng nhồi nhét lịch trình, mà hãy thong thả đi bộ, không vội vã. Bởi chỉ cần rẽ vào một con hẻm nhỏ, bạn có thể tình cờ gặp một ngôi chùa yên tĩnh hay một quán cà phê mang nét xưa cũ. Nếu cứ cố đi đúng theo kế hoạch, bạn sẽ buộc phải bỏ lỡ những cuộc gặp gỡ tình cờ như thế. Những nơi được ghi trên bản đồ chưa chắc đã là toàn bộ Kyoto.","Không chỉ những điểm du lịch nổi tiếng, nếu bạn ghé cả những quán nhỏ mà người dân địa phương hay lui tới, bạn sẽ thấy được nét hấp dẫn thật sự của Kyoto. Đối lập với vẻ lộng lẫy của các điểm du lịch, ở những quán nhỏ bạn cảm nhận được không khí đời thường của Kyoto. Kyoto cũng là thành phố vừa trân trọng giữ gìn các công trình cổ, vừa tích cực tiếp nhận văn hóa mới. Chính việc truyền thống và sự thay đổi cùng tồn tại một cách tự nhiên là lý do khiến Kyoto được yêu mến lâu dài."],"vocab":["thủ đô","hưng thịnh, phồn vinh (dạng gốc: 栄える)","tín ngưỡng","đại diện, tiêu biểu","diện mạo, vẻ ngoài","chán, ngán","vẫn như xưa, mang nét xưa cũ","tình cờ","cùng tồn tại, cộng sinh"],"grammar":[{"t":"〜に伴って","note":"Nghĩa là \"cùng với…, theo sự… mà…\": khi vế trước thay đổi thì vế sau cũng thay đổi theo. Ví dụ: 「時代の移り変わりに伴って町の姿は少しずつ変わってきました」"},{"t":"〜ざるを得ない","note":"Nghĩa là \"buộc phải…, đành phải…\", đi với thể ない của động từ (する thành せざるを得ない). Ví dụ: 「偶然の出会いを見逃さざるを得なくなってしまいます」"},{"t":"〜に対して","note":"Dùng để đối chiếu, nghĩa là \"trái với…, so với…\", để so sánh hai sự vật. Ví dụ: 「観光地の華やかさに対して、小さな店には京都の日常の空気が感じられます」"},{"t":"〜とは限らない","note":"Nghĩa là \"chưa chắc…, không hẳn…\", dùng để phủ định quan niệm \"tất cả đều…\". Ví dụ: 「地図に載っている場所だけが京都のすべてとは限らないのです」"}]},"a-n4-3-n3":{"title":"古都・京都を歩く","topic":"Du lịch","trans":["Kyoto là thành phố từng là thủ đô của Nhật Bản hơn một nghìn năm trước, và đến nay vẫn còn lại rất nhiều ngôi chùa, đền thờ cổ. Hoa anh đào mùa xuân và lá đỏ mùa thu đều rất đẹp, mỗi mùa lại cho thấy một diện mạo hoàn toàn khác. Vì vậy, dù đến bao nhiêu lần cũng không chán.","Khi đi du lịch Kyoto, mình khuyên bạn nên đi bộ thong thả, đừng vội vã. Thử rẽ vào một con hẻm nhỏ, đôi khi bạn sẽ gặp một ngôi chùa yên tĩnh hay một quán cà phê mang nét xưa cũ. Những cuộc gặp gỡ bất ngờ như vậy cũng có thể nói là niềm vui riêng có của những chuyến du lịch đi bộ.","Đừng chỉ ngắm các điểm du lịch nổi tiếng, bạn hãy ghé cả những quán nhỏ mà người dân địa phương hay lui tới nhé. Khác với những nơi dành cho khách du lịch, ở đó bạn cảm nhận được cuộc sống thường ngày của Kyoto. Làm như vậy, nét hấp dẫn thật sự của Kyoto chắc chắn sẽ dần dần hiện ra.","Nét hấp dẫn của Kyoto nằm ở chỗ vừa trân trọng giữ gìn các công trình cổ, vừa tiếp nhận cả văn hóa mới. Kyoto không chỉ đơn thuần giữ lại những thứ xưa cũ, mà liên tục thay đổi cùng thời đại. Chính vì thế, Kyoto là thành phố thu hút nhiều người từ xưa đến nay."],"vocab":["thủ đô","rất nhiều, vô số","diện mạo, vẻ ngoài","đến thăm, ghé thăm","chán, ngán","vẫn như xưa, mang nét xưa cũ","đến tận nơi, đích thân ghé","địa phương, nơi mình sống","sức hấp dẫn, nét quyến rũ","tiếp nhận, đưa vào"],"grammar":[{"t":"〜によって","note":"Nghĩa là \"tùy theo…\" hoặc \"bằng cách…, thông qua…\". Trong 「季節によってまったく違う表情を見せてくれます」 là tùy theo mùa mà khác nhau; còn 「そうすることによって」 là thông qua cách làm này."},{"t":"〜わけではない","note":"Phủ định một phần, nghĩa là \"không có nghĩa là…, không phải là…\". Trong 「昔のものをただ残しているわけではなく」 nghĩa là không phải chỉ đơn thuần giữ lại đồ xưa."},{"t":"〜だけでなく","note":"Nghĩa là \"không chỉ… mà còn…\". Trong 「有名な観光地を見るだけでなく、地元の人が通う小さな店にも足を運んでみてください」 là không chỉ ngắm danh thắng mà còn ghé cả những quán nhỏ của người địa phương."},{"t":"〜はずだ","note":"Diễn tả suy đoán của người nói dựa trên lý do, nghĩa là \"chắc chắn sẽ…, hẳn là…\". Trong 「本当の京都の魅力が少しずつ見えてくるはずです」 là suy đoán rằng làm vậy sẽ thấy được nét hấp dẫn của Kyoto."}]},"a-n4-4-n2":{"title":"Chuyến du lịch một mình đầu tiên","topic":"Du lịch","trans":["Tháng trước, lần đầu tiên tôi đi du lịch một mình và quyết định đến thăm Kanazawa, nơi tôi đã để ý từ lâu. Trước khi khởi hành, tôi không khỏi cảm thấy bất an, nhưng việc tự lên kế hoạch lại thú vị hơn tôi tưởng. Không cần phải chiều theo ai, có thể tự do chọn nơi mình muốn đến, tôi nghĩ đó cũng là một sức hấp dẫn lớn.","Hôm đó tôi đi tàu Shinkansen từ sáng sớm và đến Kanazawa sau buổi trưa, quy mô của nhà ga khiến tôi không khỏi choáng ngợp. Vừa đến nơi, tôi quyết định đi xem khu vườn nổi tiếng trước. Nhờ thời tiết đẹp, tôi đã chụp được rất nhiều ảnh với phong cảnh khu vườn làm nền. Dù là nơi lần đầu ghé thăm, tôi vẫn có thể đi tham quan theo nhịp độ của riêng mình, tôi cảm thấy đó chính là điểm hay riêng có của việc đi du lịch một mình.","Khi trời tối, tôi ghé chợ và thưởng thức thỏa thích hải sản tươi ngon. Vì đi một mình nên tôi không cần để ý đến người khác, muốn gọi món gì thì gọi, muốn ăn bao nhiêu thì gọi bấy nhiêu. Khi đi du lịch theo nhóm, mong muốn của mọi người chưa chắc đã giống nhau, nên tôi thấy sự tự do này thật đáng quý. Khi đi bộ một mình trong một thị trấn xa lạ, cũng có lúc tôi thấy hơi cô đơn, nhưng cảm giác tự do dễ chịu còn lấn át hơn nhiều.","Theo hành trình tiến triển, nỗi bất an trước khi đi dần dần nhạt đi, tâm trạng cũng trở nên thoải mái hơn. Qua chuyến đi này, tôi có được sự tự tin rằng \"dù một mình cũng xoay xở được\", đó là một thu hoạch lớn. Cảm giác ngại ngần khi hành động một mình dường như đã nhỏ đi nhờ trải nghiệm lần này. Nếu có cơ hội, tôi muốn lại một mình đến một thị trấn khác."],"vocab":[{"w":"不安","m":"bất an, lo lắng"},{"w":"圧倒","m":"áp đảo, choáng ngợp"},{"w":"海の幸","m":"hải sản"},{"w":"味わう","m":"thưởng thức, cảm nhận"},{"w":"気を遣う","m":"để ý, quan tâm đến người khác"},{"w":"貴重","m":"quý giá, đáng quý"},{"w":"余裕","m":"sự thong thả, thoải mái"},{"w":"収穫","m":"thu hoạch, thành quả"},{"w":"抵抗感","m":"cảm giác e ngại, chống cự"}],"grammar":[{"t":"〜ざるを得ない","note":"Diễn tả ý \"không thể không~, đành phải~\", mang sắc thái bất đắc dĩ. Ví dụ: 「出発する前は不安を感じざるを得なかった」."},{"t":"〜とは限らない","note":"Diễn tả ý \"không hẳn là~, chưa chắc~\", dùng để phủ định một nhận định toàn diện hoặc tuyệt đối. Ví dụ: 「全員の希望が一致するとは限らない」."},{"t":"〜に伴って","note":"Diễn tả ý \"cùng với~, theo đà~\", khi vế trước thay đổi thì vế sau cũng thay đổi theo. Ví dụ: 「旅が進むに伴って、出発前の不安は少しずつ薄れ」."},{"t":"〜を通して","note":"Diễn tả ý \"thông qua~\", chỉ việc đạt được kết quả nhờ một trải nghiệm hoặc phương tiện nào đó. Ví dụ: 「この旅行を通して、一人でも何とかなるという自信がついた」."}]},"a-n4-4-n3":{"title":"Chuyến du lịch một mình đầu tiên","topic":"Du lịch","trans":["Tháng trước, lần đầu tiên trong đời tôi đi du lịch một mình. Điểm đến tôi chọn là thành phố Kanazawa mà tôi đã để ý từ lâu. Trước khi đi tôi cũng có chút lo lắng, nhưng tự lên kế hoạch lại thú vị hơn tôi tưởng.","Nhờ đi chuyến Shinkansen sáng sớm, tôi đến Kanazawa ngay sau buổi trưa. Nhà ga lớn hơn tôi tưởng tượng rất nhiều, khiến tôi bất giác dừng chân lại.","Trước tiên, tôi quyết định đi xem khu vườn nổi tiếng của thành phố này. Nhờ thời tiết đẹp, tôi đã chụp được rất nhiều ảnh với khung cảnh xinh đẹp làm nền. Buổi tối tôi đến chợ và thưởng thức hải sản tươi ngon. Vì đi một mình nên tôi rất vui khi có thể gọi món mình muốn ăn, ăn bao nhiêu tùy thích.","Khi đi bộ một mình trong thị trấn xa lạ, đôi lúc tôi cũng thấy hơi cô đơn. Dù vậy, sự tự do không phải chiều theo ai khiến tôi cảm thấy vô cùng dễ chịu. Nhờ chuyến đi này, tôi có được sự tự tin rằng dù một mình cũng xoay xở được. Nếu có cơ hội, tôi muốn lại một mình đi đâu đó."],"vocab":[{"w":"計画","m":"kế hoạch"},{"w":"不安","m":"bất an, lo lắng"},{"w":"想像","m":"tưởng tượng"},{"w":"庭園","m":"khu vườn, vườn cảnh"},{"w":"恵まれる","m":"được ưu đãi, may mắn có được"},{"w":"新鮮","m":"tươi, tươi mới"},{"w":"味わう","m":"thưởng thức, cảm nhận kỹ"},{"w":"自由","m":"tự do"},{"w":"心地よい","m":"dễ chịu, thoải mái"},{"w":"自信","m":"tự tin"}],"grammar":[{"t":"〜おかげで","note":"Diễn tả kết quả tốt có được nhờ một nguyên nhân nào đó, mang sắc thái biết ơn. Ví dụ: 「朝早い新幹線に乗ったおかげで、昼過ぎには金沢に着くことができました」"},{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Ví dụ: 「この町で有名な庭園を見に行くことにしました」"},{"t":"〜ため(原因)","note":"Dùng trong văn viết hoặc bối cảnh trang trọng, diễn tả nguyên nhân, lý do. Ví dụ: 「天気に恵まれたため、きれいな景色を背景に写真をたくさん撮ることができました」"},{"t":"〜によって","note":"Diễn tả kết quả phát sinh thông qua một phương tiện hoặc trải nghiệm nào đó. Ví dụ: 「この旅行によって、一人でも何とかなるという自信がつきました」"}]},"a-n4-5-n2":{"title":"Một ngày đi làm thêm","topic":"Công việc","trans":["Mình vừa học đại học vừa làm thêm ở quán cà phê, mỗi tuần ba buổi, ca từ chiều đến tối. Đến quán, việc đầu tiên là thay đồng phục và rửa tay thật kỹ, đó là quy định trước khi bắt đầu làm việc. Ở quán ăn uống thì không thể thiếu sự quan tâm đến vệ sinh, nên mình cảm thấy thói quen này tuy nhỏ nhưng lại mang một ý nghĩa quan trọng.","Công việc rất đa dạng, gồm ghi order, pha cà phê và dọn bàn, v.v. Vào khung giờ đông khách thì bận đến mức không có thời gian thở, buộc phải chạy đi chạy lại, vất vả cả về thể lực lẫn tinh thần. Dù vậy, chỉ cần khách nói một tiếng 「ありがとう」 là mệt mỏi tan biến ngay lập tức, thật kỳ lạ.","Hồi mới đi làm, mình toàn mắc lỗi và cũng không ít lần bị các anh chị đi trước nhắc nhở. Lúc đó, ngày nào mình cũng nhận ra sâu sắc sự non nớt của bản thân. Nhưng khi tích lũy thêm kinh nghiệm, những việc mình làm được dần dần nhiều lên.","Những gì mình có được từ công việc làm thêm này không chỉ dừng lại ở thu nhập. Cách nói chuyện với mọi người và tầm quan trọng của việc hợp tác làm việc nhóm, mình cũng đã học được ngay tại nơi làm việc. Cân bằng với việc học chắc chắn không thể nói là dễ, nhưng mình cảm thấy càng vất vả thì càng thu được nhiều. Việc có được trải nghiệm này trước khi bước ra xã hội, mình nghĩ là một tài sản quý giá đối với bản thân."],"vocab":["cẩn thận, kỹ lưỡng","mặt vệ sinh, khía cạnh vệ sinh","không thể thiếu","trải rộng nhiều lĩnh vực, phạm vi rộng","không có thời gian để thở","sự non nớt, thiếu kinh nghiệm","bị buộc phải nhận ra sâu sắc","cân bằng, kết hợp cả hai","quý giá","tài sản, của cải quý giá"],"grammar":[{"t":"〜かたわら","note":"Diễn tả việc vừa làm việc chính (công việc chính hoặc việc học), vừa duy trì làm thêm một việc khác. Ví dụ:「大学に通うかたわら、カフェでアルバイトをしており」"},{"t":"〜ざるを得ない","note":"Diễn tả ngoài cách đó ra không còn cách nào khác, buộc phải làm. Ví dụ:「息つく暇もなく動き回らざるを得ず」"},{"t":"〜に伴って","note":"Diễn tả khi một sự việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ:「経験を重ねるに伴って、少しずつできる仕事が増えていった」"},{"t":"〜にとどまらない","note":"Diễn tả không chỉ giới hạn trong một phạm vi nào đó mà còn nhiều hơn thế. Ví dụ:「得たものは、収入だけにとどまらない」"}]},"a-n4-5-n3":{"title":"Một ngày đi làm thêm","topic":"Công việc","trans":["Mình vừa học đại học vừa làm thêm ở quán cà phê. Vì mỗi tuần có ba buổi làm ca từ chiều đến tối nên những hôm đó mình thấy một ngày trôi qua rất nhanh. Đến quán, việc đầu tiên là thay đồng phục, và theo quy định thì phải rửa tay thật kỹ để đảm bảo vệ sinh.","Công việc gồm ghi order, pha cà phê, dọn bàn, v.v. Giờ cao điểm bận đến mức không có thời gian thở, rất vất vả. Dù vậy, khi khách nói 「ありがとう」 với mình, mình cảm thấy mệt mỏi như bay đi mất.","Hồi mới bắt đầu, mình toàn mắc lỗi và hay bị các anh chị đi trước nhắc nhở. Mỗi lần thất bại mình đều buồn, nhưng dần dần những việc mình làm được đã nhiều lên. Nhờ công việc làm thêm, mình học được không chỉ cách kiếm tiền mà còn cách nói chuyện với mọi người và tầm quan trọng của tinh thần làm việc nhóm.","Cân bằng với việc học không hề dễ dàng, nhưng mình nghĩ may mà mình đã duy trì được. Mình cho rằng trải nghiệm này là một bài học rất tốt trước khi bước ra xã hội."],"vocab":["đồng phục","vệ sinh","gọi món, đặt hàng","thất bại, mắc lỗi","anh chị đi trước, tiền bối","nhắc nhở, chú ý","cân bằng, kết hợp cả hai","xã hội","kinh nghiệm","tầm quan trọng"],"grammar":[{"t":"〜ため(原因・理由)","note":"Diễn tả nguyên nhân, lý do, giọng trang trọng hơn 「から」. Ví dụ:「シフトに入っているため、その日は一日がとても短く感じます」"},{"t":"〜ことになっている","note":"Diễn tả quy định, thông lệ hoặc cách làm đã được định sẵn. Ví dụ:「衛生のためにしっかり手を洗うことになっています」"},{"t":"〜によって","note":"Diễn tả phương tiện, cách thức hoặc nguyên nhân, có thể dịch là \"thông qua\", \"nhờ vào\". Ví dụ:「アルバイトによって、お金だけでなく、人との話し方も学ぶことができました」"},{"t":"〜わけではない","note":"Phủ định một phần, nghĩa là \"không phải là...\". Ví dụ:「勉強との両立は簡単なわけではありませんが」"}]},"a-n4-6-n2":{"title":"Sức hấp dẫn của lễ hội mùa hè","topic":"Văn hóa","trans":["Ở Nhật Bản, cứ đến mùa hè là khắp nơi trong cả nước thường tổ chức các lễ hội mùa hè, được mọi người yêu thích rộng rãi như một nét đặc trưng của mùa. Phần lớn lễ hội mùa hè bắt nguồn từ các sự kiện của đền thần đạo hoặc chùa, và đến nay vẫn là dịp quan trọng để người dân trong vùng tụ họp. Khi màn đêm dần buông xuống, rất nhiều người mặc yukata lần lượt kéo đến khuôn viên đền hoặc chùa. Ngay cả những người ngày thường mặc đồ Tây cũng có xu hướng tận hưởng trang phục truyền thống vào ngày này.","Tại hội trường lễ hội, rất nhiều quầy hàng nối nhau san sát, chỉ cần đi dạo thôi cũng cảm nhận được bầu không khí náo nhiệt rất riêng. Có người thưởng thức takoyaki và đá bào, có người thử sức với trò vớt cá vàng, cách vui chơi tùy mỗi người. Tôi nghĩ sức hấp dẫn của lễ hội mùa hè nằm ở chỗ, thông qua đồ ăn và trò chơi, từ trẻ nhỏ đến người lớn đều có thể mỉm cười trong cùng một không gian.","Khi đêm đã khuya và lễ hội sắp kết thúc, cuối cùng những quả pháo hoa lớn cũng được bắn lên bầu trời đêm. Vừa nghe tiếng nổ lớn \"đùng\" vang lên thì ánh sáng đã lan tỏa khắp bầu trời tối đen. Khoảnh khắc ấy, những người đang tụ tập không thể không bật ra tiếng \"oa\". Sức mạnh chấn động khi âm thanh và ánh sáng hòa làm một không phải lúc nào cũng truyền tải đủ qua ảnh hay video, nên rất đáng để trải nghiệm trực tiếp tại chỗ. Chính vì là khung cảnh chỉ có thể thưởng thức vào một thời điểm hạn hẹp trong năm nên nó mới in đậm trong ký ức của nhiều người.","Như vậy, lễ hội mùa hè là sự kiện trở thành kỷ niệm quan trọng về mùa hè Nhật Bản, đồng thời cũng là dịp để cảm nhận mùa bằng chính cơ thể mình. Nếu có cơ hội đến Nhật Bản, bạn nhất định hãy mặc yukata và tận hưởng lễ hội trong cùng bầu không khí với người dân địa phương. Có thể bạn sẽ bối rối vì trang phục chưa quen, nhưng điều đó cũng sẽ trở thành một trải nghiệm khó quên của chuyến đi."],"vocab":["tổ chức, khai mạc","nét đặc trưng của mùa, biểu tượng theo mùa","khuôn viên (đền, chùa)","mặc vào, khoác lên người","xu hướng","san sát nhau (các cửa hàng)","sức sống, không khí náo nhiệt","bắn lên, phóng lên","sức chấn động, sức mạnh","bối rối, lúng túng"],"grammar":[{"t":"〜につれて","note":"Diễn tả khi vế trước thay đổi thì vế sau cũng thay đổi dần theo. Ví dụ:「夜になるにつれて、浴衣を身にまとった大勢の人々が、神社やお寺の境内へと次々に集まってきます」"},{"t":"〜かと思うと","note":"Diễn tả vừa xảy ra hành động ở vế trước thì ngay sau đó xuất hiện sự thay đổi ở vế sau. Ví dụ:「ドンという大きな音が響いたかと思うと、暗い空いっぱいに光が広がっていきます」"},{"t":"〜ずにはいられない","note":"Diễn tả việc không kìm được, không thể kiềm chế mà làm gì đó, là phản ứng tự nhiên bộc lộ ra. Ví dụ:「集まった人々は思わず『わあ』と声を上げずにはいられません」"},{"t":"〜とは限らない","note":"Diễn tả không phải lúc nào cũng như vậy, chưa chắc đều là thế, dùng để chỉ ra khả năng có ngoại lệ. Ví dụ:「写真や映像で見るだけでは十分に伝わるとは限らず、現地で体験する価値があります」"}]},"a-n4-6-n3":{"title":"Lễ hội mùa hè","topic":"Văn hóa","trans":["Ở Nhật Bản, cứ đến mùa hè là nhiều lễ hội mùa hè đủ loại được tổ chức ở khắp nơi, nên năm nào cũng có rất nhiều người mong chờ. Khi màn đêm buông xuống, những người mặc yukata dần dần tụ tập quanh đền thần đạo hoặc chùa. Yukata trông mát mẻ nên được cho là trang phục rất hợp để cảm nhận không khí lễ hội mùa hè.","Ở hội trường có rất nhiều quầy hàng xếp thành hàng, chỉ đi dạo thôi cũng thấy vui. Mọi người ăn takoyaki, đá bào, chơi vớt cá vàng, tùy ý tận hưởng buổi tối theo cách của mình. Không chỉ mua đồ ăn, việc có thể cùng gia đình và bạn bè cười đùa thông qua các trò chơi cũng là sức hấp dẫn của lễ hội.","Khi lễ hội sắp kết thúc, cuối cùng những quả pháo hoa lớn cũng được bắn lên bầu trời đêm. Sau tiếng nổ lớn \"đùng\" vang lên, ánh sáng lan tỏa khắp bầu trời đêm. Nhìn thấy khung cảnh tuyệt đẹp ấy, mọi người dường như không kìm được mà bật ra tiếng \"oa\".","Lễ hội mùa hè là sự kiện của Nhật Bản giúp cảm nhận được mùa, và đã trở thành kỷ niệm quan trọng của nhiều người. Nếu có cơ hội đến Nhật Bản, bạn nhất định hãy chọn đúng mùa hè để tham gia lễ hội nhé. Nếu mặc yukata đi chơi, chắc chắn sẽ là một trải nghiệm mùa hè đặc biệt."],"vocab":["được tổ chức, được khai mạc","yukata (kimono mùa hè)","bầu không khí","quầy hàng (ở lễ hội)","tùy ý mỗi người","sức hấp dẫn","đến gần, sắp đến","được bắn lên (pháo hoa, v.v.)","vang lên, vọng lại","sự kiện, nghi lễ"],"grammar":[{"t":"〜ため(nguyên nhân)","note":"Diễn tả nguyên nhân, lý do, mang tính văn viết hơn 「から」. Ví dụ:「各地でさまざまな夏祭りが開かれるため、毎年多くの人が楽しみにしています」"},{"t":"〜だけでなく","note":"Diễn tả \"không chỉ… mà còn…\". Ví dụ:「食べ物を買うだけでなく、遊びを通して家族や友達と笑い合えるところも、祭りの魅力です」"},{"t":"〜ようだ","note":"Suy đoán dựa trên những gì nhìn thấy, nghe thấy, \"dường như…\". Ví dụ:「思わず「わあ」と声を上げてしまうようです」"},{"t":"〜ば(điều kiện)","note":"Diễn tả điều kiện giả định, \"nếu… thì\". Ví dụ:「日本に行く機会があれば、ぜひ夏の時期を選んで、祭りに参加してみてください」"}]},"a-n4-7-n2":{"title":"Cách đổ rác","topic":"Cuộc sống","trans":["Sau khi bắt đầu sống ở Nhật, điều khiến mình ngạc nhiên nhất là cách đổ rác được quy định chi tiết hơn mình tưởng rất nhiều. Vì ở quê hương mình hầu như không để ý đến chuyện này, nên lúc đầu mình không khỏi bối rối. Rác phải được phân loại thành 「燃えるごみ」「燃えないごみ」「資源ごみ」 v.v. rồi mới được đem đi đổ.","Ngày được đổ cũng được quy định theo từng loại. Ở thị trấn mình sống, rác cháy được sẽ được thu vào thứ Hai và thứ Năm. Giờ giấc cũng có quy định, phải mang đến địa điểm chỉ định trước tám giờ sáng. Cho đến khi nhớ được ngày và giờ, mình đã buộc phải kiểm tra đi kiểm tra lại nhiều lần. Nếu phân loại sai thì có khi rác sẽ không được thu, nên không thể chủ quan.","Ban đầu, mình thấy phiền và tự hỏi tại sao phải phân loại chi tiết đến mức này. Nhưng sau đó mình nhận ra rằng chính nhờ từng cư dân tuân thủ quy tắc mà cuộc sống dễ chịu của cả thị trấn mới được duy trì. Một khi đã quen, bản thân việc phân loại hoàn toàn không phải là việc khó. Ngược lại, khi đã thành thói quen hằng ngày thì gần như bạn sẽ không còn thấy nó là gánh nặng nữa.","Nhờ việc phân loại rác được thực hiện triệt để mà thị trấn lúc nào cũng sạch sẽ. Cách đổ rác thoạt nhìn có vẻ là chuyện nhỏ nhặt, nhưng có thể nói đó là một quy ước quan trọng nâng đỡ cuộc sống của cộng đồng. Đúng là với người nước ngoài có những mặt cảm thấy là gánh nặng, nhưng đổi lại, những điều nhận được cũng hoàn toàn không ít."],"vocab":["bối rối, lúng túng","phân loại","thu gom","chỉ định","sơ suất, chủ quan","ban đầu, lúc đầu","cư dân","triệt để","sạch sẽ, gọn gàng","nhỏ nhặt, vụn vặt"],"grammar":[{"t":"〜ずにはいられない","note":"Diễn tả việc không thể không làm gì đó, không kìm được, thường dùng cho cảm xúc tự nhiên trào lên. Ví dụ:「最初は戸惑いを覚えずにはいられませんでした」"},{"t":"〜ざるを得ない","note":"Diễn tả việc buộc phải làm gì đó, không còn lựa chọn nào khác. Ví dụ:「曜日と時間を覚えるまでは、何度も確かめざるを得ませんでした」"},{"t":"〜に伴って","note":"Diễn tả khi một sự việc thay đổi thì sự việc khác cũng thay đổi hoặc xảy ra theo. Ví dụ:「住民が一人一人ルールを守ることに伴って、町全体の暮らしやすさが保たれている」"},{"t":"〜に対して","note":"Diễn tả đối với việc gì đó, hoặc đối lại với điều gì đó (đối chiếu hoặc đáp lại). Ví dụ:「それに対して得られるものも決して少なくありません」"}]},"a-n4-7-n3":{"title":"Cách đổ rác","topic":"Cuộc sống","trans":["Sau khi bắt đầu sống ở Nhật, điều khiến mình ngạc nhiên nhất là cách đổ rác rất chi tiết. Dù cùng là rác nhưng cách đổ lại khác nhau tùy theo loại, nên lúc đầu mình khá bối rối. Rác phải được phân thành 「燃えるごみ」「燃えないごみ」「資源ごみ」 v.v.","Ngày đổ rác cũng được quy định theo từng loại. Ở thị trấn mình sống, rác cháy được là thứ Hai và thứ Năm. Mọi người được dặn phải mang rác đến địa điểm đã quy định trước tám giờ sáng. Nếu phân loại sai hoặc sai giờ thì có khi rác sẽ không được thu. Vì vậy, trước khi đổ rác, việc kiểm tra lại một lần nữa là rất quan trọng.","Lúc đầu lần nào mình cũng phải tra cứu, thấy thật phiền phức. Nhưng khi quen dần, mình nhận ra việc này không khó đến vậy. Khi đã thành thói quen hằng ngày, bạn sẽ tự nhiên phân loại được mà không cần suy nghĩ.","Nhờ việc phân loại rác mà thị trấn lúc nào cũng sạch sẽ. Dù phiền, nhưng nghĩ rằng đây là quy tắc mà mọi người cùng giữ, mình lại có động lực tiếp tục."],"vocab":[{"w":"驚く","m":"ngạc nhiên, giật mình"},{"w":"細かい","m":"chi tiết, tỉ mỉ"},{"w":"種類","m":"loại, chủng loại"},{"w":"戸惑う","m":"bối rối, lúng túng"},{"w":"決める","m":"quyết định, quy định"},{"w":"確認","m":"xác nhận, kiểm tra lại"},{"w":"面倒","m":"phiền phức, rắc rối"},{"w":"慣れる","m":"quen, làm quen"},{"w":"習慣","m":"thói quen"},{"w":"保つ","m":"giữ, duy trì"}],"grammar":[{"t":"〜によって","note":"Nghĩa là「tùy theo ~」hoặc「dựa vào ~」. Ví dụ:「種類によって出し方が変わるため」"},{"t":"〜わけではない","note":"Nghĩa là「không có nghĩa là ~」, phủ định một phần. Ví dụ:「それほど難しいわけではないことが分かりました」"},{"t":"〜ようになる","note":"Diễn tả sự thay đổi về khả năng hoặc trạng thái,「trở nên có thể ~」. Ví dụ:「自然に分けられるようになります」"},{"t":"〜おかげで","note":"Diễn tả nhờ một nguyên nhân nào đó mà có kết quả tốt, 「nhờ có ~」. Ví dụ:「分別のおかげで」"}]},"a-n5-1-n2":{"title":"Một ngày của tôi","topic":"Đời sống hằng ngày","trans":["Mỗi sáng tôi dậy lúc sáu giờ, rửa mặt rồi mới ăn sáng, việc này đã thành thói quen. Bảy giờ rưỡi tôi ra khỏi nhà, đi tàu điện đến công ty để đi làm. Công việc bắt đầu từ chín giờ, nhưng để không bị muộn, tôi luôn cố gắng ra khỏi nhà sớm.","Bữa trưa tôi ăn ramen ở một quán gần công ty, hương vị rất ngon nên tôi cảm thấy rất hài lòng. Sáu giờ chiều tan làm, tôi về thẳng nhà và nấu bữa tối. Không phụ thuộc vào đồ ăn ngoài mà tự nấu, tôi thấy dù bận rộn vẫn giữ được nhịp sống của mình.","Buổi tối tôi học tiếng Nhật một chút rồi đi ngủ lúc mười một giờ. Dù không thể học lâu, tôi nghĩ việc duy trì mỗi ngày mới là điều có ý nghĩa. Cuối tuần hầu như không có việc nên tôi có nhiều thời gian rảnh hơn. Kéo theo đó, tôi đi dạo công viên với bạn bè, xem phim và cứ thế trải qua cuối tuần.","Mỗi ngày tuy bận rộn, nhưng không có nghĩa là không có niềm vui. Tôi thật sự cảm nhận được tiếng Nhật của mình đang giỏi lên từng chút một nên rất vui. Nếu cứ tiếp tục với nhịp độ này, chắc chắn tôi sẽ nói được tự nhiên hơn."],"vocab":["thói quen","đi làm (đi lại giữa nhà và nơi làm việc)","hài lòng, thỏa mãn","ăn ngoài, ăn ở ngoài","dựa vào, phụ thuộc","giữ, duy trì","sự thong thả, thời gian rảnh rỗi","trải qua, dành (thời gian)","cảm nhận thực sự"],"grammar":[{"t":"〜ことにしている","note":"Diễn tả thói quen hoặc nguyên tắc do bản thân quyết định và duy trì đều đặn. Ví dụ: 「十一時に寝ることにしています」."},{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Trong bài dùng 「それに伴って」 để nối với tình huống ở câu trước. Ví dụ: 「それに伴って、友達と公園を散歩したり、映画を見たりして過ごしています」."},{"t":"〜からといって〜とは限らない","note":"Nghĩa là \"không thể vì có lý do nào đó mà nhất định sẽ như vậy\", dùng để chỉnh lại suy nghĩ thông thường. Ví dụ: 「忙しいからといって楽しみがないとは限りません」."},{"t":"〜ず(に)","note":"Dạng văn viết của 「ない」, diễn tả không làm việc này mà làm việc khác, tương đương 「〜ないで」. Ví dụ: 「外食に頼らず自分で作ることで」."}]},"a-n5-1-n3":{"title":"Một ngày của tôi","topic":"Đời sống hằng ngày","trans":["Mỗi sáng tôi dậy lúc sáu giờ, rửa mặt rồi mới ăn sáng, tôi cố gắng giữ thói quen này. Bảy giờ rưỡi tôi ra khỏi nhà, đi tàu điện đến công ty nên buổi sáng không thể thong thả được. Công việc bắt đầu từ chín giờ nên tôi có thói quen ra khỏi nhà sớm để không bị muộn.","Buổi trưa tôi đến quán gần công ty ăn ramen. Quán ramen đó thật sự rất ngon, khiến buổi chiều tôi cũng có thêm động lực. Sáu giờ chiều tan làm, tôi về thẳng nhà nấu bữa tối.","Buổi tối tôi học tiếng Nhật một chút rồi đi ngủ lúc mười một giờ. Cuối tuần hầu như không có việc nên tôi có nhiều thời gian rảnh hơn. Tôi đi dạo công viên với bạn bè, xem phim và cứ thế trải qua cuối tuần.","Mỗi ngày tuy bận rộn, nhưng nhờ kiên trì học tập, tiếng Nhật của tôi đã giỏi lên từng chút một. Dù ngày nào cũng bận, tôi vẫn cảm nhận được sự tiến bộ của bản thân nên rất vui."],"vocab":[{"m":"đi làm, đi học (đi lại đều đặn; động từ 「通う」)"},{"m":"không bị muộn (động từ 「遅れる」)"},{"m":"sớm hơn một chút, sớm"},{"m":"tâm trạng, cảm giác"},{"m":"cố lên, nỗ lực (động từ 「頑張る」)"},{"m":"sự thong thả, thời gian rảnh rỗi"},{"m":"trải qua, dành (thời gian)"},{"m":"tiếp tục, duy trì"},{"m":"sự trưởng thành, tiến bộ"}],"grammar":[{"t":"〜ようにしている","note":"Diễn tả việc cố gắng duy trì một thói quen hoặc nỗ lực làm gì đó. Ví dụ: 「朝ごはんを食べるようにしています」"},{"t":"〜ことにしている","note":"Diễn tả thói quen do bản thân quyết định và duy trì đều đặn. Ví dụ: 「早めに出かけることにしています」"},{"t":"〜ため","note":"Diễn tả nguyên nhân, lý do, mang sắc thái văn viết hơn 「から」. Ví dụ: 「電車で会社へ通っているため、朝はあまりゆっくりできません」"},{"t":"〜によって","note":"Diễn tả phương tiện hoặc cách thức, nghĩa là \"bằng cách, thông qua\". Ví dụ: 「勉強を続けることによって、少しずつ日本語が上手になってきました」"}]},"a-n5-2-n2":{"title":"Bữa sáng ở Nhật","topic":"Văn hóa","trans":["Nhắc đến bữa sáng truyền thống của Nhật, thông thường là một bữa ăn kiểu Nhật xoay quanh cơm trắng và súp miso. Bữa sáng này thường có thêm cá nướng hoặc món trứng, và đặc điểm là dinh dưỡng cân bằng. Rong biển khô cũng được ưa chuộng từ xưa, có thể nói là món ăn kèm cơm không thể thiếu trên bàn ăn. Vì vừa đơn giản, tiện lợi lại đậm đà hương vị nên nó đã được nhiều gia đình yêu thích suốt một thời gian dài.","Tuy nhiên, những năm gần đây, cùng với sự thay đổi trong lối sống, số người ăn sáng bằng bánh mì và cà phê cũng ngày càng nhiều. Xu hướng này đặc biệt mạnh ở giới trẻ, và không ít trường hợp họ thích bữa sáng kiểu phương Tây. Dĩ nhiên, không phải người trẻ nào cũng chọn bánh mì, sở thích mỗi người một khác. Dù vậy, chắc chắn là các lựa chọn cho bữa sáng đã đa dạng hơn trước nhiều.","Vào những buổi sáng bận rộn, không có thời gian để nấu nướng, cũng có người chỉ ăn một cái cơm nắm cho xong. Để kịp giờ đi làm hay đi học, có lẽ đôi khi người ta cũng đành phải làm bữa sáng thật đơn giản. Phong cách bữa sáng ở Nhật đang đa dạng hóa như vậy, còn ở đất nước bạn thì mọi người ăn gì vào buổi sáng?","Bản thân tôi thì trong khi bữa sáng với bánh mì và cà phê đang được ưa chuộng, tôi vẫn thích cơm trắng và súp miso hơn. Bởi vì nếu ăn đầy đủ vào buổi sáng, cả cơ thể lẫn đầu óc đều tỉnh táo, và có thể trải qua một ngày thật khỏe khoắn. Tôi nghĩ bữa sáng không chỉ là một thói quen mà còn là khoảng thời gian quan trọng để điều chỉnh trạng thái cho cả ngày."],"vocab":["truyền thống","không thể thiếu","được yêu thích, quen thuộc","những năm gần đây","xu hướng","lựa chọn","sự dư dả, thong thả","đa dạng hóa","điều chỉnh, sắp xếp cho ổn","giải quyết cho xong, ăn cho xong"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「生活スタイルの変化に伴って、パンとコーヒーで朝食を済ませる人も増えています」"},{"t":"〜とは限らない","note":"Nghĩa là \"không hẳn là, không phải lúc nào cũng vậy\", dùng để phủ định cách nói quá khái quát. Ví dụ: 「若い人がみなパンを選ぶとは限らず、好みは人によってさまざまです」"},{"t":"〜ざるを得ない","note":"Diễn tả việc bị hoàn cảnh ép buộc nên đành phải làm. Ví dụ: 「朝食を簡単にせざるを得ない場合もあるのでしょう」"},{"t":"〜に対して","note":"Diễn tả sự đối lập, đặt hai việc cạnh nhau để so sánh. Ví dụ: 「パンとコーヒーの朝ごはんが人気であるのに対して、やはりごはんとみそしるが好きです」"}]},"a-n5-2-n3":{"title":"Bữa sáng ở Nhật","topic":"Văn hóa","trans":["Nhắc đến bữa sáng truyền thống của Nhật thì cơ bản là cơm trắng và súp miso. Nhiều người còn ăn kèm với cá nướng, trứng, rong biển khô, v.v., và bữa sáng này đã được yêu thích từ xa xưa.","Gần đây, số gia đình ăn sáng bằng bánh mì và cà phê cũng tăng lên. Đặc biệt trong giới trẻ, vì có thể ăn một cách nhanh gọn nên bữa sáng kiểu phương Tây rất được ưa chuộng.","Ngoài ra, buổi sáng bận rộn nên cũng có người chỉ ăn một cái cơm nắm rồi ra khỏi nhà. Vì dù không có thời gian, cơm nắm vẫn có thể vừa đi vừa ăn.","Tôi cũng thấy bữa sáng với bánh mì và cà phê vừa tiện vừa ngon, nhưng tôi vẫn thích cơm trắng và súp miso hơn. Ở đất nước của các bạn, bữa sáng như thế nào là phổ biến?","Nếu cố gắng ăn đầy đủ vào buổi sáng thì có thể trải qua cả ngày thật khỏe khoắn. Vì vậy, dù là ngày bận rộn, tôi cũng quyết định là sẽ ăn sáng."],"vocab":["truyền thống","cơ bản","kết hợp, phối hợp","yêu thích, thân thuộc","gia đình","nhanh gọn, đơn giản","kiểu phương Tây","phổ biến, thông thường","giải quyết cho xong, ăn cho xong","trải qua, sống qua"],"grammar":[{"t":"〜といえば","note":"Nghĩa là \"nhắc đến ~\", dùng để nêu ra một chủ đề. Ví dụ: 「日本の伝統的な朝ごはんといえば、ごはんとみそしるが基本です」"},{"t":"〜ため","note":"Diễn tả nguyên nhân, lý do. Ví dụ: 「手軽に食べられるため、洋風の朝ごはんが人気があります」"},{"t":"〜ようにする","note":"Diễn tả việc cố gắng hình thành một thói quen hoặc cố gắng làm gì đó. Ví dụ: 「朝にしっかり食べるようにすると、一日を元気に過ごせます」"},{"t":"〜ことにしている","note":"Diễn tả thói quen do chính mình quyết định và duy trì. Ví dụ: 「忙しい日でも朝ごはんを食べることにしています」"}]},"a-n5-3-n2":{"title":"Bức ảnh gia đình","topic":"Gia đình","trans":["Đây là bức ảnh chụp gia đình mình, một thứ quan trọng mà lần nào nhìn cũng khiến lòng mình ấm áp. Trong ảnh có tất cả năm người và một chú chó, chỉ nhìn ảnh thôi cũng cảm nhận được đầy đủ không khí náo nhiệt. Đứng ở giữa là bố mẹ mình, bố là nhân viên công ty, còn mẹ là giáo viên dạy học sinh.","Người ở bên phải là anh trai, đang là sinh viên đại học, và về tài đá bóng thì anh nổi bật hẳn trong gia đình. Bóng đá của anh đã vượt xa mức chỉ đơn thuần là thích, trình độ ấy khiến cả những người xung quanh cũng không thể không công nhận. Em bé đứng bên trái là em gái, năm nay chín tuổi, thích vẽ hơn bất cứ thứ gì. Anh và em tuy thích những thứ khác nhau, nhưng mình thấy hai người rất giống nhau ở chỗ đều có thể say mê hết mình với một điều gì đó.","Nếu phải nêu một đặc điểm của nhà mình, thì có lẽ là cả nhà ai cũng yêu chó từ tận đáy lòng. Chú chó ở phía trước bức ảnh là chó nhà mình tên 「マロ」, một thành viên không thể thiếu của gia đình. Vào ngày nghỉ, cả nhà cùng ra công viên chụp ảnh, và từ lúc nào không hay đã thành thói quen của nhà mình. Có lẽ cùng với thời gian ở bên chú chó, số lượng ảnh cũng tự nhiên tăng lên.","Hiện tại mình sống xa gia đình nên không thể ngày nào cũng gặp mặt như trước. Dù vậy, mỗi tháng mình vẫn gọi điện một lần, chỉ nghe giọng thôi là đã thấy yên tâm. Không phải cứ xa nhau về khoảng cách thì lòng người cũng sẽ xa theo. Với mình, gia đình mãi mãi là báu vật vô giá, không gì thay thế được."],"vocab":["không khí, bầu không khí","tài, trình độ, năng lực","vượt qua, vượt quá","xung quanh (những người xung quanh)","say mê, mải mê","không thể thiếu","thói quen","xa cách, rời xa","không gì thay thế được, vô giá"],"grammar":[{"t":"〜ざるを得ない","note":"Nghĩa là「buộc phải…, đành phải…」, mang sắc thái dù không muốn cũng không thể phủ nhận. Ví dụ:「その腕前は周囲も認めざるを得ないほどです」。"},{"t":"〜に伴って","note":"Nghĩa là「cùng với…, theo đà…」, vế trước thay đổi thì vế sau cũng thay đổi theo. Ví dụ:「犬と一緒に過ごす時間に伴って、写真の枚数も自然と増えていったのかもしれません」。"},{"t":"〜わけにはいかない","note":"Nghĩa là「không thể…」 vì lẽ phải hoặc hoàn cảnh không cho phép. Ví dụ:「以前のように毎日顔を合わせるわけにはいきません」。"},{"t":"〜とは限らない","note":"Nghĩa là「không hẳn là…, chưa chắc…」, dùng để phủ định cách nói tuyệt đối. Ví dụ:「気持ちまで遠くなるとは限りません」。"}]},"a-n5-3-n3":{"title":"Bức ảnh gia đình","topic":"Gia đình","trans":["Đây là ảnh gia đình mình, trong ảnh có tất cả năm người, và là một tấm mình rất thích. Đứng ở giữa ảnh là bố, người đi làm công ty, và mẹ, người làm giáo viên.","Người đứng bên phải là anh trai, hiện đang là sinh viên đại học. Anh trai rất giỏi đá bóng, mình cũng thầm tự hào về điều đó. Em bé đứng bên trái là em gái, mới chín tuổi. Em gái thích vẽ, rảnh là hay vẽ lắm.","Nhà mình giống nhau ở điểm ai cũng rất thích chó. Chú chó ở phía trước bức ảnh là chó nhà mình nuôi, tên 「マロ」. Vào ngày nghỉ, cả nhà quyết định cùng ra công viên và chụp ảnh.","Bây giờ mình sống xa nhà nên không thể ngày nào cũng gặp. Dù vậy, mỗi tháng mình đều cố gắng gọi điện nói chuyện một lần. Với mình, gia đình là báu vật quan trọng hơn bất cứ thứ gì."],"vocab":["được chụp vào (ảnh), hiện ra trong ảnh","nhân viên công ty","giỏi, sở trường","niềm tự hào","nuôi (động vật)","ra ngoài, đi chơi","xa cách, rời xa","báu vật","thích, ưng ý"],"grammar":[{"t":"〜として","note":"Chỉ tư cách, vai trò: 「với tư cách là…」. Ví dụ:「会社員として働いている父」nghĩa là bố làm việc với tư cách nhân viên công ty."},{"t":"〜ため(nguyên nhân)","note":"Chỉ nguyên nhân, lý do, văn viết trang trọng hơn「から」. Ví dụ:「今は離れて住んでいるため、毎日会うことはできません」。"},{"t":"〜ことにしている","note":"Chỉ việc tự quyết định rồi duy trì thành thói quen, kiểu「luôn làm như vậy」. Ví dụ:「写真を撮ることにしています」。"},{"t":"〜ようにしている","note":"Chỉ việc cố gắng duy trì làm một điều gì đó đều đặn. Ví dụ:「月に一度は電話で話すようにしています」。"}]},"a-n5-4-n2":{"title":"Cửa hàng tiện lợi – chỗ dựa của cuộc sống","topic":"Cuộc sống","trans":["Tôi gần như ngày nào cũng ghé cửa hàng tiện lợi, vì nó ở ngay cạnh công ty nên ghé vào chẳng mất công gì, rất tiện. Buổi sáng tôi thường mua một cái onigiri (cơm nắm) và một ly cà phê, tính ra tổng cộng chỉ khoảng ba trăm yên, nên túi tiền gia đình cũng đỡ áp lực. Giải quyết được bữa sáng nhẹ nhàng với mức giá không đắt là một điểm hấp dẫn mà nhân viên công sở bận rộn không thể bỏ qua.","Vai trò của cửa hàng tiện lợi không chỉ dừng ở việc mua sắm, bạn còn có thể thanh toán các loại phí dịch vụ công cộng như tiền điện, tiền nước. Bạn cũng có thể gửi bưu kiện hay rút tiền, rất hữu ích với những người không có thời gian đi đến nơi khác. Nhờ các dịch vụ này được gom về một chỗ, những việc vặt trong cuộc sống có thể giải quyết xong trong thời gian ngắn.","Buổi tối đói bụng, tôi thường mua một phần oden nóng hổi mang về. Oden đặc biệt được ưa chuộng vào mùa đông, và khi trời càng lạnh thì dường như số khách đến mua cũng càng đông. Gần đây, biển chỉ dẫn bằng ngoại ngữ cũng nhiều lên, một môi trường thân thiện với người nước ngoài đang dần hình thành. Ngay cả người đọc tiếng Nhật chưa tốt cũng dễ tìm thứ mình cần hơn, đây là một thay đổi lớn.","Cửa hàng tiện lợi tuy là một cửa hàng nhỏ nhưng lại có thể giải quyết một lượt rất nhiều việc khác nhau. Chính vì hàng hóa và dịch vụ phong phú, đầy đủ nên mới có nhiều người ghé qua gần như mỗi ngày như vậy. Ngày nay, với vai trò là chỗ dựa của cuộc sống ở Nhật, có thể nói cửa hàng tiện lợi đã trở thành thứ không thể thiếu."],"vocab":["đi lại thường xuyên, ghé đều đặn","tiện đường ghé qua","nằm trong (mức tiền, phạm vi)…","chi tiêu gia đình, ngân sách gia đình","phí dịch vụ công cộng (điện, nước, gas…)","chi trả, thanh toán","đầy đủ, phong phú","biển chỉ dẫn","được chuẩn bị đầy đủ, chỉnh chu","mua (văn viết, trang trọng)"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ:「寒さが厳しくなるに伴って、買い求める客も増えていくようだ」"},{"t":"〜に対して","note":"Diễn tả đối tượng hướng tới, nghĩa là \"đối với…\". Ví dụ:「外国から来た人に対しても親切な環境が整いつつある」"},{"t":"〜にもかかわらず","note":"Diễn tả điều trái với dự đoán, nghĩa là \"mặc dù… nhưng…\". Ví dụ:「コンビニは小さな店であるにもかかわらず、実にさまざまな用事をまとめて済ませることができる」"},{"t":"〜ざるを得ない","note":"Diễn tả việc về tình về lý thì đành phải, buộc phải thừa nhận…. Ví dụ:「なくてはならないものになっていると言わざるを得ない」"}]},"a-n5-4-n3":{"title":"Mua sắm ở cửa hàng tiện lợi","topic":"Cuộc sống","trans":["Tôi gần như ngày nào cũng ghé cửa hàng tiện lợi đó. Vì nó nằm ngay cạnh công ty nên dù không có thời gian cũng có thể thoải mái ghé qua, rất tiện.","Buổi sáng tôi có thói quen mua một cái onigiri (cơm nắm) và một ly cà phê. Tổng cộng khoảng ba trăm yên, nên làm bữa sáng thì không hẳn là đắt.","Ở cửa hàng tiện lợi, bạn cũng có thể thanh toán tiền điện, tiền nước, v.v. Hơn nữa còn có thể gửi bưu kiện, rút tiền nên rất hữu ích trong cuộc sống. Với những người không có thời gian đến ngân hàng hay bưu điện, đây là một sự giúp đỡ lớn.","Buổi tối đói bụng, tôi mua một phần oden nóng hổi. Oden đặc biệt được ưa chuộng vào mùa đông, những ngày trời lạnh có rất nhiều người đến mua. Gần đây biển chỉ dẫn bằng ngoại ngữ cũng nhiều hơn, nên người nước ngoài cũng dễ sử dụng hơn. Tuy chỉ là một cửa hàng nhỏ nhưng làm được rất nhiều việc, nên tôi nghĩ nó là một sự tồn tại không thể thiếu trong cuộc sống ở Nhật."],"vocab":["đến, ghé (đặc biệt đi đến)","thoải mái, không câu nệ","đặc biệt, riêng biệt","thanh toán, chi trả","giao hàng tận nhà, chuyển phát","rút (tiền từ tài khoản)","sự giúp đỡ","được ưa chuộng","hướng dẫn, chỉ dẫn, giới thiệu","không thể thiếu"],"grammar":[{"t":"〜ため","note":"Diễn tả nguyên nhân, lý do, mang sắc thái trang trọng hơn một chút so với「ので」. Ví dụ:「会社のとなりにあるため、時間がないときでも気軽に寄れて」"},{"t":"〜ことにしている","note":"Diễn tả thói quen do bản thân quyết định và duy trì đều đặn. Ví dụ:「朝はおにぎりとコーヒーを買うことにしています」"},{"t":"〜わけではない","note":"Nghĩa là \"không phải là…\", phủ định một phần, tránh bị hiểu nhầm. Ví dụ:「朝ごはんとして特別高いわけではありません」"},{"t":"〜ものの","note":"Nghĩa là \"tuy… nhưng…\", hai vế tạo nên sự đối lập. Ví dụ:「小さな店ではあるものの、いろいろなことができるので」"}]},"a-n5-5-n2":{"title":"Thị trấn nơi tôi sống","topic":"Cuộc sống","trans":["Tôi sống ở một thị trấn nhỏ gần biển, có lẽ cũng vì gần biển nên không khí rất trong lành. Thị trấn tuy không có tòa nhà lớn nào, nhưng bưu điện, bệnh viện, siêu thị… những cơ sở thiết yếu cho cuộc sống thì về cơ bản đều đầy đủ. So với đô thị hoa lệ thì có thể trông giản dị, nhưng tôi cảm thấy việc những thứ cần thiết luôn ở ngay bên cạnh đã mang lại cảm giác yên tâm cho cuộc sống mỗi ngày.","Từ ga đi bộ về nhà mất khoảng mười phút, nên gần như không gặp khó khăn gì khi di chuyển. Giữa đường có một con sông chảy qua, không qua cầu thì không về được đến nhà. Dọc bờ sông có những hàng cây anh đào, đến mùa xuân lại nở hoa rực rỡ. Vào mùa đó, rất nhiều người đến để ngắm hoa, và bờ sông vốn yên tĩnh ngày thường bỗng chốc trở nên náo nhiệt.","Gần đó còn có một ngôi chùa cổ, bước vào khuôn viên chùa, lòng tôi lạ thay lại thấy bình yên. Khoảng thời gian trôi qua trong sự tĩnh lặng là điều quý giá, giúp tôi quên đi nhịp sống thường ngày bận rộn. Mặt khác, nói về chuyện mua sắm thì phải thừa nhận là hơi bất tiện. Vì không phải thứ gì mình muốn cũng mua được ở gần nhà.","Dù vậy, người dân trong thị trấn ai cũng thân thiện, và bầu không khí dễ sống lan tỏa khắp thị trấn. Tôi nghĩ sự ấm áp của con người đủ để bù đắp cho sự bất tiện, và đó chính là nét hấp dẫn của thị trấn này. Vì những lý do đó, tôi rất yêu thị trấn này và muốn tiếp tục sống ở đây mãi mãi về sau."],"vocab":["không thể thiếu","cơ sở, công trình","về cơ bản, đại khái đầy đủ","khoảng cách","dọc bờ sông, ven sông","tuyệt đẹp, rực rỡ","mục đích, nhằm để…","khuôn viên (chùa, đền)","quý giá","bù đắp, bổ sung"],"grammar":[{"t":"〜こそ〜が","note":"Nhấn mạnh kiểu \"đúng là… nhưng…\": thừa nhận một điểm rồi chuyển sang ý đối lập. Ví dụ: 「大きなビルこそありませんが、郵便局や病院、スーパーなど、暮らしに欠かせない施設は一通りそろっています」"},{"t":"〜に比べれば","note":"Nếu so với…, dùng để nêu đối tượng so sánh. Ví dụ: 「華やかな都会に比べれば地味かもしれませんが、必要なものが身近にあることは、日々の安心感につながっていると感じます」"},{"t":"〜ざるを得ない","note":"Không thể không…, đành phải…, diễn tả việc không có lựa chọn nào khác. Ví dụ: 「買い物に関しては少し不便だと言わざるを得ません」"},{"t":"〜とは限らない","note":"Không hẳn là…, chưa chắc…, dùng để phủ định cách nói tuyệt đối. Ví dụ: 「欲しいものがすべて近所で手に入るとは限らないからです」"}]},"a-n5-5-n3":{"title":"Thị trấn của tôi","topic":"Cuộc sống","trans":["Tôi sống ở một thị trấn nhỏ gần biển, và rất thích việc không khí ở đây trong lành. Nhờ gần biển nên tôi cảm thấy mỗi ngày đều trôi qua thật dễ chịu. Thị trấn không có tòa nhà lớn, nhưng bưu điện, bệnh viện, siêu thị… những thứ cần thiết đều đầy đủ.","Đường từ ga về nhà tuy ngắn, nhưng tôi thích vừa đi bộ vừa ngắm cảnh sông và cầu. Từ ga đi bộ về nhà mất khoảng mười phút, giữa đường có một con sông nên tôi qua cầu để về nhà. Đến mùa xuân, hoa anh đào bên sông nở rất đẹp, và nhiều người đến để ngắm hoa. Gần đó còn có một ngôi chùa cổ, khi trải qua khoảng thời gian yên tĩnh ở đó, lòng tôi tự nhiên bình yên trở lại.","Đôi khi tôi cũng thấy mua sắm hơi bất tiện, nhưng đó không phải vấn đề lớn. Người trong thị trấn ai cũng thân thiện, nên tôi nghĩ đây là một nơi rất dễ sống.","Tôi rất yêu thị trấn này, nên đã quyết định sẽ tiếp tục sống ở đây mãi về sau. Vì tôi nghĩ rằng dù không có sự tiện lợi như thành phố lớn, chỉ cần có lòng tốt của mọi người và thiên nhiên là đủ rồi."],"vocab":["không khí","bưu điện","cần thiết","giữa đường","cây cầu","đến thăm, ghé đến","bình tĩnh lại, yên lòng","bất tiện","thân thiện, tử tế","sống, sinh sống"],"grammar":[{"t":"〜ため(に)","note":"Diễn tả nguyên nhân hoặc mục đích. 「川があるため」 là nguyên nhân, 「花見のために」 là mục đích. Mang tính văn viết, trang trọng hơn 「〜から」."},{"t":"〜ように","note":"Diễn tả \"để đạt đến trạng thái nào đó\" hoặc \"giống như…\". Ví dụ: 「毎日気持ちよく過ごせるように感じています」, ở đây đi sau thể khả năng để miêu tả trạng thái mà mình cảm nhận được."},{"t":"〜わけではない","note":"Diễn tả \"không có nghĩa là…\", phủ định một phần. Ví dụ: 「大きな問題というわけではありません」."},{"t":"〜ことにする","note":"Diễn tả việc người nói tự quyết định làm gì đó. Ví dụ: 「ここで暮らすことにしています」, dùng 「ている」 để thể hiện quyết định đó vẫn đang được giữ."}]},"a-n5-6-n2":{"title":"Sở thích của tôi là nhiếp ảnh","topic":"Sở thích","trans":["Sở thích của tôi là chụp ảnh. Vào ngày nghỉ, cầm máy ảnh dạo quanh phố phường đã trở thành niềm vui lớn nhất của tôi. Tôi không có điểm đến nào định sẵn, chỉ thong thả vừa đi vừa hướng ống kính về phía những thứ lọt vào mắt mình. Tôi chủ yếu chụp hoa và chim, và tôi cũng thấy thú vị ở chỗ đối tượng chụp thay đổi theo sự chuyển mùa.","Niềm vui khi chụp được một bức ảnh đúng như ý rất lớn, và tôi nghĩ chính vì có niềm vui ấy nên tôi mới không thể bỏ sở thích này. Dĩ nhiên, tùy vào bố cục và cách tận dụng ánh sáng mà ngay cả cùng một nơi, ấn tượng của bức ảnh cũng có thể hoàn toàn khác nhau. Khi chụp được bức ảnh khiến chính mình cũng hài lòng, tôi thậm chí quên cả thời gian và cứ xem đi xem lại trên màn hình. Bức ảnh càng đẹp thì càng muốn cho ai đó xem, đó có lẽ là điều rất tự nhiên.","Vì vậy, thỉnh thoảng tôi gửi ảnh cho bạn bè để nghe họ nhận xét. Bạn bè lúc nào cũng khen \"Bạn chụp đẹp quá!\", và điều đó trở thành động lực cho lần chụp tiếp theo. Nhờ cho người khác xem, đôi khi tôi còn nhận ra những điểm hay của bức ảnh mà bản thân chưa từng để ý. Nói ngược lại, nếu không có cơ hội cho mọi người xem thì có lẽ tôi đã không thể duy trì sở thích này nhiệt tình đến vậy.","Gần đây, tôi bắt đầu muốn có một chiếc máy ảnh mới có hiệu năng tốt hơn. Tuy nhiên, máy ảnh chẳng hề là món đồ rẻ, nên hiện giờ tôi buộc phải từ bỏ ý định mua ngay. Vì thế, bây giờ tôi vừa dành dụm tiền từng chút một, vừa háo hức chờ đến ngày có thể mua được nó."],"vocab":["tùy hứng, thích đâu đi đó","lọt vào mắt, thu hút sự chú ý","sự chuyển đổi, sự thay đổi theo thời gian","đối tượng được chụp","bố cục","mức độ, cách điều chỉnh, tình trạng","hài lòng","động lực, sự khích lệ","cảm tưởng, nhận xét","hiệu năng, tính năng"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi việc này thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「季節の移り変わりに伴って被写体が変わっていく」"},{"t":"〜ざるを得ない","note":"Diễn tả ngoài cách này ra không còn lựa chọn nào khác, buộc phải làm. Ví dụ: 「今はすぐに買うのをあきらめざるを得ない」"},{"t":"〜からこそ","note":"Nhấn mạnh chính vì lý do này mà mới có kết quả ở vế sau. Ví dụ: 「それがあるからこそ、この趣味をやめられない」"},{"t":"〜によって","note":"Diễn tả tùy theo điều kiện khác nhau mà kết quả sẽ khác nhau. Ví dụ: 「構図や光の加減によって、同じ場所でも写真の印象はまったく違ったものになってしまう」"}]},"a-n5-6-n3":{"title":"Sở thích của tôi là nhiếp ảnh","topic":"Sở thích","trans":["Sở thích của tôi là chụp ảnh. Vào ngày nghỉ, tôi cố gắng mang máy ảnh ra ngoài. Vừa thong thả đi dạo trong phố vừa tìm kiếm những thứ khiến mình để tâm là một trong những niềm vui của tôi. Tôi đặc biệt hay chụp hoa và chim, và việc đuổi theo những thứ chuyển động hóa ra lại vất vả hơn tôi tưởng.","Khi chụp được bức ảnh đẹp đúng như mình nghĩ, tôi thật sự rất vui. Vì thế, chụp lại nhiều lần cũng là chuyện không hiếm. Những bức ảnh đã chụp, thỉnh thoảng tôi lại gửi cho bạn bè. Khi bạn bè nói \"Bạn chụp đẹp quá!\", tôi lại muốn chụp tiếp.","Tôi muốn có một chiếc máy ảnh mới, nhưng vì giá khá cao nên không phải muốn mua là mua được ngay. Vì vậy, bây giờ tôi đang để dành tiền cho chiếc máy ảnh mới. Tôi nghĩ khoảng thời gian chờ đợi thứ mình muốn cũng là một niềm vui của sở thích."],"vocab":["sở thích","để tâm, thấy hứng thú","tìm kiếm","đuổi theo, theo đuổi","bất ngờ, ngoài dự đoán","chụp lại","không ít, thường xuyên","giá cả","để dành, tích lũy (tiền)","tâm trạng, cảm giác"],"grammar":[{"t":"〜ようにしている","note":"Diễn tả thói quen mà bạn luôn cố gắng duy trì hoặc cố gắng làm thường xuyên. Ví dụ: 「休みの日にはカメラを持って出かけるようにしています」"},{"t":"〜ことにしている","note":"Diễn tả quy tắc hoặc cách làm do bản thân tự quyết định và duy trì. Ví dụ: 「撮った写真は、ときどき友達に送ることにしています」"},{"t":"〜ため(原因)","note":"Dùng để nêu nguyên nhân, lý do, mang sắc thái văn viết hơn 「から」. Ví dụ: 「値段が高いため、すぐに買えるわけではありません」"},{"t":"〜わけではない","note":"Phủ định một phần, nghĩa là \"không phải là...\". Ví dụ: 「値段が高いため、すぐに買えるわけではありません」"}]},"a-n5-7-n2":{"title":"Gửi bưu kiện ở bưu điện","topic":"Cuộc sống","trans":["Hôm nay, để gửi bưu kiện sang Đài Loan, mình quyết định ghé bưu điện một chuyến. Ở quầy, mình nói「これを台湾までお願いします」thì nhân viên hỏi mình về cách gửi. Gửi bưu kiện có hai cách là đường biển và đường hàng không, và mình phải chọn một trong hai.","Nhân viên hỏi「船便ですか、航空便ですか」, mình so sánh cước phí với số ngày rồi hơi phân vân. Đường biển thì rẻ nhưng ngược lại phải mất khoảng một tháng mới đến nơi. Còn đường hàng không thì đến nhanh, trong khi cước phí được tính cao hơn. Nói cách khác, muốn rẻ thì mất thời gian, muốn nhanh thì tốn tiền hơn.","Mình nghĩ đành phải ưu tiên thời gian nên chọn đường hàng không. Tiếp theo, mình điền tên và địa chỉ vào phiếu, điền xong thì trả tiền. Mình hỏi bao giờ bưu kiện đến thì được cho biết khoảng một tuần. Tuy nhiên, đó chỉ là thời gian tham khảo, không phải lúc nào cũng chắc chắn đến đúng số ngày đó.","Trên đường về, mình ghé cửa hàng tiện lợi, mua tem và gửi luôn cả bưu thiếp. Không chỉ bưu điện mà cửa hàng tiện lợi cũng làm được việc này, thật tiện cho những người bận rộn. Nghe nói gửi hàng ra nước ngoài thì có vẻ khó, nhưng chỉ cần biết các bước thì hóa ra lại khá đơn giản."],"vocab":["quầy, cửa sổ giao dịch","gửi đường biển","gửi đường hàng không","cước phí, chi phí","đến nơi, được gửi tới","ưu tiên","phiếu, mẫu giấy","địa chỉ","mốc tham khảo, ước chừng","các bước, quy trình"],"grammar":[{"t":"〜反面","note":"Diễn tả một việc có hai mặt trái ngược nhau cùng lúc. Ví dụ:「船便は料金が安い反面、届くまでに一か月ほどかかります」"},{"t":"〜に対して","note":"Dùng để đối chiếu hai sự vật. Ví dụ:「航空便は早く届くのに対して、料金は高めに設定されています」"},{"t":"〜ざるを得ない","note":"Diễn tả ngoài cách này ra không còn lựa chọn nào khác, đành phải làm. Ví dụ:「私は時間を優先せざるを得ないと考え、航空便を選びました」"},{"t":"〜とは限らない","note":"Diễn tả không phải lúc nào cũng vậy, cũng có ngoại lệ. Ví dụ:「必ずその日数で届くとは限りません」"}]},"a-n5-7-n3":{"title":"Gửi bưu kiện ở bưu điện","topic":"Cuộc sống","trans":["Hôm nay mình quyết định mang bưu kiện cần gửi sang Đài Loan đến bưu điện. Ở quầy, mình nói「これを台湾までお願いします」thì nhân viên đã hỗ trợ rất nhiệt tình. Vì được hỏi「船便ですか、航空便ですか」nên mình phải chọn cách gửi.","Đường biển có cước rẻ nên là cách hay cho những ai muốn tiết kiệm tiền. Tuy nhiên, không phải đường biển không tốt, mà nghe nói phải mất khoảng một tháng mới đến nơi. Mặt khác, đường hàng không thì đến nhanh, nhưng bù lại cước phí cao hơn. Cách chọn sẽ thay đổi tùy việc bạn coi trọng giá rẻ hay tốc độ hơn.","Mình nghĩ đắt hơn một chút nhưng nhanh thì tốt hơn, nên chọn đường hàng không. Mình viết tên và địa chỉ vào phiếu rồi trả cước phí. Khi mình hỏi「いつ届きますか」thì được cho biết khoảng một tuần.","Trên đường về, mình quyết định ghé cửa hàng tiện lợi để mua tem cần thiết. Rồi mình dán chiếc tem vừa mua lên và gửi luôn cả bưu thiếp."],"vocab":["quầy, cửa sổ giao dịch","người phụ trách, nhân viên","gửi đường biển","gửi đường hàng không","cước phí, chi phí","tiết kiệm","phiếu, mẫu giấy","địa chỉ","đến nơi, được gửi tới","tem thư"],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì. Ví dụ:「今日は台湾へ送る荷物を持って、郵便局へ行くことにしました」"},{"t":"〜ため","note":"Diễn tả nguyên nhân, lý do, trang trọng hơn「から」. Ví dụ:「船便は料金が安いため、お金を節約したい人にはいい方法です」"},{"t":"〜わけではない","note":"Diễn tả \"không phải là...\", phủ định một phần. Ví dụ:「船便が悪いわけではなく、届くまでに一か月ぐらいかかるそうです」"},{"t":"〜によって","note":"Diễn tả \"tùy theo, phụ thuộc vào...\", kết quả thay đổi theo điều kiện. Ví dụ:「安さと早さのどちらを大切にするかによって、選ぶ方法は変わります」"}]},"a-n5-8-n2":{"title":"Mở tài khoản ngân hàng","topic":"Cuộc sống","trans":["Hôm nay, mình đến ngân hàng để mở tài khoản, thứ không thể thiếu khi bắt đầu cuộc sống ở Nhật. Nhân viên phụ trách ở quầy nói: 「在留カードと印鑑をお願いします」 (Cho tôi xin thẻ cư trú và con dấu), nên mình lấy chúng ra từ trong túi. Khi người nước ngoài mở tài khoản, nếu không có giấy tờ chứng minh nhân thân thì không thể tiến hành thủ tục.","Tiếp theo, mình phải điền họ tên, địa chỉ và số điện thoại vào mẫu đơn. Chữ Hán rất khó, mình nghĩ là không thể viết sai được nên đã dành thời gian viết cẩn thận từng chữ một. Với người không phải người bản ngữ tiếng Nhật, việc điền vào giấy tờ chính thức tốn nhiều sức tập trung hơn tưởng tượng. Dù có hàng loạt chữ Hán chưa quen, chỉ cần không vội vàng và bình tĩnh viết thì có thể tránh được sai sót.","Điền xong, nhân viên giải thích chi tiết về thẻ ATM. Họ nói: 「キャッシュカードは二週間ぐらいで自宅に届きます」 (Thẻ ATM sẽ được gửi đến nhà bạn trong khoảng hai tuần), nên mình biết là không dùng được ngay. Mặt khác, sổ tài khoản thì nhận được ngay trong ngày. Vì đây là cuốn sổ đầu tiên mình cầm trên tay ở Nhật, nên dù chỉ là một cuốn sổ nhỏ, mình vẫn cảm nhận được một sức nặng đặc biệt.","Suốt quá trình làm thủ tục mình luôn căng thẳng, nhưng cuối cùng vẫn hoàn thành chỉ bằng tiếng Nhật. Sống ở nước ngoài, có không ít tình huống buộc phải bỏ cuộc vì rào cản ngôn ngữ. Chính vì vậy, trải nghiệm lần này mang lại cho mình rất nhiều tự tin, và nỗi lo về cuộc sống sắp tới cũng vơi đi phần nào."],"vocab":["tài khoản (ngân hàng)","không thể thiếu","quầy giao dịch, cửa tiếp nhận","nhân viên phụ trách","điền, ghi vào","tiếng mẹ đẻ","tốn tâm sức, phải tập trung cao độ","sổ tài khoản (sổ ngân hàng)","căng thẳng, hồi hộp"],"grammar":[{"t":"〜わけにはいかない","note":"Diễn tả không thể làm việc gì đó vì lập trường hay lẽ thường. Ví dụ: 「書き間違えるわけにはいかないと思ったので」 nghĩa là nghĩ rằng không thể viết sai."},{"t":"〜にとって","note":"Diễn tả từ lập trường của ai đó. Ví dụ: 「日本語を母語としない人にとって」 nghĩa là đối với người không phải người bản ngữ tiếng Nhật."},{"t":"〜にもかかわらず","note":"Diễn tả dù vế trước như vậy, vế sau lại có kết quả trái ngược. Ví dụ: 「小さな冊子にもかかわらず」 nghĩa là dù chỉ là một cuốn sổ nhỏ."},{"t":"〜ざるを得ない","note":"Diễn tả việc buộc phải làm, không có lựa chọn nào khác. Ví dụ: 「諦めざるを得ない場面も少なくありません」 nghĩa là không ít tình huống buộc phải từ bỏ."}]},"a-n5-8-n3":{"title":"Mở tài khoản ngân hàng","topic":"Cuộc sống","trans":["Hôm nay, mình đến một ngân hàng gần nhà để mở tài khoản ngân hàng cần cho cuộc sống mới. Nhân viên ở quầy bảo mình xuất trình thẻ cư trú và con dấu, nên mình đưa ra ngay.","Tiếp theo, họ bảo mình viết họ tên, địa chỉ và số điện thoại vào mẫu đơn. Vì chữ Hán khó và mình không tự tin lắm, nên mình viết thật chậm để không viết sai. Mình cảm thấy với người nước ngoài, thủ tục phải viết bằng chữ Hán vất vả hơn mình tưởng.","Họ cho mình biết thẻ ATM sẽ được gửi đến nhà trong khoảng hai tuần. Mặt khác, sổ tài khoản thì nhận được ngay trong ngày. Vì đây là cuốn sổ đầu tiên mình có từ khi đến Nhật, nên mình thấy nó thật đặc biệt.","Trong lúc làm thủ tục mình hơi căng thẳng, nhưng điều vui nhất là mình đã làm được tất cả chỉ bằng tiếng Nhật. Nhờ trải nghiệm này, mình đã có thêm chút tự tin về cuộc sống ở Nhật."],"vocab":["tài khoản (ngân hàng)","quầy giao dịch, cửa tiếp nhận","thẻ cư trú","con dấu","mẫu đơn, tờ giấy","thủ tục","sổ tài khoản (sổ ngân hàng)","được gửi đến, đến nơi","căng thẳng, hồi hộp","tự tin"],"grammar":[{"t":"〜ように言われる","note":"Diễn tả việc bị yêu cầu hoặc được chỉ dẫn làm gì đó. Ví dụ trong bài: 「用紙に名前と住所と電話番号を書くように言われました」"},{"t":"〜ため(に)","note":"Diễn tả nguyên nhân, lý do, mang tính văn viết hơn 「ので」. Ví dụ trong bài: 「漢字が難しくて自信がなかったため、間違えないようにゆっくり書きました」"},{"t":"〜ことになっている","note":"Diễn tả quy định hoặc sự sắp xếp, dự định có sẵn. Ví dụ trong bài: 「キャッシュカードは二週間ぐらいで家に届くことになっていると教えてもらいました」"},{"t":"〜によって","note":"Diễn tả nguyên nhân hoặc phương tiện, nghĩa là \"nhờ, do, thông qua\". Ví dụ trong bài: 「この経験によって、日本での生活に少し自信が持てるようになりました」"}]},"a-n5-9-n2":{"title":"Một ngày ở công viên","topic":"Cuộc sống","trans":["Thứ Bảy thời tiết rất đẹp, đúng là ngày lý tưởng để đi chơi, nên tôi đã hẹn với bạn bè đi công viên. Địa điểm gặp nhau là nhà ga, giờ hẹn là chín giờ sáng. Đúng như hẹn, chúng tôi gặp nhau ở nhà ga lúc chín giờ sáng rồi cùng đi đến công viên.","Thật ra từ tối hôm trước tôi đã chuẩn bị sẵn hộp cơm bento, bên trong có trứng cuộn, cơm nắm và rau. Tôi làm dư thêm một chút phần cho bạn vì nghĩ rằng ăn cùng nhau sẽ vui hơn. Chúng tôi đạp xe đến công viên, dọc đường có rất nhiều cây anh đào xếp thành hàng. Gió thổi rất dễ chịu, vừa đạp xe tôi vừa cảm nhận rõ sự chuyển mùa trên làn da.","Đến công viên, chúng tôi ngồi trên ghế dài ăn cơm hộp. Người ta thường nói ăn ngoài trời thì món ăn càng ngon hơn, và lần này đúng là rất ngon thật. Bạn tôi cũng khen \"ngon quá\", nên tôi cảm thấy công làm món này thật xứng đáng. Ăn xong, chúng tôi chơi cầu lông và chụp ảnh.","Nhìn quanh, tôi ấn tượng với vẻ mặt vui vẻ của mọi người. Lúc về đến nhà vào buổi chiều tối, tuy hơi mệt nhưng lòng tôi rất mãn nguyện. Dù vậy, nghĩ lại thì đó thật sự là một ngày đầy đủ và vui vẻ. Tuần sau tôi cũng muốn đến công viên nữa, nhưng không phải lúc nào thời tiết cũng đẹp như vậy."],"vocab":["được ưu đãi, may mắn có được","tuyệt vời, tốt nhất","hẹn gặp nhau","chuẩn bị","nhồi, đóng gói vào","dễ chịu, thoải mái","nổi bật hơn, ngon hơn","giá trị, công sức đáng giá","gây ấn tượng","đầy đủ, trọn vẹn"],"grammar":[{"t":"〜ものの","note":"Diễn tả \"tuy... nhưng...\", hai vế đối lập nhau. Ví dụ: 「少し疲れたものの、気持ちは満ち足りていた」"},{"t":"〜甲斐があった","note":"Diễn tả công sức bỏ ra đã được đền đáp, rất xứng đáng. Ví dụ: 「作った甲斐があったと感じた」"},{"t":"〜とはいえ","note":"Nghĩa là \"tuy nói vậy\", nối tiếp ý trước rồi đưa ra một cách nhìn khác. Ví dụ: 「とはいえ、振り返ってみると、とても充実した楽しい一日だったと言える」"},{"t":"〜とは限らない","note":"Diễn tả \"không hẳn là...\", phủ định cách nói tuyệt đối. Ví dụ: 「いつも天気に恵まれるとは限らない」"}]},"a-n5-9-n3":{"title":"Một ngày vui chơi ở công viên","topic":"Cuộc sống","trans":["Thứ Bảy thời tiết rất đẹp, vì đã hẹn với bạn bè đi công viên nên từ sáng tôi đã rất mong chờ. Chín giờ sáng tôi gặp bạn ở nhà ga, rồi từ đó đạp xe đến công viên. Dọc đường có rất nhiều cây anh đào, gió cũng dễ chịu nên việc đạp xe trở nên thật thú vị.","Tối hôm trước, tôi đã làm sẵn hộp cơm bento gồm trứng cuộn, cơm nắm và rau. Để bạn cũng có thể ăn, tôi làm thêm một ít phần cho bạn. Ngồi trên ghế dài trong công viên ăn, có lẽ vì ăn ngoài trời nên tôi cảm thấy ngon hơn mọi khi rất nhiều.","Bạn tôi cũng khen \"ngon quá\", nên tôi nghĩ công làm đồ ăn thật xứng đáng. Ăn xong, tôi và bạn chơi cầu lông và chụp ảnh. Mọi người trông rất vui, nhìn cảnh đó, ngay cả tôi cũng mỉm cười theo.","Đến chiều tối, tôi quyết định về nhà. Tuy hơi mệt nhưng được ở bên bạn nên đó là một ngày rất vui. Tôi mong tuần sau cũng có thể đến công viên chơi như vậy."],"vocab":["lời hẹn, hẹn","hẹn gặp nhau","hướng đến, đi về phía","tối hôm trước","trứng cuộn kiểu Nhật","phần, suất","cảm giác, tâm trạng","dáng vẻ, tình hình","nụ cười","chiều tối"],"grammar":[{"t":"〜ように","note":"Diễn tả mục đích, \"để có thể...\". Ví dụ: 「友達にも食べてもらえるように、友達の分も少しだけ作っておきました」"},{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Ví dụ: 「夕方になったので、私は家に帰ることにしました」"},{"t":"〜せいか","note":"Nghĩa là \"có lẽ là vì...\", nguyên nhân không chắc chắn, thường dẫn đến một kết quả nào đó. Ví dụ: 「外で食べるせいか、いつもよりずっとおいしく感じました」"},{"t":"〜かいがある","note":"Diễn tả công sức bỏ ra được đền đáp, rất xứng đáng. Ví dụ: 「作ったかいがあったと思いました」"}]},"eh-n4-2-n2":{"title":"Lần đầu đến quán ramen","topic":"Truyện tranh","trans":["Gần ga có một quán ramen khá nổi tiếng, hôm nay Tanutarō quyết định lấy hết can đảm lần đầu bước vào quán. Ở cửa có đặt một chiếc máy bán vé, nghe nói quán này có quy định phải mua vé ăn trước. Thế nhưng nút bấm nhiều quá, cậu chẳng biết nên bấm nút nào, đành đứng đơ ra tại chỗ.","Đúng lúc đó, Kon đang xếp hàng phía sau tốt bụng chỉ cho cậu: 「いちばん左が普通のラーメンだよ」 (Nút ngoài cùng bên trái là ramen thường đó). Ở một quán lần đầu đến thì vốn hay bối rối, nên một câu nói như vậy càng đáng quý hơn bất cứ điều gì. Nhờ thế, cậu mua được vé ăn một cách suôn sẻ, thở phào nhẹ nhõm rồi ngồi xuống chỗ của mình.","Ngồi vào chỗ, đưa vé ăn cho nhân viên xong, cậu được hỏi: 「麺のかたさはどうしますか」 (Bạn muốn sợi mì cứng mềm thế nào?). Ở các quán ramen Nhật Bản, có không ít quán cho khách chọn độ cứng của sợi mì theo sở thích. Tanutarō hơi phân vân một chút, nhưng vẫn mạnh dạn trả lời: 「かためでお願いします」 (Cho tôi mì cứng nhé). 「かため」 là từ chỉ sợi mì được luộc cứng hơn bình thường một chút.","Món nước dùng nóng hổi kết hợp với sợi mì cứng được mang ra ngon vượt cả mong đợi, đúng là tuyệt nhất. Tanutarō ăn say sưa, đến khi nhận ra thì đã uống hết sạch cả nước dùng. Tuy từng lúng túng trước máy bán vé, nhưng nhờ sự giúp đỡ tận tình, có thể nói đây là một lần đầu tiên khó quên."],"vocab":[{"w":"評判","m":"danh tiếng, tiếng tăm"},{"w":"暖簾をくぐる","m":"vén rèm noren bước vào quán"},{"w":"仕組み","m":"cơ chế, cách vận hành, quy định"},{"w":"見当","m":"phỏng đoán, manh mối (見当もつかない: hoàn toàn không biết)"},{"w":"立ち尽くす","m":"đứng chết trân, đứng đơ ra"},{"w":"戸惑う","m":"bối rối, lúng túng"},{"w":"尋ねる","m":"hỏi"},{"w":"上回る","m":"vượt quá, vượt trội hơn"},{"w":"途方に暮れる","m":"bó tay, không biết phải làm sao"}],"grammar":[{"t":"〜だけに","note":"Diễn tả \"chính vì ... nên càng ...\", sự việc ở vế trước dẫn đến kết quả hay cảm xúc tương ứng ở vế sau. Ví dụ:「初めての店では戸惑うことが多いだけに、こうした一言は何よりありがたいものである」"},{"t":"〜に合わせて","note":"Diễn tả việc điều chỉnh cho phù hợp với một điều kiện hay sở thích nào đó. Ví dụ:「好みに合わせて麺のかたさを選べる店も少なくないようだ」"},{"t":"〜ものの","note":"Diễn tả \"tuy ... nhưng ...\", vế sau thường là hành động trái với dự đoán từ vế trước. Ví dụ:「たぬたろうは少し迷ったものの、「かためでお願いします」と思い切って答えた」"},{"t":"〜とは〜のことだ","note":"Dùng để định nghĩa, giải thích ý nghĩa của một từ. Ví dụ:「「かため」とは、普通よりも少しかたく茹でた麺のことを指す言葉である」"}]},"eh-n4-2-n3":{"title":"Lần đầu đến quán ramen","topic":"Truyện tranh","trans":["Gần ga có một quán ramen nổi tiếng được nhiều người ghé thăm. Hôm nay, Tanutarō quyết định lần đầu bước vào quán mà cậu đã để ý từ lâu.","Ở cửa có đặt một chiếc máy bán vé, nghe nói quán này có quy định phải mua vé ăn trước. Nút bấm nhiều quá, cậu không biết nên bấm nút nào nên đang lúng túng. Kon đứng phía sau chỉ cho cậu: 「いちばん左が普通のラーメンだよ」 (Nút ngoài cùng bên trái là ramen thường đó).","Nhờ vậy, cậu mua được vé ăn suôn sẻ, ngồi vào chỗ rồi đưa vé cho nhân viên. Sau đó, nhân viên hỏi: 「麺のかたさはどうしますか」 (Bạn muốn sợi mì cứng mềm thế nào?). Tanutarō trả lời: 「かためでお願いします」 (Cho tôi mì cứng nhé). 「かため」 là mì được luộc cứng hơn bình thường một chút, để tạo cảm giác dai ngon khi nhai.","Món nước dùng nóng hổi và sợi mì cứng được mang ra ngon hơn cả cậu tưởng, đúng là tuyệt vời. Tanutarō ăn say sưa, đến khi nhận ra thì đã uống hết sạch nước dùng. Tanutarō cũng đã hiểu rõ vì sao quán này được yêu thích đến vậy."],"vocab":[{"w":"訪れる","m":"ghé thăm, đến thăm"},{"w":"気になる","m":"để ý, bận tâm"},{"w":"券売機","m":"máy bán vé, máy bán vé ăn"},{"w":"食券","m":"vé ăn"},{"w":"押す","m":"bấm, ấn, đẩy"},{"w":"困る","m":"gặp khó khăn, lúng túng"},{"w":"店員","m":"nhân viên cửa hàng"},{"w":"歯ごたえ","m":"độ dai, cảm giác khi nhai"},{"w":"夢中","m":"say mê, mải mê"},{"w":"理由","m":"lý do"}],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Câu trong bài:「初めて入ってみることにしました」, nghĩa là cậu quyết định thử vào quán lần đầu."},{"t":"〜によって","note":"Diễn tả phương tiện, cách thức, \"bằng cách, thông qua\". Câu trong bài:「少しかたくゆでることによって」, giải thích rằng nhờ luộc cứng hơn một chút mà tạo ra độ dai."},{"t":"〜ず(に)","note":"Dạng văn viết của 〜ない, nghĩa là \"không làm ... mà\" hoặc \"không ...\". Câu trong bài:「どれを押せばいいのかわからず困っていました」, nghĩa là vì không biết nên bấm nút nào nên cậu lúng túng."},{"t":"〜以上に","note":"Diễn tả \"hơn cả ...\", vượt quá mong đợi. Câu trong bài:「思っていた以上においしく」, nghĩa là ngon hơn cả tưởng tượng."}]},"eh-n4-3-n2":{"title":"Món quà ngày mưa","topic":"Truyện tranh","trans":["Thứ Bảy tuần sau là sinh nhật của Konchan, bạn của Tanutarou. Chiếc khăn quàng màu xanh mà Konchan vẫn thường đeo có lẽ do dùng nhiều năm nên đã cũ đi rất nhiều. Thấy vậy, Tanutarou nghĩ đến việc tặng bạn một chiếc khăn quàng mới.","Thế nhưng, hôm đó trời mưa suốt từ sáng, thời tiết thật bất tiện để ra ngoài. Để kịp sinh nhật, dù trời mưa cậu vẫn buộc phải che ô đi đến tiệm tạp hóa trong thị trấn. Chiếc khăn quàng màu xanh cậu tìm thấy ở tiệm có tông màu thanh lịch, tuy giá hơi đắt nhưng cậu vẫn quyết định mua mà không do dự. Nhân viên cửa hàng gói rất cẩn thận nên trông nó thành một món quà thật đẹp.","Khi trên đường về, mưa còn nặng hạt hơn hẳn so với buổi sáng. Mưa càng lớn thì nỗi lo quà bị ướt cũng càng tăng lên. Vì vậy, Tanutarou ôm chặt chiếc cặp vào lòng, bất chấp bản thân bị ướt và cứ thế chạy tiếp.","Khi Tanutarou nói \"Chúc mừng sinh nhật\" và đưa món quà ra, Konchan ngạc nhiên đến mức mở tròn mắt vì quá bất ngờ. Tấm lòng vất vả mang quà đến trong mưa có lẽ không cần nói ra, người kia cũng cảm nhận được. Konchan quàng chiếc khăn mới vào, cười vui vẻ nói: \"Cảm ơn cậu, tớ sẽ luôn trân trọng nó nhé.\" Đồ đắt tiền chưa chắc đã khiến người ta vui, nhưng món quà được chọn bằng cả tấm lòng nghĩ cho người nhận sẽ đọng lại trong tim.\""],"vocab":[{"w":"当たる","m":"trùng với, đúng vào (một ngày nào đó)"},{"w":"身につける","m":"mang theo bên người, đeo, mặc"},{"w":"古びる","m":"cũ đi, trở nên cũ kỹ"},{"w":"値が張る","m":"giá khá đắt"},{"w":"包装","m":"gói, bao bì"},{"w":"激しい","m":"dữ dội, mạnh"},{"w":"抱え込む","m":"ôm chặt"},{"w":"差し出す","m":"đưa ra, chìa ra"},{"w":"目を丸くする","m":"ngạc nhiên mở tròn mắt"}],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「雨が強まるのに伴って、プレゼントが濡れてしまわないかという不安も大きくなった」."},{"t":"〜ざるを得ない","note":"Diễn tả ngoài cách đó ra không còn lựa chọn nào khác, đành phải làm. Ví dụ: 「雨の中でも傘をさして町の雑貨屋へ出かけざるを得なかった」."},{"t":"〜とはいえ","note":"Diễn tả thừa nhận sự việc phía trước nhưng vế sau lại là kết quả hay nhận định khác với dự đoán. Ví dụ: 「少し値が張るとはいえ、迷わず買うことにした」."},{"t":"〜とは限らない","note":"Diễn tả \"chưa chắc\", \"không phải lúc nào cũng vậy\", dùng để phủ định suy nghĩ quá tuyệt đối. Ví dụ: 「高価な物が必ずしも喜ばれるとは限らない」."}]},"eh-n4-3-n3":{"title":"Món quà ngày mưa","topic":"Truyện tranh","trans":["Thứ Bảy tuần sau là sinh nhật của Konchan, bạn của Tanutarou. Chiếc khăn quàng màu xanh mà Konchan vẫn luôn dùng đã cũ đi khá nhiều vì dùng lâu. Tanutarou quyết định tặng bạn một chiếc khăn quàng mới.","Thế nhưng, hôm đó trời mưa suốt từ sáng. Tanutarou che ô, đi bộ đến tiệm tạp hóa trong thị trấn. Ở đó, cậu tìm được một chiếc khăn quàng màu xanh rất đẹp.","Giá hơi đắt một chút, nhưng Tanutarou vẫn quyết định mua. Nhân viên cửa hàng gói chiếc khăn quàng rất cẩn thận và đẹp mắt. Trên đường về, mưa còn to hơn hẳn so với buổi sáng. Để món quà không bị ướt, Tanutarou ôm chặt chiếc cặp và chạy.","Khi cậu nói \"Chúc mừng sinh nhật\" và đưa món quà, Konchan trông rất ngạc nhiên. Konchan quàng chiếc khăn mới lên cổ và cười nói: \"Cảm ơn cậu, tớ sẽ luôn trân trọng nó nhé.\" Tanutarou thấy chạy dưới mưa như vậy thật đáng giá và cảm thấy vui từ tận đáy lòng."],"vocab":[{"w":"だいぶ","m":"khá, tương đối"},{"w":"贈る","m":"tặng"},{"w":"雑貨屋","m":"tiệm tạp hóa"},{"w":"値段","m":"giá cả"},{"w":"店員","m":"nhân viên cửa hàng"},{"w":"ていねい","m":"cẩn thận, chu đáo"},{"w":"包む","m":"gói, bọc"},{"w":"抱える","m":"ôm, ôm vào lòng"},{"w":"様子","m":"dáng vẻ, tình hình"},{"w":"大切","m":"quan trọng, trân trọng"}],"grammar":[{"t":"〜ことにする","note":"Diễn tả người nói tự mình quyết định làm việc gì. Ví dụ: 「新しいマフラーを贈ることにしました」「買うことにしました」"},{"t":"〜ように","note":"Diễn tả mục đích, để một trạng thái nào đó được thực hiện hoặc không xảy ra. Ví dụ: 「プレゼントがぬれないように、かばんをしっかり抱えて走りました」"},{"t":"〜せいで","note":"Diễn tả nguyên nhân, lý do tiêu cực, thường mang sắc thái trách móc. Ví dụ: 「長く使ったせいでだいぶ古くなっていました」"},{"t":"〜てくれる","note":"Diễn tả người khác làm việc gì đó cho mình, kèm cảm giác biết ơn. Ví dụ: 「そのマフラーをていねいにきれいに包んでくれました」"}]},"a-n2-11-n3":{"title":"居酒屋の「お通し」","topic":"Văn hóa","trans":["Khi ngồi vào bàn ở quán izakaya Nhật Bản, đôi khi bạn sẽ được mang ra một món nhỏ dù chưa gọi. Món này được gọi là「お通し」, ở vùng Kansai cũng thường gọi là「突き出し」. Bên trong có thể là edamame (đậu nành luộc), món hầm, món trộn,... mỗi quán một khác.","Trong số những người lần đầu đến Nhật, không ít người bất ngờ khi thấy tiền お通し được cộng thêm vào hóa đơn. Họ lo rằng mình bị tính tiền tùy tiện. Tiền お通し khoảng 300 đến 500 yên, và người ta nói rằng với quán thì nó gần giống như phí chỗ ngồi.","Cũng có quan điểm cho rằng đây là sự chu đáo của quán, để khách không thấy chán trong lúc chờ món. Tuy nhiên, có từ chối được hay không còn tùy quán, và gần đây cũng ngày càng có nhiều quán không mang お通し ra nữa. Nếu bạn băn khoăn, chỉ cần hỏi một câu khi vào quán là yên tâm.","Nếu hiểu được bối cảnh này, bạn sẽ thoải mái thưởng thức cả những đĩa nhỏ lạ mắt. Có thể xem お通し là một phần của văn hóa nhậu của Nhật Bản."],"vocab":["gọi món, đặt hàng","đĩa nhỏ, món ăn đựng trong bát nhỏ","thanh toán","cộng thêm, thêm vào","bất an, lo lắng","chán, buồn tẻ","quan tâm, chu đáo","từ chối","bối cảnh, nguồn gốc","lạ mắt, chưa quen thấy"],"grammar":[{"t":"〜ように","note":"Diễn tả \"để đạt được mục đích nào đó\". Phía trước thường là dạng phủ định hoặc khả năng, nêu mục đích của việc làm. Ví dụ:「客が退屈しないように、店が気を使って出すものだ」"},{"t":"〜によって","note":"Diễn tả \"tùy theo ... mà khác nhau\". Ví dụ:「中身は枝豆や煮物、和え物など、店によってさまざまである」"},{"t":"〜ば(thể điều kiện)","note":"Diễn tả \"nếu ... thì ...\", vế sau thường là kết quả tốt hoặc lời khuyên. Ví dụ:「背景を知っていれば、見慣れない小鉢も気持ちよく楽しめるだろう」"},{"t":"〜のではないか","note":"Diễn tả suy đoán hoặc lo lắng của người nói, \"chẳng lẽ là ... sao\". Ví dụ:「勝手にお金を取られたのではないかと、不安になる」"}]},"a-n2-11-n4":{"title":"居酒屋の「お通し」","topic":"Văn hóa","trans":["Khi ngồi vào bàn ở quán izakaya Nhật Bản, đôi khi sẽ có một món nhỏ mà bạn không gọi được mang ra. Món này gọi là「お通し」, thường là edamame (đậu nành luộc) hoặc món hầm, v.v. Ở vùng Kansai cũng thường gọi là「突き出し」, và món bên trong mỗi quán một khác.","Người lần đầu đến Nhật đôi khi giật mình khi thấy tiền お通し trên hóa đơn. Cũng có nhiều người nghĩ「có phải tính tiền vô lý không?」rồi thấy khó xử. Người ta nói お通し thường khoảng 300 đến 500 yên. Với quán, nó có ý nghĩa giống như phí chỗ ngồi.","Nghe nói cũng có ý muốn để khách không thấy chán trong lúc chờ món. Có từ chối được hay không tùy quán, nhưng gần đây cũng có ngày càng nhiều quán không mang お通し ra. Nếu bạn băn khoăn, chỉ cần hỏi trước khi vào quán là ổn. Biết lý do rồi, chắc bạn cũng sẽ thưởng thức được món nhỏ này như một phần của văn hóa nhậu của Nhật Bản."],"vocab":["quán izakaya (quán nhậu kiểu Nhật)","chỗ ngồi","gọi (món), nhờ vả","món hầm, món nấu","thanh toán","ngạc nhiên, giật mình","khó xử, gặp rắc rối","từ chối","tăng lên","bận tâm, để ý"],"grammar":[{"t":"〜と(〜ことがある)","note":"Diễn tả kết quả tự nhiên \"hễ ... thì ...\", cũng có thể đi với「ことがある」để nói \"đôi khi có xảy ra\". Ví dụ:「席に座ると、頼んでいない小さい料理が来ることがある」"},{"t":"〜ように(mục đích)","note":"Diễn tả \"để cho một trạng thái nào đó được thực hiện\". Ví dụ:「料理が来るまで客が退屈しないように、という気持ちもあるそうだ」"},{"t":"〜ば(thể điều kiện)","note":"Diễn tả điều kiện \"nếu ... thì ...\". Ví dụ:「店に入る時に聞いておけば大丈夫だ」「理由を知れば、小さい料理も楽しめるだろう」"},{"t":"〜そうだ(truyền đạt)","note":"Gắn sau thể thường, diễn tả thông tin nghe được \"nghe nói ...\". Ví dụ:「という気持ちもあるそうだ」"}]},"a-n2-12-n3":{"title":"Suy ngẫm về Ngày Tạ ơn Lao động","topic":"Xã hội","trans":["Ngày 23 tháng 11 được gọi là 「勤労感謝の日」 (Ngày Tạ ơn Lao động), là ngày lễ mà nhiều công ty và trường học được nghỉ. Nhìn tên gọi, ta dễ nghĩ đây là ngày dành cho người đi làm, nhưng nguồn gốc ban đầu của nó hơi khác. Từ xa xưa, vào mùa thu, Nhật Bản có tổ chức lễ 「新嘗祭」, dâng nông sản vừa thu hoạch lên thần linh để bày tỏ lòng biết ơn.","Sau chiến tranh, trong quá trình xem xét lại các chế độ, năm 1948 một đạo luật được ban hành và ngày này trở thành 「勤労感謝の日」. Luật ghi rằng đây là ngày coi trọng lao động và để mọi người cảm ơn lẫn nhau. Bạn có thể hiểu là lòng biết ơn dành cho thần linh đã mở rộng thành lòng biết ơn đối với việc lao động và làm ra sản phẩm.","Ngày nay cách làm việc ngày càng đa dạng, và hình ảnh ta nghĩ đến khi nghe từ 「勤労」 cũng đã thay đổi. Không chỉ nhà máy hay đồng ruộng, mà cửa hàng, logistics, y tế, chăm sóc điều dưỡng… có vô số công việc đang nâng đỡ cuộc sống. Ngay cả ngày lễ cũng không phải ai cũng được nghỉ, có những công việc còn phải làm vất vả hơn bình thường. Cuộc sống tiện lợi của chúng ta được xây dựng nhờ nỗ lực của những người như vậy.","Chỉ cần nói một câu 「ありがとうございます」 với người giao hàng cho mình, tấm lòng cũng đã được truyền đạt. Ở nơi làm việc cũng vậy, nói lời cảm ơn với công việc của đồng nghiệp là điều bạn có thể bắt đầu ngay nhân dịp này. Tuy nhiên, việc đi làm hay nghỉ vào ngày lễ khác nhau tùy từng công ty, nên bạn hãy xác nhận chi tiết theo hướng dẫn của công ty. Lòng biết ơn chỉ thật sự có ý nghĩa khi được nói ra thành lời trong cuộc sống hằng ngày, chứ không chỉ vào ngày lễ."],"vocab":["ngày lễ (quốc lễ)","nguồn gốc, xuất xứ","thu hoạch, mùa màng","dâng, cúng (供える)","chế độ, thể chế","được xem xét lại","logistics, vận chuyển hàng hóa","nâng đỡ, chống đỡ","được hình thành, được xây dựng (成り立つ)","đồng nghiệp"],"grammar":[{"t":"〜によって","note":"Biểu thị nguyên nhân, phương tiện hoặc căn cứ, nghĩa là 「do…, nhờ vào…, bằng…」. Ví dụ: 「私たちの便利な生活は、そうした人たちの努力によって成り立っているのだ」"},{"t":"〜わけではない","note":"Phủ định một phần, nghĩa là 「không có nghĩa là…」, không phải phủ định hoàn toàn. Ví dụ: 「祝日でも、みんなが休めるわけではなく、いつも以上に働く仕事もある」"},{"t":"〜ため","note":"Biểu thị nguyên nhân, lý do, trang trọng hơn 「から」 và thường dùng trong văn viết. Ví dụ: 「祝日の勤務や休みは会社ごとに違うため、詳しくは会社の説明を確認してほしい」"},{"t":"〜をきっかけに","note":"Biểu thị lấy việc nào đó làm cơ hội để bắt đầu hành động mới. Ví dụ: 「同僚の仕事に礼を言うことは、この日をきっかけにすぐ始められる」"}]},"a-n2-12-n4":{"title":"Ngày Tạ ơn Lao động","topic":"Xã hội","trans":["Ngày 23 tháng 11 là 「勤労感謝の日」 (Ngày Tạ ơn Lao động), một ngày lễ mà công ty và trường học được nghỉ. Nhìn tên gọi, nhiều người nghĩ đây là ngày dành cho người đi làm. Nhưng ban đầu, đó là lễ 「新嘗祭」, vào mùa thu dâng gạo mới lên thần linh để bày tỏ lòng biết ơn.","Sau chiến tranh, nhà nước đã soạn một đạo luật mới về các ngày lễ. Năm 1948, ngày này trở thành ngày lễ có tên 「勤労感謝の日」. Lòng biết ơn dành cho thần linh đã mở rộng thành lòng biết ơn đối với việc lao động và làm ra sản phẩm.","Ngày nay có rất nhiều công việc hỗ trợ cuộc sống như ở cửa hàng, bệnh viện. Có những người ngay cả ngày lễ cũng không được nghỉ, còn phải làm việc bận rộn hơn bình thường. Cuộc sống tiện lợi của chúng ta có được là nhờ những người như vậy. Nếu bạn nói 「ありがとう」 với người giao hàng cho mình, tấm lòng sẽ được truyền đến họ. Hãy thử nói ra lời cảm ơn trong cuộc sống hằng ngày nhé."],"vocab":["ngày lễ (quốc lễ)","cảm ơn, lòng biết ơn","chiến tranh","luật, pháp luật","mở rộng, lan rộng","tiện lợi","bận rộn","giao đến, chuyển đến","tấm lòng, cảm xúc"],"grammar":[{"t":"〜のおかげで","note":"Biểu thị nhờ ai đó hoặc việc gì đó mà có kết quả tốt, mang sắc thái biết ơn. Ví dụ: 「そうした人たちのおかげでできています」"},{"t":"〜てくれる","note":"Biểu thị người khác làm việc gì đó cho mình, mang sắc thái biết ơn. Ví dụ: 「荷物を届けてくれた人に」"},{"t":"〜ば(thể điều kiện)","note":"Biểu thị điều kiện 「nếu ~ thì ~」. Ví dụ: 「ありがとう」と言えば、気持ちは伝わります"},{"t":"〜ようにする","note":"Biểu thị cố gắng tạo thói quen, cố gắng làm việc gì đó. Ví dụ: 毎日の生活の中で言葉にするようにしましょう"}]},"a-n2-13-n3":{"title":"Tiệc tất niên đang thay đổi, sự tinh tế vẫn còn nguyên","topic":"Công sở","trans":["Cứ đến cuối năm, ở các công ty Nhật Bản, chuyện về 「忘年会」 (tiệc tất niên) từng tự nhiên được nhắc đến. Đó là buổi tiệc để quên đi những vất vả của một năm và gắn kết tình đồng nghiệp, trước đây ai cũng nghĩ việc tham gia là điều đương nhiên. Tuy nhiên, gần đây ngày càng có nhiều người muốn dành thời gian sau giờ làm cho bản thân nên không muốn tham gia.","Vì vậy, ngày càng nhiều công ty bỏ tiệc tối để chuyển sang tiệc trưa, hoặc cho nhân viên tự do tham gia. Đằng sau đó là việc suy nghĩ của mỗi người ngày càng khác nhau, cùng hoàn cảnh muốn ưu tiên gia đình và việc chăm sóc người thân. Không ít bạn trẻ cảm thấy ngồi cùng sếp chẳng vui vẻ gì, ngược lại chỉ thấy mệt vì phải để ý đủ thứ.","Mặt khác, cũng có người coi đây là cơ hội quý giá để giao lưu với những đồng nghiệp bình thường khó nói chuyện nên rất hoan nghênh. Về phía công ty, nếu ép nhân viên tham gia thì sự bất mãn sẽ tăng lên, nên chỉ còn cách tìm một hình thức phù hợp với hoàn cảnh của từng người. Khi được mời mà muốn từ chối, nguyên tắc cơ bản là trước hết cảm ơn người đã mời.","Nếu bạn nói 「ありがとうございます、あいにく先約がありまして」 (Cảm ơn anh/chị, rất tiếc là em đã có hẹn trước) thì sẽ không làm mất lòng ai. Bạn không nên giải thích lý do quá chi tiết, chỉ cần nói ngắn gọn rồi thêm câu 「またぜひ」 (lần sau nhất định nhé) là tốt. Khi tham gia, nếu không uống được rượu thì bạn có thể cụng ly bằng trà ô long, và nói trước là mình sẽ về sớm thì cũng nhẹ nhõm hơn. Chỉ cần người tổ chức viết thêm một câu 「参加は自由です」 (Tham gia hay không tùy bạn) vào thông báo, gánh nặng của những người từ chối sẽ nhẹ đi rất nhiều. Tôi nghĩ điều quan trọng là dù hình thức có thay đổi, tấm lòng trân trọng hoàn cảnh của nhau vẫn không đổi."],"vocab":["nơi làm việc, công sở","chăm sóc người thân (người cần được giúp đỡ)","đồng nghiệp","quý giá, hiếm có","hoàn cảnh, lý do","hẹn trước, lịch hẹn đã có","làm mất lòng, mích lòng","thêm vào, kèm thêm","người tổ chức (sự kiện)"],"grammar":[{"t":"〜どころか","note":"Diễn tả ý \"đừng nói là…, mà ngược lại…\", phía sau là nội dung trái với dự đoán. Ví dụ: 「上司との席は楽しいどころか、気を使って疲れるだけだと感じる」"},{"t":"〜ため(nguyên nhân)","note":"Dùng để nêu nguyên nhân, lý do, trang trọng hơn 「から」. Ví dụ: 「無理に参加させると不満が高まるため、それぞれの事情を考えた形を探すしかありません」"},{"t":"〜しかない","note":"Diễn tả ý \"chỉ còn cách…, ngoài ra không có lựa chọn nào khác\". Ví dụ: 「それぞれの事情を考えた形を探すしかありません」"},{"t":"Động từ thể ます bỏ ます + すぎる","note":"Diễn tả mức độ quá mức. Ví dụ: 「理由は細かく話しすぎず、短く伝えて」(話しすぎず là dạng văn viết của 話しすぎない)"}]},"a-n2-13-n4":{"title":"Tiệc tất niên đang thay đổi","topic":"Công sở","trans":["Cứ đến cuối năm, các công ty Nhật Bản thường nói về 「忘年会」 (tiệc tất niên). Ngày xưa, mọi người đi để quên đi sự mệt mỏi của một năm và coi việc tham gia là điều đương nhiên. Bây giờ số người không muốn đi nhiều lên, cũng có công ty chuyển sang tiệc trưa.","Sau giờ làm, nhiều người muốn dành thời gian cho bản thân và gia đình. Cũng có bạn trẻ thấy ăn cùng sếp thì phải để ý nhiều nên rất mệt. Nhưng cũng có người thấy vui vì được nói chuyện với đồng nghiệp bình thường ít có dịp trò chuyện. Nếu ép mọi người đi thì sẽ rất khó xử, nên công ty cân nhắc hoàn cảnh của từng người.","Khi muốn từ chối, trước hết bạn nói 「ありがとうございます」 (cảm ơn) vì người ta đã mời mình. Bạn đừng nói lý do dài dòng, chỉ cần nói 「またぜひ」 (lần sau nhất định nhé) là được. Nếu người tổ chức viết 「参加は自由です」 (tham gia hay không tùy bạn), người từ chối sẽ thấy thoải mái hơn. Điều quan trọng là nghĩ đến cảm xúc của nhau."],"vocab":["tiệc tất niên (tiệc cuối năm)","đương nhiên","tăng lên","cấp trên, sếp","đồng nghiệp","hoàn cảnh, lý do","từ chối","mời","người tổ chức hoạt động","để ý, quan tâm đến người khác"],"grammar":[{"t":"〜ために","note":"Diễn tả mục đích, \"để làm〜\". Ví dụ: 「一年の疲れを忘れるために、行くのが当たり前でした」"},{"t":"〜と(điều kiện)","note":"Diễn tả hễ làm〜 thì sẽ〜, thường dùng cho kết quả tự nhiên hoặc lời khuyên. Ví dụ: 「年末になると、日本の会社では「忘年会」の話をよくします」"},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do, nhẹ nhàng hơn 「から」. Ví dụ: 「いつも話せない同僚と話せるので、うれしいと思う人もいます」"},{"t":"〜てくれる","note":"Diễn tả người khác làm điều gì đó cho mình, kèm theo lòng biết ơn. Ví dụ: 「まず誘ってくれたことに「ありがとうございます」と言います」"}]},"a-n3-13-n2":{"title":"Khi nhận được phiếu thông báo vắng mặt","topic":"Đời sống","trans":["Tan làm về đến nhà, tôi nhận ra trong hộp thư có một tờ \"phiếu thông báo vắng mặt\" của dịch vụ giao hàng. Vì lúc tôi vắng nhà có bưu kiện được giao đến, nên tôi buộc phải nhờ họ giao lại một lần nữa. Thủ tục này được gọi là 「再配達」 (giao lại), và khá quen thuộc với những ai hay dùng dịch vụ giao hàng.","Trước đây, cách phổ biến là gọi đến số điện thoại ghi trên tờ giấy, nhưng cùng với sự phổ biến của điện thoại thông minh, tình hình đã thay đổi. Hiện nay, bạn chỉ cần quét mã QR in trên phiếu, chọn ngày và khung giờ mong muốn là có thể đăng ký. Tuy nhiên, trên phiếu còn ghi cả thời hạn lưu giữ, nên không thể chần chừ được. Nếu không làm thủ tục sớm, bưu kiện có thể bị trả lại cho người gửi, vì vậy cần chú ý.","Mặt khác, việc giao lại còn có một vấn đề: tốn thêm cả nhiên liệu xe tải lẫn nhân lực. Trong bối cảnh thiếu tài xế đã trở thành vấn đề xã hội như hiện nay, người dùng cũng được kỳ vọng nhận hàng ngay trong một lần càng nhiều càng tốt. Vì thế, những cách nhận hàng như 「置き配」 (để hàng trước cửa) và tủ giao hàng đang được chú ý. Nếu nhờ người giao để hàng trước cửa nhà hoặc trong tủ, thì dù có ở nhà hay không bạn vẫn nhận được hàng.","Bản thân tôi gần đây khi đặt hàng online cũng nghĩ sẵn cả cách nhận hàng. Từng việc chỉ là một chút chu đáo nhỏ thôi, nhưng sự quan tâm như vậy góp phần giảm gánh nặng cho phía giao hàng. Với người dùng cũng bớt được những rắc rối không cần thiết, nên có thể nói đây là thói quen đem lại niềm vui cho cả hai bên."],"vocab":["phiếu thông báo vắng mặt","vắng nhà, đi vắng","giao lại (hàng)","phổ biến, lan rộng","ghi, ghi chép","trả lại, gửi trả","nhiên liệu, xăng dầu","để hàng trước cửa","gánh nặng, trách nhiệm","sự quan tâm, ý thức chu đáo"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ:「スマートフォンの普及に伴って状況が変わった」"},{"t":"〜ざるを得ない","note":"Diễn tả việc buộc phải làm, không còn lựa chọn nào khác. Ví dụ:「改めて配達してもらうよう依頼せざるを得ない」"},{"t":"〜かねない","note":"Diễn tả khả năng có thể xảy ra kết quả xấu. Ví dụ:「荷物が送り主に返送されかねない」"},{"t":"〜にかかわらず","note":"Diễn tả việc không bị ảnh hưởng bởi điều kiện ở vế trước, dù thế nào thì vẫn…. Ví dụ:「在宅しているかどうかにかかわらず受け取ることができる」"}]},"a-n3-13-n4":{"title":"Khi nhận được phiếu vắng mặt","topic":"Đời sống","trans":["Tan làm về nhà, tôi thấy có một tờ giấy trong hộp thư. Đây là 「不在票」 (phiếu vắng mặt), là thông báo rằng lúc tôi đi vắng có bưu kiện được gửi đến. Việc nhờ họ giao lại một lần nữa được gọi là 「再配達」 (giao lại).","Bây giờ chỉ cần dùng điện thoại là đăng ký dễ dàng. Bạn chỉ cần quét mã QR trên tờ giấy, rồi chọn ngày và giờ mong muốn. Nhưng trên phiếu còn ghi cả thời hạn lưu giữ bưu kiện. Nếu không liên lạc sớm, bưu kiện cũng có thể bị trả lại cho người gửi.","Giao lại hàng rất vất vả vì tốn cả xăng xe tải lẫn sức người. Vì thế, 「置き配」 (để hàng trước cửa) hay tủ giao hàng rất tiện. Gần đây khi mua hàng trên mạng, tôi cố gắng nghĩ sẵn cả cách nhận hàng. Tôi nghĩ đây là thói quen tốt cho cả bản thân tôi và người giao hàng."],"vocab":["hộp thư","vắng nhà","bưu kiện, hành lý","giao đến","đăng ký","mong muốn","thời hạn","cửa ra vào, tiền sảnh","thói quen"],"grammar":[{"t":"〜てもらう","note":"Diễn tả việc nhờ người khác làm gì đó cho mình. Ví dụ:「もう一度届けてもらうように頼むことを」、「荷物を置いてもらう」"},{"t":"〜ないと、〜","note":"Diễn tả nếu không làm việc gì đó thì sẽ có kết quả không tốt. Ví dụ:「早く連絡しないと、荷物が送った人に戻されることもある」"},{"t":"〜ようにする","note":"Diễn tả việc cố gắng duy trì thói quen hoặc chú ý làm gì đó. Ví dụ:「受け取り方まで考えるようにしている」"},{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do, giọng nhẹ nhàng hơn「から」. Ví dụ:「トラックのガソリンも人の力も使うので大変だ」"}]},"a-n3-14-n2":{"title":"紅葉狩りに出かけよう","topic":"Văn hóa","trans":["Cuối tháng Mười, đồng nghiệp Tanaka rủ tôi: 「今週末、紅葉を見に行きませんか」 (Cuối tuần này đi ngắm lá đỏ không?). Ở Nhật, vào mùa thu có thói quen lên núi hoặc ra công viên thưởng thức những chiếc lá đổi màu, gọi là 「紅葉狩り」, được yêu thích từ xa xưa. Tôi thích lá đỏ, nhưng nghe nói các điểm du lịch nổi tiếng rất đông người nên thành thật mà nói, tôi hơi lo.","Thế rồi Tanaka đề xuất: 「人込みを避けるために、朝早く出発するのはどうでしょうか」 (Để tránh đám đông, mình xuất phát thật sớm vào buổi sáng thì sao?). Càng gần trưa thì bãi đỗ xe và đường sá càng đông đúc, nên nếu đến nơi trong buổi sáng thì nghe nói có thể thong thả đi dạo. Ngày thường có xu hướng vắng hơn, nhưng không phải lúc nào cũng yên tĩnh, nên có lẽ không nên kỳ vọng quá nhiều. Đã là mùa cao điểm thì chắc cũng đành phải chuẩn bị tinh thần là sẽ có một lượng người nhất định.","Tiếp theo, chúng tôi quyết định tra 「紅葉情報」 (thông tin lá đỏ) được đăng trên trang web của hiệp hội du lịch và trang dự báo thời tiết. Ở đó, tình trạng của cây được giải thích dễ hiểu bằng những cụm như 「色づき始め」 (bắt đầu đổi màu) và 「見ごろ」 (thời điểm đẹp nhất để ngắm). Tanaka nhắc tôi rằng thời điểm đẹp nhất khác nhau tùy từng nơi, nên trước khi đi nhất định phải kiểm tra. Sau khi bàn bạc, chúng tôi chọn một công viên nhỏ gần núi và quyết định đi chuyến tàu sớm nhất buổi sáng.","Hôm đó tôi hơi buồn ngủ, nhưng dậy sớm cũng đáng, vì trên đường hầu như không có bóng người. Những chiếc lá đỏ và vàng được ánh nắng ban mai chiếu sáng, trông như thể cả không khí cũng nhuốm màu. Giữa những ngày bận rộn, cơ hội để thong thả cảm nhận sự chuyển mùa chắc chắn không nhiều. Trên đường về, tôi cảm ơn Tanaka: 「誘ってくださって、ありがとうございました」 (Cảm ơn anh/chị đã rủ tôi). Tanaka cười và nói 「来年も行きましょう」 (Năm sau mình cũng đi nhé). Nghe câu đó, tôi bắt đầu mong chờ mùa thu năm sau ngay từ bây giờ."],"vocab":["ngắm lá đỏ","đổi màu, nhuốm màu","đám đông","đề xuất","đông đúc, chen chúc","xu hướng","chuẩn bị tinh thần, quyết tâm","thời điểm đẹp nhất để ngắm","khác nhau","mong chờ da diết"],"grammar":[{"t":"〜につれて","note":"Diễn tả khi một việc tiến triển thì việc khác cũng thay đổi theo. Ví dụ: 「昼に近づくにつれて駐車場も道路も混み合うため」"},{"t":"〜とは限らない","note":"Diễn tả không phải lúc nào cũng như vậy, vẫn có ngoại lệ. Ví dụ: 「いつも静かだとは限らない」"},{"t":"〜ざるを得ない","note":"Diễn tả việc không còn cách nào khác, đành phải làm. Ví dụ: 「ある程度の人出は覚悟せざるを得ない」"},{"t":"〜かいがある","note":"Diễn tả sự nỗ lực được đền đáp xứng đáng, thấy bõ công. Ví dụ: 「早起きしたかいがあって」"}]},"a-n3-14-n4":{"title":"紅葉を見に行こう","topic":"Văn hóa","trans":["Cuối tháng Mười, anh/chị Tanaka ở cùng công ty nói: 「今週末、紅葉を見に行きませんか」 (Cuối tuần này đi ngắm lá đỏ không?). Ở Nhật, việc lên núi hoặc ra công viên vào mùa thu để ngắm những chiếc lá đỏ và vàng được gọi là 「紅葉狩り」. Tôi thích lá đỏ, nhưng nghe nói những nơi nổi tiếng rất đông người nên tôi hơi lo.","Tanaka nói: 「朝早く出かけるのはどうですか」 (Mình đi sớm vào buổi sáng thì sao?). Đến trưa thì bãi đỗ xe và đường sá đều chật kín người và xe, nên nếu đến nơi vào buổi sáng thì nghe nói có thể thong thả đi dạo. Ngày thường thì thường vắng hơn, nhưng cũng không thể nói lúc nào cũng yên tĩnh.","Tiếp theo, tôi tra 「紅葉情報」 (thông tin lá đỏ) trên mạng. Ở đó, tình trạng của cây được viết bằng những cụm như 「色づき始め」 (bắt đầu đổi màu) và 「見ごろ」 (thời điểm đẹp nhất để ngắm). Thời điểm đẹp nhất khác nhau tùy từng nơi, nên Tanaka nhắc tôi hãy xem trước khi đi. Hai chúng tôi bàn bạc, chọn một công viên nhỏ gần núi và quyết định đi chuyến tàu sớm nhất buổi sáng.","Hôm đó tôi hơi buồn ngủ, nhưng dậy sớm thật là tốt. Trên đường hầu như không có ai. Những chiếc lá đỏ và vàng trông thật đẹp dưới ánh nắng ban mai, cứ như cả không khí cũng nhuốm màu. Trên đường về, tôi cảm ơn: 「誘ってくれて、ありがとうございました」 (Cảm ơn đã rủ mình nhé). Tanaka cười và nói 「来年も行きましょう」 (Năm sau mình cũng đi nhé), nên từ bây giờ tôi đã mong chờ mùa thu năm sau rồi."],"vocab":["lá đỏ","giống nhau, cùng","lo lắng","bãi đỗ xe","ngày thường","vắng (người)","chọn","buồn ngủ","lời cảm ơn","mong chờ, niềm vui"],"grammar":[{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do với sắc thái nhẹ nhàng. Ví dụ: 「有名な場所は人が多いと聞いたので、少し心配でした」"},{"t":"〜そうだ(truyền đạt)","note":"Diễn tả thông tin nghe được, nghĩa là \"nghe nói…\". Ví dụ: 「午前中に着けば、ゆっくり歩けるそうです」"},{"t":"〜ようにと言う/教える","note":"Diễn tả việc truyền đạt lại lời nhắc, yêu cầu ai đó làm gì. Ví dụ: 「出かける前に見るようにと田中さんが教えてくれました」"},{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì. Ví dụ: 「朝一番の電車で行くことにしました」"}]},"a-n3-15-n2":{"title":"Lần đầu làm điều chỉnh cuối năm","topic":"Công sở","trans":["Khi cuối năm đến gần, phòng nhân sự gửi cho tôi một email và hồ sơ có tiêu đề「年末調整のご案内」. Trong hồ sơ có các ô để điền tình trạng người phụ thuộc trong gia đình và phí bảo hiểm, nhưng tôi hoàn toàn không biết nên bắt đầu viết từ đâu. Đây là lần đầu tôi làm việc ở Nhật, đến cả từ「年末調整」tôi cũng chưa từng nghe qua.","Tôi hỏi anh Tanaka ngồi bên cạnh, anh ấy nói: 「毎年の手続きですから、心配はいりませんよ」, khiến tôi yên tâm hơn nhiều. Thuế bị trừ từ lương mỗi tháng rốt cuộc chỉ là tính tạm, đến cuối năm sẽ tính lại thuế của cả năm, nghe nói cơ chế là như vậy. Số thuế sẽ thay đổi tùy theo tình hình gia đình và phí bảo hiểm đã đóng, nên điền chính xác là rất quan trọng. Hơn nữa, không phải công ty nào cũng có cách điền giống nhau, nên anh ấy bảo tôi chỗ nào không rõ thì hỏi trực tiếp phòng nhân sự.","Hôm sau, tôi đến hỏi chị Sato bên phòng nhân sự. Chị vừa cho tôi xem mẫu điền, vừa giải thích tỉ mỉ từng mục một. Nghe nói nếu có loại bảo hiểm tự đóng thì đôi khi còn cần giấy chứng nhận do công ty bảo hiểm gửi đến. Không phải tôi ngại đặt câu hỏi, chỉ là thấy người phụ trách bên nhân sự trông có vẻ bận nên hơi khó mở lời. Nhưng chị Sato mỉm cười đáp: 「初めてなら聞いて当然ですよ」, khiến tâm trạng tôi nhẹ nhõm hơn một chút.","Về đến nhà, tôi quyết định tìm các giấy tờ bảo hiểm trong nhà và từ từ kiểm tra nội dung cần ghi. Thủ tục chi tiết và cách nộp sẽ khác nhau tùy công ty, nên bạn nhớ xác nhận hướng dẫn của công ty mình nhé. Điều chỉnh cuối năm thoạt nhìn có vẻ phiền phức, nhưng tôi đã hiểu đây là thủ tục quan trọng để quyết toán đúng thuế của cả năm."],"vocab":["年末調整 (thủ tục quyết toán lại thuế cả năm vào cuối năm)","người phụ thuộc (được nuôi dưỡng)","điền, ghi vào","manh mối, phỏng đoán","tạm thời, giả","cơ chế, cấu trúc","giấy chứng nhận","thoạt nhìn","quyết toán, tính toán chính xác"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ:「年末が近づくに伴って、人事部から「年末調整のご案内」というメールと書類が届いた」"},{"t":"〜に応じて","note":"Thay đổi tùy theo, phù hợp với một tình huống nào đó. Ví dụ:「家族の状況や支払った保険料に応じて税額が変わるため」"},{"t":"〜とは限らない","note":"Diễn tả điều gì đó không hẳn, không phải lúc nào cũng vậy (phủ định một phần). Ví dụ:「どの会社でも書き方が同じとは限らないので」"},{"t":"〜に対して","note":"Diễn tả đối tượng mà hành động hoặc cảm xúc hướng đến. Ví dụ:「忙しそうな人事の担当者に対して声をかけにくいと感じていた」"}]},"a-n3-15-n4":{"title":"Lần đầu làm điều chỉnh cuối năm","topic":"Công sở","trans":["Khi cuối năm gần đến, công ty gửi cho tôi email và hồ sơ. Đó là hướng dẫn về「年末調整」. Trong hồ sơ có chỗ để ghi về gia đình và tiền bảo hiểm, nhưng tôi không biết nên bắt đầu viết từ đâu. Vì đây là lần đầu tôi làm việc ở Nhật nên đến cả từ「年末調整」tôi cũng không biết.","Tôi hỏi anh Tanaka ngồi bên cạnh, anh ấy nói: 「毎年することだから、心配しなくていいですよ」. Nghe nói thuế bị trừ từ lương mỗi tháng chỉ là tính tạm. Đến cuối năm, họ sẽ tính lại thuế của cả năm một lần nữa. Cách điền sẽ hơi khác nhau tùy công ty, nên anh ấy bảo tôi chỗ nào không hiểu thì hỏi người bên nhân sự.","Hôm sau, tôi đến hỏi chị Sato bên nhân sự. Chị Sato cho tôi xem mẫu cách điền và chỉ cho tôi từng mục một. Nghe nói nếu có bảo hiểm tự đóng thì đôi khi còn cần giấy do công ty bảo hiểm gửi đến. Thấy chị ấy có vẻ bận nên tôi thấy khó mở lời. Nhưng chị Sato mỉm cười nói: 「初めてなら、聞いていいですよ」.","Về đến nhà, tôi quyết định tìm giấy tờ bảo hiểm và đọc thật chậm. Cách làm chi tiết sẽ khác nhau tùy công ty, nên bạn hãy đọc kỹ hướng dẫn của công ty nhé. Điều chỉnh cuối năm trông có vẻ vất vả, nhưng tôi đã hiểu đây là một thủ tục quan trọng."],"vocab":["cuối năm","hồ sơ, giấy tờ","bảo hiểm","lo lắng","tiền thuế","tính toán","nhân sự (phòng ban)","mẫu, bản mẫu","cần thiết","thủ tục"],"grammar":[{"t":"〜ので","note":"Diễn tả nguyên nhân, lý do, nghe nhẹ nhàng hơn「から」. Ví dụ:「日本で働くのは初めてなので、「年末調整」という言葉も知りませんでした」"},{"t":"〜そうだ(truyền đạt)","note":"Diễn tả tin nghe được từ người khác, nghĩa là「nghe nói…」. Ví dụ:「毎月の給料から引かれる税金は、とりあえずの計算だそうです」"},{"t":"〜ように言われる","note":"Diễn tả việc bị yêu cầu, dặn dò phải làm gì đó. Ví dụ:「分からないところは人事の人に聞くように言われました」"},{"t":"〜ことにする","note":"Diễn tả việc tự quyết định làm gì đó. Ví dụ:「保険の書類を探して、ゆっくり読むことにしました」"}]},"a-n3-16-n2":{"title":"Khi nhận được thiệp báo tang","topic":"Văn hóa","trans":["Đầu tháng Mười Một, đồng nghiệp là anh Tanaka gửi đến một tấm bưu thiếp, mở ra xem thì là thông báo gia đình đang có tang. Dòng chữ lịch sự 「喪中につき、年始のご挨拶をご遠慮申し上げます」 tuy ngắn nhưng đọng lại trong mắt tôi một cảm giác nặng nề. Đến lúc đó tôi mới lần đầu biết rằng bố của anh Tanaka đã mất vào mùa hè năm nay.","Loại thiệp này được gọi là 「喪中はがき」, dùng để người trong nhà có tang báo trước cho mọi người biết là mình sẽ không gửi 年賀状 (thiệp chúc Tết). Người ta nói thói quen này bắt nguồn từ quan niệm rằng trong thời gian có tang thì nên tránh những việc vui mừng. Thiệp thường được gửi đến trước khi mọi người bắt đầu chuẩn bị 年賀状, là để báo cho đối phương biết hoàn cảnh sớm, đỡ phải bận tâm không đáng có. Nói cách khác, 喪中はがき chỉ là lời thông báo \"tôi không thể gửi 年賀状\", chứ không phải yêu cầu đối phương phải hồi âm.","Tôi phân vân một lúc không biết nên xử lý thế nào, nhưng sau khi hỏi ý kiến đồng nghiệp, tôi quyết định không gửi 年賀状 cho anh Tanaka. Thay vào đó, đồng nghiệp bảo tôi rằng sau khi sang năm mới một thời gian, nếu gửi 「寒中見舞い」 thì tấm lòng sẽ được truyền đạt. 寒中見舞い là thiệp hỏi thăm sức khỏe đối phương vào thời điểm trời rét đậm, đặc điểm là không viết lời chúc mừng. Trong nội dung thiệp, tôi đặc biệt chú ý đưa vào lời cảm ơn vì đã gửi bưu thiếp và những lời quan tâm đến gia đình anh Tanaka.","Cách xử lý 年賀状 khác nhau tùy từng nơi làm việc, nên cần xác nhận kỹ hướng dẫn của công ty. Thói quen gửi 年賀状 đang giảm dần, nhưng văn hóa gửi gắm tình cảm qua những lời chào theo mùa vẫn được coi trọng đến ngày nay. Qua trải nghiệm lần này, tôi học được rằng việc quan tâm đến hoàn cảnh của đối phương và thay đổi hình thức lời chào cũng là một phép lịch sự quan trọng ở nơi làm việc."],"vocab":["thời gian có tang","chuyện không may (ở đây là tang sự)","kiêng, tránh","bén rễ, trở thành thói quen","hoàn cảnh, lý do","không cần thiết","sự bận tâm, sự lo nghĩ","thiệp/thư chào hỏi","lưu ý, cố gắng làm","thông cảm, đặt mình vào vị trí người khác"],"grammar":[{"t":"〜に基づいて","note":"Diễn tả việc dựa vào một điều gì đó làm căn cứ hoặc nền tảng. Ví dụ: 「お祝いごとを慎むべきだという考え方に基づいて、この習慣が根付いた」."},{"t":"〜にすぎない","note":"Nghĩa là \"chỉ là ~ mà thôi\", nhấn mạnh mức độ hạn chế. Ví dụ: 「『年賀状を出せません』という連絡にすぎず」."},{"t":"〜わけではない","note":"Phủ định một phần, nghĩa là \"không có nghĩa là ~\", dùng để phủ nhận một cách hiểu có thể xảy ra. Ví dụ: 「相手に返事を求めているわけではない」."},{"t":"〜を通して/〜を通じて","note":"Diễn tả việc thông qua một phương tiện hoặc trải nghiệm nào đó. Ví dụ: 「季節の挨拶を通して気持ちを伝える文化」「今回の経験を通じて」."}]},"a-n3-16-n4":{"title":"Khi nhận được thiệp báo tang","topic":"Văn hóa","trans":["Đầu tháng Mười Một, anh Tanaka ở cùng công ty gửi đến một tấm bưu thiếp. Mở ra xem, trên đó viết: 「喪中なので、新年のあいさつをしません」. Đến lúc đó tôi mới biết là bố anh Tanaka đã mất vào mùa hè.","Loại này gọi là 「喪中はがき」, là bưu thiếp báo cho mọi người biết là mình sẽ không gửi 年賀状 (thiệp chúc Tết). Có quan niệm rằng trong thời gian gia đình có người mất thì không chúc mừng. Loại bưu thiếp này thường được gửi đến trước khi mọi người chuẩn bị 年賀状.","Tôi hơi phân vân, nhưng sau khi hỏi đồng nghiệp, tôi quyết định không gửi 年賀状. Đồng nghiệp bảo tôi rằng sau khi sang năm mới, nếu gửi 「寒中見舞い」 thì tấm lòng sẽ được truyền đạt. 寒中見舞い là thư hỏi thăm đối phương vào thời điểm trời lạnh, không viết lời chúc mừng. Trong thư, tôi cố gắng viết lời cảm ơn vì đã gửi bưu thiếp và những lời quan tâm đến gia đình anh ấy. Tôi học được rằng việc nghĩ cho cảm xúc của đối phương và thay đổi cách chào hỏi cũng là một phép lịch sự quan trọng."],"vocab":["được gửi đến, đến nơi","đồng nghiệp","qua đời","thông báo, báo cho biết","chuẩn bị","phân vân, lưỡng lự","được truyền đạt, được hiểu","lo lắng, quan tâm","lời cảm ơn, quà cảm ơn"],"grammar":[{"t":"〜てみると","note":"Sau khi thử làm một việc gì đó thì phát hiện ra điều gì. Ví dụ: 「開けてみると、『喪中なので、新年のあいさつをしません』と書いてあった」."},{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm hoặc không làm gì. Ví dụ: 「年賀状は出さないことにした」."},{"t":"〜てもらう","note":"Diễn tả việc nhận được hành động hoặc thông tin từ người khác, mang sắc thái biết ơn. Ví dụ: 「気持ちが伝わると教えてもらった」."},{"t":"〜ようにする","note":"Diễn tả việc cố gắng làm gì đó, cố gắng tạo thành thói quen. Ví dụ: 「家族を思う言葉を書くようにした」."}]},"a-n4-12-n2":{"title":"Tiêm phòng cúm","topic":"Sức khỏe","trans":["Vừa bước sang tháng Mười, trước cửa phòng khám gần nhà đã dán tờ thông báo 「インフルエンザ予防接種、始めました」 (đã bắt đầu tiêm phòng cúm). Nhìn tờ thông báo đó, mình mới chợt nhận ra năm nay lại đến mùa này rồi. Thật ra mùa đông năm ngoái mình bị cúm và buộc phải nghỉ làm cả một tuần. Mình cũng thấm thía rằng chăm sóc sức khỏe cũng là một phần của công việc, nên năm nay mình quyết định đi tiêm phòng sớm.","Mình gọi điện đặt lịch rồi mới đến phòng khám. Ở quầy tiếp nhận, mình được đưa phiếu khám sàng lọc, đo thể nhiệt xong thì điền tình trạng sức khỏe vào phiếu. Mũi tiêm không đau như mình tưởng, thậm chí còn hơi hụt hẫng. Sau khi tiêm, nhân viên dặn mình ngồi nghỉ ở phòng chờ một lúc để theo dõi. Vì tình trạng cơ thể có thể thay đổi đột ngột, nên nghe theo hướng dẫn và nghỉ ngơi là điều đương nhiên.","Mặt khác, tiêm phòng không được bảo hiểm y tế chi trả, nên chi phí chắc chắn không thể gọi là rẻ. Nghe nói giá khác nhau tùy bệnh viện, còn của mình là 3.500 yên. So với điều trị, phòng bệnh là sự chuẩn bị trước khi bị bệnh, nên việc tự chi trả có lẽ cũng là điều khó tránh. Dù vậy, nghĩ đến thiệt hại khi phải nghỉ làm cả tuần thì mình thấy đây không phải khoản chi quá đắt.","Nghe nói phải mất khoảng hai tuần thì vắc-xin mới có tác dụng, nên cần tiêm sớm. Đợi dịch bắt đầu lan rộng rồi mới cuống cuồng đi tiêm thì chưa chắc đã kịp. Nếu tiêm xong trước khi dịch bùng phát, bạn có thể yên tâm trải qua mùa đông."],"vocab":["tờ thông báo dán, áp phích","thấm thía, cảm nhận sâu sắc","phiếu khám sàng lọc (điền tình trạng sức khỏe trước khi tiêm/khám)","điền vào (biểu mẫu)","hụt hẫng, thất vọng vì không như mong đợi","tự chi trả, tự chịu chi phí","thiệt hại, tổn thất","khoản chi, chi phí","lưu hành, lan rộng (dịch bệnh)"],"grammar":[{"t":"〜ざるを得ない","note":"Nghĩa là \"buộc phải, đành phải\", mang sắc thái bất đắc dĩ. Ví dụ: 「一週間も会社を休まざるを得ませんでした」."},{"t":"〜に対して","note":"Dùng để đối chiếu, nghĩa là \"so với ～, trái với ～\". Ví dụ: 「治療に対して予防は病気になる前の備えである以上」."},{"t":"〜以上","note":"Nghĩa là \"đã ～ thì, vì ～ nên\", theo sau là phán đoán hoặc kết luận hợp lý. Ví dụ: 「備えである以上、自己負担になるのも仕方ない」."},{"t":"〜とは限らない","note":"Nghĩa là \"không hẳn là ～, chưa chắc ～\", dùng để phủ định cách nói tuyệt đối. Ví dụ: 「流行が始まってから慌てて接種しても、間に合うとは限りません」."}]},"a-n4-12-n3":{"title":"Tiêm phòng cúm","topic":"Sức khỏe","trans":["Vừa sang tháng Mười, phòng khám gần nhà đã dán tờ thông báo 「予防接種を始めました」 (đã bắt đầu tiêm phòng). Mùa đông năm ngoái mình bị cúm và phải nghỉ làm cả một tuần. Vì từng có trải nghiệm đó nên năm nay mình quyết định đi tiêm phòng sớm.","Mình gọi điện đặt lịch rồi mới đến phòng khám, và được đưa phiếu khám sàng lọc ở quầy tiếp nhận. Nhân viên bảo mình đo nhiệt độ trước, sau đó ghi tình trạng sức khỏe vào phiếu. Mũi tiêm không đau như mình nghĩ nên mình thấy nhẹ nhõm hơn một chút.","Xong xuôi, mình được dặn ngồi nghỉ ở phòng chờ một lúc. Vì tiêm phòng không được bảo hiểm y tế chi trả nên mình thấy hơi đắt. Nghe nói giá khác nhau tùy bệnh viện, còn của mình là 3.500 yên.","Nghe nói phải mất khoảng hai tuần thì vắc-xin mới có tác dụng. Nếu tiêm trước khi dịch bắt đầu lan rộng, bạn có thể yên tâm trải qua mùa đông. Cơ thể cần thời gian để chuẩn bị, nên mình nghĩ tiêm sớm là điều quan trọng."],"vocab":["tiêm phòng","phiếu khám sàng lọc (điền tình trạng sức khỏe trước khi tiêm/khám)","quầy tiếp nhận","phòng chờ","bảo hiểm y tế","hiệu quả, tác dụng","lưu hành, lan rộng (dịch bệnh)","sớm hơn một chút, làm sớm","tình trạng, thể trạng","giá cả"],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Trong bài: 「今年は早めに予防接種を受けることにしました」, nói về quyết định được đưa ra nhờ trải nghiệm năm ngoái."},{"t":"〜ため(原因)","note":"Nêu nguyên nhân, lý do với giọng trang trọng, mang tính văn viết hơn 「から」. Trong bài: 「予防接種には健康保険が使えないため、少し高いと感じました」."},{"t":"〜ように言われる","note":"Diễn tả việc bị ai đó yêu cầu, dặn làm gì (lời chỉ dẫn được dẫn lại gián tiếp). Trong bài: 「問診票に書くように言われました」「待合室で休むように言われました」."},{"t":"〜によって","note":"Nghĩa là \"tùy theo…\", chỉ sự khác nhau tùy đối tượng hoặc tình huống. Trong bài: 「値段は病院によって違うそうですが」."}]},"a-n4-13-n2":{"title":"Ngày Shichi-Go-San (七五三の日)","topic":"Văn hóa","trans":["Vào một ngày thứ Bảy của tháng Mười Một, tôi cùng một người bạn đi dạo đến ngôi đền gần nhà. Vừa bước vào khuôn viên đền, tôi đã thấy rất nhiều đứa trẻ mặc những bộ kimono lộng lẫy cùng gia đình của các em. Trong số đó, hình ảnh một bé gái nhỏ mặc kimono màu đỏ chụp ảnh với vẻ mặt vui sướng thấy rõ đã để lại cho tôi ấn tượng đặc biệt.","Theo anh Tanaka, người bạn Nhật của tôi, đây là một lễ hội gọi là Shichi-Go-San (七五三). Shichi-Go-San là lễ mừng các bé tròn ba tuổi, năm tuổi và bảy tuổi lớn lên khỏe mạnh, đồng thời tạ ơn vì các bé đã bình an trưởng thành đến nay. Thông thường, gia đình sẽ nhờ đền cầu nguyện, mong con tiếp tục lớn lên khỏe mạnh. Cách tổ chức có thể không giống nhau ở mỗi gia đình, nhưng tấm lòng mong con khỏe mạnh có lẽ ở đâu cũng giống nhau.","Anh Tanaka chỉ vào những chiếc túi giấy dài mà bọn trẻ đang cầm và tiếp tục giải thích cho tôi. Bên trong túi có loại kẹo dài và mảnh gọi là Chitose-ame (千歳飴), nghe nói gửi gắm mong ước của gia đình là con sẽ sống lâu. Anh Tanaka còn cho tôi biết Chitose-ame cũng có thể mua ở các tiệm bánh kẹo truyền thống Nhật (和菓子屋).","Đối với anh Tanaka thì đây là một lễ hội quen thuộc, còn với tôi thì đó là cảnh tượng lần đầu được thấy, và tôi cảm thấy rất mới mẻ. Dù chỉ là viên kẹo trông giản dị, nhưng khi biết tình cảm gửi gắm trong đó sâu sắc đến nhường nào, tôi không thể không suy nghĩ về ý nghĩa của lễ hội này. Nếu sau này có con, chắc tôi cũng sẽ không kìm được mà chuẩn bị Chitose-ame để chúc mừng con lớn lên."],"vocab":["Khuôn viên đền, chùa","Khoác lên người, mặc (身にまとう)","Gây ấn tượng, đáng nhớ","Sự kiện thường niên, nghi lễ truyền thống","Sự trưởng thành, lớn lên","Điều ước, nguyện vọng","Giản dị, mộc mạc","Cảnh tượng, quang cảnh","Chung, giống nhau"],"grammar":[{"t":"〜とは限らない","note":"Nghĩa là \"không nhất thiết…\", chỉ ra rằng không phải lúc nào cũng vậy. Ví dụ: 「祝い方は家庭によって同じとは限らないが」 nghĩa là cách mừng ở mỗi gia đình không nhất thiết giống nhau."},{"t":"〜に対して","note":"Diễn tả sự đối lập: \"trong khi A thì B…\". Ví dụ: 「田中さんにとっては身近な行事であるのに対して、わたしには初めて目にする光景で」 đối chiếu cảm nhận của anh Tanaka với cảm nhận của người viết."},{"t":"〜ざるを得ない","note":"Nghĩa là \"đành phải…, không thể không…\", khi không còn lựa chọn nào khác. Ví dụ: 「行事の意味を考えざるを得なかった」 nghĩa là không thể không suy nghĩ về ý nghĩa của lễ hội."},{"t":"〜ずにはいられない","note":"Nghĩa là \"không thể không…, không kìm được mà…\", diễn tả cảm xúc hay thôi thúc tự nhiên trào lên. Ví dụ: 「成長を祝わずにはいられないだろう」 nghĩa là chắc chắn sẽ không kìm được mà muốn chúc mừng sự lớn lên của con."}]},"a-n4-13-n3":{"title":"Ngày Shichi-Go-San (七五三の日)","topic":"Văn hóa","trans":["Vào một ngày thứ Bảy của tháng Mười Một, tôi cùng bạn đi dạo đến ngôi đền gần nhà. Trong khuôn viên đền có thể thấy rất nhiều đứa trẻ mặc kimono đẹp cùng gia đình của các em. Một bé gái nhỏ mặc kimono màu đỏ đang nở nụ cười vui vẻ để gia đình chụp ảnh cho. Nơi đây nhộn nhịp hơn hẳn ngày thường, mang không khí như một ngày đặc biệt.","Anh Tanaka, người bạn Nhật của tôi, cho biết đây là lễ hội gọi là Shichi-Go-San (七五三). Shichi-Go-San là lễ hội để chúc mừng sự lớn lên của các bé tròn ba tuổi, năm tuổi và bảy tuổi. Nghe nói gia đình sẽ nhờ đền cầu nguyện và mong con lớn lên khỏe mạnh. Tôi nghĩ đối với gia đình, đây cũng là dịp quan trọng để cảm nhận lại sự trưởng thành của con.","Anh Tanaka chỉ vào những chiếc túi giấy dài mà bọn trẻ đang cầm. Bên trong có loại kẹo dài và mảnh gọi là Chitose-ame (千歳あめ). Nghe nói loại kẹo này gửi gắm mong ước của gia đình là con sẽ sống lâu. Anh Tanaka nói Chitose-ame cũng có thể mua ở các tiệm bánh kẹo truyền thống Nhật (和菓子屋). Nếu sau này có con, tôi cũng muốn chuẩn bị Chitose-ame và chúc mừng con theo cách như vậy."],"vocab":["Khuôn viên (đền, chùa)","Sự kiện thường niên, nghi lễ truyền thống","Sự trưởng thành, lớn lên","Chúc mừng, ăn mừng","Cầu nguyện, cầu phúc","Lớn lên, trưởng thành","Điều ước, nguyện vọng","Dài và mảnh","Tương lai","Chuẩn bị"],"grammar":[{"t":"〜ように(mục đích・mong ước)","note":"Diễn tả việc làm gì đó hoặc cầu mong để đạt được một trạng thái nào đó. Ví dụ: 「子どもが元気に育つようにとお願いするそうです」"},{"t":"〜てもらう","note":"Diễn tả việc nhờ người khác làm gì cho mình hoặc người thuộc phía mình và nhận được ơn huệ đó. Ví dụ: 「家族に写真をとってもらっていました」「お祈りをしてもらい」"},{"t":"〜てほしい","note":"Diễn tả mong muốn đối phương làm việc gì đó hoặc ở trong trạng thái nào đó. Ví dụ: 「長生きしてほしいという家族の願い」"},{"t":"〜そうです(nghe nói)","note":"Diễn tả thông tin nghe được từ người khác. Ví dụ: 「願いがこめられているそうです」"}]},"a-n4-14-n2":{"title":"Làm quen với tiền điện mùa đông","topic":"Đời sống","trans":["Mùa đông ở Nhật không chỉ lạnh ngoài trời mà ngay cả trong nhà cũng lạnh hơn bạn tưởng. Ở những căn phòng cũ, không khí lạnh lùa vào qua khe cửa sổ nên dù bật máy sưởi cũng khó mà ấm lên được. Khi nhiệt độ giảm xuống, thời gian buộc phải dựa vào máy sưởi cũng dài ra. Tháng trước, khi xem hóa đơn gửi đến, mình thấy tiền điện cao hơn bình thường khá nhiều và không khỏi giật mình.","Mình kể chuyện đó với một người bạn và được chỉ cho khá nhiều mẹo tiết kiệm. Trước hết là dùng chăn điện để làm ấm chăn đệm trước khi đi ngủ. Nghe nói máy sưởi thì làm tăng nhiệt độ phòng, còn máy tạo ẩm thì giúp mình cảm thấy ấm hơn dù nhiệt độ phòng vẫn như vậy.","Sau khi đổi sang rèm dày, cái lạnh ở gần cửa sổ giảm đi thấy rõ, mình thực sự cảm nhận được hiệu quả lớn thế nào. Mình cũng đặt nhiệt độ máy sưởi thấp hơn một chút và mặc thêm áo khoác để bù lại. Anh Tanaka còn khuyên mình nên tắt máy sưởi ở những phòng không dùng.","Còn về gói cước điện, thay vì tự phán đoán thì hỏi công ty điện lực để biết thông tin chi tiết sẽ chắc chắn hơn. Chịu lạnh không phải lúc nào cũng là tiết kiệm, chỉ cần khéo léo trong cách dùng và dụng cụ cũng có thể giảm bớt gánh nặng. Nếu tiếp tục những mẹo nhỏ này, mùa đông năm nay có vẻ mình cũng sẽ không phải lo lắng quá nhiều về tiền điện."],"vocab":["(nhiệt độ) giảm mạnh, trở nên rất lạnh","khe hở","hóa đơn, giấy thanh toán","tiết kiệm","làm ấm, đun nóng","dịu đi, giảm bớt","cảm nhận thực tế","lời khuyên","hỏi thăm, liên hệ hỏi","chịu đựng, nhẫn nại"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Trong bài: 「気温が下がるのに伴って、どうしても暖房に頼らざるを得ない時間が長くなります」"},{"t":"〜ざるを得ない","note":"Diễn tả việc buộc phải làm, không còn cách nào khác (động từ thể ない bỏ ない + ざるを得ない). Trong bài: 「暖房に頼らざるを得ない時間」"},{"t":"〜に対して","note":"Diễn tả sự đối lập, hai vế tạo thành sự so sánh tương phản. Trong bài: 「暖房が室温を上げるのに対して、加湿器は同じ室温でも暖かく感じさせてくれるそうです」"},{"t":"〜とは限らない","note":"Diễn tả điều đó không hẳn là như vậy, dùng để phủ định suy nghĩ quá tuyệt đối. Trong bài: 「寒さを我慢することだけが節約とは限らず」"}]},"a-n4-14-n3":{"title":"Tiền điện mùa đông","topic":"Đời sống","trans":["Mùa đông ở Nhật, dù ở trong nhà cũng cảm thấy lạnh hơn mình tưởng. Ở những căn phòng cũ, vì không khí lạnh lùa vào từ cửa sổ nên dù bật máy sưởi cũng khó mà ấm lên được. Tháng trước, khi xem hóa đơn, mình thấy tiền điện cao hơn mọi khi nên rất ngạc nhiên. Vì thế mình hỏi ý kiến một người bạn và được chỉ cho vài mẹo tiết kiệm.","Trước hết, mình dùng chăn điện để làm ấm chăn đệm trước khi đi ngủ. Nghe nói khi bật máy tạo ẩm, dù nhiệt độ phòng không đổi thì vẫn cảm thấy ấm hơn. Từ khi đổi sang rèm dày, cái lạnh cảm nhận được gần cửa sổ giảm đi khá nhiều. Mình đặt nhiệt độ máy sưởi thấp hơn một chút và thay vào đó quyết định mặc thêm áo khoác.","Anh Tanaka bảo mình nên tắt máy sưởi ở những phòng không dùng. Về gói cước điện, nên hỏi công ty điện lực để biết thông tin chi tiết. Chỉ cần tiếp tục những mẹo nhỏ, có vẻ mình sẽ qua mùa đông mà không phải lo lắng quá nhiều về tiền điện. Mình cảm thấy điều quan trọng không phải là chịu đựng cái lạnh, mà là biết khéo léo nghĩ cách."],"vocab":["máy sưởi","hóa đơn","bàn bạc, hỏi ý kiến","tiết kiệm","máy tạo ẩm","cài đặt","trải qua, sống qua","sự khéo léo, mẹo hay","chi phí, mức phí"],"grammar":[{"t":"〜ため(nguyên nhân)","note":"Diễn tả nguyên nhân, lý do, mang tính văn viết hơn 「から」. Ví dụ: 「古い部屋では窓から冷たい空気が入ってくるため、暖房をつけてもなかなかあたたまりません」"},{"t":"〜ようにしている","note":"Diễn tả việc cố gắng tạo thói quen, cố gắng làm điều gì đó. Ví dụ: 「寝る前にふとんをあたためておくようにしています」"},{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Ví dụ: 「そのかわり上着を着て過ごすことにしました」"},{"t":"〜わけではない","note":"Diễn tả phủ định một phần, \"không phải là...\". Ví dụ: 「寒さをがまんするわけではなく、上手に工夫することが大切だと感じました」"}]},"a-n4-15-n2":{"title":"Dọn dẹp cuối năm, nên bắt đầu sớm","topic":"Đời sống","trans":["Cứ đến tháng Mười Hai hằng năm, tôi lại bị cuốn vào việc tổng vệ sinh nhà cửa và mệt rã rời, gần như đã thành thông lệ cuối năm của tôi. Vì vậy năm nay, trước khi bước sang tháng Mười Hai, tôi quyết định viết ra danh sách những chỗ cần dọn. Nhà bếp, phòng tắm, cửa sổ, lối vào nhà… khi thực sự viết ra mới nhận thấy có nhiều chỗ hơn tôi tưởng.","Tiếp theo, tôi đến cửa hàng dược mỹ phẩm mua đủ nước tẩy rửa và miếng bọt biển dùng để dọn dẹp. Nhân viên cửa hàng cho biết nước tẩy dùng cho phòng tắm còn tẩy được cả nấm mốc, thông tin này rất hữu ích với tôi. Tuy nhiên, nếu cố làm hết một lượt thì sẽ rất mệt, nên tôi quyết định mỗi tuần chỉ dọn một chỗ.","Ví dụ tuần này là nhà bếp, tuần sau là phòng tắm; nếu quyết định trước chỗ dọn cho từng tuần thì có thể tiến hành mà không bị quá sức. Tôi kể kế hoạch này với bạn cùng phòng là Lin, bạn ấy bảo sẽ cùng làm. Tôi phụ trách nhà bếp và phòng tắm, còn Lin phụ trách cửa sổ và lối vào nhà. Còn về rác cồng kềnh, cách vứt khác nhau tùy từng khu vực, nên cần xem hướng dẫn của ủy ban quận để xác nhận.","Theo lời một người bạn, nếu bắt đầu sớm thì không chỉ việc dọn dẹp mà cả tinh thần cũng nhẹ nhõm hơn. Quả thật, làm trong lúc bị thời gian cuối năm thúc ép và làm một cách thong thả thì mức độ mệt chắc chắn hoàn toàn khác nhau. Với cách này, tôi đang rất mong chờ cuối năm nay có thể nghỉ ngơi thật thoải mái."],"vocab":["thông lệ, việc cố định hằng năm","mệt rã rời, kiệt sức","viết ra, liệt kê","mua đủ","nước tẩy rửa, chất tẩy rửa","phụ trách, đảm nhiệm","ủy ban quận (cơ quan hành chính quận)","xác nhận, kiểm tra lại","sự thong thả, dư dả"],"grammar":[{"t":"〜たところ","note":"Diễn tả sau khi làm một hành động thì nhận được kết quả bất ngờ hoặc cụ thể. Ví dụ: 「リンさんにこの計画を話したところ、いっしょにやろうと言ってくれました」"},{"t":"〜によると","note":"Chỉ nguồn của tin tức, thông tin; phía sau thường đi với 「〜そうだ、〜ということだ」. Ví dụ: 「店の人によると、おふろ用の洗剤はカビも落とせるということで」"},{"t":"〜によって違う","note":"Diễn tả sự khác nhau tùy theo đối tượng, khu vực, tình huống. Ví dụ: 「出し方が地域によって違うため、区役所の案内で確認しておく必要があります」"},{"t":"〜のと〜のとでは","note":"So sánh hai cách làm hoặc hai trạng thái, chỉ ra sự khác biệt lớn giữa chúng. Ví dụ: 「年末に追われながらやるのと、余裕を持って進めるのとでは、疲れ方がまったく違うでしょう」"}]},"a-n4-15-n3":{"title":"Dọn dẹp cuối năm, hãy bắt đầu sớm nào","topic":"Đời sống","trans":["Cứ đến tháng Mười Hai hằng năm, tôi lại bị cuốn vào việc tổng vệ sinh và lúc nào cũng mệt lả người. Vì vậy năm nay, trước khi bước sang tháng Mười Hai, tôi đã thử liệt kê những chỗ cần dọn thành một danh sách. Nhà bếp, phòng tắm, cửa sổ, lối vào nhà… nhiều hơn tôi nghĩ, khiến tôi khá ngạc nhiên.","Tiếp theo, tôi đến cửa hàng dược mỹ phẩm mua nước tẩy rửa và miếng bọt biển. Theo nhân viên cửa hàng, nước tẩy dùng cho phòng tắm còn tẩy sạch được cả nấm mốc. Vì làm hết một lượt sẽ rất mệt, nên tôi quyết định mỗi tuần chỉ dọn một chỗ. Tôi đã định sẵn thứ tự: tuần này nhà bếp, tuần sau phòng tắm, cứ thế tiếp tục.","Tôi kể với bạn cùng phòng là Lin, bạn ấy nói sẽ cùng làm. Tôi phụ trách nhà bếp và phòng tắm, còn Lin phụ trách cửa sổ và lối vào nhà. Về rác cồng kềnh, cần tra cách vứt qua hướng dẫn của ủy ban quận trước. Theo lời một người bạn, bắt đầu sớm thì tinh thần cũng thoải mái hơn. Với cách này, tôi có thể duy trì mà không bị quá sức, nên tôi nghĩ cuối năm mình cũng sẽ được nghỉ ngơi thong thả."],"vocab":["bị cuốn vào, bị thúc ép, bận rộn xoay xở","nước tẩy rửa, chất tẩy rửa","có thể tẩy được (vết bẩn, v.v.)","thứ tự, lượt","phụ trách, đảm nhiệm","ủy ban quận (cơ quan hành chính quận)","tra cứu, tìm hiểu","sự thong thả, dư dả","ngạc nhiên, giật mình"],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Trong bài: 「毎週一か所だけそうじすることにしました」 nghĩa là tôi quyết định mỗi tuần chỉ dọn một chỗ."},{"t":"〜によると〜そうだ","note":"Dẫn nguồn tin và truyền đạt thông tin nghe được. Trong bài: 「店の人によると、おふろ用の洗剤はカビもきれいに落とせるそうです」."},{"t":"〜というように","note":"Dùng để nêu ví dụ, nghĩa là \"như thế này\". Trong bài: 「今週は台所、来週はおふろ、というように、順番を決めておきました」."},{"t":"〜ことになる","note":"Diễn tả kết quả hoặc sự sắp xếp trở thành như vậy (không hoàn toàn do ý muốn cá nhân). Trong bài: 「リンさんはまどとげんかんを担当することになりました」."},{"t":"〜ため(nguyên nhân)","note":"Diễn tả nguyên nhân, lý do, mang tính văn viết hơn 「ので」. Trong bài: 「一度に全部やろうとすると疲れてしまうため」."}]},"a-n5-11-n2":{"title":"Trải nghiệm đầu tiên với thẻ IC","topic":"Cuộc sống","trans":["Mới đến Nhật chưa lâu, mình quyết định mua thẻ IC đầu tiên trong đời ở máy tại nhà ga. Mình bỏ một nghìn yên vào máy, làm xong thủ tục thì nhận được thẻ dễ đến mức bất ngờ. Trước giờ mình luôn nghĩ mua vé giấy là chuyện đương nhiên, nên sự tiện lợi này khiến mình hơi ngạc nhiên.","Khi đi tàu, chỉ cần chạm thẻ ở cổng soát vé là sẽ có một tiếng \"píp\" ngắn vang lên. Nhờ không còn mất thời gian mua vé, việc di chuyển trong nhà ga trở nên suôn sẻ hơn trước nhiều. Hơn nữa, nơi dùng được thẻ này không nhất thiết chỉ có tàu điện. Thẻ còn dùng để thanh toán trên xe buýt và ở cửa hàng tiện lợi, nên hữu ích trong rất nhiều tình huống của cuộc sống hằng ngày.","Thế nhưng hôm qua, khi định đi qua cổng soát vé thì có một tiếng \"ting tong\" rất lớn vang lên. Nguyên nhân là tiền trong thẻ không đủ. Trước tiếng động lớn bất ngờ đó, mình không biết phải làm sao và chỉ biết bối rối. Lúc ấy, nhân viên nhà ga đã tử tế chỉ cho mình: \"Bạn hãy nạp tiền ở máy bên kia nhé\".","Qua trải nghiệm này, mình thấm thía rằng thẻ không phải cứ mua xong là hết chuyện, việc quản lý số dư cũng rất quan trọng. Vì vậy bây giờ, trước khi vào ga mình luôn kiểm tra số dư trong thẻ. Tuy chỉ là một thói quen nhỏ, nhưng chỉ nhờ vậy mà mình đã có thể lên tàu mà không bị cuống."],"vocab":["mua, mua vào","cổng soát vé","không cần thiết","thanh toán","vang lên, vọng lại","số dư","bối rối, lúng túng","thấm thía, cảm nhận sâu sắc","thói quen","nhân viên nhà ga"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ:「切符を買う時間が不要になるに伴って、駅での移動は以前よりずっとスムーズになりました」"},{"t":"〜とは限らない","note":"Nghĩa là \"không nhất thiết\", phủ định suy nghĩ quá tuyệt đối. Ví dụ:「このカードが使える場所は、電車だけとは限りません」"},{"t":"〜に対して","note":"Diễn tả phản ứng hướng đến một đối tượng hoặc tình huống nào đó. Ví dụ:「突然の大きな音に対して、どうすればよいか分からず、戸惑わざるを得ませんでした」"},{"t":"〜ざるを得ない","note":"Nghĩa là \"đành phải, buộc phải\", mang sắc thái bất đắc dĩ. Ví dụ:「戸惑わざるを得ませんでした」"}]},"a-n5-11-n3":{"title":"Thẻ IC đầu tiên của mình","topic":"Cuộc sống","trans":["Vừa đến Nhật, mình đã mua thẻ IC lần đầu tiên ở máy tại nhà ga. Bỏ một nghìn yên vào máy là nhận được thẻ, dễ hơn mình tưởng nên mình thấy yên tâm hẳn.","Khi đi tàu, chỉ cần chạm thẻ ở cổng soát vé là đi qua được. Lúc đó sẽ có một tiếng \"píp\" ngắn vang lên, nên bạn biết ngay là thẻ đã dùng được.","Có thẻ IC thì không mất thời gian mua vé, rất tiện. Không chỉ tàu điện mà xe buýt và cửa hàng tiện lợi cũng dùng được, nên thẻ giúp ích nhiều cho cuộc sống hằng ngày của mình.","Thế nhưng hôm qua, ở cổng soát vé đã vang lên một tiếng \"ting tong\" rất lớn. Nguyên nhân là tiền trong thẻ không đủ.","Đang lúng túng thì nhân viên nhà ga chỉ cho mình: \"Bạn hãy nạp tiền ở máy bên kia nhé\". Nhờ vậy mình đã đi qua cổng soát vé một cách suôn sẻ.","Qua trải nghiệm này, mình học được rằng trước khi dùng thẻ, kiểm tra số tiền còn lại là việc quan trọng. Bây giờ, trước khi vào ga mình quyết định luôn xem số tiền trong thẻ."],"vocab":["cổng soát vé","máy móc, máy","yên tâm, an tâm","vé","tiện lợi","hữu ích, có ích","đủ","nguyên nhân","nạp tiền","kiểm tra, xác nhận"],"grammar":[{"t":"〜ため(原因・理由)","note":"Diễn tả nguyên nhân, lý do, mang sắc thái trang trọng, văn viết hơn「から」. Ví dụ:「切符を買う時間がかからないため、とても便利です」"},{"t":"〜によって","note":"Diễn tả nguyên nhân hoặc phương tiện, nghĩa là \"nhờ, do, bằng\". Ví dụ:「この経験によって、使う前に残りのお金を確認することが大切だと学びました」"},{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Ví dụ:「必ずカードのお金を見ることにしています」"},{"t":"〜だけでなく","note":"Nghĩa là \"không chỉ… mà còn…\". Ví dụ:「電車だけでなく、バスやコンビニでも使えます」"}]},"a-n5-12-n2":{"title":"Oden ở cửa hàng tiện lợi","topic":"Đời sống","trans":["Một đêm mùa đông, như bị cái lạnh bên ngoài cuốn hút, tôi bước vào cửa hàng tiện lợi. Cạnh quầy thu ngân có xếp nồi oden, vừa bước vào cửa hàng là mùi thơm hấp dẫn đã bay đến. Ngoài mùi thơm, tôi còn thấy đói bụng, nên không thể không mua oden.","Khi nhiệt độ giảm xuống, oden bắt đầu được bày ở cửa hàng tiện lợi. Tôi gọi nhân viên và nhờ họ cho củ cải trắng và trứng vào. Sau đó nhân viên lịch sự hỏi tôi có cần nước dùng và mù tạt vàng không. Trước câu hỏi của nhân viên, tôi trả lời chỉ cần nước dùng thôi.","Thanh toán xong, tôi không ghé đâu cả mà về thẳng nhà. Về đến nhà, nghĩ rằng phải ăn trước khi nguội, tôi bắt đầu ăn ngay. Khi đưa miếng oden nóng hổi vào miệng, cơ thể vốn đã lạnh cóng dần ấm lên từ bên trong. Củ cải thấm đẫm nước dùng có vị ngon đặc biệt trong đêm lạnh.","Xét ở điểm có thể dễ dàng ăn được món nóng, có thể nói oden ở cửa hàng tiện lợi là người bạn đồng hành đắc lực của mùa đông. Không chỉ những món đắt tiền mới mang lại cảm giác thỏa mãn, đôi khi chính những món ăn gần gũi như thế này lại cứu rỗi ta. Khi mùa lạnh đến, có lẽ tôi lại muốn ăn món oden ấy."],"vocab":["bay đến, lan tỏa (mùi)","bụng đói","nhiệt độ không khí","cửa hàng, trước cửa tiệm","hỏi, hỏi thăm","lịch sự, cẩn thận","hoàn tất, xong xuôi","nguội đi","đặc biệt, khác thường","gần gũi, thân quen"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một sự thay đổi diễn ra thì một thay đổi khác cũng diễn ra đồng thời, nghĩa là \"cùng với, theo đà…\". Ví dụ: 「気温が下がるのに伴って、コンビニの店頭にはおでんが並ぶようになる」"},{"t":"〜ざるを得ない","note":"Nghĩa là \"đành phải, không thể không ~\", là lựa chọn bất đắc dĩ do hoàn cảnh ép buộc. Ví dụ: 「おでんを買わざるを得ない気持ちになった」"},{"t":"〜に対して","note":"Chỉ đối tượng mà hành động hoặc thái độ hướng tới, thường dịch là \"đối với, trước, đáp lại\". Ví dụ: 「店員の質問に対して、私はつゆだけお願いしますと答えた」"},{"t":"〜とは限らない","note":"Nghĩa là \"không hẳn là ~, chưa chắc ~\", dùng để phủ định cách nói quá tuyệt đối. Ví dụ: 「高価な料理だけが満足感を与えるとは限らず」"}]},"a-n5-12-n3":{"title":"Oden ở cửa hàng tiện lợi","topic":"Đời sống","trans":["Vào một đêm đông rất lạnh, tôi thèm ăn món gì đó nóng nên bước vào cửa hàng tiện lợi. Tôi nhận ra cạnh quầy thu ngân có đặt nồi oden. Mùi thơm bay đến, bụng tôi bỗng đói cồn cào.","Nhìn nồi oden, món nào trông cũng ngon nên tôi phân vân, nhưng cuối cùng quyết định chọn củ cải trắng và trứng. Tôi nói với nhân viên: 「Cho tôi củ cải trắng và trứng.」 Sau đó nhân viên hỏi tôi có cần nước dùng và mù tạt vàng không. Tôi suy nghĩ một chút rồi trả lời: 「Chỉ cần nước dùng thôi, cảm ơn bạn.」","Về đến nhà, tôi quyết định ăn ngay khi còn chưa nguội. Trong lúc ăn oden nóng hổi, cơ thể đang lạnh dần dần ấm lên. Vào đêm lạnh, tôi thấy biết ơn vì có món ăn nóng mua được dễ dàng như thế này."],"vocab":["nhận ra, để ý thấy","đột nhiên, bỗng","phân vân, lưỡng lự","chọn","nhân viên cửa hàng","cần thiết, cần","nguội đi","lạnh đi, bị lạnh","dần dần","đáng biết ơn, quý giá"],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc bản thân quyết định làm gì đó. Trong bài: quyết định vào cửa hàng 「コンビニに入りました」, 「だいこんとたまごを選ぶことにしました」, 「すぐ食べることにしました」."},{"t":"〜うちに","note":"Diễn tả làm việc gì đó trong lúc một trạng thái còn đang tiếp diễn, hoặc có sự thay đổi xảy ra trong khi một hành động đang diễn ra. Trong bài: 「冷めないうちにすぐ食べる」, 「食べているうちに、冷えていた体がだんだん温かくなってきました」."},{"t":"〜かどうか","note":"Nghĩa là \"có ... hay không\", lồng một câu hỏi có/không vào trong câu. Trong bài: 「つゆとからしが必要かどうかを聞いてくれました」."},{"t":"〜てくる","note":"Diễn tả sự thay đổi hoặc trạng thái dần xuất hiện, hướng về phía người nói. Trong bài: 「いいにおいがしてきて」, 「だんだん温かくなってきました」."}]},"a-n5-13-n2":{"title":"Mua sắm mùa đông","topic":"Đời sống","trans":["Gần đây sáng và tối trời lạnh buốt hơn, khiến mình cảm nhận rõ mùa đông thực sự đã đến. Khi nhiệt độ giảm xuống, mình bắt đầu nghĩ rằng đã đến lúc cần sắm quần áo ấm mới. Vì vậy vào thứ Bảy, mình quyết định cùng bạn đến một cửa hàng để mua sắm.","Mình muốn có một chiếc áo khoác màu đen, nên ngay từ đầu đã định chỉ tìm loại đen tuyền. Thế nhưng bạn mình nói biết đâu áo khoác đỏ cũng hợp với mình, rồi gợi ý cho mình một lựa chọn khác. Mình nghĩ quả thật không phải lúc nào chỉ có màu đen mới là đáp án đúng, nên đã cầm thử chiếc áo khoác đỏ mà mình để ý. Mình hỏi nhân viên cửa hàng「着てもいいですか」(Tôi mặc thử được không ạ?), sau đó thực sự mặc thử.","Khi mặc thử, chiếc áo khoác đỏ đẹp hơn mình tưởng rất nhiều, khiến mình bất giác ngắm mãi không rời mắt. Cuối cùng, mình quyết định không mua màu đen mà mua chiếc áo khoác đỏ đó. Ngoài ra, mình còn mua thêm găng tay và khăn quàng cổ, nhờ vậy đã chuẩn bị đồ chống lạnh tương đối đầy đủ. Ba món mình chọn đều là màu mình thích, và mình cũng rất ưng sự đồng bộ về màu sắc.","Trước khi đi mua sắm, mình luôn nghĩ \"nhất định phải là màu đen\", nhưng nhờ một câu nói của bạn mà tầm nhìn của mình được mở rộng. Không cố chấp với sở thích của bản thân mà lắng nghe ý kiến của người khác, đôi khi sẽ giúp ta khám phá ra điều mới. Chính vì là mùa lạnh giá, mình muốn mặc những bộ đồ mình ưng ý và đón mùa đông với tâm trạng tích cực."],"vocab":["(nhiệt độ) giảm mạnh, lạnh buốt hơn","quần áo chống lạnh","hợp, vừa với (ai)","gợi ý, giới thiệu, khuyên (dùng)","mặc (quần áo) vào","ngắm đến mê mẩn","đại khái, về cơ bản là đủ cả","cố chấp, khăng khăng giữ ý mình","tầm nhìn, tầm mắt"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một sự thay đổi xảy ra thì một sự thay đổi khác cũng diễn ra theo (cùng với, theo đà). Ví dụ:「気温が下がるに伴って、そろそろ新しい防寒着が必要だと考えるようになった」"},{"t":"〜とは限らない","note":"Nghĩa là \"chưa chắc\", \"không phải lúc nào cũng\", dùng để phủ định một suy nghĩ quá tuyệt đối. Ví dụ:「確かに黒だけが正解とは限らないと思い」"},{"t":"〜ず(に)","note":"Dạng phủ định văn viết của「ない」, tương đương「〜ないで」. Động từ する chuyển thành「せず」. Ví dụ:「自分の好みに固執せず」"},{"t":"〜からこそ","note":"Nhấn mạnh \"chính vì lý do này\", mang sắc thái khẳng định mạnh mẽ. Ví dụ:「寒さの厳しい季節だからこそ」"}]},"a-n5-13-n3":{"title":"Mua sắm mùa đông","topic":"Đời sống","trans":["Gần đây trời đột nhiên trở lạnh, nên mình muốn mua quần áo mùa đông mới. Thứ Bảy, mình quyết định cùng bạn đến cửa hàng mua sắm. Từ trước mình đã muốn có một chiếc áo khoác đen, nên định đi tìm chiếc áo đó.","Thế nhưng bạn mình nói「赤いのもいいよ」(Cái màu đỏ cũng đẹp đó), khiến mình hơi phân vân. Mình không phải là người nhất định phải màu đen, nên quyết định hỏi nhân viên cửa hàng. Khi mình hỏi「着てみてもいいですか」(Tôi mặc thử được không ạ?), nhân viên vui vẻ cho mình thử đồ.","Mặc thử xong, chiếc áo khoác đỏ đẹp hơn mình nghĩ nhiều. Cuối cùng, ngoài chiếc áo khoác đó, mình còn mua thêm găng tay và khăn quàng cổ. Món nào cũng là màu mình thích, nên mình rất mong được phối chúng với nhau. Có những món này, dù là mùa đông lạnh giá chắc mình cũng có thể thoải mái ra ngoài."],"vocab":["đột nhiên","tìm kiếm","phân vân, lưỡng lự","câu nệ, cầu kỳ về","mặc thử (quần áo)","vui vẻ, sẵn lòng","cuối cùng, rốt cuộc","găng tay","phối hợp, kết hợp","sự mong đợi, niềm vui chờ đón"],"grammar":[{"t":"〜ため(に)","note":"Diễn tả nguyên nhân, lý do, mang sắc thái văn viết hơn「から」. Ví dụ:「最近は急に寒くなってきたため」"},{"t":"〜ことにする","note":"Diễn tả việc người nói tự quyết định làm điều gì. Ví dụ:「友だちと一緒に店へ買い物に行くことにしました」"},{"t":"〜わけではない","note":"Nghĩa là \"không phải là...\", phủ định một phần. Ví dụ:「黒い色にこだわっていたわけではないので」"},{"t":"〜そうだ(dạng phỏng đoán)","note":"Gắn vào thân động từ dạng ます hoặc thân tính từ, diễn tả suy đoán dựa trên vẻ bề ngoài hay tình hình. Ví dụ:「これなら気持ちよく出かけられそうです」"}]},"a-n5-14-n2":{"title":"友達と鍋を囲む冬の夜","topic":"Đời sống","trans":["Vào một ngày mùa đông trời ngày càng lạnh, tôi quyết định cùng bạn bè ăn lẩu ở nhà. Lẩu chuẩn bị tương đối đơn giản nên tôi thấy rất hợp khi muốn tụ tập ăn uống. Đầu tiên, để mua đủ nguyên liệu, cả nhóm cùng đi siêu thị.","Ở cửa hàng, chúng tôi vừa bàn bạc vừa quyết định mua cải thảo, đậu phụ và thịt. Nhiều người cho rằng lẩu mùa đông không thể thiếu cải thảo, và tôi cũng là một trong số đó. Chỉ riêng việc đi mua đồ, nếu có bạn bè đi cùng thì cũng thấy vui hơn bình thường.","Về đến nhà, chúng tôi lập tức thái rau và chuẩn bị cho vào nồi. Chúng tôi nấu theo thứ tự cho rau vào trước, thịt cho vào sau. Thịt rất nhanh chín nên nếu cho vào quá sớm thì đôi khi sẽ bị dai. Khi nồi lẩu sôi lên, căn phòng cũng dần ấm lên.","Dù bên ngoài là một đêm lạnh giá, trong phòng lại được bao bọc bởi làn hơi nước ấm áp. Cùng nhau gắp ăn từ một nồi lẩu, món ăn có vẻ ngon hơn hẳn. Tuy nhiên, có món ngon trên bàn ăn cũng không nhất thiết sẽ có một khoảng thời gian vui vẻ. Chính vì được ở bên những người bạn thân thiết, không cần khách sáo, nên dù là đêm lạnh tôi vẫn thấy vui từ tận đáy lòng."],"vocab":["vây quanh, quây quần","tương đối, so sánh ra","nguyên liệu","không thể thiếu","bắt tay vào làm","thêm vào, cho thêm","chín, sôi","hơi nước, hơi nóng","thân thiết, không cần khách sáo"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một sự thay đổi diễn ra thì một sự thay đổi khác cũng diễn ra song song, nghĩa là \"cùng với, theo đà…\". Ví dụ trong bài: 「鍋が煮えるに伴って、部屋の中もだんだん暖かくなっていった」"},{"t":"〜にもかかわらず","note":"Nghĩa là \"mặc dù… nhưng…\", vế trước và vế sau đối lập ngoài dự đoán. Ví dụ trong bài: 「外は寒い夜だったにもかかわらず、部屋の中は温かい湯気に包まれていた」"},{"t":"〜とは限らない","note":"Nghĩa là \"không nhất thiết…\", dùng để phủ định suy nghĩ quá tuyệt đối. Ví dụ trong bài: 「おいしい料理が食卓にあるからといって、必ず楽しい時間になるとは限らない」"},{"t":"〜からこそ","note":"Nhấn mạnh \"chính vì… nên mới…\", chỉ ra lý do thật sự. Ví dụ trong bài: 「気の置けない友達と一緒に過ごせたからこそ、寒い夜でも心から楽しかったのだと思う」"}]},"a-n5-14-n3":{"title":"友達と囲む冬の鍋","topic":"Đời sống","trans":["Vào một ngày mùa đông trời ngày càng lạnh, tôi quyết định ăn lẩu ở nhà tôi cùng bạn bè. Để chuẩn bị, đầu tiên cả nhóm cùng đi siêu thị mua đồ. Chúng tôi mua cải thảo, đậu phụ và thịt, tôi thấy đó là những nguyên liệu rất hợp để nấu lẩu.","Vừa về đến nhà, chúng tôi liền thái rau và lần lượt cho vào nồi. Vì rau khó chín nên chúng tôi cho vào trước, còn thịt thì cho vào sau. Khi nồi lẩu sôi lên, căn phòng dần ấm lên. Nhờ hơi nước nóng, ấm đến mức quên cả cái lạnh bên ngoài.","Cùng nhau ăn thì thấy ngon hơn nhiều so với khi ăn một mình. Dù bên ngoài là đêm lạnh nhưng chúng tôi đã có khoảng thời gian thật vui. Tôi nghĩ lẩu không chỉ là một món ăn mà còn là thứ giúp mọi người xích lại gần nhau hơn."],"vocab":["nồi; món lẩu","cải thảo","đậu phụ","nguyên liệu","thứ tự, lần lượt","chín, sôi","ấm áp","hơi nước, hơi nóng","trải qua, dành (thời gian)","làm cho gần lại, xích lại gần"],"grammar":[{"t":"〜ことにする","note":"Diễn tả người nói tự quyết định làm một việc gì đó. Ví dụ: 「友達と私の家で鍋をすることにしました」"},{"t":"〜ため(に)","note":"Diễn tả nguyên nhân, lý do, đi sau thể thông thường. Ví dụ: 「野菜は火が通りにくいため、先に入れて」"},{"t":"〜ようにする","note":"Diễn tả việc cố gắng để biến một hành động thành thói quen hoặc đảm bảo làm được việc đó. Ví dụ: 「肉は後から入れるようにしました」"},{"t":"〜につれて","note":"Diễn tả khi một bên thay đổi thì bên kia cũng thay đổi theo. Ví dụ: 「鍋が煮えてくるにつれて、部屋の中がだんだん暖かくなりました」"}]},"eh-n4-1-n2":{"title":"Ngày bị cảm","topic":"Truyện tranh","trans":["Sáng ngủ dậy, đầu anh đau như muốn nứt ra, cổ họng cũng như bị sưng, nói thôi cũng thấy khổ sở. Người thì nặng nề, Tanutaro nghĩ có lẽ mình bị sốt nên đành phải quyết định là hôm nay không thể đi làm được. Vì vậy anh gọi điện đến công ty và nói: 「かぜをひいてしまったので、今日はお休みをいただけないでしょうか」.","Gọi điện xong, Tanutaro đến phòng khám gần nhà. Anh đưa thẻ bảo hiểm ở quầy tiếp nhận, điền phiếu khám ghi các triệu chứng, rồi ngồi chờ đến lượt. Vừa vào phòng khám, bác sĩ hỏi anh: 「いつから具合が悪いのですか」. Tanutaro trả lời: 「昨日の夜からで、せきも出ます」, rồi lần lượt kể các triệu chứng của mình.","Sau khi khám, bác sĩ nói: 「ただのかぜですね」 và giải thích rằng đây không phải bệnh nghiêm trọng. Bác sĩ còn khuyên anh đừng gắng sức: 「薬を飲んで、ゆっくり休んだほうがいいですよ」. Lấy thuốc về nhà, Tanutaro làm đúng như lời bác sĩ, nằm nghỉ cả ngày. Tối hôm đó, Kon lo lắng nên đã mang cháo đến cho anh.","Bát cháo nóng hiền lành với cơ thể, ngon đến mức như thấm vào người đang yếu. Sau đó, nhờ uống thuốc và nghỉ ngơi, ba ngày sau Tanutaro đã khỏe hẳn. Anh cảm thấy đến bệnh viện ở Nhật khi chưa quen thì hơi đáng sợ, nhưng đi rồi mới thấy không đến mức phải lo như vậy."],"vocab":[{"w":"判断","m":"phán đoán, quyết định"},{"w":"提示","m":"xuất trình, đưa ra"},{"w":"問診票","m":"phiếu khám bệnh (ghi triệu chứng)"},{"w":"症状","m":"triệu chứng"},{"w":"具合","m":"tình trạng (sức khỏe)"},{"w":"診察","m":"khám bệnh"},{"w":"深刻","m":"nghiêm trọng"},{"w":"勧める","m":"khuyên, đề nghị"},{"w":"休養","m":"nghỉ ngơi, tĩnh dưỡng"}],"grammar":[{"t":"〜ざるを得ない","note":"Nghĩa là \"đành phải ~, buộc phải ~\", dùng khi không còn lựa chọn nào khác. Ví dụ: 「仕事に行くのは無理だと判断せざるを得ませんでした」"},{"t":"〜どおり","note":"Nghĩa là \"đúng như ~, theo ~\", đi sau danh từ. Ví dụ: 「お医者さんの言葉どおり一日中横になって過ごしました」"},{"t":"〜ものの","note":"Nghĩa là \"tuy ~ nhưng ~\", hai vế có sự trái ngược. Ví dụ: 「少し怖かったものの、行ってみれば心配するほどではなかった」"},{"t":"〜おかげで","note":"Nghĩa là \"nhờ có ~\", nêu nguyên nhân của kết quả tốt. Ví dụ: 「薬と休養のおかげで、三日後にはすっかり元気になりました」"}]},"eh-n4-1-n3":{"title":"Ngày bị cảm","topic":"Truyện tranh","trans":["Sáng ngủ dậy, đầu đau dữ dội, cổ họng cũng đau nên anh nghĩ không biết mình có bị sốt không. Tanutaro gọi điện đến công ty, nói là bị cảm nên muốn xin nghỉ hôm nay. Sau đó anh đến phòng khám gần nhà, đưa thẻ bảo hiểm ở quầy tiếp nhận và điền phiếu khám.","Bác sĩ hỏi 「いつからですか」, nên anh trả lời là từ tối qua. Khi anh nói mình cũng bị ho, bác sĩ bảo 「ただのかぜですね」. Rồi bác sĩ dặn nên uống thuốc và nghỉ ngơi cho thật tốt.","Tối hôm đó, Kon mang cháo đến cho anh. Cháo nóng hổi, ngon đến mức không chỉ người mà cả lòng cũng thấy nhẹ nhõm. Nằm một mình thì dễ thấy bất an, nhưng có người đến bên cạnh thì thấy vững dạ hơn hẳn.","Ba ngày sau, Tanutaro đã khỏe hẳn. Anh từng nghĩ đi bệnh viện ở Nhật hơi đáng sợ, nhưng đến thật thì chẳng có vấn đề gì. Nhờ trải nghiệm lần này, lần sau có không khỏe anh cũng có thể yên tâm đến bệnh viện."],"vocab":[{"w":"受付","m":"quầy tiếp nhận, lễ tân"},{"w":"保険証","m":"thẻ bảo hiểm"},{"w":"問診票","m":"phiếu khám bệnh (ghi triệu chứng)"},{"w":"伝える","m":"truyền đạt, báo cho biết"},{"w":"おかゆ","m":"cháo"},{"w":"不安","m":"bất an, lo lắng"},{"w":"心強い","m":"yên tâm, vững dạ, có chỗ dựa"},{"w":"すっかり","m":"hoàn toàn, hẳn"},{"w":"実際に","m":"thực tế, trên thực tế"},{"w":"具合","m":"tình trạng (sức khỏe)"}],"grammar":[{"t":"〜のではないかと思う","note":"Nghĩa là \"tôi nghĩ không biết có phải ... không\", dùng để nêu phỏng đoán một cách nhẹ nhàng. Ví dụ: 「熱があるのではないかと思いました」"},{"t":"〜ようなN","note":"Dùng \"giống như ...\" để so sánh hoặc miêu tả cảm giác. Ví dụ: 「心までほっとするようなおいしさでした」"},{"t":"〜てみると","note":"Nghĩa là \"khi thử làm thì thấy ...\", phía sau nêu điều phát hiện hoặc kết quả. Ví dụ: 「実際に行ってみると問題ありませんでした」"},{"t":"〜によって","note":"Chỉ nguyên nhân, phương tiện hoặc \"nhờ vào ...\". Ví dụ: 「今回の経験によって、次に具合が悪くなっても安心して病院へ行けるようになりました」"}]},"eh-n5-1-n2":{"title":"Lần đầu đến cửa hàng tiện lợi","topic":"Truyện tranh ảnh","trans":["Tanutarō mới đến Nhật hôm qua, và hôm nay cậu quyết định lần đầu bước vào một cửa hàng tiện lợi ở Nhật. Bên trong cửa hàng sáng hơn cậu tưởng, cơm nắm, bánh mì và đồ uống được xếp kín cả kệ. Dù ngạc nhiên vì có quá nhiều loại, Tanutarō vẫn thận trọng đi dạo một vòng quanh khu bày hàng.","Sau một hồi phân vân, Tanutarō chọn một hộp cơm bento và một chai trà rồi mang ra quầy thu ngân. Nhân viên hỏi cậu 「温めますか」, nhưng trước câu hỏi đó, Tanutarō không hiểu nghĩa nên không trả lời được. 「温めますか」 có nghĩa là 「熱くしますか」, tức là hỏi xem có muốn hâm nóng hộp cơm ngay tại chỗ hay không. Biết nghĩa rồi, Tanutarō trả lời: 「はい、お願いします」.","Tiếp đó nhân viên hỏi 「袋は要りますか」, lần này cậu hiểu ý ngay. Khi kinh nghiệm mua sắm tăng lên, chắc cậu cũng sẽ dần quen với những câu nói cố định như thế này. Tanutarō bình tĩnh trả lời 「大丈夫です」. Lần đầu gặp tình huống mới thường dễ căng thẳng, nhưng chỉ cần biết nghĩa một lần, lần sau bạn sẽ tự tin ứng phó được.","Hộp cơm được hâm nóng vẫn còn nóng hổi, ngon hơn cậu tưởng. Tanutarō dường như cảm nhận được rằng không hiểu tiếng Nhật không có nghĩa là việc mua sắm nhất định sẽ khó. Nhờ trải nghiệm này mà thêm tự tin, Tanutarō nghĩ rằng sắp tới mình muốn lại đến cửa hàng tiện lợi."],"vocab":["đến Nhật, thăm Nhật Bản","đến tận nơi, ghé thăm","xếp kín, chật ních","thận trọng, cẩn thận","hâm nóng, làm nóng","hỏi, hỏi thăm","quen, làm quen","ứng phó, xử lý","nóng hổi","tự tin"],"grammar":[{"t":"〜た末(に)","note":"Diễn tả sau một quá trình phân vân hoặc nỗ lực thì cuối cùng đưa ra kết quả. Ví dụ: 「迷った末、たぬたろうは弁当を一つとお茶を一つ選び」"},{"t":"〜に対して","note":"Diễn tả phản ứng, thái độ đối với một đối tượng hay vấn đề nào đó. Ví dụ: 「その質問に対して、たぬたろうは意味が分からず答えられなかった」"},{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「買い物の経験が増えるに伴って、こうした決まり文句にも少しずつ慣れていくのだろう」"},{"t":"〜とは限らない","note":"Diễn tả điều đó không hẳn lúc nào cũng đúng, dùng để phủ định suy nghĩ quá tuyệt đối. Ví dụ: 「言葉が分からないからといって、買い物が難しいとは限らない」"}]},"eh-n5-1-n3":{"title":"Lần đầu đến cửa hàng tiện lợi","topic":"Truyện tranh ảnh","trans":["Tanutarō mới đến Nhật hôm qua, và hôm nay cậu quyết định thử đến cửa hàng tiện lợi lần đầu tiên. Bên trong cửa hàng rất sáng, cơm nắm, bánh mì, đồ uống và nhiều thứ khác được xếp đầy kệ.","Tanutarō chọn một hộp cơm bento và một chai trà rồi mang ra quầy thu ngân. Lúc đó nhân viên hỏi cậu 「温めますか」, nhưng cậu không hiểu nghĩa là gì. 「温めますか」 là câu hỏi có nghĩa 「熱くしますか」 (bạn có muốn hâm nóng không?). Hiểu nghĩa rồi, Tanutarō trả lời: 「はい、お願いします」.","Tiếp theo nhân viên hỏi 「袋はいりますか」. Lần này cậu hiểu ý câu hỏi nên có thể bình tĩnh trả lời 「大丈夫です」.","Hộp cơm nóng ngon hơn cậu nghĩ rất nhiều. Nhờ trải nghiệm này, Tanutarō có thêm tự tin và bắt đầu muốn lại đến cửa hàng tiện lợi."],"vocab":["đến, tới nơi","được xếp, được bày","chọn","nhân viên cửa hàng","hâm nóng, làm nóng","nghĩa, ý nghĩa","câu hỏi","bình tĩnh, điềm tĩnh","kinh nghiệm, trải nghiệm","tự tin"],"grammar":[{"t":"〜たばかり","note":"Diễn tả hành động vừa mới xảy ra không lâu. Ví dụ: 「昨日日本に着いたばかりで」 nghĩa là cậu vừa mới đến Nhật."},{"t":"〜ことにする","note":"Diễn tả quyết định do chính mình đưa ra. Ví dụ: 「行ってみることにしました」 nghĩa là đã quyết định thử đi."},{"t":"〜ことができる","note":"Diễn tả có khả năng hoặc có cách làm việc gì đó. Ví dụ: 「落ち着いて答えることができました」 nghĩa là đã có thể bình tĩnh trả lời."},{"t":"〜によって／〜ようになる","note":"「によって」diễn tả nguyên nhân hoặc phương tiện, 「ようになる」diễn tả sự thay đổi. Ví dụ: 「この経験によって自信がつき」「思うようになりました」."}]},"eh-n5-2-n2":{"title":"Lạc đường ở nhà ga","topic":"Sách tranh","trans":["Hôm nay trời đẹp, Tanutarou quyết định đi tàu ra biển chơi. Thế nhưng khi đến nhà ga, cậu mới thấy nơi này lớn hơn mình tưởng tượng rất nhiều. Trong sân ga người đông nghịt, cậu thậm chí còn khó xác định mình nên đi hướng nào. Tàu ra biển khởi hành từ đường ray số mấy, Tanutarou hoàn toàn không có chút manh mối nào.","Cậu xem bản đồ để tìm manh mối, nhưng thông tin quá nhiều nên lại càng rối hơn. Thời gian chưa chắc đã còn dư dả, nên Tanutarou ngày càng sốt ruột. Đúng lúc cậu đứng chôn chân tại chỗ vì hết cách thì cô cáo Konchan đi ngang qua và hỏi: 「どうしましたか」(Bạn sao thế?).","Tanutarou lấy hết can đảm hỏi: 「すみません、海へ行く電車はどこですか」(Xin lỗi, tàu ra biển ở đâu ạ?). Konchan không hề tỏ vẻ khó chịu, nhẹ nhàng chỉ cho cậu: 「3番線ですよ、あそこの階段を上ってください」(Ở đường ray số 3 đó, bạn lên cầu thang đằng kia nhé). Hỏi người lạ cần có dũng khí, nhưng nhờ hỏi mà sự phân vân được giải tỏa ngay. Khi gặp khó khăn, thay vì một mình lo nghĩ, nhờ những người xung quanh giúp đỡ thường sẽ giải quyết nhanh hơn.","Tanutarou nói 「ありがとうございます」(Cảm ơn bạn) rồi vội vã chạy lên cầu thang. Dù giờ tàu chạy đã gần kề, cậu vẫn kịp lên tàu. Nhờ gặp được người tốt bụng giúp đỡ, một ngày ra biển của Tanutarou đã bắt đầu suôn sẻ."],"vocab":[{"m":"bên trong (nhà ga, v.v.), khu vực trong ga"},{"m":"không có chút manh mối nào, không thể đoán được"},{"m":"manh mối, đầu mối"},{"m":"hỗn loạn, rối bời"},{"m":"sự sốt ruột"},{"m":"(cảm xúc) ngày càng mạnh lên"},{"m":"đứng chôn chân tại chỗ"},{"m":"giải tỏa, giải quyết"},{"m":"chạy lên (cầu thang, v.v.)"},{"m":"kịp, đến kịp giờ"}],"grammar":[{"t":"〜ものの","note":"Nghĩa là \"tuy… nhưng…\", theo sau là kết quả trái với dự đoán. Ví dụ: 「地図を確認したものの、情報が多すぎてかえって混乱してしまった」"},{"t":"〜とは限らない","note":"Nghĩa là \"không hẳn là…, chưa chắc…\", dùng để phủ định một suy luận cho rằng điều gì cũng đúng trong mọi trường hợp. Ví dụ: 「時間に余裕があるとは限らないので」"},{"t":"〜一方だ","note":"Diễn tả một tình trạng cứ tiếp tục tiến triển (xấu đi hoặc mạnh lên) theo một hướng, nghĩa là \"ngày càng…\". Ví dụ: 「たぬたろうの焦りは募る一方だった」"},{"t":"〜にもかかわらず","note":"Nghĩa là \"mặc dù… nhưng…\", vế sau là kết quả không phù hợp với điều kiện ở vế trước. Ví dụ: 「発車時刻が迫っていたにもかかわらず、何とか電車に間に合うことができた」"}]},"eh-n5-2-n3":{"title":"Lạc đường ở nhà ga","topic":"Sách tranh","trans":["Hôm nay trời rất đẹp nên Tanutarou quyết định đi tàu ra biển chơi. Thế nhưng nhà ga lớn hơn cậu tưởng tượng nhiều, có rất đông người đang bước đi vội vã. Tanutarou hoàn toàn không biết tàu ra biển khởi hành từ đường ray số mấy.","Cậu nghĩ xem bản đồ chắc sẽ hiểu, nhưng kết quả lại càng khó hiểu hơn. Thời gian cũng trôi qua từng chút một nên Tanutarou dần dần thấy bất an. Lúc đó, cô cáo Konchan đi ngang qua, nhận ra vẻ bối rối của cậu nên lên tiếng hỏi thăm.","Tanutarou lịch sự hỏi: 「すみません、海へ行く電車はどこから出ますか」(Xin lỗi, tàu ra biển khởi hành từ đâu ạ?). Konchan mỉm cười chỉ cho cậu: 「3番線ですよ、あそこの階段を上がってください」(Ở đường ray số 3 đó, bạn lên cầu thang đằng kia nhé). Vì giờ tàu chạy sắp đến, Tanutarou nói lời cảm ơn rồi chạy đi ngay.","Nhờ chạy vội lên cầu thang, Tanutarou cuối cùng cũng kịp lên tàu. Cậu thật lòng biết ơn vì đã có người hỏi thăm giúp đỡ khi đang gặp khó khăn."],"vocab":[{"m":"ra ngoài, đi chơi"},{"m":"sự tưởng tượng, tưởng tượng"},{"m":"số đường ray (sân ga)"},{"m":"ngược lại, trái lại"},{"m":"bất an, lo lắng"},{"m":"tình cờ đi ngang qua"},{"m":"dáng vẻ, tình hình"},{"m":"lịch sự, cẩn thận"},{"m":"tàu khởi hành"},{"m":"kịp, đến kịp giờ"}],"grammar":[{"t":"〜ことにする","note":"Diễn tả việc người nói hoặc chủ thể tự mình quyết định làm gì đó. Ví dụ: 「電車に乗って海へ出かけることにしました」nghĩa là Tanutarou tự quyết định đi ra biển."},{"t":"〜ため(nguyên nhân)","note":"Dùng để nêu nguyên nhân, lý do, trang trọng hơn 「から」một chút. Ví dụ: 「時間も少しずつ過ぎていくため、たぬたろうはだんだん不安になってきました」"},{"t":"〜おかげで","note":"Diễn tả nhờ một nguyên nhân tốt mà có kết quả tốt, mang sắc thái biết ơn. Ví dụ: 「階段を急いで上がったおかげで、たぬたろうはなんとか電車に間に合いました」"},{"t":"〜てしまう","note":"Diễn tả kết quả đáng tiếc hoặc ngoài dự liệu, cũng có thể diễn tả sự hoàn tất. Ví dụ: 「かえって分からなくなってしまいました」"}]},"a-n5-10-n3":{"title":"Gọi món ở nhà hàng","topic":"Cuộc sống","trans":["Hôm nay mình cùng bạn đi nhà hàng để ăn uống. Vừa ngồi vào bàn, bọn mình xem thực đơn trước và suy nghĩ xem nên ăn gì. Có rất nhiều món nên mình phân vân mãi, nhưng cuối cùng vẫn chọn được món mình muốn ăn.","Vì đã quyết định xong món rồi, nên mình gọi nhân viên đến để gọi món. Mình gọi một suất cơm定食 và trà, nhân viên ghi lại order rồi quay đi. Mình cứ tưởng sẽ phải chờ lâu, nhưng món ăn lên nhanh hơn dự đoán rất nhiều.","Đồ ăn rất ngon, tuy không phải là món gì đặc biệt nhưng mình vẫn cực kỳ hài lòng. Ăn xong, mình ra quầy thu ngân để thanh toán. Vì cũng có thể trả bằng thẻ nên mình thấy rất tiện.","Cách thanh toán khác nhau tùy từng quán, nên việc có thể dùng thẻ giúp ích rất nhiều. Mình nghĩ lần sau mình lại muốn cùng bạn quay lại nhà hàng này."],"vocab":["Bữa ăn, việc ăn uống","Phân vân, không biết chọn thế nào","Chọn","Nhân viên (quán)","Gọi món, đặt hàng","Cơm suất, set ăn","Dự đoán, dự tính","Hài lòng","Trả (tiền), thanh toán","Việc thanh toán"],"grammar":[{"t":"〜ために","note":"Diễn tả mục đích, nghĩa là «để làm ～». Ví dụ: 「食事をするためにレストランへ行きました」."},{"t":"〜ことにする","note":"Diễn tả việc tự mình quyết định làm gì đó. Ví dụ: 「店員さんを呼んで注文することにしました」."},{"t":"〜わけではない","note":"Nghĩa là «không phải là ～», dùng để phủ định một phần hoặc tránh bị hiểu lầm. Ví dụ: 「特別なものを食べたわけではありませんが」."},{"t":"〜によって","note":"Nghĩa là «tùy theo ～ mà khác nhau», diễn tả sự thay đổi tùy tình huống hoặc đối tượng. Ví dụ: 「店によって支払い方法は違うので」."}]},"a-n2-6-n4":{"title":"Coi trọng thời gian ngủ","topic":"Sức khỏe","trans":["Khi bận rộn, chúng ta thường vô tình cắt giảm thời gian ngủ. Nhưng ngủ đủ giấc rất quan trọng để có một cuộc sống khỏe mạnh.","Nếu ngủ không đủ, bạn sẽ không thể tập trung. Sức khỏe cũng có thể trở nên tệ đi. Chắc hẳn cũng có nhiều người buồn ngủ vào ban ngày nên không thể làm việc hay học tập được.","Để ngủ ngon, trước hết điều quan trọng là xây dựng nhịp sinh hoạt hằng ngày. Bạn hãy thử đi ngủ và thức dậy vào cùng một giờ mỗi ngày nhé. Trước khi ngủ, tốt nhất đừng xem điện thoại thông minh. Vì ánh sáng chói của màn hình sẽ khiến não bộ tỉnh táo. Dù chỉ là khác biệt nhỏ, nếu duy trì mỗi ngày thì cũng sẽ tạo nên khoảng cách lớn. Trước tiên, bạn hãy thử bắt đầu bằng việc lên giường sớm hơn một chút nhé."],"vocab":["bận rộn","giảm bớt, cắt giảm","khỏe mạnh, tràn đầy năng lượng","quan trọng","tập trung","tình trạng (sức khỏe), trạng thái","buồn ngủ","cuộc sống, sinh hoạt","sự khác biệt","chăn nệm, đồ giường (futon)"],"grammar":[{"t":"〜てしまう","note":"Diễn tả việc lỡ làm gì đó mà không có chủ ý, hoặc sự việc dẫn đến kết quả không mong muốn. Ví dụ: 「つい寝る時間を減らしてしまいます」「頭が起きてしまうからです」"},{"t":"〜ないと","note":"Nghĩa là \"nếu không ... thì sẽ ...\", diễn tả điều kiện và kết quả. Ví dụ: 「寝る時間が足りないと、集中できなくなります」"},{"t":"〜ようにする","note":"Diễn tả việc cố gắng tạo thành thói quen hoặc cố gắng làm điều gì đó. Ví dụ: 「同じ時間に起きるようにしましょう」"},{"t":"〜たほうがいい","note":"Nghĩa là \"nên ...\", \"tốt hơn là ...\", dùng để đưa ra lời khuyên. Ví dụ: 「見るのは、やめたほうがいいです」"}]},"a-n5-10-n2":{"title":"レストランでの注文","topic":"Cuộc sống","trans":["Hôm nay mình đã cùng một người bạn đi ăn ở nhà hàng. Sau khi ngồi vào bàn, mình xem kỹ và so sánh thực đơn, rồi suy nghĩ thật kỹ xem nên chọn món nào. Khi ăn ngoài, chỉ dựa vào thông tin trên thực đơn thì rất khó hình dung được vị của món ăn, nên việc phân vân không biết chọn gì cũng không phải là hiếm.","Sau khi chọn xong món, mình gọi nhân viên đến để gọi món. Cuối cùng, mình quyết định gọi một suất set meal (định食) và trà, rồi nói với nhân viên. Những lúc nói ra món mình muốn gọi như thế này cũng là cơ hội quý giá để dùng ngay tiếng Nhật đã học.","Gọi món xong chưa đợi bao lâu thì món ăn mình gọi đã được mang ra, khiến mình hơi bất ngờ. Vị cũng rất ngon, là một bữa ăn ngon hơn cả mong đợi. Khi món ăn được phục vụ nhanh mà hương vị lại đảm bảo, thì mức độ hài lòng của khách tự nhiên sẽ cao lên.","Ăn xong, mình đứng dậy đi đến quầy thu ngân và thanh toán ở đó. Vì cũng có thể quẹt thẻ nên mình không cần mang nhiều tiền mặt, rất tiện lợi. Cùng với việc các hình thức thanh toán ngày càng đa dạng, những cửa hàng cho phép dùng thẻ cũng trở thành điểm tựa đáng tin cậy đối với du khách và người học. Cũng có những cửa hàng chỉ nhận tiền mặt, không phải nơi nào cũng dùng được thẻ, nên lần này mình thấy thật may."],"vocab":["ăn ngoài","so sánh, xem đối chiếu","tưởng tượng, hình dung","gọi món, đặt hàng","quý giá","mức độ hài lòng","thanh toán, chi trả","đa dạng hóa","đáng tin cậy, yên tâm, có chỗ dựa"],"grammar":[{"t":"〜に伴って","note":"Diễn tả khi một việc thay đổi thì việc khác cũng thay đổi theo. Ví dụ: 「支払い方法が多様化するに伴って、カードが使える店は旅行者や学習者にとっても心強い存在になっています」"},{"t":"〜とは限らない","note":"Nghĩa là \"không hẳn lúc nào cũng ...\", phủ định một phần đối với nhận định toàn diện. Ví dụ: 「どこでもカードが使えるとは限らないので、今回は助かりました」"},{"t":"〜うえに","note":"Diễn tả việc thêm vế sau vào vế trước, thường dùng cho những việc cùng chiều hướng (không những ... mà còn ...). Ví dụ: 「料理の提供が早いうえに味も確かなら、客にとって満足度は自然と高くなるものです」"},{"t":"〜ことも少なくない","note":"Dùng phủ định kép để diễn tả \"trường hợp như thế không hiếm\", giọng điệu nhẹ nhàng, kín đáo. Ví dụ: 「選ぶのに迷うことも少なくありません」"}]}};
